typedef struct XL6_IrLowerContext {
    XL6_IrModule* module;
    XL6_IrBlockId block;
    size_t functionIndex;
    XL6_IrValueId nextValue;
    XL6_DiagList* diags;
    struct XL6_IrLowerLoopTarget* loops;
    size_t loopCount;
    size_t loopCapacity;
    struct XL6_IrLowerLoopResource* loopResources;
    size_t loopResourceCount;
    size_t loopResourceCapacity;
    struct XL6_IrLowerExceptionTarget* exceptions;
    size_t exceptionCount;
    size_t exceptionCapacity;
    struct XL6_IrLowerCatchPayload* catchPayloads;
    size_t catchPayloadCount;
    size_t catchPayloadCapacity;
    struct XL6_IrLowerDeferredReturn* deferredReturns;
    size_t deferredReturnCount;
    size_t deferredReturnCapacity;
    struct XL6_IrLowerPendingReturnCleanup* pendingReturnCleanups;
    size_t pendingReturnCleanupCount;
    size_t pendingReturnCleanupCapacity;
    struct XL6_IrLowerPendingException* pendingException;
    struct XL6_IrLowerFinallyBarrier* finallyBarriers;
    size_t finallyBarrierCount;
    size_t finallyBarrierCapacity;
    struct XL6_IrLowerDeferredLoopExit* deferredLoopExits;
    size_t deferredLoopExitCount;
    size_t deferredLoopExitCapacity;
    struct XL6_IrLowerPromotedParameter* promotedParameters;
    size_t promotedParameterCount;
    size_t promotedParameterCapacity;
    struct XL6_IrLowerEvaluationOwner* evaluationOwners;
    size_t evaluationOwnerCount;
    size_t evaluationOwnerCapacity;
    uint32 nextFinallyBarrierId;
    int catchDepth;
    XL6_SymbolId nextSyntheticSymbol;
    int moduleTopLevel;
    size_t errorUnwindScope;
    /* SIZE_MAX after entry adaptation. During a checked parameter copy only
     * earlier BORROW bindings have acquired ownership; OWNED inputs already
     * belong to this activation, including those later in the signature. */
    size_t parameterOwnerLimit;
    /* 字段初值和默认实参在使用处求值。诊断仍指向声明，异常清理使用调用方作用域。 */
    XL6_IrNodeId declarationExitOrigin;
    size_t instantiation;
    int failed;
} XL6_IrLowerContext;

typedef struct XL6_IrLowerPendingException {
    size_t identity;
    struct XL6_IrLowerPendingException* outer;
} XL6_IrLowerPendingException;

/* A partially evaluated expression has owners before its consumer exists.
 * Each record is live only until the enclosing operation commits.  Failure
 * edges release these owners in reverse evaluation order; an inner handler
 * that resumes the expression does not cross its lifetime boundary. */
typedef struct XL6_IrLowerEvaluationOwner {
    XL6_SymbolId storage;
    XL6_IrTypeId type;
    XL6_IrValueId value;
    XL6_SymbolId destroySymbol;
    size_t exceptionFloor;
    int transfer;
    int pendingReturn;
} XL6_IrLowerEvaluationOwner;

/* A runtime out-parameter may name a mutable closure cell, but a cell is an
 * owned resident object rather than addressable caller stack storage.  Lower
 * that boundary through one function-local slot, then commit the received
 * value with ordinary CELL_STORE/CELL_EXCHANGE instructions only when the
 * operation reports success.  Cgen therefore never sees or invents a cell
 * payload address. */
typedef struct XL6_IrLowerStorageWriteback {
    XL6_SymbolId target;
    XL6_SymbolId temporary;
    XL6_IrTypeId type;
    int managed;
} XL6_IrLowerStorageWriteback;

