/* A function keeps its externally visible scalar parameter ABI.  When a
 * nested closure mutates that parameter, lowering materializes a separate
 * local cell before the body starts and resolves all body uses through it. */
typedef struct XL6_IrLowerPromotedParameter {
    XL6_SymbolId sourceSymbol;
    XL6_SymbolId cellStorage;
} XL6_IrLowerPromotedParameter;

typedef struct XL6_IrLowerLoopTarget {
    uint32 region;
    XL6_IrBlockId breakBlock;
    XL6_IrBlockId continueBlock;
} XL6_IrLowerLoopTarget;

typedef enum XL6_IrLowerLoopResourceKind {
    XL6_IR_LOWER_LOOP_RESOURCE_HIDDEN = 1,
    XL6_IR_LOWER_LOOP_RESOURCE_ITERATION_TARGET
} XL6_IrLowerLoopResourceKind;

/* Hidden iterator state and owned projection targets share one LIFO cleanup
 * stack, but keep different lifetime boundaries.  A hidden cursor survives a
 * continue in its owning loop; an iteration target does not. */
typedef struct XL6_IrLowerLoopResource {
    XL6_IrLowerLoopResourceKind kind;
    XL6_IrLoopResourceAbi abi;
    XL6_IrLoopTargetLifetimeAbi targetLifetimeAbi;
    XL6_SymbolId symbol;
    XL6_IrTypeId type;
    XL6_IrNodeId origin;
    uint32 loopRegion;
    size_t loopDepth;
    size_t target;
} XL6_IrLowerLoopResource;

typedef struct XL6_IrLowerExceptionTarget {
    uint32 region;
    uint32 scopeDepth;
    XL6_IrBlockId catchBlock;
} XL6_IrLowerExceptionTarget;

/* A catch binding is owned runtime state, not a source-only name.  It stays
 * active until control leaves the semantic catch scope, where every explicit
 * exit edge releases it before the frontend-planned outer cleanups run. */
typedef struct XL6_IrLowerCatchPayload {
    XL6_SymbolId symbol;
    XL6_IrTypeId type;
    XL6_IrNodeId origin;
    uint32 scopeDepth;
} XL6_IrLowerCatchPayload;

/* A supported return ABI crossing a finally first becomes explicit local
 * storage and a CFG edge.  Managed values transfer ownership with MOVE;
 * Cgen only receives STORE/JUMP/finally/LOAD/RETURN, never a source-level
 * pending-control convention. */
typedef struct XL6_IrLowerDeferredReturn {
    XL6_IrBlockId finallyBlock;
    XL6_SymbolId storage;
    XL6_IrTypeId type;
    XL6_IrNodeId origin;
    XL6_IrNodeId exitOrigin;
    size_t nextExitStep;
} XL6_IrLowerDeferredReturn;

/* While a return-specific finally copy executes, its pending slot is a live
 * owner.  A return/throw/break/continue from that finally supersedes the old
 * route and must release the slot on the same explicit exit edge. */
typedef struct XL6_IrLowerPendingReturnCleanup {
    XL6_SymbolId storage;
    XL6_IrTypeId type;
    uint32 scopeDepth;
    XL6_IrNodeId origin;
} XL6_IrLowerPendingReturnCleanup;

/* A finally barrier exists only while lowering its protected inputs.  A loop
 * exit whose resolved target is outside that barrier receives a dedicated
 * finally block; the finished XLIR contains only ordinary blocks and JUMPs. */
typedef struct XL6_IrLowerFinallyBarrier {
    uint32 id;
    size_t loopCount;
} XL6_IrLowerFinallyBarrier;

typedef struct XL6_IrLowerDeferredLoopExit {
    uint32 barrierId;
    uint32 targetRegion;
    int isContinue;
    XL6_IrBlockId targetBlock;
    XL6_IrBlockId finallyBlock;
    XL6_IrNodeId origin;
    XL6_IrNodeId exitOrigin;
    size_t nextExitStep;
} XL6_IrLowerDeferredLoopExit;

