static int xl6IrLowerDiag(XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const char* message)
{
    const XL6_IrNode* node = xl6IrNodeGet(ctx->module, origin);
    if ( ctx->diags != NULL ) {
        xl6DiagAdd(ctx->diags, node != NULL ? node->span.line : 0,
                   node != NULL ? node->span.column : 0, message);
    }
    ctx->failed = 1;
    return 0;
}


