static XL6_SymbolId xl6IrLowerResolvedNameStorage(
    const XL6_IrLowerContext* ctx, XL6_SymbolId sourceSymbol)
{
    XL6_SymbolId symbol = xl6IrLowerClosureCaptureStorage(ctx, sourceSymbol);
    if ( symbol == 0 )
        symbol = xl6IrLowerPromotedParameterStorage(ctx, sourceSymbol);
    return symbol != 0 ? symbol : sourceSymbol;
}

/* Runtime output slots start with a valid physical owner because the channel
 * transport replaces an existing payload.  Pointer-shaped managed values use
 * their canonical internal null sentinel; scalar values use an exact zero.
 * This initialization belongs to lowering and remains visible to ownership
 * verification instead of being hidden in a C local declaration. */
static XL6_IrValueId xl6IrLowerRuntimeOutputInitialValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_IrTypeId typeId)
{
    const XL6_IrType* type = xl6IrTypeGet(&ctx->module->types, typeId);
    XL6_IrRuntimeResourcePayloadAbi payloadAbi =
        xl6IrLowerRuntimeResourcePayloadAbiForType(ctx->module, typeId);
    XL6_IrInstruction* instruction;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    const char* literal = "0";
    char* canonical = NULL;
    if ( type == NULL || payloadAbi == XL6_IR_RUNTIME_RESOURCE_PAYLOAD_INVALID )
        return XL6_IR_VALUE_INVALID;
    if ( payloadAbi == XL6_IR_RUNTIME_RESOURCE_PAYLOAD_STRING_COPY ||
         payloadAbi == XL6_IR_RUNTIME_RESOURCE_PAYLOAD_XVALUE_RETAIN ) {
        return xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, origin, typeId,
                              0, NULL, 0, &result)
            ? result : XL6_IR_VALUE_INVALID;
    }
    if ( payloadAbi != XL6_IR_RUNTIME_RESOURCE_PAYLOAD_TRIVIAL_COPY )
        return XL6_IR_VALUE_INVALID;
    if ( type->cAbi == XL6_IR_C_ABI_BOOL ||
         type->cAbi == XL6_IR_C_ABI_C_BOOL ) literal = "false";
    else if ( type->cAbi == XL6_IR_C_ABI_F64 ||
              type->cAbi == XL6_IR_C_ABI_F32 ||
              type->cAbi == XL6_IR_C_ABI_C_FLOAT ||
              type->cAbi == XL6_IR_C_ABI_C_DOUBLE ) literal = "0.0";
    if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, origin, typeId,
                         0, NULL, 0, &result) ) return XL6_IR_VALUE_INVALID;
    instruction = &ctx->module->instructions[ctx->module->instructionCount - 1];
    if ( type->cAbi == XL6_IR_C_ABI_I64 )
        canonical = xl6IrLowerCanonicalIntegerLiteral(literal);
    else if ( type->cAbi == XL6_IR_C_ABI_U64 )
        canonical = xl6IrLowerCanonicalUnsignedIntegerLiteral(literal);
    else if ( type->cAbi == XL6_IR_C_ABI_TYPE_ID )
        canonical = xrtStrDupN("0x0000000000000000ULL", 21);
    else if ( type->cAbi == XL6_IR_C_ABI_F64 )
        canonical = xl6IrLowerCanonicalFloatLiteral(literal);
    else
        canonical = xrtStrDupN(literal, strlen(literal));
    instruction->immediateText = canonical;
    return canonical != NULL ? result : XL6_IR_VALUE_INVALID;
}

static int xl6IrLowerPrepareRuntimeStorageReference(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin,
    XL6_IrNodeId expressionId, const XL6_IrNode* expression,
    XL6_IrTypeId elementType, XL6_IrValueId* address,
    XL6_IrLowerStorageWriteback* writeback)
{
    XL6_SymbolId symbol;
    XL6_SymbolId temporary;
    const XL6_IrStorage* storage;
    const XL6_IrType* type;
    const XL6_IrType* cell;
    XL6_IrValueId initial;
    if ( ctx == NULL || expression == NULL || address == NULL ||
         writeback == NULL || expression->kind != XL6_IR_NODE_NAME ||
         expression->targetSymbol == 0 ) return 0;
    memset(writeback, 0, sizeof(*writeback));
    symbol = xl6IrLowerResolvedNameStorage(ctx, expression->targetSymbol);
    storage = xl6IrStorageGet(ctx->module, symbol);
    type = xl6IrTypeGet(&ctx->module->types, elementType);
    if ( storage == NULL || storage->type != elementType || type == NULL )
        return xl6IrLowerDiag(ctx, origin,
            "XLIR runtime output target has no exact storage ABI");
    if ( storage->cellType == XL6_IR_TYPE_INVALID ) {
        *address = xl6IrLowerEmitStorageSymbolAddress(
            ctx, origin, expressionId, symbol, elementType);
        return *address != XL6_IR_VALUE_INVALID;
    }
    cell = xl6IrTypeGet(&ctx->module->types, storage->cellType);
    if ( cell == NULL || cell->kind != XL6_IR_TYPE_CELL ||
         cell->cAbi != XL6_IR_C_ABI_RUNTIME_CELL_PTR ||
         cell->paramCount != 1 || cell->params == NULL ||
         cell->params[0] != elementType ||
         (type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
          (type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
           !xl6IrLowerTypeHasStorageReleaseAbi(ctx->module, elementType))) )
        return xl6IrLowerDiag(ctx, origin,
            "XLIR runtime output cell has no exact element ownership ABI");
    temporary = xl6IrLowerNewTempStorage(ctx, elementType, origin);
    initial = xl6IrLowerRuntimeOutputInitialValue(ctx, origin, elementType);
    if ( temporary == 0 || initial == XL6_IR_VALUE_INVALID ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, elementType,
                          temporary, &initial, 1, NULL) ) return 0;
    *address = xl6IrLowerEmitStorageSymbolAddress(
        ctx, origin, expressionId, temporary, elementType);
    if ( *address == XL6_IR_VALUE_INVALID ) return 0;
    writeback->target = symbol;
    writeback->temporary = temporary;
    writeback->type = elementType;
    writeback->managed =
        type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED;
    return 1;
}

/* A successful runtime output commits every temporary to its shared cell.
 * Failure leaves the source binding untouched and retires only the temporary
 * owner.  The result value dominates all three blocks and remains the value of
 * the original expression after the merge. */
static int xl6IrLowerCompleteRuntimeStorageWritebacks(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_IrValueId result,
    const XL6_IrLowerStorageWriteback* writebacks, size_t writebackCount)
{
    XL6_IrBlockId committed, rejected, merge;
    XL6_IrInstruction* branch;
    const XL6_IrType* resultType;
    size_t i;
    if ( writebackCount == 0 ) return 1;
    resultType = xl6IrTypeGet(
        &ctx->module->types, xl6IrLowerValueType(ctx, result));
    if ( resultType == NULL || resultType->cAbi != XL6_IR_C_ABI_BOOL ||
         !xl6IrLowerNewBlock(ctx, &committed) ||
         !xl6IrLowerNewBlock(ctx, &rejected) ||
         !xl6IrLowerNewBlock(ctx, &merge) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, origin,
                          XL6_IR_TYPE_INVALID, 0, &result, 1, NULL) )
        return xl6IrLowerDiag(ctx, origin,
            "XLIR runtime output writeback has no canonical boolean commit CFG");
    branch = &ctx->module->instructions[ctx->module->instructionCount - 1];
    branch->trueTarget = committed;
    branch->falseTarget = rejected;

    xl6IrLowerEnterBlock(ctx, committed);
    for ( i = 0; i < writebackCount; ++i ) {
        XL6_IrValueId value = XL6_IR_VALUE_INVALID;
        if ( !xl6IrLowerEmit(ctx,
                 writebacks[i].managed
                     ? XL6_IR_INSTR_STORAGE_TAKE : XL6_IR_INSTR_LOAD,
                 origin, writebacks[i].type, writebacks[i].temporary,
                 NULL, 0, &value) ||
             !xl6IrLowerReplaceStorageValue(
                 ctx, origin, writebacks[i].target,
                 writebacks[i].type, value) ) return 0;
    }
    if ( !xl6IrLowerEmitJump(ctx, origin, merge) ) return 0;

    xl6IrLowerEnterBlock(ctx, rejected);
    for ( i = writebackCount; i > 0; --i ) {
        const XL6_IrLowerStorageWriteback* writeback = &writebacks[i - 1];
        if ( writeback->managed &&
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RELEASE, origin,
                              writeback->type, writeback->temporary,
                              NULL, 0, NULL) ) return 0;
    }
    if ( !xl6IrLowerEmitJump(ctx, origin, merge) ) return 0;
    xl6IrLowerEnterBlock(ctx, merge);
    return 1;
}

/* Runtime resources are ordinary managed values after this boundary.  The
 * constructor/member identity and exact TypeIds were fixed in Typed XLIR;
 * lowering only anchors borrowed rvalues, emits one RuntimeOp and preserves
 * the constructor's explicit failure edge. */
static int xl6IrLowerIntrinsicRuntimeResource(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* bindings;
    const XL6_IrNode* source;
    XL6_IrValueId operands[4] = {
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID,
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID
    };
    XL6_IrRuntimeOp runtimeOp;
    XL6_IrInstruction* runtimeInstruction;
    XL6_IrLowerStorageWriteback writebacks[4];
    size_t runtimeInstructionIndex;
    size_t runtimeOperandCount;
    size_t i;
    size_t evaluationFirst;
    size_t writebackCount = 0;
    int creates;
    int mayRaise;
    int returnsVoid;
    int ok = 1;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->kind != XL6_IR_INTRINSIC_RUNTIME_RESOURCE ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->firstOperand + intrinsic->operandCount <
             intrinsic->firstOperand ||
         intrinsic->firstOperand + intrinsic->operandCount >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ) return 0;
    bindings = intrinsic->operandCount != 0
        ? &ctx->module->intrinsicOperands[intrinsic->firstOperand] : NULL;
    runtimeOp = xl6IrLowerRuntimeResourceOp(intrinsic->runtimeResourceOp);
    creates = xl6IrLowerRuntimeResourceOpCreates(
        intrinsic->runtimeResourceOp);
    mayRaise = creates || intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_CHANNEL_SEND ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_CHANNEL_TRY_SEND ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_SPECIAL_QUEUE_TRY_PUSH ||
        xl6IrLowerRuntimeResourceOpIsStack(intrinsic->runtimeResourceOp) ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_SET ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_GET_INTO ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_FIRST_INTO ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_LAST_INTO ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_LOWER_BOUND_INTO ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_UPPER_BOUND_INTO ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_MERGE ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_KEYS ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_VALUES ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_CLONE;
    returnsVoid = intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_CHANNEL_CLOSE ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_SPECIAL_QUEUE_CLOSE ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_STACK_CLEAR ||
        intrinsic->runtimeResourceOp ==
            XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_CLEAR;
    if ( runtimeOp == XL6_IR_RUNTIME_NONE ||
         !xl6IrLowerRuntimeResourceSignatureCompatible(
             ctx->module, intrinsic, bindings) ||
          (mayRaise &&
           xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL) ) return 0;
    evaluationFirst = ctx->evaluationOwnerCount;
    for ( i = 0; i < intrinsic->operandCount; ++i ) {
        source = xl6IrNodeGet(ctx->module, bindings[i].expression);
        if ( source == NULL ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR runtime resource operand has no exact lowered value ABI");
            ok = 0;
            break;
        }
        if ( bindings[i].abi == XL6_IR_INTRINSIC_OPERAND_STORAGE_REF ) {
            const XL6_IrType* reference = xl6IrTypeGet(
                &ctx->module->types, bindings[i].type);
            if ( reference == NULL ||
                 reference->kind != XL6_IR_TYPE_STORAGE_REF ||
                 reference->paramCount != 1 || reference->params == NULL ||
                 writebackCount >= sizeof(writebacks) / sizeof(writebacks[0]) ||
                 !xl6IrLowerPrepareRuntimeStorageReference(
                     ctx, id, bindings[i].expression, source,
                     reference->params[0], &operands[i],
                     &writebacks[writebackCount]) )
                ok = 0;
            if ( !ok ) break;
            if ( writebacks[writebackCount].target != 0 )
                writebackCount += 1;
            continue;
        }
        /* Contextual null has the destination TypeId already, but still
         * needs the expected-type NULL operation, never a literal token. */
        operands[i] = bindings[i].type == source->storageType && source->sourceKind != XL6_AST_NULL
            ? xl6IrLowerNode(ctx, bindings[i].expression)
            : xl6IrLowerNodeAsType(ctx, id, bindings[i].expression, source, bindings[i].type);
        if ( operands[i] == XL6_IR_VALUE_INVALID ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR runtime resource operand has no exact lowered value ABI");
            ok = 0;
            break;
        }
        if ( bindings[i].abi == XL6_IR_INTRINSIC_OPERAND_BORROW ) {
            /* Borrow lifetime follows the lowered value's owner, not the AST
             * rvalue category.  In particular, a may-raise call result has
             * already crossed an outcome CFG before it reaches this operand;
             * reusing the pre-outcome SSA token would be a second transfer. */
            operands[i] = xl6IrLowerProtectOwnedBorrow(
                ctx, bindings[i].expression, operands[i]);
            if ( operands[i] == XL6_IR_VALUE_INVALID ) {
                ok = 0;
                break;
            }
        }
    }
    if ( !ok ) goto done;
    runtimeOperandCount = intrinsic->operandCount;
    /* Optional source syntax stops at the Typed XLIR boundary.  Lowered XLIR
     * gives Cgen one exact merge ABI: receiver, peer, overwrite. */
    if ( intrinsic->runtimeResourceOp ==
             XL6_IR_RUNTIME_RESOURCE_OP_AVL_TREE_MERGE &&
         runtimeOperandCount == 2 ) {
        XL6_IrTypeId boolType = xl6IrLowerFindTypeByCAbi(
            ctx->module, XL6_IR_C_ABI_BOOL);
        XL6_IrInstruction* constant;
        if ( boolType == XL6_IR_TYPE_INVALID ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id, boolType,
                 0, NULL, 0, &operands[2]) ) {
            ok = 0;
            goto done;
        }
        constant = &ctx->module->instructions[
            ctx->module->instructionCount - 1];
        constant->immediateText = xrtStrDupN("true", 4);
        if ( constant->immediateText == NULL ) {
            ok = 0;
            goto done;
        }
        runtimeOperandCount = 3;
    }
    runtimeInstructionIndex = ctx->module->instructionCount;
    if ( returnsVoid && mayRaise ) {
        /* A source void operation can still have a physical status result.
         * Its SSA token belongs solely to the explicit error outcome; it is
         * not a synthetic language return value or a backend TLS probe. */
        XL6_IrTypeId statusType=xl6IrLowerFindTypeByCAbi(ctx->module,XL6_IR_C_ABI_BOOL);
        *result=xl6IrLowerEmitRuntimeCall(ctx,id,statusType,runtimeOp,operands,runtimeOperandCount);
        if ( statusType == XL6_IR_TYPE_INVALID || *result == XL6_IR_VALUE_INVALID ) {
            ok=0; goto done;
        }
    } else if ( returnsVoid ) {
        if ( !xl6IrLowerEmitRuntimeCallVoid(
                 ctx, id, runtimeOp, operands, runtimeOperandCount) ) {
            ok = 0;
            goto done;
        }
    } else {
        *result = xl6IrLowerEmitRuntimeCall(
            ctx, id, call->storageType, runtimeOp,
            operands, runtimeOperandCount);
        if ( *result == XL6_IR_VALUE_INVALID ) {
            ok = 0;
            goto done;
        }
    }
    runtimeInstruction = &ctx->module->instructions[runtimeInstructionIndex];
    runtimeInstruction->payloadType = intrinsic->payloadType;
    runtimeInstruction->runtimeResourcePayloadAbi =
        intrinsic->runtimeResourcePayloadAbi;
    runtimeInstruction->runtimeResourceKeyType =
        intrinsic->runtimeResourceKeyType;
    runtimeInstruction->runtimeResourceKeyPayloadAbi =
        intrinsic->runtimeResourceKeyPayloadAbi;
    runtimeInstruction->runtimeResourceKeyOrderAbi =
        intrinsic->runtimeResourceKeyOrderAbi;
    if ( intrinsic->runtimeResourceOp ==
             XL6_IR_RUNTIME_RESOURCE_OP_THREAD_CREATE )
        runtimeInstruction->calleeType = bindings[0].type;
    if ( mayRaise && !xl6IrLowerEmitRuntimeErrorEdge(
              ctx, id, call, *result) ) ok = 0;
    if ( ok && !xl6IrLowerCompleteRuntimeStorageWritebacks(
             ctx, id, *result, writebacks, writebackCount) ) ok = 0;
    if ( ok && !xl6IrLowerCompleteEvaluationBorrows(
             ctx, id, evaluationFirst, result) ) ok = 0;
    if ( returnsVoid ) *result=XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationFirst;
    if ( !ok ) *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* `xcall(fn)` is the typed boundary from an XLIR closure to an XRT callable
 * xvalue.  The operation borrows the closure; the returned xvalue owns the
 * retained callable/closure chain. */
static int xl6IrLowerIntrinsicFutureCancel(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic,
    XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* source;
    const XL6_IrType* sourceType;
    const XL6_IrType* resultType;
    XL6_IrNodeId sourceId;
    XL6_IrValueId future;
    XL6_IrValueId loaded;
    XL6_SymbolId temporary = 0;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_FUTURE_CANCEL ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_VALUE ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    sourceId = binding->expression;
    source = xl6IrNodeGet(ctx->module, sourceId);
    sourceType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    resultType = xl6IrTypeGet(&ctx->module->types, call->storageType);
    if ( source == NULL || sourceType == NULL || resultType == NULL ||
         binding->type != source->storageType ||
         binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         sourceType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         sourceType->paramCount != 1 || resultType->cAbi != XL6_IR_C_ABI_BOOL ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR future cancel requires one borrowed Future and a boolean result ABI");
        return 1;
    }
    future = xl6IrLowerNode(ctx, sourceId);
    if ( future == XL6_IR_VALUE_INVALID ) return 1;
    if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
        temporary = xl6IrLowerNewTempStorage(ctx, source->storageType, id);
        if ( temporary == 0 ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, sourceId, source->storageType,
                              temporary, &future, 1, NULL) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, sourceId, source->storageType,
                              temporary, NULL, 0, &loaded) ) return 1;
        future = loaded;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType, XL6_IR_RUNTIME_FUTURE_CANCEL, &future, 1);
    if ( *result == XL6_IR_VALUE_INVALID ) return 1;
    if ( temporary != 0 && !xl6IrLowerEmit(
             ctx, XL6_IR_INSTR_RELEASE, sourceId, source->storageType,
             temporary, NULL, 0, NULL) ) *result = XL6_IR_VALUE_INVALID;
    return 1;
}

static XL6_IrRuntimeOp xl6IrLowerFutureMemberRuntimeOp(
    XL6_IrIntrinsicKind kind)
{
    switch ( kind ) {
    case XL6_IR_INTRINSIC_FUTURE_WAIT:
        return XL6_IR_RUNTIME_FUTURE_WAIT;
    case XL6_IR_INTRINSIC_FUTURE_WAIT_TIMEOUT:
        return XL6_IR_RUNTIME_FUTURE_WAIT_TIMEOUT;
    case XL6_IR_INTRINSIC_FUTURE_WAIT_UNTIL:
        return XL6_IR_RUNTIME_FUTURE_WAIT_UNTIL;
    case XL6_IR_INTRINSIC_FUTURE_IS_DONE:
        return XL6_IR_RUNTIME_FUTURE_IS_DONE;
    case XL6_IR_INTRINSIC_FUTURE_IS_PENDING:
        return XL6_IR_RUNTIME_FUTURE_IS_PENDING;
    case XL6_IR_INTRINSIC_FUTURE_IS_CANCELLED:
        return XL6_IR_RUNTIME_FUTURE_IS_CANCELLED;
    case XL6_IR_INTRINSIC_FUTURE_IS_FAILED:
        return XL6_IR_RUNTIME_FUTURE_IS_FAILED;
    default:
        return XL6_IR_RUNTIME_NONE;
    }
}

/* Typed XLIR has already converted member syntax into an exact operation and
 * placed the borrowed Future at operand zero.  Lowering preserves only that
 * ABI and optional millisecond I64; it never inspects the member spelling. */
static int xl6IrLowerIntrinsicFutureMember(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic,
    XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* bindings;
    const XL6_IrNode* source;
    const XL6_IrType* sourceType;
    const XL6_IrType* resultType;
    const XL6_IrType* timeType = NULL;
    XL6_IrRuntimeOp runtimeOp;
    XL6_IrValueId operands[2] = {
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID
    };
    XL6_IrValueId loaded;
    XL6_SymbolId temporary = 0;
    size_t operandCount;
    int takesTime;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL )
        return 0;
    runtimeOp = xl6IrLowerFutureMemberRuntimeOp(intrinsic->kind);
    if ( runtimeOp == XL6_IR_RUNTIME_NONE ) return 0;
    takesTime = intrinsic->kind == XL6_IR_INTRINSIC_FUTURE_WAIT_TIMEOUT ||
        intrinsic->kind == XL6_IR_INTRINSIC_FUTURE_WAIT_UNTIL;
    operandCount = takesTime ? 2u : 1u;
    if ( intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != operandCount ||
         intrinsic->firstOperand + operandCount < intrinsic->firstOperand ||
         intrinsic->firstOperand + operandCount >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_VALUE ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ) return 0;
    bindings = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    source = xl6IrNodeGet(ctx->module, bindings[0].expression);
    sourceType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    resultType = xl6IrTypeGet(&ctx->module->types, call->storageType);
    if ( takesTime )
        timeType = xl6IrTypeGet(&ctx->module->types, bindings[1].type);
    if ( source == NULL || sourceType == NULL || resultType == NULL ||
         bindings[0].type != source->storageType ||
         bindings[0].abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         sourceType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         sourceType->paramCount != 1 || resultType->cAbi != XL6_IR_C_ABI_BOOL ||
         (takesTime && (xl6IrNodeGet(
              ctx->module, bindings[1].expression) == NULL ||
          timeType == NULL || timeType->cAbi != XL6_IR_C_ABI_I64 ||
          bindings[1].abi != XL6_IR_INTRINSIC_OPERAND_VALUE)) ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR Future member operation requires one borrowed Future, an optional I64 time value and a boolean result ABI");
        return 1;
    }
    operands[0] = xl6IrLowerNode(ctx, bindings[0].expression);
    if ( operands[0] == XL6_IR_VALUE_INVALID ) return 1;
    if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
        temporary = xl6IrLowerNewTempStorage(ctx, source->storageType, id);
        if ( temporary == 0 ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, bindings[0].expression,
                              source->storageType, temporary, &operands[0], 1, NULL) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, bindings[0].expression,
                              source->storageType, temporary, NULL, 0, &loaded) )
            return 1;
        operands[0] = loaded;
    }
    if ( takesTime ) {
        operands[1] = xl6IrLowerNode(ctx, bindings[1].expression);
        if ( operands[1] == XL6_IR_VALUE_INVALID ) return 1;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType, runtimeOp, operands, operandCount);
    if ( *result == XL6_IR_VALUE_INVALID ) return 1;
    if ( temporary != 0 && !xl6IrLowerEmit(
             ctx, XL6_IR_INSTR_RELEASE, bindings[0].expression,
             source->storageType, temporary, NULL, 0, NULL) )
        *result = XL6_IR_VALUE_INVALID;
    return 1;
}

static XL6_IrRuntimeOp xl6IrLowerFutureInspectionRuntimeOp(
    XL6_IrIntrinsicKind kind)
{
    switch ( kind ) {
    case XL6_IR_INTRINSIC_FUTURE_STATE:
        return XL6_IR_RUNTIME_FUTURE_STATE;
    case XL6_IR_INTRINSIC_FUTURE_STATUS:
        return XL6_IR_RUNTIME_FUTURE_STATUS;
    case XL6_IR_INTRINSIC_FUTURE_ERROR:
        return XL6_IR_RUNTIME_FUTURE_ERROR_REF;
    default:
        return XL6_IR_RUNTIME_NONE;
    }
}

static XL6_IrRuntimeOp xl6IrLowerFutureMetadataRuntimeOp(
    XL6_IrIntrinsicKind kind)
{
    switch ( kind ) {
    case XL6_IR_INTRINSIC_FUTURE_SET_DEBUG_NAME:
        return XL6_IR_RUNTIME_FUTURE_SET_DEBUG_NAME;
    case XL6_IR_INTRINSIC_FUTURE_DEBUG_NAME:
        return XL6_IR_RUNTIME_FUTURE_DEBUG_NAME_COPY;
    case XL6_IR_INTRINSIC_FUTURE_CREATE_TIME_MS:
        return XL6_IR_RUNTIME_FUTURE_CREATE_TIME_MS;
    case XL6_IR_INTRINSIC_FUTURE_COMPLETE_TIME_MS:
        return XL6_IR_RUNTIME_FUTURE_COMPLETE_TIME_MS;
    case XL6_IR_INTRINSIC_FUTURE_PENDING_CONTINUATIONS:
        return XL6_IR_RUNTIME_FUTURE_PENDING_CONTINUATIONS;
    default:
        return XL6_IR_RUNTIME_NONE;
    }
}

static int xl6IrLowerIntrinsicFutureInspection(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic,
    XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* source;
    const XL6_IrType* sourceType;
    const XL6_IrType* resultType;
    XL6_IrRuntimeOp runtimeOp;
    XL6_IrValueId future;
    XL6_IrValueId loaded;
    XL6_SymbolId temporary = 0;
    int returnsError;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL )
        return 0;
    runtimeOp = xl6IrLowerFutureInspectionRuntimeOp(intrinsic->kind);
    if ( runtimeOp == XL6_IR_RUNTIME_NONE ) return 0;
    returnsError = intrinsic->kind == XL6_IR_INTRINSIC_FUTURE_ERROR;
    if ( intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != (returnsError
             ? XL6_IR_INTRINSIC_RESULT_OWNED
             : XL6_IR_INTRINSIC_RESULT_VALUE) ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    source = xl6IrNodeGet(ctx->module, binding->expression);
    sourceType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    resultType = xl6IrTypeGet(&ctx->module->types, call->storageType);
    if ( source == NULL || sourceType == NULL || resultType == NULL ||
         binding->type != source->storageType ||
         binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         sourceType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         sourceType->paramCount != 1 ||
         (returnsError
              ? (resultType->cAbi != XL6_IR_C_ABI_RUNTIME_ERROR_PTR ||
                 resultType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED)
              : resultType->cAbi != XL6_IR_C_ABI_I64) ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR Future state/status/error operation requires one borrowed Future and an exact scalar or owned-error result ABI");
        return 1;
    }
    future = xl6IrLowerNode(ctx, binding->expression);
    if ( future == XL6_IR_VALUE_INVALID ) return 1;
    if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
        temporary = xl6IrLowerNewTempStorage(ctx, source->storageType, id);
        if ( temporary == 0 ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, binding->expression,
                              source->storageType, temporary, &future, 1, NULL) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, binding->expression,
                              source->storageType, temporary, NULL, 0, &loaded) )
            return 1;
        future = loaded;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType, runtimeOp, &future, 1);
    if ( *result == XL6_IR_VALUE_INVALID ) return 1;
    if ( temporary != 0 && !xl6IrLowerEmit(
             ctx, XL6_IR_INSTR_RELEASE, binding->expression,
             source->storageType, temporary, NULL, 0, NULL) )
        *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* Typed XLIR owns operation/effect identity. Borrowed operands join the same
 * evaluation-owner transaction used by other checked runtime operations. */
static int xl6IrLowerIntrinsicFutureMetadata(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* bindings;
    const XL6_IrNode* source;
    const XL6_IrNode* name = NULL;
    const XL6_IrType* sourceType;
    const XL6_IrType* nameType = NULL;
    const XL6_IrType* resultType;
    XL6_IrRuntimeOp runtimeOp;
    XL6_IrValueId operands[2] = {
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID
    };
    size_t firstOwner;
    int setsName;
    int returnsName;
    size_t operandCount;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL )
        return 0;
    runtimeOp = xl6IrLowerFutureMetadataRuntimeOp(intrinsic->kind);
    if ( runtimeOp == XL6_IR_RUNTIME_NONE ) return 0;
    setsName = intrinsic->kind == XL6_IR_INTRINSIC_FUTURE_SET_DEBUG_NAME;
    returnsName = intrinsic->kind == XL6_IR_INTRINSIC_FUTURE_DEBUG_NAME;
    operandCount = setsName ? 2u : 1u;
    if ( intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != operandCount ||
         intrinsic->firstOperand + operandCount >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != (returnsName
             ? XL6_IR_INTRINSIC_RESULT_OWNED
             : XL6_IR_INTRINSIC_RESULT_VALUE) ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ) return 0;
    bindings = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    source = xl6IrNodeGet(ctx->module, bindings[0].expression);
    sourceType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    resultType = xl6IrTypeGet(&ctx->module->types, call->storageType);
    if ( setsName ) {
        name = xl6IrNodeGet(ctx->module, bindings[1].expression);
        nameType = name != NULL
            ? xl6IrTypeGet(&ctx->module->types, name->storageType) : NULL;
    }
    if ( source == NULL || sourceType == NULL || resultType == NULL ||
         bindings[0].type != source->storageType ||
         bindings[0].abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         sourceType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         sourceType->paramCount != 1 ||
         (setsName &&
          (name == NULL || nameType == NULL ||
           bindings[1].type != name->storageType ||
           bindings[1].abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
           nameType->cAbi != XL6_IR_C_ABI_MANAGED_STRING ||
           nameType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED)) ||
         (setsName
              ? resultType->cAbi != XL6_IR_C_ABI_BOOL
              : returnsName
                  ? (resultType->cAbi != XL6_IR_C_ABI_MANAGED_STRING ||
                     resultType->ownershipAbi !=
                         XL6_IR_OWNERSHIP_ABI_MANAGED)
                  : resultType->cAbi != XL6_IR_C_ABI_I64) ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR Future metadata operation requires an exact borrowed Future, optional managed name and result ABI");
        return 1;
    }
    firstOwner = ctx->evaluationOwnerCount;
    operands[0] = xl6IrLowerNode(ctx, bindings[0].expression);
    if ( operands[0] == XL6_IR_VALUE_INVALID ) return 1;
    operands[0] = xl6IrLowerProtectOwnedBorrow(ctx, id, operands[0]);
    if ( operands[0] == XL6_IR_VALUE_INVALID ) return 1;
    if ( setsName ) {
        operands[1] = xl6IrLowerNode(ctx, bindings[1].expression);
        if ( operands[1] == XL6_IR_VALUE_INVALID ) return 1;
        operands[1] = xl6IrLowerProtectOwnedBorrow(ctx, id, operands[1]);
        if ( operands[1] == XL6_IR_VALUE_INVALID ) return 1;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType, runtimeOp, operands, operandCount);
    if ( *result == XL6_IR_VALUE_INVALID ) return 1;
    if (!xl6IrLowerCompleteEvaluationBorrows(ctx, id, firstOwner, result))
        *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* Task aggregates own no source Future.  Typed XLIR has already flattened the
 * literal collection and fixed the result ABI.  all/race carry a common
 * payload; whenAny deliberately accepts heterogeneous payloads and carries an
 * exact I64 index result. Operand owners form one evaluation transaction, so a
 * later launch failure releases the earlier handles on the same failure CFG. */
static int xl6IrLowerIntrinsicTaskAggregate(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic,
    XL6_IrValueId* result)
{
    XL6_IrValueId* futures = NULL;
    XL6_SymbolId* temporaries = NULL;
    const XL6_IrType* resultFuture;
    const XL6_IrType* payload;
    size_t i, evaluationFirst = ctx->evaluationOwnerCount;
    int whenAny;
    int ok = 1;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         (intrinsic->kind != XL6_IR_INTRINSIC_TASK_ALL &&
          intrinsic->kind != XL6_IR_INTRINSIC_TASK_RACE &&
          intrinsic->kind != XL6_IR_INTRINSIC_TASK_WHEN_ANY) ||
         intrinsic->operandCount == 0 ||
         intrinsic->firstOperand + intrinsic->operandCount >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         intrinsic->payloadType == XL6_IR_TYPE_INVALID ||
         intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_INVALID ||
         intrinsic->payloadAbi != xl6IrLowerAsyncResultAbi(
              ctx->module, intrinsic->payloadType) ||
         (intrinsic->kind == XL6_IR_INTRINSIC_TASK_ALL &&
          intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID &&
          !xl6IrLowerTaskAllPayloadBoxerSupported(
              ctx->module, intrinsic->payloadType,
              intrinsic->payloadAbi)) ||
         (resultFuture = xl6IrTypeGet(
             &ctx->module->types, call->storageType)) == NULL ||
         resultFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         resultFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         resultFuture->paramCount != 1 || resultFuture->params == NULL ||
         (payload = xl6IrTypeGet(
              &ctx->module->types, intrinsic->payloadType)) == NULL ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) return 0;
    whenAny = intrinsic->kind == XL6_IR_INTRINSIC_TASK_WHEN_ANY;
    if ( whenAny &&
         (resultFuture->params[0] != intrinsic->payloadType ||
          payload->cAbi != XL6_IR_C_ABI_I64 ||
          payload->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL ||
          intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_COPY_I64) ) return 0;

    futures = (XL6_IrValueId*)xrtCalloc(
        intrinsic->operandCount, sizeof(*futures));
    temporaries = (XL6_SymbolId*)xrtCalloc(
        intrinsic->operandCount, sizeof(*temporaries));
    if ( futures == NULL || temporaries == NULL ) {
        xrtFree(futures); xrtFree(temporaries);
        xl6IrLowerDiag(ctx, id,
            "XLIR task aggregate operand frame allocation failed");
        return 1;
    }
    for ( i = 0; i < intrinsic->operandCount; ++i ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[intrinsic->firstOperand + i];
        const XL6_IrNode* source = xl6IrNodeGet(ctx->module, binding->expression);
        const XL6_IrType* future = source != NULL
            ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
        if ( source == NULL || future == NULL ||
             binding->type != source->storageType ||
             binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
             future->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
             future->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
             future->paramCount != 1 || future->params == NULL ||
             xl6IrTypeGet(&ctx->module->types, future->params[0]) == NULL ||
             (!whenAny && future->params[0] != intrinsic->payloadType &&
              !xl6IrLowerCallableTypesCompatible(
                   ctx->module, future->params[0], intrinsic->payloadType)) ||
             (futures[i] = xl6IrLowerNode(
                 ctx, binding->expression)) == XL6_IR_VALUE_INVALID ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR task aggregate operand has no borrowed compatible Future payload ABI");
            ok = 0; break;
        }
        futures[i] = xl6IrLowerAnchorResolvedCallBorrow(ctx, id, binding->expression,
            source, source->storageType, XL6_IR_PARAMETER_ABI_BORROW, futures[i], &temporaries[i]);
        if (futures[i] == XL6_IR_VALUE_INVALID || (temporaries[i] != 0 &&
            !xl6IrLowerProtectEvaluationStorage(ctx, binding->expression, temporaries[i], futures[i], 0, 0))) {
            ok = 0; break;
        }
    }
    if ( ok ) {
        XL6_IrRuntimeOp runtimeOp = intrinsic->kind == XL6_IR_INTRINSIC_TASK_ALL
            ? XL6_IR_RUNTIME_FUTURE_ALL_XVALUES
            : intrinsic->kind == XL6_IR_INTRINSIC_TASK_RACE
                ? XL6_IR_RUNTIME_FUTURE_RACE
                : XL6_IR_RUNTIME_FUTURE_WHEN_ANY_INDEX;
        *result = xl6IrLowerEmitRuntimeCall(
            ctx, id, call->storageType, runtimeOp,
            futures, intrinsic->operandCount);
        if ( *result != XL6_IR_VALUE_INVALID ) {
            XL6_IrInstruction* instruction =
                &ctx->module->instructions[ctx->module->instructionCount - 1];
            instruction->payloadType = intrinsic->payloadType;
            instruction->asyncResultAbi = intrinsic->payloadAbi;
        } else ok = 0;
    }
    if ( ok && !xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) ) ok = 0;
    if (ok && !xl6IrLowerCompleteEvaluationBorrows(ctx, id, evaluationFirst, result)) ok = 0;
    ctx->evaluationOwnerCount = evaluationFirst;
    xrtFree(futures); xrtFree(temporaries);
    if ( !ok ) *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* Collapse a source array-vararg tail into the signature's one borrowed
 * array<var> slot.  The returned container is owned; the caller anchors it
 * until TASK_SPAWN_CLOSURE has copied the canonical worker frame. */
static XL6_IrValueId xl6IrLowerTaskSpawnArrayTail(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin,
    const XL6_IrIntrinsicCall* intrinsic, size_t firstTailOperand,
    XL6_IrTypeId targetType)
{
    const XL6_IrType* target = xl6IrTypeGet(
        &ctx->module->types, targetType);
    XL6_IrTypeId boolType = xl6IrLowerFindTypeByCAbi(
        ctx->module, XL6_IR_C_ABI_BOOL);
    XL6_IrValueId container;
    size_t i, first = ctx->evaluationOwnerCount;
    if ( intrinsic == NULL ||
         firstTailOperand > intrinsic->operandCount ||
         target == NULL ||
         target->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
         target->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         target->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
         boolType == XL6_IR_TYPE_INVALID ) return XL6_IR_VALUE_INVALID;
    container = xl6IrLowerEmitRuntimeCall(
        ctx, origin, targetType, xl6IrArrayConstructionRuntimeOp(ctx->module,targetType),
        NULL, 0);
    if ( container != XL6_IR_VALUE_INVALID )
        container = xl6IrLowerMaybeBindRuntimeTypeIdentity(
            ctx, origin, targetType, targetType, container);
    if ( container == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
    container = xl6IrLowerProtectEvaluationValue(ctx, origin, targetType, container);
    if (container == XL6_IR_VALUE_INVALID) return XL6_IR_VALUE_INVALID;
    for ( i = firstTailOperand; i < intrinsic->operandCount; ++i ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[intrinsic->firstOperand + i];
        const XL6_IrNode* item = xl6IrNodeGet(
            ctx->module, binding->expression);
        const XL6_IrType* itemType = item != NULL
            ? xl6IrTypeGet(&ctx->module->types, item->storageType) : NULL;
        XL6_IrValueId boxed;
        XL6_IrValueId appended;
        XL6_IrValueId operands[2];
        if ( item == NULL || itemType == NULL ||
             binding->type != item->storageType ||
             binding->abi !=
                 (itemType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED
                      ? XL6_IR_INTRINSIC_OPERAND_BORROW
                      : XL6_IR_INTRINSIC_OPERAND_VALUE) ||
             !xl6IrTypeCanBoxRuntimeXValue(
                 ctx->module, item->storageType) )
            return XL6_IR_VALUE_INVALID;
        boxed = xl6IrLowerCollectionItemAsRuntimeXValue(
            ctx, origin, binding->expression, item);
        if ( boxed == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
        operands[0] = container;
        operands[1] = boxed;
        appended = xl6IrLowerEmitRuntimeCall(
            ctx, origin, boolType,
            XL6_IR_RUNTIME_XVALUE_ARRAY_APPEND_NEW, operands, 2);
        if ( appended == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
    }
    if (!xl6IrLowerCommitEvaluationOwners(ctx, origin, first)) return XL6_IR_VALUE_INVALID;
    return container;
}

static XL6_IrFutureContinuationKind xl6IrLowerFutureContinuationKind(
    XL6_IrIntrinsicKind kind)
{
    switch ( kind ) {
    case XL6_IR_INTRINSIC_FUTURE_THEN:
        return XL6_IR_FUTURE_CONTINUATION_THEN;
    case XL6_IR_INTRINSIC_FUTURE_CATCH:
        return XL6_IR_FUTURE_CONTINUATION_CATCH;
    case XL6_IR_INTRINSIC_FUTURE_FINALLY:
        return XL6_IR_FUTURE_CONTINUATION_FINALLY;
    default:
        return XL6_IR_FUTURE_CONTINUATION_INVALID;
    }
}

/* A continuation captures exactly two borrowed managed values: its source
 * Future and its language closure.  Rvalues are anchored until the runtime
 * registration helper has retained the closure and source.  All callback
 * signature and payload decisions were made in Typed XLIR. */
static int xl6IrLowerIntrinsicFutureContinuation(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* bindings;
    XL6_IrValueId operands[2] = {
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID
    };
    XL6_SymbolId temporaries[2] = {0, 0};
    XL6_IrFutureContinuationKind continuationKind;
    size_t i, evaluationFirst = ctx != NULL ? ctx->evaluationOwnerCount : 0;
    int ok = 1;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         (continuationKind = xl6IrLowerFutureContinuationKind(
              intrinsic->kind)) == XL6_IR_FUTURE_CONTINUATION_INVALID ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != 2 ||
         intrinsic->firstOperand + 2 >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         intrinsic->sourcePayloadType == XL6_IR_TYPE_INVALID ||
         intrinsic->payloadType == XL6_IR_TYPE_INVALID ||
         intrinsic->sourcePayloadAbi == XL6_IR_ASYNC_RESULT_INVALID ||
         intrinsic->sourcePayloadAbi == XL6_IR_ASYNC_RESULT_VOID ||
         intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_INVALID ||
         intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_VOID ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) return 0;
    bindings = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    for ( i = 0; i < 2; ++i ) {
        const XL6_IrNode* source = xl6IrNodeGet(
            ctx->module, bindings[i].expression);
        const XL6_IrType* sourceType = source != NULL
            ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
        XL6_IrValueId loaded;
        if ( source == NULL || sourceType == NULL ||
             bindings[i].type != source->storageType ||
             bindings[i].abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
             sourceType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
             (i == 0 && sourceType->cAbi !=
                  XL6_IR_C_ABI_RUNTIME_FUTURE_PTR) ||
             (i == 1 && sourceType->cAbi != XL6_IR_C_ABI_CLOSURE_PTR) ||
             (operands[i] = xl6IrLowerNode(
                  ctx, bindings[i].expression)) == XL6_IR_VALUE_INVALID ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR Future continuation operand has no borrowed managed ABI");
            ok = 0;
            break;
        }
        if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
            temporaries[i] = xl6IrLowerNewTempStorage(
                ctx, source->storageType, id);
            if ( temporaries[i] == 0 ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE,
                     bindings[i].expression, source->storageType,
                     temporaries[i], &operands[i], 1, NULL) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD,
                     bindings[i].expression, source->storageType,
                     temporaries[i], NULL, 0, &loaded) ) {
                ok = 0;
                break;
            }
            operands[i] = loaded;
            if (!xl6IrLowerProtectEvaluationStorage(ctx, id, temporaries[i], loaded, 0, 0)) {
                ok = 0;
                break;
            }
        }
    }
    if ( ok ) {
        *result = xl6IrLowerEmitRuntimeCall(
            ctx, id, call->storageType,
            XL6_IR_RUNTIME_FUTURE_CONTINUE_CLOSURE, operands, 2);
        if ( *result != XL6_IR_VALUE_INVALID ) {
            XL6_IrInstruction* instruction =
                &ctx->module->instructions[
                    ctx->module->instructionCount - 1];
            instruction->calleeType = bindings[1].type;
            instruction->sourcePayloadType = intrinsic->sourcePayloadType;
            instruction->sourceAsyncResultAbi = intrinsic->sourcePayloadAbi;
            instruction->payloadType = intrinsic->payloadType;
            instruction->asyncResultAbi = intrinsic->payloadAbi;
            instruction->futureContinuationKind = continuationKind;
        } else ok = 0;
    }
    if ( ok && !xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) ) ok = 0;
    if ( ok && !xl6IrLowerCompleteEvaluationBorrows(ctx, id, evaluationFirst, result) ) ok = 0;
    if ( !ok ) *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* task.spawn is a typed closure invocation executed by the XRT task pool.
 * Typed XLIR has already fixed the closure signature and argument order.
 * Lowering anchors every managed rvalue until the runtime frame has retained
 * it, then records only the physical callable/result ABI on the RuntimeOp. */
static int xl6IrLowerIntrinsicTaskSpawn(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* callableBinding;
    const XL6_IrType* callable;
    const XL6_IrType* resultFuture;
    XL6_IrValueId* operands = NULL;
    XL6_SymbolId* temporaries = NULL;
    int arrayVariadic;
    size_t fixedParameterCount;
    size_t canonicalOperandCount;
    size_t i, evaluationFirst = ctx != NULL ? ctx->evaluationOwnerCount : 0;
    int ok = 1;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->kind != XL6_IR_INTRINSIC_TASK_SPAWN ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount < 1 ||
         intrinsic->firstOperand + intrinsic->operandCount >
             ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         intrinsic->payloadType == XL6_IR_TYPE_INVALID ||
         intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_INVALID ||
         intrinsic->payloadAbi != xl6IrLowerAsyncResultAbi(
              ctx->module, intrinsic->payloadType) ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) return 0;
    callableBinding = &ctx->module->intrinsicOperands[
        intrinsic->firstOperand];
    callable = xl6IrTypeGet(&ctx->module->types, callableBinding->type);
    resultFuture = xl6IrTypeGet(&ctx->module->types, call->storageType);
    arrayVariadic = callable != NULL &&
        callable->callableErasureAbi ==
            XL6_IR_CALLABLE_ERASURE_ARRAY_VARIADIC;
    fixedParameterCount = arrayVariadic && callable->paramCount != 0
        ? callable->paramCount - 1
        : callable != NULL ? callable->paramCount : SIZE_MAX;
    canonicalOperandCount = callable != NULL
        ? callable->paramCount + 1 : 0;
    if ( callable == NULL || callableBinding->abi !=
             XL6_IR_INTRINSIC_OPERAND_BORROW ||
         callable->kind != XL6_IR_TYPE_FUNCTION ||
         callable->cAbi != XL6_IR_C_ABI_CLOSURE_PTR ||
         callable->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         (callable->callableErasureAbi !=
              XL6_IR_CALLABLE_ERASURE_FIXED && !arrayVariadic) ||
         (!arrayVariadic
              ? canonicalOperandCount != intrinsic->operandCount
              : callable->paramCount == 0 ||
                intrinsic->operandCount < fixedParameterCount + 1) ||
         ((intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_VOID &&
           (callable->returnCount != 0 ||
            callable->callableResultType != XL6_IR_TYPE_INVALID)) ||
          (intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID &&
           (callable->returnCount != 1 ||
            callable->callableResultType != intrinsic->payloadType))) ||
         (callable->paramCount != 0 &&
          (callable->parameterModes == NULL ||
           callable->parameterAbis == NULL)) ||
         resultFuture == NULL ||
         resultFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         resultFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         resultFuture->paramCount != 1 || resultFuture->params == NULL ||
         resultFuture->params[0] != intrinsic->payloadType ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR task spawn requires an exact borrowed closure, canonical arguments and Future payload ABI");
        return 1;
    }
    if ( arrayVariadic ) {
        const XL6_IrType* tail = xl6IrTypeGet(
            &ctx->module->types,
            callable->params[fixedParameterCount]);
        if ( tail == NULL ||
             tail->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
             tail->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
             tail->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
             callable->parameterModes[fixedParameterCount] !=
                 XL6_IR_PARAMETER_MODE_DEFAULT ||
             !xl6IrTaskSpawnParameterAbiSupported(
                 tail, callable->parameterModes[fixedParameterCount],
                 callable->parameterAbis[fixedParameterCount]) ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR task spawn array-vararg tail has no canonical borrowed array frame ABI");
            return 1;
        }
    }
    operands = (XL6_IrValueId*)xrtCalloc(
        canonicalOperandCount, sizeof(*operands));
    temporaries = (XL6_SymbolId*)xrtCalloc(
        canonicalOperandCount, sizeof(*temporaries));
    if ( operands == NULL || temporaries == NULL ) {
        xrtFree(operands); xrtFree(temporaries);
        xl6IrLowerDiag(ctx, id,
            "XLIR task spawn operand frame allocation failed");
        return 1;
    }
    /* Operand zero is the borrowed closure.  The following fixed source
     * operands map one-to-one to signature slots; an array-vararg tail is
     * materialized separately below as the final canonical slot. */
    for ( i = 0; i < fixedParameterCount + 1; ++i ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[intrinsic->firstOperand + i];
        const XL6_IrNode* source = xl6IrNodeGet(
            ctx->module, binding->expression);
        const XL6_IrType* sourceType = source != NULL
            ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
        const XL6_IrType* expectedType = i == 0 ? callable :
            xl6IrTypeGet(&ctx->module->types, callable->params[i - 1]);
        XL6_IrParameterAbi parameterAbi = i == 0
            ? XL6_IR_PARAMETER_ABI_BORROW
            : callable->parameterAbis[i - 1];
        if ( source == NULL || sourceType == NULL || expectedType == NULL ||
             binding->type != source->storageType ||
             (i == 0
                  ? binding->type != callableBinding->type
                  : !xl6IrTaskSpawnArgumentCanBind(
                        ctx->module, binding->type,
                        callable->params[i - 1])) ||
             !xl6IrTaskSpawnParameterAbiSupported(
                  expectedType, i == 0 ? XL6_IR_PARAMETER_MODE_DEFAULT
                      : callable->parameterModes[i - 1], parameterAbi) ||
             binding->abi !=
                 (sourceType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED
                      ? XL6_IR_INTRINSIC_OPERAND_BORROW
                      : XL6_IR_INTRINSIC_OPERAND_VALUE) ||
             (operands[i] = i == 0
                  ? xl6IrLowerNode(ctx, binding->expression)
                  : xl6IrLowerNodeAsType(
                        ctx, id, binding->expression, source,
                        callable->params[i - 1])) ==
                 XL6_IR_VALUE_INVALID ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR task spawn operand has no exact callable parameter ownership ABI");
            ok = 0;
            break;
        }
        if ( xl6IrLowerValueType(ctx, operands[i]) !=
                 (i == 0 ? callableBinding->type
                         : callable->params[i - 1]) &&
             i != 0 && xl6IrLowerCallableTypesCompatible(
                 ctx->module, xl6IrLowerValueType(ctx, operands[i]),
                 callable->params[i - 1]) )
            operands[i] = xl6IrLowerEmitValueCopy(
                ctx, binding->expression, callable->params[i - 1],
                operands[i]);
        operands[i] = xl6IrLowerAnchorResolvedCallBorrow(
            ctx, id, binding->expression, source,
            i == 0 ? callableBinding->type : callable->params[i - 1],
            /* The launcher borrows even a byval callee input: its independent
             * frame owner is acquired transactionally and consumed at invoke. */
            expectedType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED
                ? XL6_IR_PARAMETER_ABI_BORROW : XL6_IR_PARAMETER_ABI_VALUE,
            operands[i], &temporaries[i]);
        if ( operands[i] == XL6_IR_VALUE_INVALID ||
             (temporaries[i] != 0 && !xl6IrLowerProtectEvaluationStorage(ctx, id,
                 temporaries[i], operands[i], 0, 0)) ) {
            ok = 0;
            break;
        }
    }
    if ( ok && arrayVariadic ) {
        size_t parameter = fixedParameterCount;
        size_t operand = parameter + 1;
        XL6_IrValueId tail = xl6IrLowerTaskSpawnArrayTail(
            ctx, id, intrinsic, fixedParameterCount + 1,
            callable->params[parameter]);
        if ( tail == XL6_IR_VALUE_INVALID ) ok = 0;
        if ( ok ) {
            operands[operand] = xl6IrLowerAnchorResolvedCallBorrow(
                ctx, id, id, call, callable->params[parameter],
                callable->parameterAbis[parameter], tail,
                &temporaries[operand]);
            if ( operands[operand] == XL6_IR_VALUE_INVALID ||
                 (temporaries[operand] != 0 && !xl6IrLowerProtectEvaluationStorage(ctx, id,
                     temporaries[operand], operands[operand], 0, 0)) ) ok = 0;
        }
    }
    if ( ok ) {
        *result = xl6IrLowerEmitRuntimeCall(
            ctx, id, call->storageType,
            XL6_IR_RUNTIME_TASK_SPAWN_CLOSURE,
            operands, canonicalOperandCount);
        if ( *result != XL6_IR_VALUE_INVALID ) {
            XL6_IrInstruction* instruction =
                &ctx->module->instructions[
                    ctx->module->instructionCount - 1];
            instruction->calleeType = callableBinding->type;
            instruction->callableErasureAbi =
                callable->callableErasureAbi;
            instruction->payloadType = intrinsic->payloadType;
            instruction->asyncResultAbi = intrinsic->payloadAbi;
        } else ok = 0;
    }
    if ( ok && !xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) ) ok = 0;
    if ( ok && !xl6IrLowerCompleteEvaluationBorrows(ctx, id, evaluationFirst, result) ) ok = 0;
    xrtFree(operands); xrtFree(temporaries);
    if ( !ok ) *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* Named task.all/task.race preserve one borrowed typed array operand. The
 * payload and public Future shape have already been fixed by Typed XLIR. */
static int xl6IrLowerIntrinsicTaskAggregateArray(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* source;
    const XL6_IrType* arrayType;
    const XL6_IrType* inputFuture;
    const XL6_IrType* resultFuture;
    const XL6_IrType* publicPayload;
    XL6_IrValueId array;
    XL6_IrValueId loaded;
    XL6_SymbolId temporary = 0;
    size_t evaluationFirst = ctx != NULL ? ctx->evaluationOwnerCount : 0;
    int isAll;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         (intrinsic->kind != XL6_IR_INTRINSIC_TASK_ALL_ARRAY &&
          intrinsic->kind != XL6_IR_INTRINSIC_TASK_RACE_ARRAY) ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         intrinsic->payloadType == XL6_IR_TYPE_INVALID ||
         intrinsic->payloadAbi == XL6_IR_ASYNC_RESULT_INVALID ||
         intrinsic->payloadAbi != xl6IrLowerAsyncResultAbi(
             ctx->module, intrinsic->payloadType) ||
         (intrinsic->kind == XL6_IR_INTRINSIC_TASK_ALL_ARRAY &&
          intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID &&
          !xl6IrLowerTaskAllPayloadBoxerSupported(
              ctx->module, intrinsic->payloadType,
              intrinsic->payloadAbi)) ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    source = xl6IrNodeGet(ctx->module, binding->expression);
    arrayType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    inputFuture = arrayType != NULL && arrayType->paramCount == 1 &&
        arrayType->params != NULL
            ? xl6IrTypeGet(&ctx->module->types, arrayType->params[0]) : NULL;
    resultFuture = xl6IrTypeGet(&ctx->module->types, call->storageType);
    publicPayload = resultFuture != NULL && resultFuture->paramCount == 1 &&
        resultFuture->params != NULL
            ? xl6IrTypeGet(&ctx->module->types, resultFuture->params[0]) : NULL;
    isAll = intrinsic->kind == XL6_IR_INTRINSIC_TASK_ALL_ARRAY;
    if ( source == NULL || binding->type != source->storageType ||
         binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         arrayType == NULL ||
         arrayType->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
         arrayType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         arrayType->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
         arrayType->paramCount != 1 || arrayType->params == NULL ||
         inputFuture == NULL ||
         inputFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         inputFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         inputFuture->paramCount != 1 || inputFuture->params == NULL ||
         inputFuture->params[0] != intrinsic->payloadType ||
         resultFuture == NULL ||
         resultFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         resultFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         resultFuture->paramCount != 1 || resultFuture->params == NULL ||
         publicPayload == NULL ||
         (isAll && intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID
              ? (publicPayload->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
                 publicPayload->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
                 publicPayload->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
                 publicPayload->paramCount != 1 || publicPayload->params == NULL ||
                 (publicPayload->params[0] != intrinsic->payloadType &&
                  !xl6IrLowerCallableTypesCompatible(
                      ctx->module, publicPayload->params[0],
                      intrinsic->payloadType)))
              : (resultFuture->params[0] != intrinsic->payloadType &&
                 !xl6IrLowerCallableTypesCompatible(
                     ctx->module, resultFuture->params[0],
                     intrinsic->payloadType))) ) return 0;
    array = xl6IrLowerNode(ctx, binding->expression);
    if ( array == XL6_IR_VALUE_INVALID ) return 1;
    if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
        temporary = xl6IrLowerNewTempStorage(ctx, source->storageType, id);
        if ( temporary == 0 ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, binding->expression,
                              source->storageType, temporary, &array, 1, NULL) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, binding->expression,
                              source->storageType, temporary, NULL, 0, &loaded) )
            return 1;
        array = loaded;
        if (!xl6IrLowerProtectEvaluationStorage(ctx, id, temporary, loaded, 0, 0)) return 1;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType,
        isAll ? XL6_IR_RUNTIME_FUTURE_ALL_XVALUES_ARRAY
              : XL6_IR_RUNTIME_FUTURE_RACE_ARRAY,
        &array, 1);
    if ( *result != XL6_IR_VALUE_INVALID ) {
        XL6_IrInstruction* instruction =
            &ctx->module->instructions[ctx->module->instructionCount - 1];
        instruction->payloadType = intrinsic->payloadType;
        instruction->asyncResultAbi = intrinsic->payloadAbi;
    }
    if (*result != XL6_IR_VALUE_INVALID &&
        (!xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) ||
         !xl6IrLowerCompleteEvaluationBorrows(ctx, id, evaluationFirst, result)))
        *result = XL6_IR_VALUE_INVALID;
    return 1;
}

/* The named/expression array form remains one borrowed xvalue-backed typed
 * array. Its element Future<T> identity is already verified in Typed XLIR;
 * lowering anchors only an rvalue container and never expands its contents. */
static int xl6IrLowerIntrinsicTaskWhenAnyArray(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* source;
    const XL6_IrType* arrayType;
    const XL6_IrType* elementFuture;
    const XL6_IrType* resultFuture;
    const XL6_IrType* payload;
    XL6_IrValueId array;
    XL6_IrValueId loaded;
    XL6_SymbolId temporary = 0;
    size_t evaluationFirst = ctx != NULL ? ctx->evaluationOwnerCount : 0;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->kind != XL6_IR_INTRINSIC_TASK_WHEN_ANY_ARRAY ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_COPY_I64 ||
         intrinsic->payloadType == XL6_IR_TYPE_INVALID ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    source = xl6IrNodeGet(ctx->module, binding->expression);
    arrayType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    elementFuture = arrayType != NULL && arrayType->paramCount == 1 &&
        arrayType->params != NULL
            ? xl6IrTypeGet(&ctx->module->types, arrayType->params[0]) : NULL;
    resultFuture = xl6IrTypeGet(&ctx->module->types, call->storageType);
    payload = xl6IrTypeGet(&ctx->module->types, intrinsic->payloadType);
    if ( source == NULL || binding->type != source->storageType ||
         binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         arrayType == NULL ||
         arrayType->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
         arrayType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         arrayType->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
         arrayType->paramCount != 1 || arrayType->params == NULL ||
         elementFuture == NULL ||
         elementFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         elementFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         elementFuture->paramCount != 1 || elementFuture->params == NULL ||
         xl6IrTypeGet(&ctx->module->types,
             elementFuture->params[0]) == NULL ||
         resultFuture == NULL ||
         resultFuture->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR ||
         resultFuture->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
         resultFuture->paramCount != 1 || resultFuture->params == NULL ||
         resultFuture->params[0] != intrinsic->payloadType ||
         payload == NULL || payload->cAbi != XL6_IR_C_ABI_I64 ||
         payload->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL ) return 0;
    array = xl6IrLowerNode(ctx, binding->expression);
    if ( array == XL6_IR_VALUE_INVALID ) return 1;
    if ( source->valueCategory == XL6_IR_VALUE_RVALUE ) {
        temporary = xl6IrLowerNewTempStorage(ctx, source->storageType, id);
        if ( temporary == 0 ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, binding->expression,
                              source->storageType, temporary, &array, 1, NULL) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, binding->expression,
                              source->storageType, temporary, NULL, 0, &loaded) )
            return 1;
        array = loaded;
        if (!xl6IrLowerProtectEvaluationStorage(ctx, id, temporary, loaded, 0, 0)) return 1;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType,
        XL6_IR_RUNTIME_FUTURE_WHEN_ANY_INDEX_ARRAY, &array, 1);
    if ( *result != XL6_IR_VALUE_INVALID ) {
        XL6_IrInstruction* instruction =
            &ctx->module->instructions[ctx->module->instructionCount - 1];
        instruction->payloadType = intrinsic->payloadType;
        instruction->asyncResultAbi = intrinsic->payloadAbi;
    }
    if (*result != XL6_IR_VALUE_INVALID &&
        (!xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) ||
         !xl6IrLowerCompleteEvaluationBorrows(ctx, id, evaluationFirst, result)))
        *result = XL6_IR_VALUE_INVALID;
    return 1;
}

static int xl6IrLowerIntrinsicXCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic,
    XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* source;
    const XL6_IrType* sourceType;
    const XL6_IrType* signature;
    XL6_IrTypeId signatureType;
    XL6_IrTypeId closureType;
    XL6_IrRuntimeOp runtimeOp;
    XL6_IrNodeId sourceId;
    XL6_IrValueId closure;
    XL6_SymbolId borrowedTemporary = 0;
    size_t evaluationOwnerFirst;
    if ( result != NULL ) *result = XL6_IR_VALUE_INVALID;
    if ( ctx == NULL || call == NULL || intrinsic == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_XCALL || intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    sourceId = binding->expression;
    source = xl6IrNodeGet(ctx->module, sourceId);
    sourceType = source != NULL
        ? xl6IrTypeGet(&ctx->module->types, source->storageType) : NULL;
    signatureType = source != NULL
        ? xl6IrLowerRuntimeCallableSourceSignature(
            ctx->module, source->storageType)
        : XL6_IR_TYPE_INVALID;
    signature = xl6IrTypeGet(&ctx->module->types, signatureType);
    if ( source == NULL ||
         sourceType == NULL || signature == NULL ||
         binding->type != source->storageType ||
         binding->abi != XL6_IR_INTRINSIC_OPERAND_BORROW ||
         !xl6IrLowerTypeIsRuntimeXValue(ctx->module, call->storageType) ||
         xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL ) {
        xl6IrLowerDiag(ctx, id,
                        "XLIR xcall requires an expression with the supported exact callable ABI");
        return 1;
    }
    closure = xl6IrLowerNode(ctx, sourceId);
    if ( closure == XL6_IR_VALUE_INVALID || result == NULL ) return 1;
    closureType = xl6IrLowerValueType(ctx, closure);
    if ( closureType == signatureType )
        runtimeOp = XL6_IR_RUNTIME_XVALUE_CALLABLE_FROM_CLOSURE;
    else if ( closureType == source->storageType && sourceType->kind ==
                 XL6_IR_TYPE_NULLABLE )
        runtimeOp = XL6_IR_RUNTIME_XVALUE_NULLABLE_CLOSURE_BOX;
    else {
        xl6IrLowerDiag(ctx, id,
            "XLIR xcall closure value does not match its narrowed or nullable callable ABI");
        return 1;
    }
    closure = xl6IrLowerAnchorResolvedCallBorrow(
        ctx, id, sourceId, source, closureType, XL6_IR_PARAMETER_ABI_BORROW,
        closure, &borrowedTemporary);
    if ( closure == XL6_IR_VALUE_INVALID ) return 1;
    evaluationOwnerFirst = ctx->evaluationOwnerCount;
    if ( borrowedTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, id, borrowedTemporary, closure, 0, 0) ) return 1;
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, id, call->storageType, runtimeOp,
        &closure, 1);
    if ( *result == XL6_IR_VALUE_INVALID ) goto done;
    ctx->module->instructions[ctx->module->instructionCount - 1].calleeType =
        signatureType;
    ctx->module->instructions[ctx->module->instructionCount - 1].callableErasureAbi =
        signature->callableErasureAbi;
    ctx->module->instructions[ctx->module->instructionCount - 1].runtimeIdentityType =
        signatureType;
    if ( !xl6IrLowerEmitRuntimeErrorEdge(ctx, id, call, *result) )
        *result = XL6_IR_VALUE_INVALID;
    if ( *result != XL6_IR_VALUE_INVALID && borrowedTemporary != 0 &&
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RELEASE, id, closureType,
                          borrowedTemporary, NULL, 0, NULL) )
        *result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return 1;
}

static const XL6_IrDynamicCallSite* xl6IrLowerDynamicCallSiteGet(
    const XL6_IrModule* module, XL6_IrNodeId origin, size_t* index)
{
    size_t i;
    const XL6_IrDynamicCallSite* result = NULL;
    if ( index != NULL ) *index = SIZE_MAX;
    if ( module == NULL || origin == XL6_IR_NODE_INVALID ) return NULL;
    for ( i = 0; i < module->dynamicCallSiteCount; ++i ) {
        if ( module->dynamicCallSites[i].origin != origin ) continue;
        if ( result != NULL ) return NULL;
        result = &module->dynamicCallSites[i];
        if ( index != NULL ) *index = i;
    }
    return result;
}

/* Dynamic invocation consumes only verified frame metadata.  Operand zero is
 * the borrowed callable/receiver; arguments remain in source evaluation order
 * and each becomes an owned xvalue transferred to the runtime operation. */
static XL6_IrValueId xl6IrLowerDynamicCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* call)
{
    const XL6_IrDynamicCallSite* site;
    XL6_IrValueId* operands = NULL;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    size_t siteIndex = SIZE_MAX;
    size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
    size_t argumentOwnerFirst = evaluationOwnerFirst, argumentOwnerLast = evaluationOwnerFirst;
    int writing = xl6IrNodeIsDynamicMemberWrite(ctx->module, id);
    const XL6_IrNode* destination = writing
        ? xl6IrNodeGet(ctx->module, ctx->module->children[call->firstChild]) : call;
    size_t phase, i;
    site = xl6IrLowerDynamicCallSiteGet(ctx->module, id, &siteIndex);
    if (call == NULL || destination == NULL || site == NULL || siteIndex == SIZE_MAX ||
        !xl6IrLowerTypeIsRuntimeXValue(ctx->module, site->resultType) ||
        site->resultType != destination->storageType ||
        site->resultAbi != xl6IrDynamicCallExpectedResultAbi(ctx->module, site) ||
        site->evaluationOrder != (writing ? XL6_IR_DYNAMIC_CALL_ARGUMENTS_FIRST : XL6_IR_DYNAMIC_CALL_SUBJECT_FIRST) ||
        site->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
        (((call->callKind == XL6_SEM_CALL_DYNAMIC_FUNCTION || call->callKind == XL6_SEM_CALL_FUNCTION_VALUE)) !=
            (site->kind == XL6_IR_DYNAMIC_CALL_FUNCTION)) ||
        ((call->callKind == XL6_SEM_CALL_DYNAMIC_METHOD) != (site->kind == XL6_IR_DYNAMIC_CALL_METHOD)) ||
        (xl6IrNodeIsDynamicMemberRead(ctx->module, id) != (site->kind == XL6_IR_DYNAMIC_CALL_MEMBER_GET)) ||
        (writing != (site->kind == XL6_IR_DYNAMIC_CALL_MEMBER_SET)) ||
        xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW) == NULL) {
        xl6IrLowerDiag(ctx, id, "XLIR dynamic call has no verified evaluation, frame and outcome descriptor");
        return XL6_IR_VALUE_INVALID;
    }
    operands = (XL6_IrValueId*)xrtCalloc(site->argumentCount + 1, sizeof(*operands));
    if (operands == NULL) { ctx->failed = 1; return XL6_IR_VALUE_INVALID; }
    for (phase = 0; phase < 2; ++phase) {
        int evaluateSubject = (phase == 0) == (site->evaluationOrder == XL6_IR_DYNAMIC_CALL_SUBJECT_FIRST);
        if (evaluateSubject) {
            XL6_SymbolId subjectTemporary = 0;
            XL6_IrTypeId subjectType;
            const XL6_IrNode* subject = xl6IrNodeGet(ctx->module, site->subject);
            operands[0] = xl6IrLowerNode(ctx, site->subject);
            if (operands[0] == XL6_IR_VALUE_INVALID) goto done;
            /* Retain using the actual lowered representation, including flow-narrowed nominal values. */
            subjectType = xl6IrLowerValueType(ctx, operands[0]);
            if (!xl6IrLowerTypeIsRuntimeXValue(ctx->module, subjectType)) {
                xl6IrLowerDiag(ctx, id, "XLIR dynamic call subject has no lowered xvalue ABI");
                goto done;
            }
            operands[0] = xl6IrLowerAnchorResolvedCallBorrow(ctx, id, site->subject, subject, subjectType,
                XL6_IR_PARAMETER_ABI_BORROW, operands[0], &subjectTemporary);
            if (operands[0] == XL6_IR_VALUE_INVALID ||
                (subjectTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
                    ctx, id, subjectTemporary, operands[0], 0, 0))) goto done;
        } else {
            argumentOwnerFirst = ctx->evaluationOwnerCount;
            for (i = 0; i < site->argumentCount; ++i) {
                const XL6_IrDynamicCallArgument* binding = &ctx->module->dynamicCallArguments[site->firstArgument + i];
                const XL6_IrNode* expression = xl6IrNodeGet(ctx->module, binding->expression);
                if (binding->admission != XL6_IR_DYNAMIC_CALL_ARGUMENT_ADMISSION_VERIFIED) {
                    xl6IrLowerDiag(ctx, id, "XLIR dynamic call argument has an unsupported runtime-xvalue boxing ABI");
                    goto done;
                }
                operands[i + 1] = xl6IrLowerNodeAsRuntimeXValue(
                    ctx, id, binding->expression, expression, site->resultType);
                if (operands[i + 1] == XL6_IR_VALUE_INVALID) goto done;
                operands[i + 1] = xl6IrLowerProtectEvaluationValue(
                    ctx, binding->expression, site->resultType, operands[i + 1]);
                if (operands[i + 1] == XL6_IR_VALUE_INVALID) goto done;
            }
            argumentOwnerLast = ctx->evaluationOwnerCount;
        }
    }
    if (!xl6IrLowerCommitEvaluationOwnerRange(ctx, id, argumentOwnerFirst, argumentOwnerLast)) goto done;
    result = xl6IrLowerEmitRuntimeCall(ctx, id, site->resultType,
        site->kind == XL6_IR_DYNAMIC_CALL_FUNCTION
            ? XL6_IR_RUNTIME_XVALUE_DYNAMIC_CALL : XL6_IR_RUNTIME_XVALUE_DYNAMIC_METHOD_CALL,
        operands, site->argumentCount + 1);
    if (result != XL6_IR_VALUE_INVALID) {
        XL6_IrInstruction* instruction = &ctx->module->instructions[ctx->module->instructionCount - 1];
        instruction->dynamicCallSite = siteIndex;
        instruction->dynamicCallResultAbi = site->resultAbi;
        instruction->dynamicCollectionOp = site->fallbackCollectionOp;
        if (!xl6IrLowerCompleteEvaluationCall(ctx, id, call, NULL, &result, evaluationOwnerFirst))
            result = XL6_IR_VALUE_INVALID;
    }
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    xrtFree(operands);
    return result;
}

static XL6_IrCallVariadicAbi xl6IrLowerCallableTargetVariadicAbi(
    XL6_IrCallableErasureAbi abi);

static XL6_IrValueId xl6IrLowerFunctionValueCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node)
{
    const XL6_IrNode* callee;
    const XL6_IrNode* args;
    const XL6_IrCallSite* site;
    const XL6_IrType* signature;
    XL6_IrTypeId signatureType = XL6_IR_TYPE_INVALID;
    XL6_IrCallVariadicAbi variadicAbi;
    size_t fixedParameterCount;
    const XL6_IrExitPlan* errorPlan;
    XL6_IrValueId* operands = NULL;
    XL6_SymbolId* borrowedTemps = NULL;
    XL6_SymbolId calleeTemporary = 0;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
    size_t i;
    if ( node == NULL || node->childCount != 2 ) {
        xl6IrLowerDiag(ctx, id, "XLIR closure call has no resolved callable storage ABI");
        return XL6_IR_VALUE_INVALID;
    }
    callee = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
    args = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
    if ( callee != NULL &&
         xl6IrLowerTypeIsErasedCallable(
             ctx->module, callee->storageType) )
        return xl6IrLowerDynamicCall(ctx, id, node);
    /* Flow narrowing keeps the declared nullable storage on the callee node
     * and records the proven callable element in `type`.  NAME lowering emits
     * the matching NULLABLE_UNWRAP, so the call contract must consume that
     * exact result TypeId rather than looking back through declared storage. */
    if ( callee != NULL )
        signatureType = callee->type != XL6_IR_TYPE_INVALID
            ? callee->type : callee->storageType;
    signature = xl6IrTypeGet(&ctx->module->types, signatureType);
    site = xl6IrCallSiteGet(ctx->module, id);
    variadicAbi = signature != NULL
        ? xl6IrLowerCallableTargetVariadicAbi(
            signature->callableErasureAbi)
        : (XL6_IrCallVariadicAbi)-1;
    fixedParameterCount = signature != NULL &&
            variadicAbi != (XL6_IrCallVariadicAbi)-1 &&
            variadicAbi != XL6_IR_CALL_VARIADIC_NONE &&
            signature->paramCount != 0
        ? signature->paramCount - 1
        : signature != NULL ? signature->paramCount : SIZE_MAX;
    errorPlan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW);
    if ( callee == NULL || args == NULL || args->kind != XL6_IR_NODE_LIST ||
         signature == NULL || signature->kind != XL6_IR_TYPE_FUNCTION ||
         signature->cAbi != XL6_IR_C_ABI_CLOSURE_PTR ||
         (signature->paramCount != 0 &&
          (signature->parameterModes == NULL || signature->parameterAbis == NULL)) ||
         site == NULL || site->callKind != XL6_SEM_CALL_FUNCTION_VALUE ||
         site->targetSymbol != node->targetSymbol ||
         site->receiver != ctx->module->children[node->firstChild] ||
         site->resultType != node->storageType ||
         variadicAbi == (XL6_IrCallVariadicAbi)-1 ||
         variadicAbi == XL6_IR_CALL_VARIADIC_C ||
         site->variadicAbi != variadicAbi ||
         site->fixedParameterCount != fixedParameterCount ||
         signature->callableResultType != node->storageType || errorPlan == NULL ) {
        xl6IrLowerDiag(ctx, id, "XLIR closure call has no exact signature and result ABI");
        return XL6_IR_VALUE_INVALID;
    }
    operands = (XL6_IrValueId*)xrtCalloc(
        signature->paramCount + 1, sizeof(*operands));
    if ( signature->paramCount != 0 )
        borrowedTemps = (XL6_SymbolId*)xrtCalloc(
            signature->paramCount, sizeof(*borrowedTemps));
    if ( operands == NULL ||
         (signature->paramCount != 0 && borrowedTemps == NULL) ) {
        xrtFree(operands); xrtFree(borrowedTemps); ctx->failed = 1; return XL6_IR_VALUE_INVALID;
    }
    operands[0] = xl6IrLowerNode(ctx, ctx->module->children[node->firstChild]);
    if ( operands[0] == XL6_IR_VALUE_INVALID ||
         xl6IrLowerValueType(ctx, operands[0]) != signatureType ) goto done;
    /* Invocation borrows its callable just like an ordinary borrowed
     * parameter. An indexed callable is an assignable lvalue yet its read
     * result is an owned projection (MOVE); value category alone cannot
     * determine lifetime. Use the shared, ownership-aware borrow contract. */
    operands[0] = xl6IrLowerAnchorResolvedCallBorrow(
        ctx, id, ctx->module->children[node->firstChild], callee, signatureType,
        XL6_IR_PARAMETER_ABI_BORROW, operands[0], &calleeTemporary);
    if ( operands[0] == XL6_IR_VALUE_INVALID ) goto done;
    if ( calleeTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, id, calleeTemporary, operands[0], 0, 0) ) goto done;
    for ( i = 0; i < fixedParameterCount; ++i ) {
        const XL6_IrCallArgument* binding =
            &ctx->module->callArguments[site->firstArgument + i];
        XL6_IrNodeId argumentId = binding->expression;
        const XL6_IrNode* expression;
        if ( binding->source != XL6_IR_CALL_ARGUMENT_EXPLICIT ||
             binding->parameter != i ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR closure call argument mode does not match its canonical signature");
            goto done;
        }
        expression = xl6IrNodeGet(ctx->module, argumentId);
        if ( expression == NULL ) {
            xl6IrLowerDiag(ctx, id, "XLIR closure call argument has no resolved expression");
            goto done;
        }
        if ( signature->parameterAbis[i] == XL6_IR_PARAMETER_ABI_INOUT ||
             signature->parameterAbis[i] == XL6_IR_PARAMETER_ABI_OUT ) {
            operands[i + 1] = xl6IrLowerEmitStorageAddress(
                ctx, id, argumentId, expression, signature->params[i]);
            if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) goto done;
            continue;
        }
        /* A first-class callable uses the same typed value boundary as a
         * resolved direct target. Compare the materialized SSA TypeId, not
         * declared source storage: scalar conversion, nullable injection and
         * flow projection must be explicit instructions before CLOSURE_CALL.
         * INOUT/OUT above still require the exact source storage address. */
        operands[i + 1] = xl6IrLowerNodeAsType(
            ctx, id, argumentId, expression, signature->params[i]);
        if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) goto done;
        if ( xl6IrLowerValueType(ctx, operands[i + 1]) != signature->params[i] &&
             xl6IrLowerCallableTypesCompatible(
                 ctx->module, xl6IrLowerValueType(ctx, operands[i + 1]), signature->params[i]) )
            operands[i + 1] = xl6IrLowerEmitValueCopy(
                ctx, argumentId, signature->params[i], operands[i + 1]);
        if ( operands[i + 1] == XL6_IR_VALUE_INVALID ||
             xl6IrLowerValueType(ctx, operands[i + 1]) != signature->params[i] ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR closure call argument has no exact materialized parameter TypeId");
            goto done;
        }
        operands[i + 1] = xl6IrLowerPrepareOwnedCallArgument(
            ctx, id, signature->params[i], signature->parameterAbis[i],
            expression, operands[i + 1]);
        if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) goto done;
        operands[i + 1] = xl6IrLowerAnchorResolvedCallBorrow(
            ctx, id, argumentId, expression, signature->params[i],
            signature->parameterAbis[i], operands[i + 1], &borrowedTemps[i]);
        if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) goto done;
        if ( signature->parameterAbis[i] == XL6_IR_PARAMETER_ABI_OWNED ) {
            operands[i + 1] = xl6IrLowerProtectEvaluationValue(
                ctx, argumentId, signature->params[i], operands[i + 1]);
            if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) goto done;
        } else if ( borrowedTemps[i] != 0 && !xl6IrLowerProtectEvaluationStorage(
                        ctx, argumentId, borrowedTemps[i], operands[i + 1], 0, 0) )
            goto done;
    }
    if ( variadicAbi == XL6_IR_CALL_VARIADIC_ARRAY ||
         variadicAbi == XL6_IR_CALL_VARIADIC_DICT ) {
        size_t parameter = fixedParameterCount;
        if (!xl6IrLowerPrepareCallSiteAggregate(ctx, id, site,
                signature->params[parameter], signature->parameterAbis[parameter],
                &operands[parameter + 1], &borrowedTemps[parameter])) goto done;
        for (i = fixedParameterCount; i < site->argumentCount; ++i)
            if (!xl6IrLowerCallSiteAggregateAppend(ctx, id, site,
                    &ctx->module->callArguments[site->firstArgument + i],
                    operands[parameter + 1])) goto done;
    }
    if ( !xl6IrLowerCommitEvaluationOwners(ctx, id, evaluationOwnerFirst) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLOSURE_CALL, id, node->storageType, 0,
                         operands, signature->paramCount + 1, &result) ) {
        result = XL6_IR_VALUE_INVALID;
        goto done;
    }
    ctx->module->instructions[ctx->module->instructionCount - 1].calleeType = signatureType;
    {
        XL6_IrLowerCallCleanup cleanup = {
            borrowedTemps, signature->paramCount, NULL, calleeTemporary, 0};
        if (!xl6IrLowerCompleteCall(ctx, id, node, NULL, &result, errorPlan, &cleanup)) {
            result = XL6_IR_VALUE_INVALID;
            goto done;
        }
    }
    if ( signature->callableResultType == XL6_IR_TYPE_INVALID )
        result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    xrtFree(operands);
    xrtFree(borrowedTemps);
    return result;
}

/* `base(...)` is a direct call on the current create receiver.  Typed XLIR has
 * already selected the exact base create overload and bound all arguments;
 * lowering only makes the inherited receiver upcast and borrow explicit. */
static XL6_IrValueId xl6IrLowerBaseConstructorCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node)
{
    const XL6_IrFunction* function;
    const XL6_IrNode* functionDeclaration;
    const XL6_IrCallTarget* target;
    const XL6_IrCallSite* callSite;
    const XL6_IrStorage* receiverStorage;
    XL6_SymbolId receiverSymbol;
    XL6_IrValueId* operands = NULL;
    XL6_SymbolId* borrowedTemps = NULL;
    size_t i, first = ctx->evaluationOwnerCount;
    XL6_IrValueId outcome = XL6_IR_VALUE_INVALID;
    int emitted = 0;
    if ( ctx == NULL || node == NULL ||
         node->callKind != XL6_SEM_CALL_BASE_CONSTRUCTOR ||
         node->childCount != 2 || node->targetSymbol == 0 ||
         ctx->functionIndex >= ctx->module->functionCount ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR base constructor call has no active create receiver ABI");
        return XL6_IR_VALUE_INVALID;
    }
    function = &ctx->module->functions[ctx->functionIndex];
    functionDeclaration = xl6IrNodeGet(ctx->module, function->declaration);
    target = xl6IrCallTargetGet(ctx->module, node->targetSymbol);
    callSite = xl6IrCallSiteGet(ctx->module, id);
    receiverSymbol = function->parameterCount != 0
        ? ctx->module->functionParameters[function->firstParameter] : 0;
    receiverStorage = xl6IrStorageGet(ctx->module, receiverSymbol);
    if ( function->kind != XL6_IR_FUNCTION_USER ||
         functionDeclaration == NULL ||
         functionDeclaration->sourceKind != XL6_AST_CREATE ||
         target == NULL || target->kind != XL6_IR_CALL_TARGET_INTERNAL ||
         target->returnType != XL6_IR_TYPE_INVALID ||
         (target->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE &&
          target->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE) ||
         target->variadicAbi != XL6_IR_CALL_VARIADIC_NONE ||
         target->parameterCount == 0 || target->parameterTypes == NULL ||
         target->parameterAbis == NULL ||
         target->parameterAbis[0] != XL6_IR_PARAMETER_ABI_BORROW ||
         receiverStorage == NULL ||
         receiverStorage->kind != XL6_IR_STORAGE_PARAMETER ||
         !xl6IrLowerClassValueAssignableTo(
             ctx, target->parameterTypes[0], receiverStorage->type) ||
         callSite == NULL ||
         callSite->callKind != XL6_SEM_CALL_BASE_CONSTRUCTOR ||
         callSite->targetSymbol != target->symbol ||
         callSite->receiver != XL6_IR_NODE_INVALID ||
         callSite->resultType != XL6_IR_TYPE_INVALID ||
         callSite->variadicAbi != XL6_IR_CALL_VARIADIC_NONE ||
         callSite->fixedParameterCount != callSite->argumentCount ||
         target->parameterCount != callSite->argumentCount + 1 ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR base constructor call has no exact inherited receiver and CallSite ABI");
        return XL6_IR_VALUE_INVALID;
    }
    operands = (XL6_IrValueId*)xrtCalloc(
        target->parameterCount, sizeof(*operands));
    borrowedTemps = (XL6_SymbolId*)xrtCalloc(
        target->parameterCount, sizeof(*borrowedTemps));
    if ( operands == NULL || borrowedTemps == NULL ) {
        xrtFree(operands); xrtFree(borrowedTemps); ctx->failed = 1;
        return XL6_IR_VALUE_INVALID;
    }
    if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id,
                          receiverStorage->type, receiverSymbol,
                          NULL, 0, &operands[0]) ) goto done_base;
    if ( receiverStorage->type != target->parameterTypes[0] )
        operands[0] = xl6IrLowerEmitValueCopy(
            ctx, id, target->parameterTypes[0], operands[0]);
    if ( operands[0] != XL6_IR_VALUE_INVALID )
        operands[0] = xl6IrLowerEmitRuntimeCall(
            ctx, id, target->parameterTypes[0],
            XL6_IR_RUNTIME_XVALUE_RETAIN, &operands[0], 1);
    borrowedTemps[0] = operands[0] != XL6_IR_VALUE_INVALID
        ? xl6IrLowerNewTempStorage(ctx, target->parameterTypes[0], id) : 0;
    if ( borrowedTemps[0] == 0 ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id,
                          target->parameterTypes[0], borrowedTemps[0],
                          &operands[0], 1, NULL) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id,
                          target->parameterTypes[0], borrowedTemps[0],
                          NULL, 0, &operands[0]) ) goto done_base;
    if (!xl6IrLowerProtectEvaluationStorage(ctx, id, borrowedTemps[0], operands[0], 0, 0))
        goto done_base;
    for ( i = 0; i < callSite->argumentCount; ++i ) {
        const XL6_IrCallArgument* binding =
            xl6IrCallSiteEvaluationArgument(ctx->module, callSite, i);
        const XL6_IrNode* expression =
            xl6IrNodeGet(ctx->module, binding->expression);
        size_t parameter = binding->parameter + 1;
        if ( parameter >= target->parameterCount ||
             (binding->source != XL6_IR_CALL_ARGUMENT_EXPLICIT &&
              binding->source != XL6_IR_CALL_ARGUMENT_DEFAULT) ||
             expression == NULL ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR base constructor argument has no fixed parameter binding ABI");
            goto done_base;
        }
        operands[parameter] = xl6IrLowerCallArgumentAsType(
            ctx, id, binding, target->parameterTypes[parameter]);
        operands[parameter] = xl6IrLowerPrepareOwnedCallArgument(
            ctx, id, target->parameterTypes[parameter],
            target->parameterAbis[parameter], expression,
            operands[parameter]);
        operands[parameter] = xl6IrLowerAnchorResolvedCallBorrow(
            ctx, id, binding->expression, expression,
            target->parameterTypes[parameter],
            target->parameterAbis[parameter], operands[parameter],
            &borrowedTemps[parameter]);
        if ( operands[parameter] == XL6_IR_VALUE_INVALID ) goto done_base;
        operands[parameter] = xl6IrLowerProtectCallEvaluationOperand(ctx, binding->expression,
            target->parameterTypes[parameter], target->parameterAbis[parameter],
            operands[parameter], borrowedTemps[parameter]);
        if (operands[parameter] == XL6_IR_VALUE_INVALID) goto done_base;
    }
    emitted = xl6IrLowerCommitEvaluationOwners(ctx, id, first) && xl6IrLowerEmit(
        ctx, XL6_IR_INSTR_CALL, id, XL6_IR_TYPE_INVALID,
        target->symbol, operands, target->parameterCount,
        target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE ? &outcome : NULL);
    if (emitted) {
        XL6_IrLowerCallCleanup cleanup = {borrowedTemps, target->parameterCount, NULL, 0, 0};
        emitted = xl6IrLowerOrderCallCleanup(ctx, callSite, 1, borrowedTemps, NULL, target->parameterCount) &&
            xl6IrLowerCompleteCall(ctx, id, node, target, &outcome, NULL, &cleanup);
    }
done_base:
    xrtFree(operands);
    xrtFree(borrowedTemps);
    if ( !emitted && !ctx->failed )
        xl6IrLowerDiag(ctx, id,
            "XLIR base constructor call could not materialize its explicit CALL ABI");
    return XL6_IR_VALUE_INVALID;
}

/* A resolved class construction is a two-step XLIR value: allocate the owned
 * object handle, then invoke the resolved create body with that handle as its
 * explicit borrowed receiver.  The function body and the call instruction
 * therefore use ordinary verified ABI machinery; Cgen has no constructor or
 * member-layout special case to reconstruct. */
static XL6_IrValueId xl6IrLowerConstructorCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node)
{
    const XL6_IrCallTarget* target;
    const XL6_IrCallSite* callSite;
    const XL6_IrClassLayout* layout;
    const XL6_IrExitPlan* errorPlan = NULL;
    XL6_IrValueId object;
    XL6_IrValueId callResult = XL6_IR_VALUE_INVALID;
    XL6_IrValueId* operands = NULL;
    XL6_SymbolId* borrowedTemps = NULL;
    XL6_SymbolId objectTemporary = 0;
    size_t i, evaluationFirst = ctx->evaluationOwnerCount;
    if ( node == NULL || node->callKind != XL6_SEM_CALL_CONSTRUCTOR ||
         node->childCount != 2 ||
         !xl6IrLowerTypeIsRuntimeXValue(ctx->module, node->storageType) ) {
        xl6IrLowerDiag(ctx, id, "XLIR constructor call has no resolved class object ABI");
        return XL6_IR_VALUE_INVALID;
    }
    target = xl6IrCallTargetGet(ctx->module, node->targetSymbol);
    if ( target == NULL ) return xl6IrLowerDefaultClassConstructorCall(ctx, id, node);
    callSite = xl6IrCallSiteGet(ctx->module, id);
    layout = xl6IrLowerClassLayoutGet(ctx->module, node->storageType);
    if ( target == NULL || target->kind != XL6_IR_CALL_TARGET_INTERNAL ||
         target->returnType != XL6_IR_TYPE_INVALID ||
         (target->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE &&
          target->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE) ||
         target->parameterCount == 0 || target->parameterTypes == NULL ||
         target->parameterAbis == NULL || target->parameterAbis[0] != XL6_IR_PARAMETER_ABI_BORROW ||
         target->parameterTypes[0] != node->storageType || layout == NULL || callSite == NULL ||
         callSite->callKind != XL6_SEM_CALL_CONSTRUCTOR ||
         callSite->targetSymbol != node->targetSymbol || callSite->resultType != node->storageType ||
         callSite->receiver != XL6_IR_NODE_INVALID ||
         callSite->variadicAbi != XL6_IR_CALL_VARIADIC_NONE ||
         callSite->fixedParameterCount != callSite->argumentCount ||
         target->parameterCount != callSite->argumentCount + 1 ) {
        xl6IrLowerDiag(ctx, id, "XLIR constructor call has no complete create receiver ABI");
        return XL6_IR_VALUE_INVALID;
    }
    if ( target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE &&
         (errorPlan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW)) == NULL ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR may-raise constructor has no result-carrier or propagation cleanup ABI");
        return XL6_IR_VALUE_INVALID;
    }
    object = xl6IrLowerBeginClassConstruction(ctx, id, node->storageType, &objectTemporary);
    if ( object == XL6_IR_VALUE_INVALID ||
         !xl6IrLowerClassInitializeRuntimeTag(ctx, id, layout, object) ) return XL6_IR_VALUE_INVALID;
    /* Class construction order is a verified IR fact: runtime tag, inherited
     * fields, this class's declaration initializers, then the explicit create
     * body.  The body may replace an initialized field but never determines
     * whether its storage exists. */
    if ( layout->baseType != XL6_IR_TYPE_INVALID ) {
        const XL6_IrClassLayout* base = xl6IrLowerClassLayoutGet(ctx->module, layout->baseType);
        if ( base == NULL ||
              !xl6IrLowerDefaultClassInitialize(ctx, id, base, &object, 0) ) {
            xl6IrLowerDiag(ctx, id, "XLIR explicit class constructor has no verified default-base initialization ABI");
            return XL6_IR_VALUE_INVALID;
        }
    } else if ( layout->baseDeclaration != XL6_IR_NODE_INVALID &&
                !xl6IrLowerClassInitializeInheritedDefaults(ctx, id, layout, &object) ) {
        xl6IrLowerDiag(ctx, id,
                        "XLIR explicit class constructor has no verified inherited default-field ABI");
        return XL6_IR_VALUE_INVALID;
    }
    if ( !xl6IrLowerExplicitClassInitializeOwnFields(ctx, id, layout, &object) ) {
        xl6IrLowerDiag(ctx, id,
                        "XLIR explicit class constructor has no verified own-field initializer ABI");
        return XL6_IR_VALUE_INVALID;
    }
    operands = (XL6_IrValueId*)xrtCalloc(target->parameterCount, sizeof(*operands));
    borrowedTemps = (XL6_SymbolId*)xrtCalloc(target->parameterCount, sizeof(*borrowedTemps));
    if ( operands == NULL || borrowedTemps == NULL ) {
        xrtFree(operands); xrtFree(borrowedTemps); ctx->failed = 1;
        return XL6_IR_VALUE_INVALID;
    }
    /* The pending construction storage is the receiver's explicit protection.
     * A second retain/temporary is neither a new semantic owner nor necessary
     * for the call. Argument evaluation rolls back this same pending owner. */
    operands[0] = object;
    for ( i = 0; i < callSite->argumentCount; ++i ) {
        const XL6_IrCallArgument* binding =
            xl6IrCallSiteEvaluationArgument(ctx->module, callSite, i);
        XL6_IrNodeId argumentId = binding->expression;
        const XL6_IrNode* expression;
        size_t parameter = binding->parameter + 1;
        if ( binding->source != XL6_IR_CALL_ARGUMENT_EXPLICIT &&
             binding->source != XL6_IR_CALL_ARGUMENT_DEFAULT ) {
            xrtFree(operands); xrtFree(borrowedTemps);
            xl6IrLowerDiag(ctx, id, "XLIR constructor CallSite has no fixed argument ABI");
            return XL6_IR_VALUE_INVALID;
        }
        expression = xl6IrNodeGet(ctx->module, argumentId);
        operands[parameter] = xl6IrLowerCallArgumentAsType(
            ctx, id, binding, target->parameterTypes[parameter]);
        operands[parameter] = xl6IrLowerPrepareOwnedCallArgument(
            ctx, id, target->parameterTypes[parameter],
            target->parameterAbis[parameter], expression,
            operands[parameter]);
        if ( operands[parameter] == XL6_IR_VALUE_INVALID ) {
            xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
        }
        /* Constructor arguments obey the same BORROW lifetime contract as
         * every other resolved call.  A named managed string is already
         * borrowed from stable storage and must never be placed into an
         * owning temporary that the caller releases after create returns. */
        operands[parameter] = xl6IrLowerAnchorResolvedCallBorrow(
            ctx, id, argumentId, expression,
            target->parameterTypes[parameter],
            target->parameterAbis[parameter], operands[parameter],
            &borrowedTemps[parameter]);
        if ( operands[parameter] == XL6_IR_VALUE_INVALID ) {
            xrtFree(operands); xrtFree(borrowedTemps);
            return XL6_IR_VALUE_INVALID;
        }
        operands[parameter] = xl6IrLowerProtectCallEvaluationOperand(ctx, argumentId,
            target->parameterTypes[parameter], target->parameterAbis[parameter],
            operands[parameter], borrowedTemps[parameter]);
        if (operands[parameter] == XL6_IR_VALUE_INVALID) {
            xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
        }
    }
    if ( !xl6IrLowerCommitEvaluationOwners(ctx, id, evaluationFirst) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CALL, id, XL6_IR_TYPE_INVALID,
                         callSite->targetSymbol, operands, target->parameterCount,
                         target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE
                             ? &callResult : NULL) ) {
        xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
    }
    {
        XL6_IrLowerCallCleanup cleanup = {
            borrowedTemps, target->parameterCount, NULL, 0, objectTemporary};
        if (!xl6IrLowerOrderCallCleanup(ctx, callSite, 1, borrowedTemps, NULL, target->parameterCount) ||
            !xl6IrLowerCompleteCall(ctx, id, node, target, &callResult, errorPlan, &cleanup)) {
            xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
        }
    }
    {
        XL6_IrValueId transferredObject;
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id, node->storageType,
                              objectTemporary, NULL, 0, &transferredObject) ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_MOVE, id, node->storageType,
                              objectTemporary, &transferredObject, 1, NULL) ) {
            xrtFree(operands); xrtFree(borrowedTemps);
            return XL6_IR_VALUE_INVALID;
        }
        object = transferredObject;
    }
    object = xl6IrLowerCommitClassLifetime(ctx, id, layout, object);
    if ( object == XL6_IR_VALUE_INVALID ) {
        xrtFree(operands); xrtFree(borrowedTemps);
        return XL6_IR_VALUE_INVALID;
    }
    xrtFree(operands);
    xrtFree(borrowedTemps);
    return object;
}

static const XL6_IrExitPlan* xl6IrLowerValueInitializerErrorPlan(
    const XL6_IrLowerContext* ctx, XL6_IrNodeId declaration,
    const XL6_IrValueInitializer* initializer)
{
    size_t i;
    if ( ctx == NULL || ctx->module == NULL || initializer == NULL ||
         initializer->declaration != declaration ||
         initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ) return NULL;
    for ( i = 0; i < ctx->module->exitPlanCount; ++i ) {
        const XL6_IrExitPlan* plan = &ctx->module->exitPlans[i];
        if ( plan->origin == declaration &&
             plan->kind == XL6_SEM_EXIT_THROW &&
             plan->point == XL6_IR_EXIT_POINT_BEFORE_NODE )
            return plan;
    }
    return NULL;
}

static XL6_IrValueId xl6IrLowerValueInitializer(
    XL6_IrLowerContext* ctx,
    XL6_IrNodeId declarationId,
    const XL6_IrValueInitializer* initializer)
{
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    const XL6_IrType* type;
    XL6_IrInstruction* instruction;
    const char* immediate;
    if ( ctx == NULL || initializer == NULL ||
         initializer->declaration != declarationId ) return XL6_IR_VALUE_INVALID;
    type = xl6IrTypeGet(&ctx->module->types, initializer->type);
    if ( type == NULL ) return XL6_IR_VALUE_INVALID;
    if ( initializer->abi == XL6_IR_INITIALIZER_EXPLICIT ) {
        const XL6_IrNode* expression =
            xl6IrNodeGet(ctx->module, initializer->expression);
        if (initializer->runtimeOp == XL6_IR_RUNTIME_XVALUE_CLOSURE_CAST_CHECKED) {
            if (initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE || expression == NULL ||
                xl6IrLowerValueInitializerErrorPlan(ctx, declarationId, initializer) == NULL)
                return XL6_IR_VALUE_INVALID;
            return xl6IrLowerNodeAsType(ctx, declarationId, initializer->expression, expression, initializer->type);
        }
        if ( initializer->runtimeOp ==
                 XL6_IR_RUNTIME_INTEGER_CONVERT_CHECKED ) {
            if ( initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
                 initializer->scalarConversionAbi !=
                     XL6_IR_SCALAR_CONVERSION_INVALID ||
                 expression == NULL ||
                 !xl6IrContextualCheckedIntegerConversionAllowed(
                     ctx->module, declarationId,
                     initializer->expression, initializer->type) ||
                 xl6IrLowerValueInitializerErrorPlan(
                     ctx, declarationId, initializer) == NULL )
                return XL6_IR_VALUE_INVALID;
            return xl6IrLowerNodeAsType(
                ctx, declarationId, initializer->expression,
                expression, initializer->type);
        }
        if ( initializer->runtimeOp ==
                 XL6_IR_RUNTIME_XVALUE_CALLABLE_FROM_CLOSURE ) {
            const XL6_IrNode* declaration =
                xl6IrNodeGet(ctx->module, declarationId);
            const XL6_IrExitPlan* errorPlan =
                xl6IrLowerValueInitializerErrorPlan(
                    ctx, declarationId, initializer);
            const XL6_IrType* signature = expression != NULL
                ? xl6IrTypeGet(
                    &ctx->module->types, expression->storageType)
                : NULL;
            XL6_IrValueId closure;
            size_t first = ctx->evaluationOwnerCount;
            if ( expression == NULL || declaration == NULL ||
                 errorPlan == NULL ||
                 !xl6IrLowerTypeIsErasedCallable(
                     ctx->module, initializer->type) ||
                 signature == NULL ||
                 signature->callableErasureAbi !=
                     initializer->callableErasureAbi ||
                 !xl6IrLowerRuntimeCallableSignatureSupported(
                     ctx->module, expression->storageType) )
                return XL6_IR_VALUE_INVALID;
            closure = xl6IrLowerNode(ctx, initializer->expression);
            if ( closure == XL6_IR_VALUE_INVALID ||
                 xl6IrLowerValueType(ctx, closure) !=
                     expression->storageType )
                return XL6_IR_VALUE_INVALID;
            closure = xl6IrLowerProtectOwnedBorrow(ctx, declarationId, closure);
            if (closure == XL6_IR_VALUE_INVALID) return closure;
            result = xl6IrLowerEmitRuntimeCall(
                ctx, declarationId, initializer->type,
                XL6_IR_RUNTIME_XVALUE_CALLABLE_FROM_CLOSURE,
                &closure, 1);
            if ( result == XL6_IR_VALUE_INVALID )
                return XL6_IR_VALUE_INVALID;
            instruction = &ctx->module->instructions[
                ctx->module->instructionCount - 1];
            instruction->calleeType = expression->storageType;
            instruction->callableErasureAbi =
                initializer->callableErasureAbi;
            instruction->runtimeIdentityType = expression->storageType;
            return xl6IrLowerEmitRuntimeErrorEdgeWithPlan(
                ctx, declarationId, declaration, result, errorPlan) &&
                xl6IrLowerCompleteEvaluationBorrows(ctx, declarationId, first, &result)
                ? result : XL6_IR_VALUE_INVALID;
        }
        if ( initializer->runtimeOp ==
                 XL6_IR_RUNTIME_XVALUE_WEAK_CREATE ) {
            const XL6_IrNode* declaration =
                xl6IrNodeGet(ctx->module, declarationId);
            const XL6_IrExitPlan* errorPlan =
                xl6IrLowerValueInitializerErrorPlan(
                    ctx, declarationId, initializer);
            if ( declaration == NULL || expression == NULL ||
                 type == NULL || errorPlan == NULL ||
                 initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
                 initializer->scalarConversionAbi !=
                     XL6_IR_SCALAR_CONVERSION_INVALID ||
                 initializer->runtimeResourceOp !=
                     XL6_IR_RUNTIME_RESOURCE_OP_INVALID ||
                 initializer->callableErasureAbi !=
                     XL6_IR_CALLABLE_ERASURE_INVALID )
                return XL6_IR_VALUE_INVALID;
            return xl6IrLowerWeakCreate(
                ctx, declarationId, declaration,
                initializer->expression, expression,
                initializer->type, errorPlan);
        }
        if (initializer->runtimeOp==XL6_IR_RUNTIME_ARRAY_IMPORT_CHAIN) {
            if (!expression || initializer->errorAbi!=XL6_IR_ERROR_ABI_MAY_RAISE ||
                !xl6IrContextualArrayImportRequired(ctx->module,expression->storageType,initializer->type) ||
                !xl6IrLowerValueInitializerErrorPlan(ctx,declarationId,initializer)) return XL6_IR_VALUE_INVALID;
            return xl6IrLowerNodeAsRuntimeXValue(ctx,declarationId,initializer->expression,expression,initializer->type);
        }
        if (xl6IrRuntimeBoxingErrorPhysicalAbi(initializer->runtimeOp) != XL6_IR_CALL_ERROR_PHYSICAL_INVALID) {
            if (expression == NULL || initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
                initializer->runtimeOp != xl6IrAllocatingBoxOpForType(ctx->module, expression->storageType) ||
                type->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
                xl6IrLowerValueInitializerErrorPlan(ctx, declarationId, initializer) == NULL)
                return XL6_IR_VALUE_INVALID;
            return xl6IrLowerNodeAsRuntimeXValue(ctx, declarationId, initializer->expression, expression, initializer->type);
        }
        if ( initializer->runtimeOp != XL6_IR_RUNTIME_NONE ||
             initializer->runtimeResourceOp !=
                 XL6_IR_RUNTIME_RESOURCE_OP_INVALID ||
             initializer->callableErasureAbi !=
                 XL6_IR_CALLABLE_ERASURE_INVALID ||
             initializer->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE )
            return XL6_IR_VALUE_INVALID;
        if ( initializer->scalarConversionAbi !=
             XL6_IR_SCALAR_CONVERSION_INVALID ) {
            XL6_IrValueId source = xl6IrLowerNode(ctx, initializer->expression);
            return source != XL6_IR_VALUE_INVALID && expression != NULL
                ? xl6IrLowerEmitVerifiedScalarConvert(
                    ctx, declarationId, expression->storageType,
                    initializer->type, source,
                    initializer->scalarConversionAbi)
                : XL6_IR_VALUE_INVALID;
        }
        return xl6IrLowerNodeAsType(
            ctx, declarationId, initializer->expression, expression, initializer->type);
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_NULL_SENTINEL ||
         initializer->abi == XL6_IR_INITIALIZER_TAGGED_NULL ) {
        return xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, declarationId,
                              initializer->type, 0, NULL, 0, &result)
            ? result : XL6_IR_VALUE_INVALID;
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_SCALAR_ZERO ) {
        immediate = type->cAbi == XL6_IR_C_ABI_TYPE_ID
                    ? "0x0000000000000000ULL"
                    : type->cAbi == XL6_IR_C_ABI_F64 ||
                    type->cAbi == XL6_IR_C_ABI_C_FLOAT ||
                    type->cAbi == XL6_IR_C_ABI_C_DOUBLE ? "0.0" : "0";
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, declarationId,
                             initializer->type, 0, NULL, 0, &result) )
            return XL6_IR_VALUE_INVALID;
        instruction = &ctx->module->instructions[ctx->module->instructionCount - 1];
        instruction->immediateText = type->cAbi == XL6_IR_C_ABI_I64
            ? xl6IrLowerCanonicalIntegerLiteral(immediate)
            : type->cAbi == XL6_IR_C_ABI_U64
                ? xl6IrLowerCanonicalUnsignedIntegerLiteral(immediate)
            : type->cAbi == XL6_IR_C_ABI_TYPE_ID
                ? xrtStrDupN(immediate, strlen(immediate))
            : type->cAbi == XL6_IR_C_ABI_F64
                ? xl6IrLowerCanonicalFloatLiteral(immediate)
                : xrtStrDupN(immediate, strlen(immediate));
        return instruction->immediateText != NULL ? result : XL6_IR_VALUE_INVALID;
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_UNION_ZERO ) {
        if ( type->kind != XL6_IR_TYPE_UNION ||
             type->cAbi != XL6_IR_C_ABI_UNION ||
             type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL ||
             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_UNION_ZERO, declarationId,
                              initializer->type, 0, NULL, 0, &result) )
            return XL6_IR_VALUE_INVALID;
        return result;
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_STRING_EMPTY ) {
        return xl6IrLowerEmitRuntimeLiteralCall(ctx, declarationId, initializer->type,
            XL6_IR_RUNTIME_STRING_DUP, "\"\"", NULL, 0);
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_XVALUE_NULL ||
         initializer->abi == XL6_IR_INITIALIZER_CLASS_NULL ) {
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RUNTIME_CALL, declarationId,
                             initializer->type, 0, NULL, 0, &result) )
            return XL6_IR_VALUE_INVALID;
        instruction = &ctx->module->instructions[ctx->module->instructionCount - 1];
        instruction->runtimeOp = XL6_IR_RUNTIME_XVALUE_NULL;
        instruction->immediateText = xrtStrDupN("null", 4);
        return instruction->immediateText != NULL ? result : XL6_IR_VALUE_INVALID;
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_XVALUE_CONTAINER_EMPTY ) {
        if ( type->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
             (initializer->runtimeOp != XL6_IR_RUNTIME_XVALUE_ARRAY_NEW &&
              initializer->runtimeOp != XL6_IR_RUNTIME_ARRAY_CREATE &&
              initializer->runtimeOp != XL6_IR_RUNTIME_XVALUE_INT_MAP_NEW &&
              initializer->runtimeOp != XL6_IR_RUNTIME_XVALUE_OBJECT_NEW &&
              initializer->runtimeOp != XL6_IR_RUNTIME_XVALUE_SET_NEW) )
            return XL6_IR_VALUE_INVALID;
        result = xl6IrLowerEmitRuntimeCall(
            ctx, declarationId, initializer->type, initializer->runtimeOp, NULL, 0);
        return result == XL6_IR_VALUE_INVALID
            ? result
            : xl6IrLowerMaybeBindRuntimeTypeIdentity(
                ctx, declarationId, initializer->type, initializer->type, result);
    }
    if ( initializer->abi ==
             XL6_IR_INITIALIZER_RUNTIME_RESOURCE_DEFAULT ) {
        const XL6_IrNode* declaration =
            xl6IrNodeGet(ctx->module, declarationId);
        const XL6_IrExitPlan* errorPlan =
            xl6IrLowerValueInitializerErrorPlan(
                ctx, declarationId, initializer);
        XL6_IrRuntimeOp runtimeOp = xl6IrLowerRuntimeResourceOp(
            initializer->runtimeResourceOp);
        if ( declaration == NULL || errorPlan == NULL ||
             runtimeOp == XL6_IR_RUNTIME_NONE ||
             !xl6IrLowerRuntimeResourceOpCreates(
                 initializer->runtimeResourceOp) ||
             type->runtimeResourceAbi !=
                 xl6IrLowerRuntimeResourceAbiForOp(
                     initializer->runtimeResourceOp) ||
             initializer->runtimeOp != XL6_IR_RUNTIME_NONE ||
             initializer->scalarConversionAbi !=
                 XL6_IR_SCALAR_CONVERSION_INVALID ||
              initializer->callableErasureAbi !=
                  XL6_IR_CALLABLE_ERASURE_INVALID ||
              initializer->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
              !xl6IrLowerRuntimeResourceMetadataMatches(
                  ctx->module, initializer->runtimeResourceOp,
                  initializer->type, initializer->payloadType,
                  initializer->runtimeResourcePayloadAbi,
                  initializer->runtimeResourceKeyType,
                  initializer->runtimeResourceKeyPayloadAbi,
                  initializer->runtimeResourceKeyOrderAbi) )
            return XL6_IR_VALUE_INVALID;
        result = xl6IrLowerEmitRuntimeCall(
            ctx, declarationId, initializer->type, runtimeOp, NULL, 0);
        if ( result == XL6_IR_VALUE_INVALID ) return result;
        instruction = &ctx->module->instructions[
            ctx->module->instructionCount - 1];
        instruction->payloadType = initializer->payloadType;
        instruction->runtimeResourcePayloadAbi =
            initializer->runtimeResourcePayloadAbi;
        instruction->runtimeResourceKeyType =
            initializer->runtimeResourceKeyType;
        instruction->runtimeResourceKeyPayloadAbi =
            initializer->runtimeResourceKeyPayloadAbi;
        instruction->runtimeResourceKeyOrderAbi =
            initializer->runtimeResourceKeyOrderAbi;
        return xl6IrLowerEmitRuntimeErrorEdgeWithPlan(
            ctx, declarationId, declaration, result, errorPlan)
            ? result : XL6_IR_VALUE_INVALID;
    }
    if ( initializer->abi == XL6_IR_INITIALIZER_CLASS_DEFAULT )
        return xl6IrLowerDefaultClassConstruct(
            ctx, declarationId, initializer->type);
    return XL6_IR_VALUE_INVALID;
}

/* Conditional index writes keep one address scope across the null branch.
 * The read is only observed by NULL_TEST; the RHS is acquired on the null edge
 * and consumed by the shared commit. The merge releases address anchors on
 * either successful path; failure edges unwind that same scope automatically. */
static int xl6IrLowerElementAssignIfNull(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node,
    const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    const XL6_IrType* itemType;
    XL6_IrLowerElementTargetPlan plan;
    int itemIsNonNull;
    int addressMayBeAbsent;
    XL6_IrTypeId boolType;
    XL6_IrValueId current, isNull, replacement, updated;
    XL6_IrBlockId assignBlock, mergeBlock;
    XL6_IrInstruction* branch;
    if (ctx == NULL || node == NULL || lhs == NULL || rhs == NULL ||
        node->text == NULL || strcmp(node->text, "?=") != 0 ||
        !((node->lvalueKind == XL6_SEM_LVALUE_INDEX && lhs->kind == XL6_IR_NODE_INDEX) ||
          ((node->lvalueKind == XL6_SEM_LVALUE_FIELD || node->lvalueKind == XL6_SEM_LVALUE_DYNAMIC_MEMBER) &&
           lhs->kind == XL6_IR_NODE_MEMBER))) return 0;
    itemType = xl6IrTypeGet(&ctx->module->types, lhs->storageType);
    itemIsNonNull = itemType != NULL && itemType->nullAbi == XL6_IR_NULL_ABI_NONE;
    addressMayBeAbsent = lhs->kind == XL6_IR_NODE_INDEX &&
        (lhs->indexWriteAbi == XL6_IR_INDEX_WRITE_XVALUE_OBJECT_LITERAL_SET_NEW ||
         lhs->indexWriteAbi == XL6_IR_INDEX_WRITE_XVALUE_OBJECT_STRING_SET_NEW);
    if (itemType == NULL || !xl6IrLowerPrepareElementTargetPlan(ctx, id, lhs, &plan))
        return -1;
    /* A non-null array/list element cannot select the assignment branch, but
     * a typed dictionary can still have no value for a key. Its raw carrier
     * read represents that absence independently of the declared item type. */
    if (itemIsNonNull && !addressMayBeAbsent)
        return xl6IrLowerReleaseElementTargetPlan(ctx, id, &plan) ? 1 : -1;
    boolType = xl6IrLowerFindTypeByCAbi(ctx->module, XL6_IR_C_ABI_BOOL);
    current = plan.memberAddress
        ? xl6IrLowerReadElementTargetPlan(ctx, ctx->module->children[node->firstChild], &plan, NULL)
        : xl6IrLowerBorrowElementTargetPlan(ctx, id, &plan);
    if (xl6IrLowerValueHasOwner(ctx, current))
        current = xl6IrLowerProtectOwnedBorrow(ctx, id, current);
    if (boolType == XL6_IR_TYPE_INVALID || current == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, id, boolType, 0, &current, 1, &isNull) ||
        !xl6IrLowerNewBlock(ctx, &assignBlock) ||
        !xl6IrLowerNewBlock(ctx, &mergeBlock) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, id, XL6_IR_TYPE_INVALID, 0, &isNull, 1, NULL))
        goto failure;
    branch = &ctx->module->instructions[ctx->module->instructionCount - 1];
    branch->trueTarget = assignBlock;
    branch->falseTarget = mergeBlock;

    xl6IrLowerEnterBlock(ctx, assignBlock);
    replacement = xl6IrLowerNodeAsType(ctx, id, rhsId, rhs, lhs->storageType);
    if (replacement == XL6_IR_VALUE_INVALID) goto failure;
    updated = xl6IrLowerEmitElementTargetWrite(
        ctx, id, &plan, replacement, rhs);
    if (updated == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerCompleteElementWrite(ctx, id, &plan, updated) ||
        !xl6IrLowerEmitJump(ctx, id, mergeBlock)) goto failure;

    xl6IrLowerEnterBlock(ctx, mergeBlock);
    return xl6IrLowerReleaseElementTargetPlan(ctx, id, &plan) ? 1 : -1;
failure:
    xl6IrLowerDisposeElementTargetPlan(&plan);
    return -1;
}

/* Freeze a named/cell/static destination before any RHS evaluation. This
 * transient lowering plan emits ordinary verified storage instructions; no
 * address spelling or source ownership inference escapes into Cgen. */
typedef struct XL6_IrLowerStorageTargetPlan {
    XL6_SymbolId symbol;
    XL6_IrTypeId type;
    XL6_IrNullAbi nullAbi;
    XL6_IrCAbi cAbi;
    int managed;
    int cell;
} XL6_IrLowerStorageTargetPlan;

static int xl6IrLowerPrepareStorageTargetPlan(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* lhs,
    XL6_IrLowerStorageTargetPlan* plan)
{
    const XL6_IrClassStaticField* field;
    const XL6_IrStorage* storage;
    const XL6_IrType* type;
    XL6_SymbolId symbol;
    if (ctx == NULL || lhs == NULL || plan == NULL) return -1;
    field = xl6IrLowerClassStaticFieldFromMember(ctx->module, lhs);
    if (field == NULL && lhs->kind != XL6_IR_NODE_NAME) return 0;
    symbol = field != NULL ? field->storageSymbol : lhs->targetSymbol == 0 ? 0
        : xl6IrLowerClosureCaptureStorage(ctx, lhs->targetSymbol);
    if (symbol == 0) symbol = xl6IrLowerPromotedParameterStorage(ctx, lhs->targetSymbol);
    if (symbol == 0) symbol = lhs->targetSymbol;
    storage = xl6IrStorageGet(ctx->module, symbol);
    type = storage != NULL ? xl6IrTypeGet(&ctx->module->types, storage->type) : NULL;
    /* Flow refinement changes an observed value, never the owning slot's
     * declared type. Publication still targets its exact nullable carrier. */
    int refined = type != NULL && type->kind == XL6_IR_TYPE_NULLABLE &&
        type->paramCount == 1 && type->params != NULL && type->params[0] == lhs->storageType;
    if (symbol == 0 || storage == NULL || type == NULL ||
        (storage->type != lhs->storageType && !refined) ||
        (field != NULL && (storage->kind != XL6_IR_STORAGE_GLOBAL ||
                          field->type != storage->type ||
                          storage->cellType != XL6_IR_TYPE_INVALID)) ||
        (type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
         (type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
          !xl6IrLowerTypeHasStorageReleaseAbi(ctx->module, storage->type)))) {
        xl6IrLowerDiag(ctx, origin, "XLIR storage target requires an exact type and ownership ABI");
        return -1;
    }
    plan->symbol = symbol;
    plan->type = storage->type;
    plan->nullAbi = type->nullAbi;
    plan->cAbi = type->cAbi;
    plan->managed = type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED;
    plan->cell = storage->cellType != XL6_IR_TYPE_INVALID;
    return 1;
}

static XL6_IrValueId xl6IrLowerReadStorageTargetPlan(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrLowerStorageTargetPlan* plan)
{
    XL6_IrValueId value = XL6_IR_VALUE_INVALID;
    return xl6IrLowerEmit(ctx, plan->cell ? XL6_IR_INSTR_CELL_LOAD : XL6_IR_INSTR_LOAD,
        origin, plan->type, plan->symbol, NULL, 0, &value) ? value : XL6_IR_VALUE_INVALID;
}

/* Replacement is a publication followed by independently fallible cleanup.
 * The old payload is an explicit SSA owner, never a destructor hidden inside
 * a STORE. Reentry from that destructor sees the new destination and may
 * replace it again; no stale outer write is performed after the callback. */
static int xl6IrLowerReplaceStorageValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_SymbolId symbol,
    XL6_IrTypeId typeId, XL6_IrValueId value)
{
    const XL6_IrStorage* storage = xl6IrStorageGet(ctx->module, symbol);
    const XL6_IrType* type = xl6IrTypeGet(&ctx->module->types, typeId);
    int cell = storage != NULL && storage->cellType != XL6_IR_TYPE_INVALID;
    XL6_IrValueId previous;
    XL6_SymbolId previousOwner;
    XL6_IrLowerCallCleanup cleanup = {0};
    if (storage == NULL || storage->type != typeId || type == NULL ||
        value == XL6_IR_VALUE_INVALID || xl6IrLowerValueType(ctx, value) != typeId)
        return xl6IrLowerDiag(ctx, origin, "XLIR storage replacement requires an exact payload ABI");
    if (type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL)
        return xl6IrLowerEmit(ctx, cell ? XL6_IR_INSTR_CELL_STORE : XL6_IR_INSTR_STORE,
            origin, typeId, symbol, &value, 1, NULL);
    value = xl6IrLowerAcquireValueOwner(ctx, origin, value);
    previousOwner = xl6IrLowerNewTempStorage(ctx, typeId, origin);
    if (value == XL6_IR_VALUE_INVALID || previousOwner == 0) return 0;
    if (cell) {
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CELL_EXCHANGE, origin, typeId,
                symbol, &value, 1, &previous)) return 0;
    } else {
        /* LOAD/MOVE and STORE are non-calling instructions. Together they
         * implement the same payload exchange for direct or indirect slots. */
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, typeId, symbol, NULL, 0, &previous) ||
            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_MOVE, origin, typeId, symbol, &previous, 1, NULL) ||
            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, typeId, symbol, &value, 1, NULL)) return 0;
    }
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, typeId, previousOwner, &previous, 1, NULL)) return 0;
    cleanup.temporaries = &previousOwner; cleanup.temporaryCount = 1;
    return xl6IrLowerCompleteOwnedCleanup(ctx, origin, xl6IrNodeGet(ctx->module, origin),
        NULL, XL6_IR_TYPE_INVALID, NULL, &cleanup);
}

static int xl6IrLowerWriteStorageTargetPlan(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrLowerStorageTargetPlan* plan,
    XL6_IrValueId value)
{
    return xl6IrLowerReplaceStorageValue(ctx, origin, plan->symbol, plan->type, value);
}

static int xl6IrLowerEmitStorageAssignment(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrLowerStorageTargetPlan* plan,
    XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrValueId value = xl6IrLowerNodeAsType(ctx, origin, rhsId, rhs, plan->type);
    if (value != XL6_IR_VALUE_INVALID && xl6IrLowerValueType(ctx, value) != plan->type)
        value = xl6IrLowerEmitIntegerStorageNormalize(ctx, origin, plan->type, value);
    return xl6IrLowerWriteStorageTargetPlan(ctx, origin, plan, value);
}

static int xl6IrLowerStorageAssign(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* lhs,
    XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerStorageTargetPlan plan;
    int prepared = xl6IrLowerPrepareStorageTargetPlan(ctx, origin, lhs, &plan);
    if (prepared <= 0) return prepared;
    return xl6IrLowerEmitStorageAssignment(ctx, origin, &plan, rhsId, rhs) ? 1 : -1;
}

/* string/bytes are value sequences.  An indexed write snapshots the current
 * owner, computes a fresh value with the exact SET_COPY RuntimeOp, then uses
 * the ordinary storage exchange path to retire the previous owner.  Only a
 * named receiver is currently admitted by Typed XLIR; no nested write-back
 * chain is guessed here. */
static int xl6IrLowerValueSequenceElementAssign(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* lhs,
    XL6_IrValueId item)
{
    const XL6_IrNode* receiver;
    const XL6_IrNode* key;
    XL6_IrLowerStorageTargetPlan storage;
    XL6_IrTypeId indexType;
    XL6_IrRuntimeOp operation;
    XL6_IrValueId operands[3];
    XL6_IrValueId current;
    XL6_IrValueId owned;
    XL6_IrValueId replacement = XL6_IR_VALUE_INVALID;
    size_t first;
    int prepared;
    if ( ctx == NULL || lhs == NULL || lhs->kind != XL6_IR_NODE_INDEX ||
         lhs->sourceKind != XL6_AST_INDEX || lhs->childCount != 2 ||
         (lhs->indexWriteAbi != XL6_IR_INDEX_WRITE_STRING_SCALAR_SET_COPY &&
          lhs->indexWriteAbi != XL6_IR_INDEX_WRITE_BYTES_SET_COPY) )
        return 0;
    receiver = xl6IrNodeGet(
        ctx->module, ctx->module->children[lhs->firstChild]);
    key = xl6IrNodeGet(
        ctx->module, ctx->module->children[lhs->firstChild + 1]);
    if ( item != XL6_IR_VALUE_INVALID &&
         lhs->indexWriteAbi == XL6_IR_INDEX_WRITE_BYTES_SET_COPY &&
         xl6IrLowerValueType(ctx, item) != lhs->storageType )
        item = xl6IrLowerEmitIntegerStorageNormalize(
            ctx, origin, lhs->storageType, item);
    if ( receiver == NULL || key == NULL || receiver->kind != XL6_IR_NODE_NAME ||
         item == XL6_IR_VALUE_INVALID ||
         xl6IrLowerValueType(ctx, item) != lhs->storageType )
        return xl6IrLowerDiag(ctx, origin,
            "XLIR string/bytes indexed write has no addressable receiver, key or exact item ABI");
    prepared = xl6IrLowerPrepareStorageTargetPlan(
        ctx, origin, receiver, &storage);
    if ( prepared <= 0 )
        return prepared < 0 ? 0 : xl6IrLowerDiag(ctx, origin,
            "XLIR string/bytes indexed write receiver has no writable storage plan");
    indexType = xl6IrLowerFindIntegerType(
        ctx->module, XL6_IR_INTEGER_TARGET_SIGNED_64);
    operation = lhs->indexWriteAbi ==
            XL6_IR_INDEX_WRITE_STRING_SCALAR_SET_COPY
        ? XL6_IR_RUNTIME_STRING_SCALAR_SET_COPY
        : XL6_IR_RUNTIME_BYTES_SET_COPY;
    if ( indexType == XL6_IR_TYPE_INVALID )
        return xl6IrLowerDiag(ctx, origin,
            "XLIR string/bytes indexed write has no canonical signed index TypeId");
    first = ctx->evaluationOwnerCount;
    current = storage.type == receiver->storageType
        ? xl6IrLowerReadStorageTargetPlan(ctx, origin, &storage)
        : xl6IrLowerNode(ctx, ctx->module->children[lhs->firstChild]);
    owned = xl6IrLowerOwnedStorageValue(
        ctx, origin, receiver->storageType, receiver, current);
    operands[0] = xl6IrLowerAnchorEvaluationBorrow(
        ctx, origin, receiver->storageType, owned);
    operands[1] = xl6IrLowerNodeAsType(
        ctx, origin, ctx->module->children[lhs->firstChild + 1], key,
        indexType);
    operands[2] = item;
    if ( operands[0] == XL6_IR_VALUE_INVALID ||
         operands[1] == XL6_IR_VALUE_INVALID ) goto done;
    replacement = xl6IrLowerEmitRuntimeCall(
        ctx, origin, receiver->storageType, operation, operands, 3);
    if ( replacement == XL6_IR_VALUE_INVALID ||
         !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, &replacement) ) {
        replacement = XL6_IR_VALUE_INVALID; goto done;
    }
    if ( storage.type != receiver->storageType &&
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_WRAP, origin, storage.type,
                         0, &replacement, 1, &replacement) ) {
        replacement = XL6_IR_VALUE_INVALID; goto done;
    }
    if ( !xl6IrLowerWriteStorageTargetPlan(
             ctx, origin, &storage, replacement) )
        replacement = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = first;
    return replacement != XL6_IR_VALUE_INVALID;
}

/* Null-aware assignment uses the same storage plan and commit as '='. Only
 * the null branch evaluates its RHS; the observed value need not survive
 * that branch because it is used solely by NULL_TEST before RHS evaluation. */
static int xl6IrLowerStorageAssignIfNull(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node,
    const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerStorageTargetPlan plan;
    XL6_IrTypeId boolType;
    XL6_IrValueId current, isNull;
    XL6_IrBlockId assignBlock, mergeBlock;
    XL6_IrInstruction* branch;
    int prepared;
    if (ctx == NULL || node == NULL || lhs == NULL || rhs == NULL ||
        node->text == NULL || strcmp(node->text, "?=") != 0) return 0;
    prepared = xl6IrLowerPrepareStorageTargetPlan(ctx, id, lhs, &plan);
    if (prepared < 0) return -1;
    if (prepared == 0) return xl6IrLowerElementAssignIfNull(ctx, id, node, lhs, rhsId, rhs);
    if (plan.nullAbi == XL6_IR_NULL_ABI_NONE) return 1;
    if (plan.nullAbi != XL6_IR_NULL_ABI_POINTER_SENTINEL &&
        plan.nullAbi != XL6_IR_NULL_ABI_XVALUE_SENTINEL &&
        !(plan.nullAbi == XL6_IR_NULL_ABI_TAGGED_VALUE && plan.cAbi == XL6_IR_C_ABI_TAGGED_NULLABLE)) {
        xl6IrLowerDiag(ctx, id,
            "XLIR null-aware assignment requires exact null-test and storage ownership ABIs");
        return -1;
    }
    boolType = xl6IrLowerFindTypeByCAbi(ctx->module, XL6_IR_C_ABI_BOOL);
    current = xl6IrLowerReadStorageTargetPlan(ctx, id, &plan);
    if (boolType == XL6_IR_TYPE_INVALID || current == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, id, boolType, 0, &current, 1, &isNull) ||
        !xl6IrLowerNewBlock(ctx, &assignBlock) || !xl6IrLowerNewBlock(ctx, &mergeBlock) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, id, XL6_IR_TYPE_INVALID, 0, &isNull, 1, NULL))
        return -1;
    branch = &ctx->module->instructions[ctx->module->instructionCount - 1];
    branch->trueTarget = assignBlock;
    branch->falseTarget = mergeBlock;
    xl6IrLowerEnterBlock(ctx, assignBlock);
    if (!xl6IrLowerEmitStorageAssignment(ctx, id, &plan, rhsId, rhs) ||
        !xl6IrLowerEmitJump(ctx, id, mergeBlock)) return -1;
    xl6IrLowerEnterBlock(ctx, mergeBlock);
    return 1;
}

/* A named function value is not storage and must not be represented as a
 * LOAD from its declaration symbol.  Lowering creates one deduplicated,
 * capture-free adapter body for each resolved target/signature pair.  The
 * adapter body is emitted later as ordinary verified CFG, including default
 * argument evaluation, so Cgen sees neither the source declaration nor an
 * implicit function-pointer conversion. */
static XL6_IrClosureTarget* xl6IrLowerNamedAdapterGet(
    XL6_IrModule* module, XL6_SymbolId adaptedTarget, XL6_IrTypeId signatureType)
{
    size_t i;
    if ( module == NULL || adaptedTarget == 0 || signatureType == XL6_IR_TYPE_INVALID ) return NULL;
    for ( i = 0; i < module->closureTargetCount; ++i ) {
        XL6_IrClosureTarget* closure = &module->closureTargets[i];
        if ( closure->kind == XL6_IR_CLOSURE_TARGET_NAMED_ADAPTER &&
             closure->adaptedTargetSymbol == adaptedTarget &&
             closure->signatureType == signatureType ) return closure;
    }
    return NULL;
}

static XL6_IrCallVariadicAbi xl6IrLowerCallableTargetVariadicAbi(
    XL6_IrCallableErasureAbi abi)
{
    switch ( abi ) {
    case XL6_IR_CALLABLE_ERASURE_FIXED:
        return XL6_IR_CALL_VARIADIC_NONE;
    case XL6_IR_CALLABLE_ERASURE_ARRAY_VARIADIC:
        return XL6_IR_CALL_VARIADIC_ARRAY;
    case XL6_IR_CALLABLE_ERASURE_DICT_VARIADIC:
        return XL6_IR_CALL_VARIADIC_DICT;
    case XL6_IR_CALLABLE_ERASURE_C_VARIADIC:
        return XL6_IR_CALL_VARIADIC_C;
    default:
        return (XL6_IrCallVariadicAbi)-1;
    }
}

/* A variadic callable keeps its carrier as the final physical parameter.  A
 * narrower callable may omit defaulted fixed parameters before that carrier,
 * so adapter binding is not always a simple prefix.  Resolve the positional
 * relation here while both exact signatures are available; the generated
 * adapter CFG then contains only ordinary loads/defaults/call operands. */
static size_t xl6IrLowerNamedAdapterTargetParameter(
    const XL6_IrType* signature, const XL6_IrCallTarget* target,
    size_t signatureParameter)
{
    if ( signature == NULL || target == NULL ||
         signatureParameter >= signature->paramCount ) return SIZE_MAX;
    if ( target->variadicAbi != XL6_IR_CALL_VARIADIC_NONE &&
         signatureParameter + 1 == signature->paramCount )
        return target->parameterCount != 0
            ? target->parameterCount - 1 : SIZE_MAX;
    return signatureParameter < target->parameterCount
        ? signatureParameter : SIZE_MAX;
}

static size_t xl6IrLowerNamedAdapterSignatureParameter(
    const XL6_IrType* signature, const XL6_IrCallTarget* target,
    size_t targetParameter)
{
    size_t fixedSignatureCount;
    if ( signature == NULL || target == NULL ||
         targetParameter >= target->parameterCount ) return SIZE_MAX;
    if ( target->variadicAbi == XL6_IR_CALL_VARIADIC_NONE )
        return targetParameter < signature->paramCount
            ? targetParameter : SIZE_MAX;
    if ( signature->paramCount == 0 || target->parameterCount == 0 )
        return SIZE_MAX;
    if ( targetParameter + 1 == target->parameterCount )
        return signature->paramCount - 1;
    fixedSignatureCount = signature->paramCount - 1;
    return targetParameter < fixedSignatureCount
        ? targetParameter : SIZE_MAX;
}

static int xl6IrLowerSetNamedAdapterCallParameterNames(
    XL6_IrModule* module, XL6_IrClosureTarget* closure,
    const XL6_IrNode* parameters, const XL6_IrType* signature,
    const XL6_IrCallTarget* target)
{
    char** names = NULL;
    size_t parameter;
    if ( module == NULL || closure == NULL || parameters == NULL ||
         parameters->kind != XL6_IR_NODE_LIST || signature == NULL ||
         target == NULL || parameters->childCount != target->parameterCount )
        return 0;
    if ( signature->paramCount == 0 ) return 1;
    names = (char**)xrtCalloc(signature->paramCount, sizeof(*names));
    if ( names == NULL ) return 0;
    for ( parameter = 0; parameter < signature->paramCount; ++parameter ) {
        size_t targetParameter = xl6IrLowerNamedAdapterTargetParameter(
            signature, target, parameter);
        const XL6_IrNode* source = targetParameter != SIZE_MAX
            ? xl6IrNodeGet(module,
                module->children[parameters->firstChild + targetParameter])
            : NULL;
        size_t prior;
        if ( source == NULL || source->kind != XL6_IR_NODE_PARAM_DECL ||
             source->text == NULL || source->text[0] == '\0' ) goto fail;
        for ( prior = 0; prior < parameter; ++prior )
            if ( strcmp(names[prior], source->text) == 0 ) goto fail;
        names[parameter] = xrtStrDupN(source->text, strlen(source->text));
        if ( names[parameter] == NULL ) goto fail;
    }
    closure->callParameterNames = names;
    closure->callParameterCount = signature->paramCount;
    return 1;
fail:
    for ( parameter = 0; parameter < signature->paramCount; ++parameter )
        xrtFree(names[parameter]);
    xrtFree(names);
    return 0;
}

static XL6_IrClosureTarget* xl6IrLowerRegisterNamedAdapter(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* name)
{
    XL6_IrClosureTarget* closure;
    const XL6_IrType* signature;
    const XL6_IrCallTarget* target;
    const XL6_IrNode* declaration;
    const XL6_IrNode* parameters;
    XL6_IrCallVariadicAbi variadicAbi;
    size_t i;
    if ( ctx == NULL || name == NULL || name->kind != XL6_IR_NODE_NAME ||
         name->namedCallableAbi !=
             XL6_IR_NAMED_CALLABLE_CAPTURE_FREE_ADAPTER ||
         name->namedCallableTargetSymbol == 0 ||
         name->namedCallableSignatureType == XL6_IR_TYPE_INVALID ) return NULL;
    closure = xl6IrLowerNamedAdapterGet(
        ctx->module, name->namedCallableTargetSymbol,
        name->namedCallableSignatureType);
    if ( closure != NULL ) return closure;
    signature = xl6IrTypeGet(
        &ctx->module->types, name->namedCallableSignatureType);
    target = xl6IrCallTargetGet(
        ctx->module, name->namedCallableTargetSymbol);
    variadicAbi = signature != NULL
        ? xl6IrLowerCallableTargetVariadicAbi(signature->callableErasureAbi)
        : (XL6_IrCallVariadicAbi)-1;
    declaration = target != NULL ? xl6IrNodeGet(ctx->module, target->declaration) : NULL;
    parameters = declaration != NULL && declaration->kind == XL6_IR_NODE_FUNC_DECL &&
                 declaration->sourceKind != XL6_AST_ANON_FUNC && declaration->childCount > 1
        ? xl6IrNodeGet(ctx->module, ctx->module->children[declaration->firstChild + 1]) : NULL;
    if ( signature == NULL || signature->kind != XL6_IR_TYPE_FUNCTION ||
         signature->cAbi != XL6_IR_C_ABI_CLOSURE_PTR ||
         (signature->paramCount != 0 &&
          (signature->parameterModes == NULL || signature->parameterAbis == NULL)) ||
         target == NULL ||
         (target->kind != XL6_IR_CALL_TARGET_INTERNAL &&
          target->kind != XL6_IR_CALL_TARGET_INTERNAL_GENERATOR &&
          target->kind != XL6_IR_CALL_TARGET_EXTERN_C) ||
         (target->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE &&
          target->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE) ||
         variadicAbi == (XL6_IrCallVariadicAbi)-1 ||
         target->variadicAbi != variadicAbi ||
         declaration == NULL ||
         (declaration->sourceKind != XL6_AST_FUNC &&
          declaration->sourceKind != XL6_AST_EXPORT_FUNC &&
          declaration->sourceKind != XL6_AST_EXTERN_FUNC) ||
         xl6IrLowerEnclosingClass(ctx->module, target->declaration) != XL6_IR_NODE_INVALID ||
         parameters == NULL || parameters->kind != XL6_IR_NODE_LIST ||
         parameters->childCount != target->parameterCount ||
         target->parameterCount < signature->paramCount ||
         (target->returnType != signature->callableResultType &&
           !(signature->returnCount == 1 && xl6IrLowerCallableTypesCompatible(
              ctx->module, target->returnType, signature->callableResultType))) ) {
        xl6IrLowerDiag(ctx, origin,
                        "XLIR named function value has no verified capture-free adapter ABI");
        return NULL;
    }
    for ( i = 0; i < signature->paramCount; ++i ) {
        size_t targetParameter = xl6IrLowerNamedAdapterTargetParameter(
            signature, target, i);
        if ( targetParameter == SIZE_MAX ||
             target->parameterTypes[targetParameter] != signature->params[i] ||
             target->parameterAbis[targetParameter] != signature->parameterAbis[i] ) {
            xl6IrLowerDiag(ctx, origin,
                            "XLIR named function adapter parameter does not match its callable signature");
            return NULL;
        }
    }
    for ( i = 0; i < target->parameterCount; ++i ) {
        const XL6_IrNode* parameter = xl6IrNodeGet(
            ctx->module, ctx->module->children[parameters->firstChild + i]);
        if ( xl6IrLowerNamedAdapterSignatureParameter(
                 signature, target, i) != SIZE_MAX ) continue;
        if ( parameter == NULL || parameter->kind != XL6_IR_NODE_PARAM_DECL ||
             parameter->symbol == 0 || parameter->childCount < 2 ) {
            xl6IrLowerDiag(ctx, origin,
                            "XLIR named function adapter requires explicit typed default arguments");
            return NULL;
        }
    }
    if ( !xl6IrLowerGrow((void**)&ctx->module->closureTargets,
                          &ctx->module->closureTargetCapacity,
                          ctx->module->closureTargetCount,
                          sizeof(*ctx->module->closureTargets)) ) {
        ctx->failed = 1;
        return NULL;
    }
    closure = &ctx->module->closureTargets[ctx->module->closureTargetCount++];
    memset(closure, 0, sizeof(*closure));
    closure->kind = XL6_IR_CLOSURE_TARGET_NAMED_ADAPTER;
    closure->declaration = origin;
    closure->targetSymbol = xl6IrLowerNewSyntheticSymbol(ctx);
    closure->adaptedTargetSymbol = name->namedCallableTargetSymbol;
    closure->signatureType = name->namedCallableSignatureType;
    closure->rawCallbackAbi = XL6_IR_CLOSURE_RAW_CALLBACK_NONE;
    closure->firstCapture = ctx->module->closureCaptureCount;
    closure->captureCount = 0;
    if ( closure->targetSymbol == 0 ||
         !xl6IrLowerSetNamedAdapterCallParameterNames(
              ctx->module, closure, parameters, signature, target) ||
         !xl6IrLowerSetClosureCallParameterDefaults(
              ctx, closure, parameters, signature, target, 1) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR named function adapter has no verified call-frame parameter metadata");
        return NULL;
    }
    closure->rawCallbackAbi =
        xl6IrLowerClosureRawCallbackAbi(ctx->module, closure);
    return closure;
}

/* An owned operand is anchored before evaluating any later operand. The
 * borrowed runtime operation and its error edge consume only this explicit
 * lifetime, never a source-level ownership guess in Cgen. */
static XL6_IrValueId xl6IrLowerAnchorEvaluationBorrow(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin,
    XL6_IrTypeId type, XL6_IrValueId owned)
{
    XL6_SymbolId storage = xl6IrLowerNewTempStorage(ctx, type, origin);
    XL6_IrValueId loaded = XL6_IR_VALUE_INVALID;
    if ( owned == XL6_IR_VALUE_INVALID || storage == 0 ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, type,
                          storage, &owned, 1, NULL) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, type,
                          storage, NULL, 0, &loaded) ||
         !xl6IrLowerProtectEvaluationStorage(ctx, origin, storage, loaded, 0, 0) )
        return XL6_IR_VALUE_INVALID;
    return loaded;
}

/* Select an exact managed binary operation before evaluating either child.
 * String, dynamic and derived-class comparisons share one evaluation
 * transaction. Runtime argument binding, success cleanup and failure cleanup
 * consequently cannot drift into separate per-operator implementations. */
static int xl6IrLowerManagedBinary(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    const XL6_IrNode* const sources[2], XL6_IrValueId* result)
{
    const XL6_IrType* types[2];
    const XL6_IrClassLayout* layout;
    XL6_IrCAbi abis[2];
    XL6_IrTypeId sourceTypes[2];
    XL6_IrTypeId operandType = XL6_IR_TYPE_INVALID;
    XL6_IrTypeId payloadType = XL6_IR_TYPE_INVALID;
    XL6_IrRuntimeOp operation = XL6_IR_RUNTIME_NONE;
    XL6_IrValueId values[2];
    XL6_IrOpcode opcode = node->opcode;
    size_t first = ctx->evaluationOwnerCount;
    size_t i;
    int strings = 0;
    int bytes = 0;
    int stringChar = 0;
    int dynamicResult = 0;
    int negate = opcode == XL6_IR_OPCODE_NE;
    if ( sources[0] == NULL || sources[1] == NULL || result == NULL ) return 0;
    if ( node->operatorExecutionType != XL6_IR_TYPE_INVALID ) {
        const XL6_IrType* execution = xl6IrTypeGet(
            &ctx->module->types, node->operatorExecutionType);
        if ( execution == NULL || execution->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL )
            return 0;
    }
    for ( i = 0; i < 2; ++i ) {
        sourceTypes[i] = sources[i]->storageType;
        types[i] = xl6IrTypeGet(&ctx->module->types, sourceTypes[i]);
        if ( types[i] == NULL ) return 0;
        abis[i] = types[i]->cAbi;
    }
    layout = sourceTypes[0] == sourceTypes[1]
        ? xl6IrLowerClassLayoutGet(ctx->module, sourceTypes[0]) : NULL;
    if ( abis[0] == XL6_IR_C_ABI_MANAGED_BYTES &&
         abis[1] == XL6_IR_C_ABI_MANAGED_BYTES ) {
        bytes = 1;
        operandType = sourceTypes[0];
        switch ( opcode ) {
        case XL6_IR_OPCODE_ADD: operation = XL6_IR_RUNTIME_BYTES_CONCAT; break;
        case XL6_IR_OPCODE_EQ: case XL6_IR_OPCODE_NE:
            operation = XL6_IR_RUNTIME_BYTES_EQUAL; break;
        case XL6_IR_OPCODE_LT: operation = XL6_IR_RUNTIME_BYTES_ORDER_LT; break;
        case XL6_IR_OPCODE_LE: operation = XL6_IR_RUNTIME_BYTES_ORDER_LE; break;
        case XL6_IR_OPCODE_GT: operation = XL6_IR_RUNTIME_BYTES_ORDER_GT; break;
        case XL6_IR_OPCODE_GE: operation = XL6_IR_RUNTIME_BYTES_ORDER_GE; break;
        default: return 0;
        }
    } else if ( opcode == XL6_IR_OPCODE_ADD &&
                xl6IrLowerTypeIsManagedString(ctx->module, node->storageType) &&
                ((abis[0] == XL6_IR_C_ABI_MANAGED_STRING &&
                  abis[1] == XL6_IR_C_ABI_CHAR_U32) ||
                 (abis[0] == XL6_IR_C_ABI_CHAR_U32 &&
                  abis[1] == XL6_IR_C_ABI_MANAGED_STRING)) ) {
        stringChar = 1;
        operandType = node->storageType;
        operation = abis[0] == XL6_IR_C_ABI_MANAGED_STRING
            ? XL6_IR_RUNTIME_STRING_CONCAT_CHAR_RIGHT
            : XL6_IR_RUNTIME_STRING_CONCAT_CHAR_LEFT;
    } else if ( ((abis[0] == XL6_IR_C_ABI_MANAGED_STRING && abis[1] == XL6_IR_C_ABI_MANAGED_STRING) ||
          (opcode == XL6_IR_OPCODE_ADD && xl6IrLowerTypeIsManagedString(ctx->module, node->storageType) &&
           (abis[0] == XL6_IR_C_ABI_MANAGED_STRING || abis[0] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR) &&
           (abis[1] == XL6_IR_C_ABI_MANAGED_STRING || abis[1] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR))) ) {
        strings = 1;
        operandType = opcode == XL6_IR_OPCODE_ADD ? node->storageType : sourceTypes[0];
        switch ( opcode ) {
        case XL6_IR_OPCODE_ADD: operation = XL6_IR_RUNTIME_STRING_CONCAT; break;
        case XL6_IR_OPCODE_EQ: case XL6_IR_OPCODE_NE: {
            const XL6_IrType* leftType = xl6IrTypeGet(&ctx->module->types,xl6IrNodeMaterializedValueType(ctx->module,sources[0]));
            const XL6_IrType* rightType = xl6IrTypeGet(&ctx->module->types,xl6IrNodeMaterializedValueType(ctx->module,sources[1]));
            if (!leftType || !rightType) return -1;
            operation = leftType->kind == XL6_IR_TYPE_NULLABLE || rightType->kind == XL6_IR_TYPE_NULLABLE
                ? XL6_IR_RUNTIME_NULLABLE_STRING_EQUAL : XL6_IR_RUNTIME_STRING_EQUAL;
            break;
        }
        case XL6_IR_OPCODE_LT: operation = XL6_IR_RUNTIME_STRING_ORDER_LT; break;
        case XL6_IR_OPCODE_LE: operation = XL6_IR_RUNTIME_STRING_ORDER_LE; break;
        case XL6_IR_OPCODE_GT: operation = XL6_IR_RUNTIME_STRING_ORDER_GT; break;
        case XL6_IR_OPCODE_GE: operation = XL6_IR_RUNTIME_STRING_ORDER_GE; break;
        case XL6_IR_OPCODE_APPROX: operation = XL6_IR_RUNTIME_STRING_APPROX; break;
        default: return 0;
        }
    } else if ( (opcode == XL6_IR_OPCODE_EQ || opcode == XL6_IR_OPCODE_NE) &&
                types[0]->kind == XL6_IR_TYPE_CLASS &&
                abis[0] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR && layout != NULL &&
                layout->equalityAbi == XL6_IR_CLASS_EQUALITY_ABI_RUNTIME_DERIVED &&
                layout->equalityTarget == 0 ) {
        operation = XL6_IR_RUNTIME_CLASS_DERIVED_EQUAL;
        operandType = payloadType = sourceTypes[0];
    } else if ( abis[0] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
                abis[1] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ) {
        switch ( opcode ) {
        case XL6_IR_OPCODE_EQ: case XL6_IR_OPCODE_NE: operation = XL6_IR_RUNTIME_XVALUE_EQUAL; break;
        case XL6_IR_OPCODE_LT: operation = XL6_IR_RUNTIME_XVALUE_ORDER_LT; break;
        case XL6_IR_OPCODE_LE: operation = XL6_IR_RUNTIME_XVALUE_ORDER_LE; break;
        case XL6_IR_OPCODE_GT: operation = XL6_IR_RUNTIME_XVALUE_ORDER_GT; break;
        case XL6_IR_OPCODE_GE: operation = XL6_IR_RUNTIME_XVALUE_ORDER_GE; break;
        case XL6_IR_OPCODE_APPROX: operation = XL6_IR_RUNTIME_XVALUE_APPROX; break;
        default:
            if ( !xl6IrLowerTypeIsRuntimeXValue(ctx->module, node->storageType) ) return 0;
            dynamicResult = 1;
            switch ( opcode ) {
            case XL6_IR_OPCODE_ADD: operation = XL6_IR_RUNTIME_XVALUE_BINARY_ADD; break;
            case XL6_IR_OPCODE_SUB: operation = XL6_IR_RUNTIME_XVALUE_BINARY_SUB; break;
            case XL6_IR_OPCODE_MUL: operation = XL6_IR_RUNTIME_XVALUE_BINARY_MUL; break;
            case XL6_IR_OPCODE_DIV: operation = XL6_IR_RUNTIME_XVALUE_BINARY_DIV; break;
            case XL6_IR_OPCODE_MOD: operation = XL6_IR_RUNTIME_XVALUE_BINARY_MOD; break;
            case XL6_IR_OPCODE_BIT_AND: operation = XL6_IR_RUNTIME_XVALUE_BINARY_BIT_AND; break;
            case XL6_IR_OPCODE_BIT_OR: operation = XL6_IR_RUNTIME_XVALUE_BINARY_BIT_OR; break;
            case XL6_IR_OPCODE_BIT_XOR: operation = XL6_IR_RUNTIME_XVALUE_BINARY_BIT_XOR; break;
            case XL6_IR_OPCODE_SHL: operation = XL6_IR_RUNTIME_XVALUE_BINARY_SHL; break;
            case XL6_IR_OPCODE_SHR: operation = XL6_IR_RUNTIME_XVALUE_BINARY_SHR; break;
            default: return 0;
            }
        }
        operandType = xl6IrLowerFindDynamicBuiltinType(ctx->module);
    } else return 0;
    *result = XL6_IR_VALUE_INVALID;
    if ( operandType == XL6_IR_TYPE_INVALID ||
         (!dynamicResult && operation != XL6_IR_RUNTIME_STRING_CONCAT &&
          operation != XL6_IR_RUNTIME_STRING_CONCAT_CHAR_RIGHT &&
          operation != XL6_IR_RUNTIME_STRING_CONCAT_CHAR_LEFT &&
          operation != XL6_IR_RUNTIME_BYTES_CONCAT &&
          !xl6IrLowerTypeIsBool(ctx->module, node->storageType)) ) {
        xl6IrLowerDiag(ctx, origin, "XLIR managed binary has no exact operand/result ABI");
        return -1;
    }
    for ( i = 0; i < 2; ++i ) {
        XL6_IrNodeId child = ctx->module->children[node->firstChild + i];
        XL6_IrValueId owned;
        XL6_IrTypeId ownedType = operandType;
        if ( stringChar && abis[i] == XL6_IR_C_ABI_CHAR_U32 ) {
            values[i] = xl6IrLowerNode(ctx, child);
            if ( values[i] == XL6_IR_VALUE_INVALID ) goto done;
            continue;
        }
        if ( !strings && !bytes && !stringChar ) {
            owned = xl6IrLowerNodeAsRuntimeXValue(ctx, origin, child, sources[i], operandType);
        } else if ( abis[i] == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ) {
            XL6_IrValueId input = xl6IrLowerNodeAsRuntimeXValue(
                ctx, origin, child, sources[i], sourceTypes[i]);
            input = xl6IrLowerAnchorEvaluationBorrow(ctx, origin, sourceTypes[i], input);
            if ( input == XL6_IR_VALUE_INVALID ) goto done;
            owned = xl6IrLowerEmitRuntimeCall(ctx, origin, operandType,
                XL6_IR_RUNTIME_XVALUE_TO_STRING, &input, 1);
        } else {
            owned = xl6IrLowerNode(ctx, child);
            /* A flow-narrowed nullable name has already produced a concrete
             * string/bytes SSA value. Its copy and anchor must use that actual
             * TypeId, not the nullable type of the original storage. */
            ownedType = xl6IrLowerValueType(ctx, owned);
            owned = xl6IrLowerOwnedStorageValue(ctx, origin, ownedType, sources[i], owned);
        }
        values[i] = xl6IrLowerAnchorEvaluationBorrow(ctx, origin, ownedType, owned);
        if ( values[i] == XL6_IR_VALUE_INVALID ) goto done;
    }
    *result = xl6IrLowerEmitRuntimeCall(ctx, origin, node->storageType, operation, values, 2);
    if ( *result == XL6_IR_VALUE_INVALID ) goto done;
    if ( payloadType != XL6_IR_TYPE_INVALID )
        ctx->module->instructions[ctx->module->instructionCount - 1].payloadType = payloadType;
    /* Allocating dynamic arithmetic shares the central checked-box producer
     * path. Do not split a second error edge after its outcome/cleanup CFG. */
    if ( !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, result) ) {
        *result = XL6_IR_VALUE_INVALID;
        goto done;
    }
    if ( negate ) {
        XL6_IrValueId inverted;
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_UNARY, origin, node->storageType,
                             0, result, 1, &inverted) ) {
            *result = XL6_IR_VALUE_INVALID;
            goto done;
        }
        ctx->module->instructions[ctx->module->instructionCount - 1].opcode = XL6_IR_OPCODE_NOT;
        *result = inverted;
    }
done:
    ctx->evaluationOwnerCount = first;
    return *result != XL6_IR_VALUE_INVALID ? 1 : -1;
}

/* A RANGE IntrinsicCall is a typed descriptor rather than a runtime value.
 * Membership is one of its explicit consumers: lowering fixes omitted
 * start/step operands and emits a four-i64 operation for Cgen. */
static XL6_IrValueId xl6IrLowerRangeContains(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* expression,
    XL6_IrNodeId itemId, const XL6_IrNode* itemNode,
    XL6_IrNodeId rangeId, const XL6_IrNode* rangeNode)
{
    const XL6_IrIntrinsicCall* intrinsic = xl6IrIntrinsicCallGet(
        ctx->module, rangeId);
    const XL6_IrType* itemType;
    XL6_IrTypeId descriptorType = XL6_IR_TYPE_INVALID;
    XL6_IrValueId operands[4];
    size_t i;
    if ( expression == NULL || itemNode == NULL || rangeNode == NULL ||
         rangeNode->kind != XL6_IR_NODE_CALL ||
         rangeNode->callKind != XL6_SEM_CALL_BUILTIN || intrinsic == NULL ||
         intrinsic->kind != XL6_IR_INTRINSIC_RANGE ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_DESCRIPTOR ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ||
         intrinsic->resultType != rangeNode->storageType ||
         intrinsic->operandCount < 1 || intrinsic->operandCount > 3 ||
         intrinsic->firstOperand + intrinsic->operandCount < intrinsic->firstOperand ||
         intrinsic->firstOperand + intrinsic->operandCount >
             ctx->module->intrinsicOperandCount ||
         !xl6IrLowerTypeIsBool(ctx->module, expression->storageType) ||
         (itemType = xl6IrTypeGet(
              &ctx->module->types, itemNode->storageType)) == NULL ||
         itemType->cAbi != XL6_IR_C_ABI_I64 ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR range membership has no exact descriptor, integer item or boolean ABI");
        return XL6_IR_VALUE_INVALID;
    }
    for ( i = 0; i < intrinsic->operandCount; ++i ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[intrinsic->firstOperand + i];
        const XL6_IrNode* argument = xl6IrNodeGet(
            ctx->module, binding->expression);
        const XL6_IrType* argumentType = xl6IrTypeGet(
            &ctx->module->types, binding->type);
        if ( binding->abi != XL6_IR_INTRINSIC_OPERAND_VALUE ||
             argument == NULL || argument->storageType != binding->type ||
             argumentType == NULL || argumentType->cAbi != XL6_IR_C_ABI_I64 ) {
            xl6IrLowerDiag(ctx, origin,
                "XLIR range membership has no exact descriptor, integer item or boolean ABI");
            return XL6_IR_VALUE_INVALID;
        }
        if ( descriptorType == XL6_IR_TYPE_INVALID ) descriptorType = binding->type;
    }
    operands[0] = xl6IrLowerNode(ctx, itemId);
    if ( intrinsic->operandCount == 1 ) {
        operands[1] = xl6IrLowerEmitIntConst(ctx, origin, descriptorType, "0");
        operands[2] = xl6IrLowerNode(
            ctx, ctx->module->intrinsicOperands[intrinsic->firstOperand].expression);
        operands[3] = xl6IrLowerEmitIntConst(ctx, origin, descriptorType, "1");
    } else {
        operands[1] = xl6IrLowerNode(
            ctx, ctx->module->intrinsicOperands[intrinsic->firstOperand].expression);
        operands[2] = xl6IrLowerNode(
            ctx, ctx->module->intrinsicOperands[intrinsic->firstOperand + 1].expression);
        operands[3] = intrinsic->operandCount == 3
            ? xl6IrLowerNode(
                ctx, ctx->module->intrinsicOperands[intrinsic->firstOperand + 2].expression)
            : xl6IrLowerEmitIntConst(ctx, origin, descriptorType, "1");
    }
    for ( i = 0; i < 4; ++i )
        if ( operands[i] == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
    return xl6IrLowerEmitRuntimeCall(
        ctx, origin, expression->storageType,
        XL6_IR_RUNTIME_I64_RANGE_CONTAINS, operands, 4);
}

/* Static managed-string membership has a representation-specific operation;
 * both operands are borrowed and every owned rvalue is anchored explicitly.
 * Evaluation order is source order: needle first, haystack second. The runtime
 * ABI orders them differently; binding operands must not reorder evaluation. */
static XL6_IrValueId xl6IrLowerStringContains(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* expression,
    XL6_IrNodeId itemId, const XL6_IrNode* itemNode,
    XL6_IrNodeId stringId, const XL6_IrNode* stringNode)
{
    XL6_IrValueId operands[2];
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    XL6_SymbolId temporaries[2] = { 0, 0 };
    size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
    size_t operand;
    if ( expression == NULL || itemNode == NULL || stringNode == NULL ||
         !xl6IrLowerTypeIsBool(ctx->module, expression->storageType) ||
         !xl6IrLowerTypeIsManagedString(ctx->module, itemNode->storageType) ||
         !xl6IrLowerTypeIsManagedString(ctx->module, stringNode->storageType) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR string membership has no exact haystack, needle or boolean ABI");
        return XL6_IR_VALUE_INVALID;
    }
    for ( operand = 2; operand > 0; --operand ) {
        size_t slot = operand - 1;
        const XL6_IrNode* source = slot == 0 ? stringNode : itemNode;
        XL6_IrValueId value = xl6IrLowerNode(ctx, slot == 0 ? stringId : itemId);
        /* Even a named needle needs its own value: evaluating the haystack may
         * replace its storage. The last operand has no later evaluation. */
        if ( slot == 1 ) {
            value = xl6IrLowerOwnedStorageValue(
                ctx, origin, source->storageType, source, value);
            temporaries[slot] = xl6IrLowerNewTempStorage(ctx, source->storageType, origin);
            if ( value == XL6_IR_VALUE_INVALID || temporaries[slot] == 0 ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, source->storageType,
                                  temporaries[slot], &value, 1, NULL) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, source->storageType,
                                  temporaries[slot], NULL, 0, &operands[slot]) ) goto done;
        } else {
            operands[slot] = xl6IrLowerBorrowManagedStringOperand(
                ctx, origin, source, value, &temporaries[slot]);
        }
        if ( operands[slot] == XL6_IR_VALUE_INVALID ||
             (temporaries[slot] != 0 && !xl6IrLowerProtectEvaluationStorage(
                  ctx, origin, temporaries[slot], operands[slot], 0, 0)) ) goto done;
    }
    result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, expression->storageType,
        XL6_IR_RUNTIME_STRING_CONTAINS, operands, 2);
    if ( result != XL6_IR_VALUE_INVALID &&
         !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, evaluationOwnerFirst, &result) )
        result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return result;
}

/* Membership is resolved into a concrete collection operation before Cgen.
 * Both XRT operands are explicit borrows: the item/key is boxed into an owned
 * temporary and a collection rvalue is anchored until the call has completed.
 * Typed sets retain their direct operation; arrays/lists/dicts and the open
 * dynamic value use one verified runtime-tag dispatch operation. */
static XL6_IrValueId xl6IrLowerXValueContains(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* expression,
    XL6_IrNodeId itemId, const XL6_IrNode* itemNode,
    XL6_IrNodeId collectionId, const XL6_IrNode* collectionNode,
    XL6_IrRuntimeOp requestedOperation)
{
    const XL6_IrType* collectionType;
    const XL6_IrType* itemType;
    XL6_IrTypeId boxedType;
    XL6_IrValueId boxed;
    XL6_IrValueId loaded;
    XL6_IrValueId collectionValue;
    XL6_IrValueId operands[2];
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    XL6_SymbolId itemTemporary = 0;
    XL6_SymbolId collectionTemporary = 0;
    size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
    size_t operand;
    int receiverFirst;
    int isDynamic;
    int isTypedCollection;
    int itemMatches = 0;

    if ( expression == NULL || itemNode == NULL || collectionNode == NULL ||
         (requestedOperation != XL6_IR_RUNTIME_NONE &&
          requestedOperation != XL6_IR_RUNTIME_XVALUE_ARRAY_REMOVE_VALUE) ||
         !xl6IrLowerTypeIsBool(ctx->module, expression->storageType) ||
         (collectionType = xl6IrTypeGet(
              &ctx->module->types, collectionNode->storageType)) == NULL ||
         (itemType = xl6IrTypeGet(&ctx->module->types, itemNode->storageType)) == NULL ||
         collectionType->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR xvalue membership has no exact collection, element/key or boolean ABI");
        return XL6_IR_VALUE_INVALID;
    }

    isDynamic = xl6IrLowerTypeIsDynamicXValueBuiltin(
        ctx->module, collectionNode->storageType);
    isTypedCollection = collectionType->collectionAbi == XL6_IR_COLLECTION_ARRAY ||
        collectionType->collectionAbi == XL6_IR_COLLECTION_LIST ||
        collectionType->collectionAbi == XL6_IR_COLLECTION_SET ||
        collectionType->collectionAbi == XL6_IR_COLLECTION_DICT;
    if ( requestedOperation == XL6_IR_RUNTIME_XVALUE_ARRAY_REMOVE_VALUE &&
         (isDynamic || collectionType->collectionAbi != XL6_IR_COLLECTION_ARRAY) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR array remove-value has no exact statically typed array ABI");
        return XL6_IR_VALUE_INVALID;
    }
    if ( isTypedCollection )
        itemMatches = xl6IrCollectionContainsOperandCompatible(
            ctx->module, collectionNode->storageType, itemNode->storageType);
    if ( !(isDynamic || (isTypedCollection && itemMatches)) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR xvalue membership has no exact collection, element/key or boolean ABI");
        return XL6_IR_VALUE_INVALID;
    }
    if ( collectionType->collectionAbi == XL6_IR_COLLECTION_SET &&
         !xl6IrLowerSetElementHasRuntimeIdentity(
             ctx->module, collectionNode->storageType) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR typed set membership has no complete runtime hash/equality identity ABI");
        return XL6_IR_VALUE_INVALID;
    }

    /* Element membership shares the exact boxing contract with INSERT and
     * INDEX_OF.  Dict membership instead boxes its string key; an open var
     * retains the existing dynamic value/key ABI. */
    boxedType = isTypedCollection &&
        collectionType->collectionAbi != XL6_IR_COLLECTION_DICT
            ? xl6IrCollectionBoxedElementType(
                ctx->module, collectionNode->storageType)
            : itemType->cAbi == XL6_IR_C_ABI_RUNTIME_XVALUE_PTR
                ? itemNode->storageType : collectionNode->storageType;
    receiverFirst = expression->kind == XL6_IR_NODE_CALL;
    for ( operand = 0; operand < 2; ++operand ) {
        if ( (operand == 0) == receiverFirst ) {
            /* A receiver precedes its argument; an infix container follows its
             * item. A receiver borrow must survive argument-side replacement. */
            collectionValue = collectionNode->kind == XL6_IR_NODE_COLLECTION ||
                              collectionNode->sourceKind == XL6_AST_TYPED_LITERAL
                ? xl6IrLowerNodeAsRuntimeXValue(ctx, origin, collectionId,
                      collectionNode, collectionNode->storageType)
                : xl6IrLowerNode(ctx, collectionId);
            collectionValue = xl6IrLowerBorrowRuntimeXValueOperand(
                ctx, origin, collectionNode, collectionValue, &collectionTemporary);
            if ( collectionValue == XL6_IR_VALUE_INVALID ) goto done;
            if ( receiverFirst && collectionTemporary == 0 ) {
                /* This path received a physical borrow, not a NodeAsRuntimeXValue
                 * owned result. Acquire the receiver explicitly before pinning. */
                XL6_IrValueId retained = XL6_IR_VALUE_INVALID;
                if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RETAIN, origin,
                                      collectionNode->storageType, 0,
                                      &collectionValue, 1, &retained) ) goto done;
                collectionValue = retained;
                collectionTemporary = xl6IrLowerNewTempStorage(
                    ctx, collectionNode->storageType, origin);
                if ( collectionValue == XL6_IR_VALUE_INVALID || collectionTemporary == 0 ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, collectionNode->storageType,
                                      collectionTemporary, &collectionValue, 1, NULL) ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, collectionNode->storageType,
                                      collectionTemporary, NULL, 0, &collectionValue) ) goto done;
            }
            if ( collectionTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
                     ctx, origin, collectionTemporary, collectionValue, 0, 0) ) goto done;
            operands[0] = collectionValue;
        } else {
            boxed = xl6IrLowerNodeAsRuntimeXValue(ctx, origin, itemId, itemNode, boxedType);
            itemTemporary = xl6IrLowerNewTempStorage(ctx, boxedType, origin);
            if ( boxed == XL6_IR_VALUE_INVALID || itemTemporary == 0 ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, boxedType,
                                  itemTemporary, &boxed, 1, NULL) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, boxedType,
                                  itemTemporary, NULL, 0, &loaded) ||
                 !xl6IrLowerProtectEvaluationStorage(
                     ctx, origin, itemTemporary, loaded, 0, 0) ) goto done;
            operands[1] = loaded;
        }
    }
    result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, expression->storageType,
        requestedOperation != XL6_IR_RUNTIME_NONE
            ? requestedOperation
            : collectionType->collectionAbi == XL6_IR_COLLECTION_SET && !isDynamic
                ? XL6_IR_RUNTIME_XVALUE_SET_HAS
                : XL6_IR_RUNTIME_XVALUE_CONTAINS,
        operands, 2);
    if ( result != XL6_IR_VALUE_INVALID &&
         requestedOperation == XL6_IR_RUNTIME_XVALUE_ARRAY_REMOVE_VALUE &&
         !xl6IrLowerEmitRuntimeErrorEdge(ctx, origin, expression, result) )
        result = XL6_IR_VALUE_INVALID;
    if ( result != XL6_IR_VALUE_INVALID &&
         !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, evaluationOwnerFirst, &result) )
        result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return result;
}

static int xl6IrLowerIntrinsicCollectionContains(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    XL6_IrNodeId itemId;
    const XL6_IrNode* item;
    const XL6_IrNode* receiver;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_COLLECTION_CONTAINS ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->receiver == XL6_IR_NODE_INVALID ||
         intrinsic->receiverType == XL6_IR_TYPE_INVALID ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_VALUE ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ) return 0;
    itemId = ctx->module->intrinsicOperands[intrinsic->firstOperand].expression;
    item = xl6IrNodeGet(ctx->module, itemId);
    receiver = xl6IrNodeGet(ctx->module, intrinsic->receiver);
    if ( item == NULL || receiver == NULL ||
         receiver->storageType != intrinsic->receiverType ||
         ctx->module->intrinsicOperands[intrinsic->firstOperand].type !=
             item->storageType ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR collection contains has no exact typed receiver or item ABI");
        return -1;
    }
    *result = xl6IrLowerXValueContains(
        ctx, origin, call, itemId, item, intrinsic->receiver, receiver,
        XL6_IR_RUNTIME_NONE);
    return *result != XL6_IR_VALUE_INVALID ? 1 : -1;
}

static int xl6IrLowerIntrinsicArrayRemoveValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrIntrinsicOperand* binding;
    const XL6_IrNode* item;
    const XL6_IrNode* receiver;
    const XL6_IrType* itemType;
    XL6_IrIntrinsicOperandAbi expectedItemAbi;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_ARRAY_REMOVE_VALUE ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->receiver == XL6_IR_NODE_INVALID ||
         intrinsic->receiverType == XL6_IR_TYPE_INVALID ||
         intrinsic->collectionAbi != XL6_IR_COLLECTION_ARRAY ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_VALUE ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ) return 0;
    binding = &ctx->module->intrinsicOperands[intrinsic->firstOperand];
    item = xl6IrNodeGet(ctx->module, binding->expression);
    receiver = xl6IrNodeGet(ctx->module, intrinsic->receiver);
    itemType = xl6IrTypeGet(&ctx->module->types, binding->type);
    expectedItemAbi = itemType != NULL &&
        itemType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED
            ? XL6_IR_INTRINSIC_OPERAND_BORROW
            : XL6_IR_INTRINSIC_OPERAND_VALUE;
    if ( item == NULL || receiver == NULL || itemType == NULL ||
         item->storageType != binding->type ||
         receiver->storageType != intrinsic->receiverType ||
         binding->abi != expectedItemAbi ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR array remove-value has no exact borrowed array or element operand ABI");
        return -1;
    }
    *result = xl6IrLowerXValueContains(
        ctx, origin, call, binding->expression, item,
        intrinsic->receiver, receiver,
        XL6_IR_RUNTIME_XVALUE_ARRAY_REMOVE_VALUE);
    return *result != XL6_IR_VALUE_INVALID ? 1 : -1;
}

/* The shared collection contract fixes each operation's result and boxing
 * TypeIds before emission.  Erased receivers keep their collection identity;
 * POP/TAKE transfer an owned dynamic element without open member dispatch. */
static int xl6IrLowerIntrinsicTypedCollectionMember(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrNode* receiver;
    const XL6_IrType* receiverType;
    const XL6_IrType* resultType;
    XL6_IrValueId operands[3] = {
        XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID, XL6_IR_VALUE_INVALID
    };
    XL6_SymbolId receiverTemporary = 0;
    XL6_SymbolId operandTemporaries[2] = { 0, 0 };
    XL6_IrInstruction* emitted;
    XL6_IrIntrinsicResultAbi expectedResultAbi;
    size_t operandIndex;
    size_t evaluationOwnerFirst;
    int status = -1;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_TYPED_COLLECTION_MEMBER ||
         intrinsic->receiver == XL6_IR_NODE_INVALID ||
         intrinsic->receiverType == XL6_IR_TYPE_INVALID ||
         intrinsic->operandCount > 2 ||
         intrinsic->resultType != call->storageType ||
         intrinsic->errorAbi != xl6IrTypedCollectionErrorAbi(intrinsic->typedCollectionOp) ) return 0;
    receiver = xl6IrNodeGet(ctx->module, intrinsic->receiver);
    receiverType = xl6IrTypeGet(&ctx->module->types, intrinsic->receiverType);
    resultType = xl6IrTypeGet(&ctx->module->types, intrinsic->resultType);
    expectedResultAbi = resultType != NULL &&
        (intrinsic->typedCollectionOp == XL6_IR_TYPED_COLLECTION_POP ||
         intrinsic->typedCollectionOp == XL6_IR_TYPED_COLLECTION_TAKE) &&
        resultType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED
            ? XL6_IR_INTRINSIC_RESULT_OWNED
            : XL6_IR_INTRINSIC_RESULT_VALUE;
    if ( receiver == NULL || receiverType == NULL || resultType == NULL ||
         receiver->storageType != intrinsic->receiverType ||
         intrinsic->resultAbi != expectedResultAbi ||
         !xl6IrLowerTypedCollectionSignatureCompatible(ctx, intrinsic) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR typed collection member has no exact operation, receiver, operand or result ABI");
        return -1;
    }
    evaluationOwnerFirst = ctx->evaluationOwnerCount;
    operands[0] = xl6IrLowerNode(ctx, intrinsic->receiver);
    operands[0] = xl6IrLowerAcquireValueOwner(ctx, origin, operands[0]);
    operands[0] = xl6IrLowerBorrowRuntimeXValueOperand(
        ctx, origin, receiver, operands[0], &receiverTemporary);
    if ( operands[0] == XL6_IR_VALUE_INVALID ||
         (receiverTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, origin, receiverTemporary, operands[0], 0, 0)) ) goto done;
    for ( operandIndex = 0;
          operandIndex < intrinsic->operandCount; ++operandIndex ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[
                intrinsic->firstOperand + operandIndex];
        const XL6_IrNode* argument =
            xl6IrNodeGet(ctx->module, binding->expression);
        const XL6_IrType* argumentType =
            xl6IrTypeGet(&ctx->module->types, binding->type);
        if ( argument == NULL || argumentType == NULL ||
             argument->storageType != binding->type ) goto done;
        if ( intrinsic->typedCollectionOp ==
                 XL6_IR_TYPED_COLLECTION_INDEX_OF ||
             (intrinsic->typedCollectionOp ==
                  XL6_IR_TYPED_COLLECTION_INSERT && operandIndex == 1) ) {
            XL6_IrTypeId boxedType = xl6IrCollectionBoxedElementType(
                ctx->module, intrinsic->receiverType);
            XL6_IrValueId loaded = XL6_IR_VALUE_INVALID;
            operands[operandIndex + 1] = xl6IrLowerNodeAsRuntimeXValue(
                ctx, origin, binding->expression, argument, boxedType);
            operandTemporaries[operandIndex] =
                xl6IrLowerNewTempStorage(ctx, boxedType, origin);
            if ( operands[operandIndex + 1] != XL6_IR_VALUE_INVALID &&
                 operandTemporaries[operandIndex] != 0 &&
                 xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, boxedType,
                     operandTemporaries[operandIndex],
                     &operands[operandIndex + 1], 1, NULL) &&
                 xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, boxedType,
                     operandTemporaries[operandIndex], NULL, 0, &loaded) )
                operands[operandIndex + 1] = loaded;
            else
                operands[operandIndex + 1] = XL6_IR_VALUE_INVALID;
        } else if ( intrinsic->typedCollectionOp ==
                        XL6_IR_TYPED_COLLECTION_IS_DISJOINT ) {
            operands[operandIndex + 1] = xl6IrLowerNode(
                ctx, binding->expression);
            operands[operandIndex + 1] = xl6IrLowerBorrowRuntimeXValueOperand(
                ctx, origin, argument, operands[operandIndex + 1],
                &operandTemporaries[operandIndex]);
        } else if ( intrinsic->typedCollectionOp ==
                        XL6_IR_TYPED_COLLECTION_TAKE &&
                    intrinsic->collectionAbi == XL6_IR_COLLECTION_DICT ) {
            operands[operandIndex + 1] = xl6IrLowerNode(
                ctx, binding->expression);
            operands[operandIndex + 1] = xl6IrLowerBorrowManagedStringOperand(
                ctx, origin, argument, operands[operandIndex + 1],
                &operandTemporaries[operandIndex]);
        } else {
            operands[operandIndex + 1] = xl6IrLowerNode(
                ctx, binding->expression);
        }
        if ( operands[operandIndex + 1] == XL6_IR_VALUE_INVALID ||
             (operandTemporaries[operandIndex] != 0 &&
              !xl6IrLowerProtectEvaluationStorage(ctx, origin,
                  operandTemporaries[operandIndex], operands[operandIndex + 1], 0, 0)) ) goto done;
    }
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, intrinsic->resultType,
        XL6_IR_RUNTIME_XVALUE_TYPED_COLLECTION_METHOD,
        operands, intrinsic->operandCount + 1);
    if ( *result == XL6_IR_VALUE_INVALID ) goto done;
    emitted = &ctx->module->instructions[ctx->module->instructionCount - 1];
    emitted->collectionAbi = intrinsic->collectionAbi;
    emitted->typedCollectionOp = intrinsic->typedCollectionOp;
    if (intrinsic->typedCollectionOp==XL6_IR_TYPED_COLLECTION_RESIZE)
        emitted->collectionDefaultAbi=xl6IrValueDefaultAbiForType(&ctx->module->types,
            xl6IrTypeGet(&ctx->module->types,xl6IrCollectionElementType(ctx->module,intrinsic->receiverType)));
    if (intrinsic->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE &&
        !xl6IrLowerEmitRuntimeErrorEdge(ctx, origin, call, *result)) goto done;
    if (!xl6IrLowerCompleteEvaluationBorrows(ctx, origin, evaluationOwnerFirst, result)) goto done;
    status = 1;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return status;
}

static int xl6IrLowerIntrinsicCollectionRemove(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrNode* receiver;
    const XL6_IrNode* operandNode;
    const XL6_IrType* receiverType;
    const XL6_IrType* operandType;
    XL6_IrNodeId operandId;
    XL6_IrValueId operands[2];
    XL6_SymbolId receiverTemporary = 0;
    XL6_SymbolId operandTemporary = 0;
    XL6_IrTypeId operandStorageType = XL6_IR_TYPE_INVALID;
    size_t evaluationOwnerFirst;
    int status = -1;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->kind != XL6_IR_INTRINSIC_COLLECTION_REMOVE ||
         intrinsic->operandCount != 1 ||
         intrinsic->firstOperand >= ctx->module->intrinsicOperandCount ||
         intrinsic->receiver == XL6_IR_NODE_INVALID ||
         intrinsic->receiverType == XL6_IR_TYPE_INVALID ||
         intrinsic->collectionAbi < XL6_IR_COLLECTION_ARRAY ||
         intrinsic->collectionAbi > XL6_IR_COLLECTION_DICT ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_VALUE ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ) return 0;
    operandId = ctx->module->intrinsicOperands[intrinsic->firstOperand].expression;
    receiver = xl6IrNodeGet(ctx->module, intrinsic->receiver);
    operandNode = xl6IrNodeGet(ctx->module, operandId);
    receiverType = receiver != NULL
        ? xl6IrTypeGet(&ctx->module->types, receiver->storageType) : NULL;
    operandType = operandNode != NULL
        ? xl6IrTypeGet(&ctx->module->types, operandNode->storageType) : NULL;
    if ( receiver == NULL || operandNode == NULL || receiverType == NULL ||
         operandType == NULL || receiver->storageType != intrinsic->receiverType ||
         receiverType->collectionAbi != intrinsic->collectionAbi ||
         ctx->module->intrinsicOperands[intrinsic->firstOperand].type !=
             operandNode->storageType ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR collection remove has no exact typed receiver or operand ABI");
        return -1;
    }
    evaluationOwnerFirst = ctx->evaluationOwnerCount;
    operands[0] = xl6IrLowerNode(ctx, intrinsic->receiver);
    operands[0] = xl6IrLowerAcquireValueOwner(ctx, origin, operands[0]);
    operands[0] = xl6IrLowerBorrowRuntimeXValueOperand(
        ctx, origin, receiver, operands[0], &receiverTemporary);
    if ( operands[0] == XL6_IR_VALUE_INVALID ||
         (receiverTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, origin, receiverTemporary, operands[0], 0, 0)) ) goto done;
    if ( intrinsic->collectionAbi == XL6_IR_COLLECTION_ARRAY ||
         intrinsic->collectionAbi == XL6_IR_COLLECTION_LIST ) {
        if ( operandType->cAbi != XL6_IR_C_ABI_I64 ) goto done;
        operands[1] = xl6IrLowerNode(ctx, operandId);
    } else if ( intrinsic->collectionAbi == XL6_IR_COLLECTION_DICT ) {
        if ( operandType->cAbi != XL6_IR_C_ABI_MANAGED_STRING ) goto done;
        operands[1] = xl6IrLowerNode(ctx, operandId);
        operands[1] = xl6IrLowerBorrowManagedStringOperand(
            ctx, origin, operandNode, operands[1], &operandTemporary);
        operandStorageType = operandNode->storageType;
    } else {
        XL6_IrValueId loaded = XL6_IR_VALUE_INVALID;
        operandStorageType = xl6IrCollectionBoxedElementType(
            ctx->module, intrinsic->receiverType);
        operands[1] = xl6IrLowerNodeAsRuntimeXValue(
            ctx, origin, operandId, operandNode, operandStorageType);
        operandTemporary = xl6IrLowerNewTempStorage(
            ctx, operandStorageType, origin);
        if ( operands[1] != XL6_IR_VALUE_INVALID && operandTemporary != 0 &&
             xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, operandStorageType,
                             operandTemporary, &operands[1], 1, NULL) &&
             xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, operandStorageType,
                             operandTemporary, NULL, 0, &loaded) )
            operands[1] = loaded;
        else
            operands[1] = XL6_IR_VALUE_INVALID;
    }
    if ( operands[1] == XL6_IR_VALUE_INVALID ||
         (operandTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, origin, operandTemporary, operands[1], 0, 0)) ) goto done;
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, call->storageType,
        XL6_IR_RUNTIME_XVALUE_COLLECTION_REMOVE, operands, 2);
    if ( *result == XL6_IR_VALUE_INVALID ) goto done;
    ctx->module->instructions[ctx->module->instructionCount - 1].collectionAbi =
        intrinsic->collectionAbi;
    if (!xl6IrLowerCompleteEvaluationBorrows(ctx, origin, evaluationOwnerFirst, result)) goto done;
    status = 1;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return status;
}

/* Dynamic collection dispatch remains dynamic only in its receiver tag.  The
 * member spelling, arity, argument ownership and owned result ABI are already
 * fixed by the Typed intrinsic.  All explicit arguments become fresh owned
 * xvalues and are consumed by the single lowered runtime operation. */
static int xl6IrLowerIntrinsicDynamicCollectionMember(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* call,
    const XL6_IrIntrinsicCall* intrinsic, XL6_IrValueId* result)
{
    const XL6_IrNode* receiver;
    XL6_IrValueId operands[3];
    XL6_SymbolId receiverTemporary = 0;
    size_t i, evaluationFirst = ctx->evaluationOwnerCount, argumentFirst;
    if ( ctx == NULL || call == NULL || intrinsic == NULL || result == NULL ||
         intrinsic->kind != XL6_IR_INTRINSIC_DYNAMIC_COLLECTION_MEMBER ||
         intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ||
         intrinsic->receiver == XL6_IR_NODE_INVALID ||
         intrinsic->receiverType == XL6_IR_TYPE_INVALID ||
         intrinsic->resultType != call->storageType ||
         intrinsic->resultAbi != XL6_IR_INTRINSIC_RESULT_OWNED ||
         intrinsic->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE ||
         intrinsic->collectionAbi != XL6_IR_COLLECTION_NONE ||
         !xl6IrDynamicCollectionOpOperandCountValid(
             intrinsic->dynamicCollectionOp, intrinsic->operandCount) ||
         intrinsic->operandCount > 2 ||
         intrinsic->firstOperand + intrinsic->operandCount <
             intrinsic->firstOperand ||
         intrinsic->firstOperand + intrinsic->operandCount >
             ctx->module->intrinsicOperandCount ) return 0;
    receiver = xl6IrNodeGet(ctx->module, intrinsic->receiver);
    if ( receiver == NULL ||
         receiver->storageType != intrinsic->receiverType ||
         !xl6IrLowerTypeIsDynamicXValueBuiltin(
             ctx->module, intrinsic->receiverType) ||
         !xl6IrLowerTypeIsDynamicXValueBuiltin(
             ctx->module, intrinsic->resultType) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR dynamic collection member has no exact open xvalue receiver or result ABI");
        return -1;
    }
    operands[0] = xl6IrLowerNode(ctx, intrinsic->receiver);
    operands[0] = xl6IrLowerBorrowRuntimeXValueOperand(
        ctx, origin, receiver, operands[0], &receiverTemporary);
    if ( operands[0] == XL6_IR_VALUE_INVALID ||
         (receiverTemporary != 0 && !xl6IrLowerProtectEvaluationStorage(
             ctx, origin, receiverTemporary, operands[0], 0, 0)) ) return -1;
    argumentFirst = ctx->evaluationOwnerCount;
    for ( i = 0; i < intrinsic->operandCount; ++i ) {
        const XL6_IrIntrinsicOperand* binding =
            &ctx->module->intrinsicOperands[intrinsic->firstOperand + i];
        const XL6_IrNode* argument =
            xl6IrNodeGet(ctx->module, binding->expression);
        if ( binding->abi != XL6_IR_INTRINSIC_OPERAND_CONSUME ||
             argument == NULL || argument->storageType != binding->type ||
             !xl6IrTypeCanBoxRuntimeXValue(
                 ctx->module, binding->type) ) {
            xl6IrLowerDiag(ctx, origin,
                "XLIR dynamic collection member argument has no consumed boxed xvalue ABI");
            return -1;
        }
        operands[i + 1] = xl6IrLowerNodeAsRuntimeXValue(
            ctx, origin, binding->expression, argument,
            intrinsic->receiverType);
        if ( operands[i + 1] == XL6_IR_VALUE_INVALID ) return -1;
        operands[i + 1] = xl6IrLowerProtectEvaluationValue(ctx, origin,
            intrinsic->receiverType, operands[i + 1]);
        if (operands[i + 1] == XL6_IR_VALUE_INVALID) return -1;
    }
    if (!xl6IrLowerCommitEvaluationOwners(ctx, origin, argumentFirst)) return -1;
    *result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, intrinsic->resultType,
        XL6_IR_RUNTIME_XVALUE_DYNAMIC_COLLECTION_METHOD,
        operands, intrinsic->operandCount + 1);
    if ( *result == XL6_IR_VALUE_INVALID ) return -1;
    ctx->module->instructions[ctx->module->instructionCount - 1]
        .dynamicCollectionOp = intrinsic->dynamicCollectionOp;
    if (!xl6IrLowerCompleteEvaluationBorrows(ctx, origin, evaluationFirst, result)) return -1;
    return 1;
}

static XL6_IrRuntimeOp xl6IrLowerCheckedIntegerRuntimeOp(XL6_IrOpcode opcode)
{
    switch ( opcode ) {
    case XL6_IR_OPCODE_DIV: return XL6_IR_RUNTIME_INTEGER_DIV_CHECKED;
    case XL6_IR_OPCODE_MOD: return XL6_IR_RUNTIME_INTEGER_MOD_CHECKED;
    case XL6_IR_OPCODE_SHL: return XL6_IR_RUNTIME_INTEGER_SHL_CHECKED;
    case XL6_IR_OPCODE_SHR: return XL6_IR_RUNTIME_INTEGER_SHR_CHECKED;
    default: return XL6_IR_RUNTIME_NONE;
    }
}

/* Checked scalar arithmetic owns its failure CFG in Lowered XLIR.  The
 * RuntimeOp carries the semantic operation, integerTarget carries exact
 * width/signedness, and ERROR_TEST is adjacent to the operation.  Backends do
 * not trace operand definitions or reinterpret a physical BINARY opcode. */
static XL6_IrValueId xl6IrLowerEmitCheckedIntegerArithmetic(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    XL6_IrTypeId type, XL6_IrOpcode opcode,
    XL6_IrValueId left, XL6_IrValueId right)
{
    const XL6_IrType* integerType = xl6IrTypeGet(&ctx->module->types, type);
    const XL6_IrExitPlan* errorPlan;
    XL6_IrRuntimeOp runtimeOp = xl6IrLowerCheckedIntegerRuntimeOp(opcode);
    XL6_IrValueId operands[2];
    XL6_IrValueId result;
    XL6_IrBlockId successBlock = XL6_IR_BLOCK_INVALID;
    XL6_IrBlockId failureBlock = XL6_IR_BLOCK_INVALID;
    XL6_IrInstruction* operation;
    XL6_IrInstruction* errorTest;
    if ( ctx == NULL || node == NULL || integerType == NULL ||
         integerType->integerTarget == XL6_IR_INTEGER_TARGET_INVALID ||
         runtimeOp == XL6_IR_RUNTIME_NONE ||
         node->operatorErrorAbi != XL6_IR_ERROR_ABI_MAY_RAISE ||
         xl6IrLowerValueType(ctx, left) != type ||
         xl6IrLowerValueType(ctx, right) != type ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR checked integer arithmetic has no exact operand, target and failure ABI");
        return XL6_IR_VALUE_INVALID;
    }
    operands[0] = left;
    operands[1] = right;
    result = xl6IrLowerEmitRuntimeCall(
        ctx, origin, type, runtimeOp, operands, 2);
    if ( result == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
    operation = &ctx->module->instructions[ctx->module->instructionCount - 1];
    operation->integerTarget = integerType->integerTarget;
    errorPlan = xl6IrLowerExitPlan(ctx, origin, XL6_SEM_EXIT_THROW);
    if ( errorPlan == NULL ||
         !xl6IrLowerNewBlock(ctx, &successBlock) ||
         !xl6IrLowerNewBlock(ctx, &failureBlock) ||
         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_TEST, origin,
                          XL6_IR_TYPE_INVALID, 0, &result, 1, NULL) ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR checked integer arithmetic has no explicit failure CFG ABI");
        return XL6_IR_VALUE_INVALID;
    }
    errorTest = &ctx->module->instructions[ctx->module->instructionCount - 1];
    errorTest->trueTarget = successBlock;
    errorTest->falseTarget = failureBlock;
    xl6IrLowerEnterBlock(ctx, failureBlock);
    if ( !xl6IrLowerEmitExceptionTransfer(ctx, origin, node, errorPlan, 0) )
        return XL6_IR_VALUE_INVALID;
    xl6IrLowerEnterBlock(ctx, successBlock);
    return result;
}

/* Compound assignment is one typed read-modify-write operation regardless of
 * whether its destination is direct storage or a class field.  This helper
 * owns the scalar operator ABI; destination-specific lowering only supplies
 * the previous value and commits the returned value. */
static XL6_IrValueId xl6IrLowerScalarCompoundValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    XL6_IrTypeId type, XL6_IrValueId previous, XL6_IrValueId rhs)
{
    const XL6_IrType* targetType = xl6IrTypeGet(&ctx->module->types, type);
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    int valid = node != NULL && node->opcode != XL6_IR_OPCODE_INVALID &&
        targetType != NULL &&
        targetType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
        (targetType->cAbi == XL6_IR_C_ABI_I64 ||
         targetType->cAbi == XL6_IR_C_ABI_U64 ||
         targetType->cAbi == XL6_IR_C_ABI_F64) &&
        !(targetType->cAbi == XL6_IR_C_ABI_F64 &&
          node->opcode != XL6_IR_OPCODE_ADD &&
          node->opcode != XL6_IR_OPCODE_SUB &&
          node->opcode != XL6_IR_OPCODE_MUL &&
          node->opcode != XL6_IR_OPCODE_DIV) &&
        xl6IrLowerValueType(ctx, previous) == type;

    if ( valid && node->opcode == XL6_IR_OPCODE_POW ) {
        XL6_IrValueId operands[2];
        valid = node->operatorErrorAbi == XL6_IR_ERROR_ABI_NO_RAISE &&
            targetType->cAbi == XL6_IR_C_ABI_I64 &&
            targetType->integerTarget == XL6_IR_INTEGER_TARGET_SIGNED_64 &&
            xl6IrLowerValueType(ctx, rhs) == type;
        operands[0] = previous;
        operands[1] = rhs;
        if ( valid )
            result = xl6IrLowerEmitRuntimeCall(
                ctx, origin, type, XL6_IR_RUNTIME_I64_POW, operands, 2);
        valid = valid && result != XL6_IR_VALUE_INVALID;
    } else if ( valid &&
                node->operatorErrorAbi == XL6_IR_ERROR_ABI_MAY_RAISE &&
                xl6IrLowerCheckedIntegerRuntimeOp(node->opcode) !=
                    XL6_IR_RUNTIME_NONE &&
                targetType->integerTarget != XL6_IR_INTEGER_TARGET_INVALID ) {
        valid = xl6IrLowerValueType(ctx, rhs) == type;
        if ( valid )
            result = xl6IrLowerEmitCheckedIntegerArithmetic(
                ctx, origin, node, type, node->opcode, previous, rhs);
        valid = valid && result != XL6_IR_VALUE_INVALID;
    } else if ( valid && targetType->integerTarget >=
                          XL6_IR_INTEGER_TARGET_SIGNED_8 &&
                targetType->integerTarget <=
                          XL6_IR_INTEGER_TARGET_UNSIGNED_32 ) {
        XL6_IrTypeId promotedType = xl6IrLowerFindIntegerType(
            ctx->module, XL6_IR_INTEGER_TARGET_SIGNED_64);
        XL6_IrTypeId rhsType = xl6IrLowerValueType(ctx, rhs);
        const XL6_IrType* rhsInteger = xl6IrTypeGet(
            &ctx->module->types, rhsType);
        XL6_IrValueId promotedPrevious;
        XL6_IrValueId promotedRhs = rhs;
        /* Add/sub/mul are closed under final modulo normalization.  Division,
         * remainder and shifts need separately fixed promotion/failure ABIs. */
        valid = promotedType != XL6_IR_TYPE_INVALID &&
            (node->opcode == XL6_IR_OPCODE_ADD ||
             node->opcode == XL6_IR_OPCODE_SUB ||
             node->opcode == XL6_IR_OPCODE_MUL) &&
            rhsInteger != NULL && rhsInteger->cAbi == XL6_IR_C_ABI_I64;
        promotedPrevious = valid
            ? xl6IrLowerEmitScalarConvert(
                ctx, origin, type, promotedType, previous)
            : XL6_IR_VALUE_INVALID;
        if ( valid && rhsType != promotedType )
            promotedRhs = xl6IrLowerEmitScalarConvert(
                ctx, origin, rhsType, promotedType, rhs);
        valid = valid && promotedPrevious != XL6_IR_VALUE_INVALID &&
            promotedRhs != XL6_IR_VALUE_INVALID;
        if ( valid )
            result = xl6IrLowerEmitBinary(
                ctx, origin, promotedType, node->opcode,
                promotedPrevious, promotedRhs);
        if ( valid && result != XL6_IR_VALUE_INVALID )
            result = xl6IrLowerEmitIntegerStorageNormalize(
                ctx, origin, type, result);
        valid = valid && result != XL6_IR_VALUE_INVALID;
    } else if ( valid ) {
        valid = xl6IrLowerValueType(ctx, rhs) == type;
        if ( valid )
            result = xl6IrLowerEmitBinary(
                ctx, origin, type, node->opcode, previous, rhs);
        valid = valid && result != XL6_IR_VALUE_INVALID;
    }
    if ( !valid ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR compound assignment has no exact scalar read/operator/write ABI");
        return XL6_IR_VALUE_INVALID;
    }
    return result;
}

/* A class overload selected for compound assignment is an ordinary verified
 * CallTarget with the previous value as its receiver.  The semantic phase has
 * already fixed compoundOperatorSymbol; this path never searches for
 * __add__/__sub__ (or any other magic spelling). */
static XL6_IrValueId xl6IrLowerOverloadedCompoundValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* assignment,
    const XL6_IrNode* previousNode, XL6_IrValueId previous,
    XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    const XL6_IrCallTarget* target;
    const XL6_IrClassDispatchSlot* slot = NULL;
    XL6_IrValueId operands[2];
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    XL6_SymbolId temporaries[2] = {0, 0};
    size_t evaluationFirst = ctx->evaluationOwnerCount;
    size_t dispatchSlot;
    XL6_IrTypeId rhsType;
    XL6_IrParameterAbi rhsAbi;
    int emitted;
    if ( ctx == NULL || assignment == NULL || previousNode == NULL ||
         rhs == NULL || assignment->compoundOperatorSymbol == 0 ||
         assignment->opcode == XL6_IR_OPCODE_INVALID ||
         (target = xl6IrCallTargetGet(
              ctx->module, assignment->compoundOperatorSymbol)) == NULL ||
         target->kind != XL6_IR_CALL_TARGET_INTERNAL ||
         (target->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE &&
          target->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE) ||
         assignment->operatorErrorAbi != XL6_IR_ERROR_ABI_NO_RAISE ||
         target->returnType != previousNode->storageType ||
         target->parameterCount != 2 || target->parameterTypes == NULL ||
         target->parameterAbis == NULL ||
         target->parameterTypes[0] != previousNode->storageType ||
         target->parameterAbis[0] != XL6_IR_PARAMETER_ABI_BORROW ||
         xl6IrLowerValueType(ctx, previous) != previousNode->storageType ) {
        xl6IrLowerDiag(ctx, origin,
            "XLIR overloaded compound assignment has no exact synchronous CallTarget ABI");
        return XL6_IR_VALUE_INVALID;
    }
    rhsType = target->parameterTypes[1];
    rhsAbi = target->parameterAbis[1];
    /* The read value survives RHS evaluation even if that evaluation replaces
     * the original lvalue. Keep a separate owner through the call outcome. */
    operands[0] = xl6IrLowerAcquireValueOwner(ctx, origin, previous);
    temporaries[0] = xl6IrLowerNewTempStorage(ctx, previousNode->storageType, origin);
    if (operands[0] == XL6_IR_VALUE_INVALID || temporaries[0] == 0 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, previousNode->storageType,
            temporaries[0], &operands[0], 1, NULL) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, origin, previousNode->storageType,
            temporaries[0], NULL, 0, &operands[0]) ||
        !xl6IrLowerProtectEvaluationStorage(ctx, origin, temporaries[0], operands[0], 0, 0))
        return XL6_IR_VALUE_INVALID;
    operands[1] = xl6IrLowerNodeAsType(
        ctx, origin, rhsId, rhs, rhsType);
    operands[1] = xl6IrLowerPrepareOwnedCallArgument(
        ctx, origin, rhsType, rhsAbi,
        rhs, operands[1]);
    operands[1] = xl6IrLowerAnchorResolvedCallBorrow(
        ctx, origin, rhsId, rhs, rhsType,
        rhsAbi, operands[1], &temporaries[1]);
    if ( operands[1] == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
    target = xl6IrCallTargetGet(ctx->module, assignment->compoundOperatorSymbol);
    if (target == NULL) return XL6_IR_VALUE_INVALID;
    dispatchSlot = xl6IrLowerClassDispatchSlotByDeclarationSymbol(
        ctx->module, assignment->compoundOperatorSymbol);
    if ( dispatchSlot != SIZE_MAX ) {
        slot = &ctx->module->classDispatchSlots[dispatchSlot];
        if ( slot->returnType != target->returnType ||
             slot->parameterCount != 1 || slot->parameterTypes == NULL ||
             slot->parameterTypes[0] != target->parameterTypes[1] ) {
            xl6IrLowerDiag(ctx, origin,
                "XLIR overloaded compound assignment has no exact virtual dispatch slot ABI");
            return XL6_IR_VALUE_INVALID;
        }
    }
    ctx->evaluationOwnerCount = evaluationFirst;
    emitted = xl6IrLowerEmit(
        ctx, dispatchSlot != SIZE_MAX ? XL6_IR_INSTR_VIRTUAL_CALL
                                      : XL6_IR_INSTR_CALL,
        origin, target->returnType,
        dispatchSlot != SIZE_MAX ? 0 : target->symbol,
        operands, 2, &result);
    if ( emitted && dispatchSlot != SIZE_MAX )
        ctx->module->instructions[ctx->module->instructionCount - 1]
            .dispatchSlot = (uint32)(dispatchSlot + 1);
    if (emitted) {
        XL6_IrLowerCallCleanup cleanup = {temporaries, 2, NULL, 0, 0};
        emitted = xl6IrLowerCompleteCall(ctx, origin, assignment, target, &result, NULL, &cleanup);
    }
    return emitted ? result : XL6_IR_VALUE_INVALID;
}


/* The value operation is independent of the destination transaction. Its
 * input is an exact old value; the common scope owns snapshots across RHS
 * evaluation and leaves the new owner for the caller's typed commit. */
static XL6_IrValueId xl6IrLowerCompoundValue(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    const XL6_IrNode* lhs, XL6_IrValueId previous, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrTypeId type = lhs->storageType;
    const XL6_IrType* info = xl6IrTypeGet(&ctx->module->types, type);
    XL6_IrRuntimeOp operation;
    XL6_IrCAbi abi;
    int managed;
    if (info == NULL || previous == XL6_IR_VALUE_INVALID || xl6IrLowerValueType(ctx, previous) != type)
        return XL6_IR_VALUE_INVALID;
    if (node->compoundOperatorSymbol != 0)
        return xl6IrLowerOverloadedCompoundValue(ctx, origin, node, lhs, previous, rhsId, rhs);
    abi = info->cAbi;
    managed = info->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED;
    operation = xl6IrCollectionAlgebraRuntimeOp(
        &ctx->module->types, type, type, rhs->storageType, node->opcode);
    if (managed) {
        previous = xl6IrLowerAcquireValueOwner(ctx, origin, previous);
        previous = xl6IrLowerProtectOwnedBorrow(ctx, origin, previous);
        if (previous == XL6_IR_VALUE_INVALID) return previous;
    }
    if (abi == XL6_IR_C_ABI_MANAGED_STRING)
        return xl6IrLowerManagedStringConcatValue(
            ctx, origin, node, type, previous, rhsId, rhs, XL6_IR_VALUE_INVALID);
    if (operation != XL6_IR_RUNTIME_NONE) {
        XL6_IrValueId operands[2];
        XL6_IrErrorAbi errorAbi=operation==XL6_IR_RUNTIME_XVALUE_ARRAY_CONCAT
            ? XL6_IR_ERROR_ABI_MAY_RAISE : XL6_IR_ERROR_ABI_NO_RAISE;
        if (node->operatorErrorAbi != errorAbi ||
            !xl6IrCollectionAlgebraRuntimeSignatureValid(
                &ctx->module->types, operation, type, type, rhs->storageType)) {
            xl6IrLowerDiag(ctx, origin, "XLIR compound algebra requires an exact RuntimeOp signature");
            return XL6_IR_VALUE_INVALID;
        }
        operands[0] = previous;
        operands[1] = xl6IrLowerNode(ctx, rhsId);
        if (xl6IrLowerValueType(ctx, operands[1]) != rhs->storageType) return XL6_IR_VALUE_INVALID;
        operands[1] = xl6IrLowerProtectOwnedBorrow(ctx, origin, operands[1]);
        if (operands[1] == XL6_IR_VALUE_INVALID) return XL6_IR_VALUE_INVALID;
        return xl6IrLowerEmitRuntimeCall(ctx, origin, type, operation, operands, 2);
    } else {
        XL6_IrValueId rhsValue = xl6IrLowerNodeAsType(ctx, origin, rhsId, rhs, type);
        if (!managed && xl6IrLowerTypeIsRuntimeXValue(ctx->module, xl6IrLowerValueType(ctx, rhsValue))) {
            rhsValue = xl6IrLowerProtectOwnedBorrow(ctx, origin, rhsValue);
            rhsValue = rhsValue != XL6_IR_VALUE_INVALID
                ? xl6IrLowerProjectBorrowedXValueAsExactType(ctx, origin, rhsValue, type)
                : XL6_IR_VALUE_INVALID;
        }
        return xl6IrLowerScalarCompoundValue(ctx, origin, node, type, previous, rhsValue);
    }
}

static int xl6IrLowerStorageCompoundAssign(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerStorageTargetPlan plan;
    XL6_IrValueId previous, updated;
    size_t evaluationFirst = ctx->evaluationOwnerCount;
    int prepared = xl6IrLowerPrepareStorageTargetPlan(ctx, origin, lhs, &plan);
    if (prepared <= 0) return prepared;
    previous = xl6IrLowerReadStorageTargetPlan(ctx, origin, &plan);
    updated = xl6IrLowerCompoundValue(ctx, origin, node, lhs, previous, rhsId, rhs);
    return updated != XL6_IR_VALUE_INVALID &&
        xl6IrLowerWriteStorageTargetPlan(ctx, origin, &plan, updated) &&
        xl6IrLowerReleaseEvaluationBorrows(ctx, origin, evaluationFirst) ? 1 : -1;
}

/* One address acquisition encloses the same value operation used by direct
 * storage and properties; every exit keeps the exact receiver/key owners. */
static int xl6IrLowerElementCompoundAssign(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerElementTargetPlan plan;
    XL6_IrValueId previous, updated;
    if (ctx == NULL || node == NULL || lhs == NULL || rhs == NULL ||
        node->opcode == XL6_IR_OPCODE_INVALID ||
        (node->lvalueKind != XL6_SEM_LVALUE_INDEX && node->lvalueKind != XL6_SEM_LVALUE_FIELD &&
         node->lvalueKind != XL6_SEM_LVALUE_DYNAMIC_MEMBER)) return 0;
    if (!xl6IrLowerPrepareElementTargetPlan(ctx, origin, lhs, &plan)) return -1;
    previous = xl6IrLowerReadElementTargetPlan(ctx, ctx->module->children[node->firstChild], &plan, NULL);
    updated = xl6IrLowerCompoundValue(ctx, origin, node, lhs, previous, rhsId, rhs);
    if (updated == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerWriteElementTargetPlan(ctx, origin, &plan, updated, lhs)) {
        xl6IrLowerDisposeElementTargetPlan(&plan);
        return -1;
    }
    return 1;
}

/* Property access is a typed call transaction, not a second expression
 * evaluator. Freeze the logical argument vector before evaluation; GET and
 * SET project separate physical vectors from the same protected values. */
typedef struct XL6_IrLowerPropertyTargetPlan {
    XL6_IrNodeId propertyOrigin;
    XL6_IrNodeId setterOrigin;
    XL6_IrTypeId type;
    size_t accessCount;
    size_t evaluationFirst;
    XL6_IrNodeId* argumentIds;
    XL6_IrTypeId* argumentTypes;
    XL6_IrParameterAbi* argumentAbis;
    XL6_IrValueId* values;
    XL6_IrValueId* operands;
} XL6_IrLowerPropertyTargetPlan;

static void xl6IrLowerDisposePropertyTargetPlan(XL6_IrLowerPropertyTargetPlan* plan)
{
    xrtFree(plan->argumentIds); xrtFree(plan->argumentTypes); xrtFree(plan->argumentAbis);
    xrtFree(plan->values); xrtFree(plan->operands);
    memset(plan, 0, sizeof(*plan));
}

static int xl6IrLowerPropertyAccessorSignature(
    const XL6_IrModule* module, const XL6_IrPropertyAccessorSignature* signature,
    XL6_IrTypeId type, size_t accessCount, int setter)
{
    size_t i;
    if (signature->resultType != (setter ? XL6_IR_TYPE_INVALID : type) ||
        signature->parameterCount + 1 != accessCount + (setter ? 1u : 0u)) return 0;
    for (i = 0; i < signature->parameterCount; ++i) {
        const XL6_IrType* parameter = xl6IrTypeGet(&module->types, signature->parameterTypes[i]);
        XL6_IrParameterAbi abi = signature->parameterAbis[i];
        if (parameter == NULL ||
            (parameter->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL
                ? abi != XL6_IR_PARAMETER_ABI_VALUE
                : (parameter->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ||
                   (abi != XL6_IR_PARAMETER_ABI_BORROW && abi != XL6_IR_PARAMETER_ABI_OWNED)))) return 0;
    }
    return !setter || signature->parameterTypes[accessCount - 1] == type;
}

static int xl6IrLowerPreparePropertyTargetPlan(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_IrNodeId lhsId,
    const XL6_IrNode* lhs, XL6_SymbolId getterSymbol, XL6_SymbolId setterSymbol,
    XL6_IrLowerPropertyTargetPlan* plan)
{
    const XL6_IrCallSite* getter = getterSymbol != 0 || setterSymbol == 0
        ? xl6IrCallSiteGet(ctx->module, lhsId) : NULL;
    const XL6_IrCallSite* setter = setterSymbol != 0
        ? xl6IrCallSiteGet(ctx->module, origin) : NULL;
    const XL6_IrCallSite* access = getter != NULL ? getter : setter;
    XL6_IrPropertyAccessorSignature get = {0}, set = {0};
    const XL6_IrPropertyAccessorSignature* signature;
    size_t i;
    memset(plan, 0, sizeof(*plan));
    plan->evaluationFirst = ctx->evaluationOwnerCount;
    /* A container index following a zero-argument getter is not an accessor:
     * only the inner MEMBER owns its CallSite. No source-tree flattening. */
    if (lhs == NULL || access == NULL) return 0;
    /* A resolved __getField__/__item__ syntax site is a different operation,
     * not a property accessor. Dispatch by the explicit semantic kind before
     * asking for the property ABI; never poison that operation's own lowering. */
    if (getterSymbol == 0 && setterSymbol == 0 &&
        lhs->callKind != XL6_SEM_CALL_PROPERTY_GET && lhs->callKind != XL6_SEM_CALL_WITNESS) return 0;
    if ((getterSymbol != 0 && (getter == NULL || getter->targetSymbol != getterSymbol)) ||
        (setterSymbol != 0 && (setter == NULL || setter->targetSymbol != setterSymbol)) ||
        (getter != NULL && !xl6IrGetPropertyAccessorSignature(ctx->module, getter, &get)) ||
        (setter != NULL && !xl6IrGetPropertyAccessorSignature(ctx->module, setter, &set))) goto invalid;
    if (getter != NULL && setter != NULL &&
        (setter->preparedGetter != getter->origin || getter->receiver != setter->receiver ||
         get.receiverType != set.receiverType)) goto invalid;
    signature = getter != NULL ? &get : &set;
    plan->propertyOrigin = getter != NULL ? getter->origin : lhsId;
    plan->setterOrigin = setter != NULL ? setter->origin : XL6_IR_NODE_INVALID;
    plan->type = lhs->storageType;
    plan->accessCount = signature->parameterCount + (getter != NULL ? 1u : 0u);
    if ((getter != NULL && !xl6IrLowerPropertyAccessorSignature(
            ctx->module, &get, plan->type, plan->accessCount, 0)) ||
        (setter != NULL && !xl6IrLowerPropertyAccessorSignature(
            ctx->module, &set, plan->type, plan->accessCount, 1))) goto invalid;
    plan->argumentIds = (XL6_IrNodeId*)xrtCalloc(plan->accessCount, sizeof(*plan->argumentIds));
    plan->argumentTypes = (XL6_IrTypeId*)xrtCalloc(plan->accessCount, sizeof(*plan->argumentTypes));
    plan->argumentAbis = (XL6_IrParameterAbi*)xrtCalloc(plan->accessCount, sizeof(*plan->argumentAbis));
    plan->values = (XL6_IrValueId*)xrtCalloc(plan->accessCount, sizeof(*plan->values));
    plan->operands = (XL6_IrValueId*)xrtCalloc(plan->accessCount + 1, sizeof(*plan->operands));
    if (!plan->argumentIds || !plan->argumentTypes || !plan->argumentAbis || !plan->values || !plan->operands) {
        ctx->failed = 1; xl6IrLowerDisposePropertyTargetPlan(plan); return -1;
    }
    plan->argumentIds[0] = access->receiver;
    plan->argumentTypes[0] = signature->receiverType;
    plan->argumentAbis[0] = XL6_IR_PARAMETER_ABI_BORROW;
    for (i = 1; i < plan->accessCount; ++i) {
        const XL6_IrCallArgument* binding = &ctx->module->callArguments[access->firstArgument + i - 1];
        if (binding->source != XL6_IR_CALL_ARGUMENT_EXPLICIT || binding->parameter != i - 1 ||
            (getter != NULL && setter != NULL &&
             (get.parameterTypes[i - 1] != set.parameterTypes[i - 1] ||
              get.parameterAbis[i - 1] != set.parameterAbis[i - 1]))) goto invalid;
        plan->argumentTypes[i] = signature->parameterTypes[i - 1];
        plan->argumentAbis[i] = signature->parameterAbis[i - 1];
        plan->argumentIds[i] = binding->expression;
    }
    return 1;
invalid:
    xl6IrLowerDisposePropertyTargetPlan(plan);
    xl6IrLowerDiag(ctx, origin, "XLIR property transaction has no exact synchronous accessor signature");
    return -1;
}

static int xl6IrLowerEvaluatePropertyTargetPlan(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_IrLowerPropertyTargetPlan* plan)
{
    size_t i;
    for (i = 0; i < plan->accessCount; ++i) {
        const XL6_IrNode* argument = xl6IrNodeGet(ctx->module, plan->argumentIds[i]);
        if (argument == NULL) return 0;
        plan->values[i] = xl6IrLowerNodeAsType(ctx, origin, plan->argumentIds[i], argument, plan->argumentTypes[i]);
        if (xl6IrLowerValueType(ctx, plan->values[i]) != plan->argumentTypes[i]) return 0;
        /* Shared access operands outlive getter/RHS/setter and alias mutation.
         * Consuming accessor parameters receive separate owned references. */
        plan->values[i] = xl6IrLowerAcquireValueOwner(ctx, origin, plan->values[i]);
        plan->values[i] = xl6IrLowerProtectOwnedBorrow(ctx, origin, plan->values[i]);
        if (plan->values[i] == XL6_IR_VALUE_INVALID) return 0;
    }
    return 1;
}

static int xl6IrLowerEmitPropertyAccessor(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    XL6_IrLowerPropertyTargetPlan* plan, int setter, int terminal,
    XL6_IrValueId value, XL6_IrValueId* result)
{
    const XL6_IrCallSite* site = xl6IrCallSiteGet(ctx->module,
        setter ? plan->setterOrigin : plan->propertyOrigin);
    XL6_IrPropertyAccessorSignature signature;
    const XL6_IrCallTarget* target;
    XL6_IrInstructionKind kind;
    XL6_SymbolId symbol;
    uint32 dispatchSlot;
    size_t count = plan->accessCount + (setter ? 1u : 0u), i;
    size_t consumingFirst = ctx->evaluationOwnerCount;
    XL6_IrLowerCallCleanup intermediate = {0};
    if (site == NULL || !xl6IrGetPropertyAccessorSignature(ctx->module, site, &signature)) return 0;
    symbol = site->targetSymbol;
    dispatchSlot = site->dispatchSlot;
    kind = site->dispatchKind == XL6_IR_CALL_DISPATCH_PROTOCOL ? XL6_IR_INSTR_PROTOCOL_CALL
        : site->dispatchKind == XL6_IR_CALL_DISPATCH_CLASS ? XL6_IR_INSTR_VIRTUAL_CALL : XL6_IR_INSTR_CALL;
    memcpy(plan->operands, plan->values, plan->accessCount * sizeof(*plan->operands));
    if (setter) plan->operands[plan->accessCount] = value;
    for (i = 1; i < count; ++i) {
        if (signature.parameterAbis[i - 1] == XL6_IR_PARAMETER_ABI_OWNED) {
            plan->operands[i] = xl6IrLowerAcquireValueOwner(ctx, origin, plan->operands[i]);
            plan->operands[i] = xl6IrLowerProtectEvaluationValue(
                ctx, origin, signature.parameterTypes[i - 1], plan->operands[i]);
            if (plan->operands[i] == XL6_IR_VALUE_INVALID) return 0;
        }
    }
    target = kind != XL6_IR_INSTR_PROTOCOL_CALL ? xl6IrCallTargetGet(ctx->module, symbol) : NULL;
    if (target != NULL &&
        !xl6IrLowerProjectCallTargetPhysicalOperands(ctx, origin, target, plan->operands, count)) return 0;
    target = kind != XL6_IR_INSTR_PROTOCOL_CALL ? xl6IrCallTargetGet(ctx->module, symbol) : NULL;
    if (!xl6IrLowerCommitEvaluationOwners(ctx, origin, consumingFirst) ||
        !xl6IrLowerEmit(ctx, kind, origin, signature.resultType,
            kind == XL6_IR_INSTR_CALL ? symbol : 0, plan->operands, count,
            !setter || signature.errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE ? result : NULL)) return 0;
    if (kind != XL6_IR_INSTR_CALL)
        ctx->module->instructions[ctx->module->instructionCount - 1].dispatchSlot = dispatchSlot;
    return terminal
        ? xl6IrLowerCompleteEvaluationCall(ctx, origin, node, target, result, plan->evaluationFirst)
        : xl6IrLowerCompleteCall(ctx, origin, node, target, result, NULL, &intermediate);
}

static XL6_IrValueId xl6IrLowerResolvedPropertyGet(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node)
{
    XL6_IrLowerPropertyTargetPlan plan;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    int prepared = xl6IrLowerPreparePropertyTargetPlan(ctx, origin, origin, node, 0, 0, &plan);
    if (prepared <= 0) return XL6_IR_VALUE_INVALID;
    if (!xl6IrLowerEvaluatePropertyTargetPlan(ctx, origin, &plan) ||
        !xl6IrLowerEmitPropertyAccessor(ctx, plan.propertyOrigin,
            xl6IrNodeGet(ctx->module, plan.propertyOrigin), &plan, 0, 1, XL6_IR_VALUE_INVALID, &result))
        result = XL6_IR_VALUE_INVALID;
    ctx->evaluationOwnerCount = plan.evaluationFirst;
    xl6IrLowerDisposePropertyTargetPlan(&plan);
    return result;
}

/* A safe primitive-sequence read separates bounds absence from projection
 * failure. Length and ordinal are exact SSA values; checked UTF-8/scalar or
 * byte projection runs only in range and preserves its ordinary error edge. */
static XL6_IrValueId xl6IrLowerSafeSequenceIndex(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    XL6_IrValueId preparedReceiver)
{
    const XL6_IrNode* receiverNode = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
    const XL6_IrNode* key = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
    const XL6_IrType* resultType = xl6IrTypeGet(&ctx->module->types, node->storageType);
    const XL6_IrType* receiverType;
    XL6_IrTypeId integer = xl6IrLowerFindIntegerType(ctx->module, XL6_IR_INTEGER_TARGET_SIGNED_64);
    XL6_IrTypeId boolean = xl6IrLowerFindTypeByCAbi(ctx->module, XL6_IR_C_ABI_BOOL);
    XL6_IrValueId operands[2], count, zero, negative, inRange, result = XL6_IR_VALUE_INVALID;
    XL6_IrBlockId rangeBlock, presentBlock, absentBlock, mergeBlock;
    XL6_SymbolId storage;
    size_t first = ctx->evaluationOwnerCount;
    operands[0] = preparedReceiver;
    if (operands[0] == XL6_IR_VALUE_INVALID) {
        operands[0] = xl6IrLowerNode(ctx, ctx->module->children[node->firstChild]);
        operands[0] = xl6IrLowerAcquireValueOwner(ctx, origin, operands[0]);
        operands[0] = xl6IrLowerProtectOwnedBorrow(ctx, origin, operands[0]);
    }
    receiverType = xl6IrTypeGet(&ctx->module->types, xl6IrLowerValueType(ctx, operands[0]));
    if (receiverNode == NULL || key == NULL || receiverType == NULL || resultType == NULL ||
        resultType->kind != XL6_IR_TYPE_NULLABLE || resultType->paramCount != 1 ||
        resultType->params == NULL || integer == XL6_IR_TYPE_INVALID || boolean == XL6_IR_TYPE_INVALID ||
        (receiverType->cAbi != XL6_IR_C_ABI_MANAGED_STRING &&
         receiverType->cAbi != XL6_IR_C_ABI_MANAGED_BYTES)) goto done;
    operands[1] = xl6IrLowerNodeAsType(ctx, origin, ctx->module->children[node->firstChild + 1], key, integer);
    count = xl6IrLowerEmitRuntimeCall(ctx, origin, integer,
        receiverType->cAbi == XL6_IR_C_ABI_MANAGED_STRING
            ? XL6_IR_RUNTIME_STRING_UTF8_COUNT : XL6_IR_RUNTIME_BYTES_LENGTH, operands, 1);
    zero = xl6IrLowerEmitIntConst(ctx, origin, integer, "0");
    negative = xl6IrLowerEmitBinary(ctx, origin, boolean, XL6_IR_OPCODE_LT, operands[1], zero);
    storage = xl6IrLowerNewTempStorage(ctx, node->storageType, origin);
    if (count == XL6_IR_VALUE_INVALID || negative == XL6_IR_VALUE_INVALID || storage == 0 ||
        !xl6IrLowerNewBlock(ctx, &rangeBlock) || !xl6IrLowerNewBlock(ctx, &presentBlock) ||
        !xl6IrLowerNewBlock(ctx, &absentBlock) || !xl6IrLowerNewBlock(ctx, &mergeBlock) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, origin, XL6_IR_TYPE_INVALID, 0, &negative, 1, NULL)) goto done;
    ctx->module->instructions[ctx->module->instructionCount - 1].trueTarget = absentBlock;
    ctx->module->instructions[ctx->module->instructionCount - 1].falseTarget = rangeBlock;
    xl6IrLowerEnterBlock(ctx, rangeBlock);
    inRange = xl6IrLowerEmitBinary(ctx, origin, boolean, XL6_IR_OPCODE_LT, operands[1], count);
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, origin, XL6_IR_TYPE_INVALID, 0, &inRange, 1, NULL)) goto done;
    ctx->module->instructions[ctx->module->instructionCount - 1].trueTarget = presentBlock;
    ctx->module->instructions[ctx->module->instructionCount - 1].falseTarget = absentBlock;
    xl6IrLowerEnterBlock(ctx, presentBlock);
    result = xl6IrLowerEmitRuntimeCall(ctx, origin, resultType->params[0],
        receiverType->cAbi == XL6_IR_C_ABI_MANAGED_STRING
            ? XL6_IR_RUNTIME_STRING_SCALAR_AT : XL6_IR_RUNTIME_BYTES_AT, operands, 2);
    if (result == XL6_IR_VALUE_INVALID || !xl6IrLowerEmitRuntimeErrorEdge(ctx, origin, node, result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_WRAP, origin, node->storageType, 0, &result, 1, &result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, storage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;
    xl6IrLowerEnterBlock(ctx, absentBlock);
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, origin, node->storageType, 0, NULL, 0, &result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, storage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;
    xl6IrLowerEnterBlock(ctx, mergeBlock);
    result = xl6IrLowerReadJoinStorage(ctx, origin, node->storageType, storage);
    if (result != XL6_IR_VALUE_INVALID &&
        !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, &result)) result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = first;
    return result;
}

/* The source key is lowered only in the present block. The prepared receiver
 * is an independent owner, so evaluating that key may replace the source slot
 * or throw without invalidating the lookup. Result projection/retention stays
 * in the existing typed index emitters, not in Cgen or a library wrapper. */
static XL6_IrValueId xl6IrLowerSafeIndexReceiverGate(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node)
{
    XL6_IrLowerEvaluationOwner receiverOwner;
    const XL6_IrNode* key;
    const XL6_IrType* receiverType;
    XL6_IrTypeId boolean;
    XL6_IrValueId receiver, presentReceiver, isNull, result = XL6_IR_VALUE_INVALID;
    XL6_IrBlockId presentBlock, nullBlock, mergeBlock;
    XL6_SymbolId resultStorage;
    size_t first = ctx->evaluationOwnerCount;
    int ok = 0;
    key = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
    receiver = xl6IrLowerNode(ctx, ctx->module->children[node->firstChild]);
    receiverType = xl6IrTypeGet(&ctx->module->types, xl6IrLowerValueType(ctx, receiver));
    if (key == NULL || receiverType == NULL) goto done;
    receiver = xl6IrLowerAcquireValueOwner(ctx, origin, receiver);
    receiver = xl6IrLowerProtectOwnedBorrow(ctx, origin, receiver);
    boolean = xl6IrLowerFindTypeByCAbi(ctx->module, XL6_IR_C_ABI_BOOL);
    resultStorage = xl6IrLowerNewTempStorage(ctx, node->storageType, origin);
    if (receiver == XL6_IR_VALUE_INVALID || boolean == XL6_IR_TYPE_INVALID ||
        resultStorage == 0 || ctx->evaluationOwnerCount != first + 1 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, origin, boolean, 0, &receiver, 1, &isNull) ||
        !xl6IrLowerNewBlock(ctx, &presentBlock) || !xl6IrLowerNewBlock(ctx, &nullBlock) ||
        !xl6IrLowerNewBlock(ctx, &mergeBlock) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, origin, XL6_IR_TYPE_INVALID, 0, &isNull, 1, NULL)) goto done;
    receiverOwner = ctx->evaluationOwners[first];
    ctx->module->instructions[ctx->module->instructionCount - 1].trueTarget = nullBlock;
    ctx->module->instructions[ctx->module->instructionCount - 1].falseTarget = presentBlock;
    xl6IrLowerEnterBlock(ctx, presentBlock);
    presentReceiver = receiver;
    if (node->indexReceiverGate == XL6_IR_INDEX_RECEIVER_NULLABLE) {
        if (receiverType->kind != XL6_IR_TYPE_NULLABLE || receiverType->paramCount != 1 ||
            receiverType->params == NULL ||
            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_UNWRAP, origin, receiverType->params[0],
                0, &receiver, 1, &presentReceiver)) goto done;
    }
    if (xl6IrLowerTypeIsManagedString(ctx->module, xl6IrLowerValueType(ctx, presentReceiver)) ||
        xl6IrLowerTypeIsManagedBytes(ctx->module, xl6IrLowerValueType(ctx, presentReceiver)))
        result = xl6IrLowerSafeSequenceIndex(ctx, origin, node, presentReceiver);
    else if (xl6IrLowerTypeIsManagedString(ctx->module, key->storageType) ||
        xl6IrLowerTypeIsRuntimeXValue(ctx->module, key->storageType))
        result = xl6IrLowerRuntimeXValueKeyRead(ctx, origin, node, presentReceiver);
    else result = xl6IrLowerRuntimeXValueIndexI64(ctx, origin, node, presentReceiver);
    if (result == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, &result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, resultStorage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;
    xl6IrLowerEnterBlock(ctx, nullBlock);
    ctx->evaluationOwners[first] = receiverOwner;
    ctx->evaluationOwnerCount = first + 1;
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, origin, node->storageType, 0, NULL, 0, &result) ||
        !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, &result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, resultStorage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;
    xl6IrLowerEnterBlock(ctx, mergeBlock);
    result = xl6IrLowerReadJoinStorage(ctx, origin, node->storageType, resultStorage);
    ok = result != XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = first;
    if (!ok) {
        xl6IrLowerDiag(ctx, origin, "XLIR safe index has no exact receiver gate, key or lifted result ABI");
        return XL6_IR_VALUE_INVALID;
    }
    return result;
}

/* Nullable getter invocation is a normal accessor transaction behind a CFG
 * gate. The receiver owner spans both successors, so alias mutation and a
 * throwing getter cannot invalidate it. Neither backend nor a library wrapper
 * has to rediscover the member, repeat its receiver, or guess a null result. */
static XL6_IrValueId xl6IrLowerNullablePropertyGet(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* node,
    const XL6_IrCallSite* site)
{
    XL6_IrPropertyAccessorSignature signature;
    XL6_IrLowerPropertyTargetPlan plan;
    XL6_IrLowerEvaluationOwner receiverOwner;
    XL6_IrNode invocation = *node;
    const XL6_IrType* nullable;
    XL6_IrTypeId receiverType, elementType, boolean;
    XL6_IrValueId receiver, isNull, result = XL6_IR_VALUE_INVALID;
    XL6_IrBlockId presentBlock, nullBlock, mergeBlock;
    XL6_SymbolId resultStorage;
    size_t first = ctx->evaluationOwnerCount;
    int ok = 0;
    memset(&plan, 0, sizeof(plan));
    if (site == NULL || site->receiverGate != XL6_IR_CALL_RECEIVER_NULLABLE_GETTER ||
        !xl6IrGetPropertyAccessorSignature(ctx->module, site, &signature) ||
        signature.parameterCount != 0) goto done;
    invocation.type = invocation.storageType = signature.resultType;
    if (xl6IrLowerPreparePropertyTargetPlan(ctx, origin, origin, &invocation, 0, 0, &plan) <= 0)
        goto done;
    receiver = xl6IrLowerNode(ctx, site->receiver);
    receiverType = xl6IrLowerValueType(ctx, receiver);
    nullable = xl6IrTypeGet(&ctx->module->types, receiverType);
    if (nullable == NULL || nullable->kind != XL6_IR_TYPE_NULLABLE ||
        nullable->paramCount != 1 || nullable->params == NULL) goto done;
    elementType = nullable->params[0];
    receiver = xl6IrLowerAcquireValueOwner(ctx, origin, receiver);
    receiver = xl6IrLowerProtectOwnedBorrow(ctx, origin, receiver);
    boolean = xl6IrLowerFindTypeByCAbi(ctx->module, XL6_IR_C_ABI_BOOL);
    resultStorage = xl6IrLowerNewTempStorage(ctx, node->storageType, origin);
    if (receiver == XL6_IR_VALUE_INVALID || boolean == XL6_IR_TYPE_INVALID ||
        resultStorage == 0 || ctx->evaluationOwnerCount != first + 1 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, origin, boolean, 0, &receiver, 1, &isNull) ||
        !xl6IrLowerNewBlock(ctx, &presentBlock) || !xl6IrLowerNewBlock(ctx, &nullBlock) ||
        !xl6IrLowerNewBlock(ctx, &mergeBlock) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, origin, XL6_IR_TYPE_INVALID, 0, &isNull, 1, NULL)) goto done;
    receiverOwner = ctx->evaluationOwners[first];
    ctx->module->instructions[ctx->module->instructionCount - 1].trueTarget = nullBlock;
    ctx->module->instructions[ctx->module->instructionCount - 1].falseTarget = presentBlock;
    xl6IrLowerEnterBlock(ctx, presentBlock);
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_UNWRAP, origin, elementType,
            0, &receiver, 1, &plan.values[0])) goto done;
    if (elementType != signature.receiverType)
        plan.values[0] = xl6IrLowerEmitValueCopy(ctx, origin, signature.receiverType, plan.values[0]);
    if (plan.values[0] == XL6_IR_VALUE_INVALID ||
        !xl6IrLowerEmitPropertyAccessor(ctx, origin, &invocation, &plan, 0, 1,
            XL6_IR_VALUE_INVALID, &result)) goto done;
    if (signature.resultType != node->storageType &&
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_WRAP, origin, node->storageType,
            0, &result, 1, &result)) goto done;
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, resultStorage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;

    xl6IrLowerEnterBlock(ctx, nullBlock);
    ctx->evaluationOwners[first] = receiverOwner;
    ctx->evaluationOwnerCount = first + 1;
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, origin, node->storageType, 0, NULL, 0, &result) ||
        !xl6IrLowerCompleteEvaluationBorrows(ctx, origin, first, &result) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, origin, node->storageType, resultStorage, &result, 1, NULL) ||
        !xl6IrLowerEmitJump(ctx, origin, mergeBlock)) goto done;
    xl6IrLowerEnterBlock(ctx, mergeBlock);
    result = xl6IrLowerReadJoinStorage(ctx, origin, node->storageType, resultStorage);
    ok = result != XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = first;
    xl6IrLowerDisposePropertyTargetPlan(&plan);
    if (!ok) {
        xl6IrLowerDiag(ctx, origin, "XLIR nullable getter has no exact receiver gate, accessor or lifted result ABI");
        return XL6_IR_VALUE_INVALID;
    }
    return result;
}

/* Protocol requirements have a separate witness-slot ABI, not class accessor
 * CallTargets. Route them by their explicit semantic kind before evaluating
 * the RHS; never retry a failed class setter as protocol syntax. */
static int xl6IrLowerProtocolPropertySet(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* assignment,
    const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    const XL6_IrCallSite* site = xl6IrCallSiteGet(ctx->module, origin);
    (void)lhs; (void)rhsId; (void)rhs;
    if (assignment->callKind != XL6_SEM_CALL_WITNESS) return 0;
    (void)xl6IrLowerProtocolInvocation(ctx, origin, assignment, site);
    return ctx->failed ? -1 : 1;
}

static int xl6IrLowerResolvedPropertySet(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* assignment,
    XL6_IrNodeId lhsId, const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerPropertyTargetPlan plan;
    XL6_IrValueId value, result = XL6_IR_VALUE_INVALID;
    int prepared, ok = 0;
    if (assignment->callKind != XL6_SEM_CALL_PROPERTY_SET || assignment->targetSymbol == 0) return 0;
    prepared = xl6IrLowerPreparePropertyTargetPlan(ctx, origin, lhsId, lhs, 0, assignment->targetSymbol, &plan);
    if (prepared <= 0) return prepared;
    /* '=' evaluates its RHS before receiver/key expressions, exactly once.
     * Acquire it before those expressions can replace a borrowed source. */
    value = xl6IrLowerNodeAsType(ctx, origin, rhsId, rhs, plan.type);
    value = xl6IrLowerAcquireValueOwner(ctx, origin, value);
    value = xl6IrLowerProtectOwnedBorrow(ctx, origin, value);
    if (value != XL6_IR_VALUE_INVALID && xl6IrLowerValueType(ctx, value) == plan.type &&
        xl6IrLowerEvaluatePropertyTargetPlan(ctx, origin, &plan))
        ok = xl6IrLowerEmitPropertyAccessor(ctx, origin, assignment, &plan, 1, 1, value, &result);
    ctx->evaluationOwnerCount = plan.evaluationFirst;
    xl6IrLowerDisposePropertyTargetPlan(&plan);
    return ok ? 1 : -1;
}

static int xl6IrLowerResolvedPropertyCompoundAssign(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* assignment,
    XL6_IrNodeId lhsId, const XL6_IrNode* lhs, XL6_IrNodeId rhsId, const XL6_IrNode* rhs)
{
    XL6_IrLowerPropertyTargetPlan plan;
    const XL6_IrNode* property = lhs;
    XL6_IrValueId previous = XL6_IR_VALUE_INVALID, updated, result = XL6_IR_VALUE_INVALID;
    int prepared, ok = 0;
    if (!xl6IrNodeIsPropertyUpdate(assignment) || assignment->targetSymbol == 0 ||
        property == NULL || (property->callKind != XL6_SEM_CALL_PROPERTY_GET &&
        property->callKind != XL6_SEM_CALL_WITNESS) || property->targetSymbol == 0)
        return 0;
    prepared = xl6IrLowerPreparePropertyTargetPlan(ctx, origin, lhsId, lhs,
        property->targetSymbol, assignment->targetSymbol, &plan);
    if (prepared <= 0) return prepared;
    if (!xl6IrLowerEvaluatePropertyTargetPlan(ctx, origin, &plan) ||
        !xl6IrLowerEmitPropertyAccessor(ctx, plan.propertyOrigin,
            xl6IrNodeGet(ctx->module, plan.propertyOrigin), &plan, 0, 0, XL6_IR_VALUE_INVALID, &previous))
        goto cleanup;
    updated = xl6IrLowerCompoundValue(ctx, origin, assignment, lhs, previous, rhsId, rhs);
    if (updated == XL6_IR_VALUE_INVALID) goto cleanup;
    updated = xl6IrLowerAcquireValueOwner(ctx, origin, updated);
    updated = xl6IrLowerProtectOwnedBorrow(ctx, origin, updated);
    if (updated != XL6_IR_VALUE_INVALID && xl6IrLowerValueType(ctx, updated) == plan.type)
        ok = xl6IrLowerEmitPropertyAccessor(ctx, origin, assignment, &plan, 1, 1, updated, &result);
cleanup:
    ctx->evaluationOwnerCount = plan.evaluationFirst;
    xl6IrLowerDisposePropertyTargetPlan(&plan);
    return ok ? 1 : -1;
}

static XL6_IrValueId xl6IrLowerNumericEnumVariantMember(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node)
{
    const XL6_IrType* type = node != NULL
        ? xl6IrTypeGet(&ctx->module->types, node->storageType) : NULL;
    const XL6_IrEnumVariant* variant;
    if ( node == NULL || node->kind != XL6_IR_NODE_MEMBER ||
         type == NULL || type->kind != XL6_IR_TYPE_NUMERIC_ENUM ||
         node->targetSymbol == 0 ) return XL6_IR_VALUE_INVALID;
    /* A property's result can be an enum too. The resolved declaration, not
     * the expression's result type, establishes variant construction. Leave
     * getters/static fields to their already resolved access recipes. */
    if (node->targetSymbol >= ctx->module->symbolNodeCapacity) return XL6_IR_VALUE_INVALID;
    const XL6_IrNode* declaration=xl6IrNodeGet(ctx->module,ctx->module->symbolNodes[node->targetSymbol]);
    if (!declaration || declaration->kind != XL6_IR_NODE_ENUM_VARIANT) return XL6_IR_VALUE_INVALID;
    variant = xl6IrEnumVariantGet(
        ctx->module, node->storageType, node->targetSymbol, NULL);
    XL6_IrValueId result = xl6IrLowerNumericEnumConstant(ctx, id, variant);
    if ( result == XL6_IR_VALUE_INVALID ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR numeric enum variant has no canonical integer initializer ABI");
        return XL6_IR_VALUE_INVALID;
    }
    return result;
}

static XL6_IrValueId xl6IrLowerTaggedEnumVariantCall(
    XL6_IrLowerContext* ctx, XL6_IrNodeId id, const XL6_IrNode* node)
{
    const XL6_IrType* resultType = node != NULL
        ? xl6IrTypeGet(&ctx->module->types, node->storageType) : NULL;
    const XL6_IrEnumVariant* variant;
    const XL6_IrNode* arguments;
    XL6_IrTypeId dynamicType;
    XL6_IrTypeId boolType;
    XL6_IrValueId object;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    XL6_SymbolId objectStorage;
    size_t evaluationOwnerFirst;
    size_t variantIndex;
    size_t payloadOffset;
    if ( node == NULL || node->kind != XL6_IR_NODE_CALL ||
         node->callKind != XL6_SEM_CALL_ENUM_VARIANT ||
         node->childCount != 2 || node->targetSymbol == 0 ||
         resultType == NULL ||
         resultType->kind != XL6_IR_TYPE_TAGGED_ENUM ||
         resultType->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR ||
         resultType->ownershipAbi != XL6_IR_OWNERSHIP_ABI_MANAGED ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR tagged enum construction has no exact result and target ABI");
        return XL6_IR_VALUE_INVALID;
    }
    variant = xl6IrEnumVariantGet(
        ctx->module, node->storageType, node->targetSymbol, &variantIndex);
    arguments = xl6IrNodeGet(
        ctx->module, ctx->module->children[node->firstChild + 1]);
    dynamicType = xl6IrLowerFindDynamicBuiltinType(ctx->module);
    boolType = xl6IrLowerFindTypeByCAbi(
        ctx->module, XL6_IR_C_ABI_BOOL);
    if ( variant == NULL || arguments == NULL ||
         arguments->kind != XL6_IR_NODE_LIST ||
         arguments->childCount != variant->payloadCount ||
         dynamicType == XL6_IR_TYPE_INVALID ||
         boolType == XL6_IR_TYPE_INVALID ) {
        xl6IrLowerDiag(ctx, id,
            "XLIR tagged enum construction has no exact layout, arity or runtime ABI");
        return XL6_IR_VALUE_INVALID;
    }
    evaluationOwnerFirst = ctx->evaluationOwnerCount;
    object = xl6IrLowerEmitRuntimeCall(
        ctx, id, node->storageType,
        XL6_IR_RUNTIME_TAGGED_ENUM_NEW, NULL, 0);
    if ( object != XL6_IR_VALUE_INVALID ) {
        XL6_IrInstruction* instruction = &ctx->module->instructions[
            ctx->module->instructionCount - 1];
        instruction->enumVariant = variantIndex;
        if (!xl6IrLowerEmitRuntimeErrorEdge(ctx, id, node, object)) goto done;
    }
    if ( object != XL6_IR_VALUE_INVALID )
        object = xl6IrLowerBindRuntimeTypeIdentity(
            ctx, id, node->storageType, node->storageType, object);
    if ( object == XL6_IR_VALUE_INVALID ) goto done;
    /* Payload evaluation can fail or suspend. The partially initialized enum
     * is a transaction owner until all payloads have been installed. */
    objectStorage = xl6IrLowerNewTempStorage(ctx, node->storageType, id);
    if (objectStorage == 0 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id, node->storageType, objectStorage, &object, 1, NULL) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id, node->storageType, objectStorage, NULL, 0, &object) ||
        !xl6IrLowerProtectEvaluationStorage(ctx, id, objectStorage, object, 1, 0)) goto done;
    for ( payloadOffset = 0; payloadOffset < variant->payloadCount;
          ++payloadOffset ) {
        size_t payloadIndex = variant->firstPayload + payloadOffset;
        const XL6_IrEnumPayload* payload =
            &ctx->module->enumPayloads[payloadIndex];
        XL6_IrNodeId wrapperId = ctx->module->children[
            arguments->firstChild + payloadOffset];
        const XL6_IrNode* wrapper = xl6IrNodeGet(ctx->module, wrapperId);
        XL6_IrNodeId expressionId;
        const XL6_IrNode* expression;
        XL6_IrValueId value;
        XL6_IrValueId boxed;
        XL6_IrValueId stored;
        XL6_IrValueId operands[2];
        size_t firstOwner;
        if ( wrapper == NULL || wrapper->sourceKind != XL6_AST_ARG ||
             wrapper->flags != 0 || wrapper->childCount != 1 ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR tagged enum construction requires normalized positional payload arguments");
            goto done;
        }
        expressionId = ctx->module->children[wrapper->firstChild];
        expression = xl6IrNodeGet(ctx->module, expressionId);
        value = xl6IrLowerNodeAsType(
            ctx, id, expressionId, expression, payload->type);
        if ( expression == NULL || value == XL6_IR_VALUE_INVALID ||
             xl6IrLowerValueType(ctx, value) != payload->type ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR tagged enum payload argument has no exact substituted TypeId ABI");
            goto done;
        }
        /* Non-xvalue boxing borrows/copies its payload. Preserve and close
         * an owned string/closure payload independently of the enum's new
         * xvalue owner, including literal arguments. */
        firstOwner = ctx->evaluationOwnerCount;
        if (!xl6IrLowerTypeIsRuntimeXValue(ctx->module, payload->type))
            value = xl6IrLowerProtectOwnedBorrow(ctx, expressionId, value);
        boxed = xl6IrLowerBoxRuntimeXValue(
            ctx, id, dynamicType, expression, value);
        if ( boxed == XL6_IR_VALUE_INVALID ||
             !xl6IrLowerCompleteEvaluationBorrows(ctx, expressionId, firstOwner, &boxed) ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR tagged enum payload has no verified xvalue boxing ABI");
            goto done;
        }
        operands[0] = object;
        operands[1] = boxed;
        stored = xl6IrLowerEmitRuntimeCall(
            ctx, id, boolType,
            XL6_IR_RUNTIME_TAGGED_ENUM_PAYLOAD_SET_NEW,
            operands, 2);
        if ( stored != XL6_IR_VALUE_INVALID ) {
            XL6_IrInstruction* instruction = &ctx->module->instructions[
                ctx->module->instructionCount - 1];
            instruction->enumVariant = variantIndex;
            instruction->enumPayload = payloadIndex;
        }
        if ( stored == XL6_IR_VALUE_INVALID ||
             !xl6IrLowerEmitRuntimeErrorEdge(ctx, id, node, stored) )
            goto done;
    }
    if (ctx->evaluationOwnerCount != evaluationOwnerFirst + 1 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORAGE_TAKE, id, node->storageType,
            objectStorage, NULL, 0, &result)) result = XL6_IR_VALUE_INVALID;
done:
    ctx->evaluationOwnerCount = evaluationOwnerFirst;
    return result;
}

/* Convert an already evaluated product projection at its destination's
 * physical boundary. The source's protected borrow remains live until the
 * caller either transfers it unchanged or destroys it after conversion. */
static XL6_IrValueId xl6IrLowerProjectedValueAsType(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, XL6_IrNodeId sourceId,
    XL6_IrValueId value, XL6_IrTypeId targetType)
{
    XL6_IrTypeId sourceType = xl6IrLowerValueType(ctx, value);
    if (sourceType == targetType) return value;
    if (xl6IrLowerTypeIsRuntimeXValue(ctx->module, targetType))
        return xl6IrLowerBoxRuntimeXValue(ctx, origin, targetType,
            xl6IrNodeGet(ctx->module, sourceId), value);
    return xl6IrLowerEmitVerifiedScalarConvert(ctx, origin, sourceType, targetType, value,
        xl6IrClassifyScalarConversionAbi(xl6IrTypeGet(&ctx->module->types, sourceType),
            xl6IrTypeGet(&ctx->module->types, targetType)));
}

/* A product RHS is evaluated once. Detach its fields into individually
 * protected owners before evaluating any destination or destructor. Taking a
 * field changes only the private carrier, so user-visible target evaluation
 * and commits remain left-to-right. Failed writes unwind the still-pending
 * fields through the ordinary evaluation cleanup, not Cgen aggregate repair. */
static int xl6IrLowerProductBindings(
    XL6_IrLowerContext* ctx, XL6_IrNodeId origin, const XL6_IrNode* bindings,
    XL6_IrNodeId sourceId, XL6_IrTypeId productType, int declaration)
{
    const XL6_IrType* product = xl6IrTypeGet(&ctx->module->types, productType);
    XL6_IrValueId aggregate, *elements = NULL;
    size_t field, first;
    int ok = 0;
    if (product == NULL || product->cAbi != XL6_IR_C_ABI_PRODUCT ||
        bindings == NULL || bindings->kind != XL6_IR_NODE_LIST ||
        bindings->childCount != product->paramCount) goto done;
    aggregate = xl6IrLowerNode(ctx, sourceId);
    if (aggregate == XL6_IR_VALUE_INVALID || xl6IrLowerValueType(ctx, aggregate) != productType) goto done;
    elements = (XL6_IrValueId*)xrtCalloc(product->paramCount, sizeof(*elements));
    if (elements == NULL) goto done;
    first = ctx->evaluationOwnerCount;
    for (field = 0; field < product->paramCount; ++field) {
        const XL6_IrType* type = xl6IrTypeGet(&ctx->module->types, product->params[field]);
        int managed = type != NULL && type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED;
        if (type == NULL || !xl6IrLowerEmit(ctx, managed ? XL6_IR_INSTR_PRODUCT_TAKE : XL6_IR_INSTR_PRODUCT_GET,
                origin, product->params[field], 0, &aggregate, 1, &elements[field])) goto done;
        ctx->module->instructions[ctx->module->instructionCount - 1].elementIndex = field;
        if (managed) elements[field] = xl6IrLowerProtectEvaluationValue(
            ctx, origin, product->params[field], elements[field]);
        if (elements[field] == XL6_IR_VALUE_INVALID) goto done;
    }
    for (field = 0; field < product->paramCount; ++field) {
        XL6_IrNodeId targetId = ctx->module->children[bindings->firstChild + field];
        const XL6_IrNode* target = xl6IrNodeGet(ctx->module, targetId);
        const XL6_IrType* type = xl6IrTypeGet(&ctx->module->types, product->params[field]);
        int managed = type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED;
        int discarded = target != NULL && target->kind == XL6_IR_NODE_NAME &&
            (declaration ? target->symbol : target->targetSymbol) == 0 &&
            target->text != NULL && strcmp(target->text, "_") == 0;
        if (managed && (first >= ctx->evaluationOwnerCount ||
            ctx->evaluationOwners[first].value != elements[field])) goto done;
        if (discarded || (!declaration && target != NULL && target->kind == XL6_IR_NODE_INDEX)) {
            if (!discarded) {
                XL6_IrLowerElementTargetPlan plan = {0};
                XL6_IrValueId value;
                /* The field stays a protected borrow while the address and
                 * boxing are evaluated. The index ABI acquires its own item. */
                if (!xl6IrLowerPrepareElementTargetPlan(ctx, targetId, target, &plan)) goto done;
                value = xl6IrLowerProjectedValueAsType(
                    ctx, origin, sourceId, elements[field], target->storageType);
                if (value == XL6_IR_VALUE_INVALID ||
                    !xl6IrLowerWriteElementTargetPlan(ctx, origin, &plan, value,
                        xl6IrNodeGet(ctx->module, sourceId))) {
                    xl6IrLowerDisposeElementTargetPlan(&plan); goto done;
                }
            }
            if (managed) {
                ctx->evaluationOwners[first].transfer = 0;
                if (!xl6IrLowerCompleteEvaluationBorrowRange(ctx, origin, first, first + 1, NULL)) goto done;
            }
        } else if (declaration) {
            XL6_IrStorageKind kind =
                ctx->module->functions[ctx->functionIndex].kind == XL6_IR_FUNCTION_MODULE_INIT &&
                ctx->moduleTopLevel ? XL6_IR_STORAGE_GLOBAL : XL6_IR_STORAGE_LOCAL;
            XL6_IrTypeId cellType;
            if (target == NULL || target->kind != XL6_IR_NODE_NAME || target->symbol == 0 ||
                !xl6IrLowerRegisterStorage(ctx, kind, target->symbol, product->params[field],
                    targetId, ctx->module->functions[ctx->functionIndex].declaration)) goto done;
            cellType = xl6IrLowerCaptureCellTypeForSource(ctx->module, target->symbol);
            if (cellType != XL6_IR_TYPE_INVALID &&
                !xl6IrLowerSetStorageCell(ctx, target->symbol, cellType, targetId)) goto done;
            /* Transfer this field out of the pending product owners before
             * shared cell construction protects it across allocation. Other
             * fields stay protected; no second owner aliases the same value. */
            if (managed && !xl6IrLowerCommitEvaluationOwnerRange(ctx, origin, first, first + 1)) goto done;
            if (cellType != XL6_IR_TYPE_INVALID
                ? !xl6IrLowerConstructCell(ctx, targetId, targetId, target->symbol, elements[field])
                : !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, targetId, product->params[field],
                    target->symbol, &elements[field], 1, NULL)) goto done;
        } else {
            XL6_IrLowerStorageTargetPlan plan;
            XL6_IrValueId value = elements[field];
            if (xl6IrLowerPrepareStorageTargetPlan(ctx, origin, target, &plan) != 1) goto done;
            if (plan.type != product->params[field]) {
                /* Projected fields cross the same typed storage boundary as
                 * ordinary RHS values. Keep all pending fields protected
                 * while constructing a distinct carrier; do not reevaluate
                 * the product or transfer its source owner into a box. */
                value = xl6IrLowerProjectedValueAsType(ctx, origin, sourceId, value, plan.type);
                if (value == XL6_IR_VALUE_INVALID) goto done;
                if (managed) {
                    ctx->evaluationOwners[first].transfer = 0;
                    if (!xl6IrLowerCompleteEvaluationBorrowRange(
                            ctx, origin, first, first + 1, &value)) goto done;
                }
                if (!xl6IrLowerWriteStorageTargetPlan(ctx, origin, &plan, value)) goto done;
                continue;
            }
            if ((managed && !xl6IrLowerCommitEvaluationOwnerRange(ctx, origin, first, first + 1)) ||
                !xl6IrLowerWriteStorageTargetPlan(ctx, origin, &plan, value)) goto done;
        }
    }
    ok = ctx->evaluationOwnerCount == first;
done:
    xrtFree(elements);
    if (!ok && !ctx->failed) xl6IrLowerDiag(ctx, origin,
        "XLIR product binding has no exact protected field transaction");
    return ok;
}

static XL6_IrValueId xl6IrLowerNode(XL6_IrLowerContext* ctx, XL6_IrNodeId id)
{
    const XL6_IrNode* node = xl6IrNodeGet(ctx->module, id);
    XL6_IrValueId values[2];
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    size_t i;
    if ( node == NULL ) { xl6IrLowerDiag(ctx, id, "XLIR lowering received an invalid node"); return 0; }
    /* Ownership planning is semantic input, not an optional Cgen hint.  Until
     * this lowering path emits RETAIN/RELEASE/MOVE/DROP and cleanup edges, a
     * planned action must stop here rather than being silently erased by the
     * scalar backend. */
    if ( node->ownershipPlanned && node->storageType != XL6_IR_TYPE_INVALID &&
         !(node->kind == XL6_IR_NODE_AWAIT &&
           xl6IrLowerAsyncResultAbi(ctx->module, node->storageType) == XL6_IR_ASYNC_RESULT_VOID) &&
         xl6IrLowerTypeNeedsOwnership(ctx->module, node->storageType) ) {
        const XL6_IrType* ownershipType = xl6IrTypeGet(&ctx->module->types, node->storageType);
        if ( ownershipType != NULL && ownershipType->name != NULL &&
             strcmp(ownershipType->name, "function") == 0 &&
             ownershipType->cAbi != XL6_IR_C_ABI_CLOSURE_PTR &&
             !xl6IrLowerTypeIsErasedCallable(
                 ctx->module, node->storageType) ) {
            xl6IrLowerDiag(ctx, id,
                            "XLIR function value requires a lowered closure environment and invoke ABI");
            return 0;
        }
        if ( ownershipType == NULL ||
             (ownershipType->cAbi != XL6_IR_C_ABI_MANAGED_STRING &&
              ownershipType->cAbi != XL6_IR_C_ABI_MANAGED_BYTES &&
              ownershipType->cAbi != XL6_IR_C_ABI_RUNTIME_XVALUE_PTR &&
              ownershipType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR &&
              ownershipType->cAbi != XL6_IR_C_ABI_RUNTIME_GENERATOR_PTR &&
              ownershipType->cAbi != XL6_IR_C_ABI_RUNTIME_ERROR_PTR &&
              ownershipType->cAbi != XL6_IR_C_ABI_CLOSURE_PTR &&
              ownershipType->cAbi != XL6_IR_C_ABI_PRODUCT) ) {
            xl6IrLowerDiag(ctx, id, "XLIR lowering requires explicit ownership instructions");
            return 0;
        }
    }
    switch ( node->kind ) {
    case XL6_IR_NODE_MODULE:
    case XL6_IR_NODE_LIST:
    case XL6_IR_NODE_BLOCK:
        for ( i = 0; i < node->childCount; ++i ) {
            const XL6_IrNode* child = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + i]);
            int savedModuleTopLevel = ctx->moduleTopLevel;
            /* Structured source has no labels that can re-enter the current
             * sequence after an unconditional terminator.  Do not append
             * unreachable statements to an already terminated XLIR block;
             * declarations were registered before CFG lowering. */
            if ( (node->kind == XL6_IR_NODE_MODULE ||
                  node->kind == XL6_IR_NODE_BLOCK) &&
                 xl6IrLowerBlockTerminated(ctx) ) {
                for ( ; i < node->childCount; ++i )
                    if ( !xl6IrLowerRemoveUnreachableSubtreeCleanup(
                             ctx, ctx->module->children[node->firstChild + i]) ) {
                        xl6IrLowerDiag(ctx, id,
                            "XLIR unreachable local cleanup could not be removed from its exit plans");
                        return XL6_IR_VALUE_INVALID;
                    }
                break;
            }
            if ( child != NULL && child->kind != XL6_IR_NODE_FUNC_DECL &&
                 child->kind != XL6_IR_NODE_TYPE_DECL && child->kind != XL6_IR_NODE_ENUM_DECL &&
                 child->kind != XL6_IR_NODE_IMPORT ) {
                ctx->moduleTopLevel = node->kind == XL6_IR_NODE_MODULE &&
                    ctx->module->functions[ctx->functionIndex].kind == XL6_IR_FUNCTION_MODULE_INIT;
                (void)xl6IrLowerNode(ctx, ctx->module->children[node->firstChild + i]);
                ctx->moduleTopLevel = savedModuleTopLevel;
            }
        }
        if ( node->kind == XL6_IR_NODE_BLOCK && !ctx->failed &&
             !xl6IrLowerBlockTerminated(ctx) &&
             xl6IrLowerMayCompleteNormallyDepth(ctx->module, id, 0) &&
             !xl6IrLowerEmitNormalBlockCleanup(ctx, id) ) return 0;
        return 0;
    case XL6_IR_NODE_FUNC_DECL:
        {
            const XL6_IrClosureTarget* closure = xl6IrLowerClosureTargetGet(ctx->module, node->symbol);
            XL6_IrValueId* captures = NULL;
            if ( node->sourceKind != XL6_AST_ANON_FUNC || closure == NULL ) {
                xl6IrLowerDiag(ctx, id, "XLIR anonymous function has no lowered closure target ABI");
                return XL6_IR_VALUE_INVALID;
            }
            if ( closure->captureCount != 0 ) {
                captures = (XL6_IrValueId*)xrtCalloc(closure->captureCount, sizeof(*captures));
                if ( captures == NULL ) { ctx->failed = 1; return XL6_IR_VALUE_INVALID; }
                for ( i = 0; i < closure->captureCount; ++i ) {
                    const XL6_IrClosureCapture* item = &ctx->module->closureCaptures[closure->firstCapture + i];
                    XL6_SymbolId source = xl6IrLowerClosureCaptureStorage(ctx, item->sourceSymbol);
                    if ( source == 0 ) source = xl6IrLowerPromotedParameterStorage(ctx, item->sourceSymbol);
                    if ( source == 0 ) source = item->sourceSymbol;
                    if ( !xl6IrLowerEmit(ctx,
                                         item->abi == XL6_IR_CLOSURE_CAPTURE_RETAIN_CELL
                                             ? XL6_IR_INSTR_CELL_RETAIN : XL6_IR_INSTR_LOAD,
                                         id,
                                         item->abi == XL6_IR_CLOSURE_CAPTURE_RETAIN_CELL
                                             ? item->cellType : item->type,
                                         source, NULL, 0, &captures[i]) ) break;
                }
            }
            if ( ctx->failed || !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLOSURE_MAKE, id, node->storageType,
                                                node->symbol, captures, closure->captureCount, &result) ) {
                xrtFree(captures);
                xl6IrLowerDiag(ctx, id, "XLIR anonymous function has no lowered closure target ABI");
                return XL6_IR_VALUE_INVALID;
            }
            xrtFree(captures);
            if (!xl6IrLowerEmitRuntimeErrorEdge(ctx, id, node, result)) return XL6_IR_VALUE_INVALID;
        }
        return result;
    case XL6_IR_NODE_INTERPOLATED_STRING:
        return xl6IrLowerInterpolatedString(ctx, id, node);
    case XL6_IR_NODE_COLLECTION:
        /* Collection literals are ordinary owned expressions once Typed
         * XLIR has fixed their exact runtime xvalue TypeId.  Lower them here
         * as well as at assignment/call/return boundaries so an expression
         * statement still evaluates every element in order and hands the
         * resulting owner to the generic STORE/RELEASE discard contract. */
        if ( !xl6IrLowerTypeIsRuntimeXValue(ctx->module, node->storageType) ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR collection expression has no resolved runtime xvalue storage ABI");
            return XL6_IR_VALUE_INVALID;
        }
        return xl6IrLowerNodeAsRuntimeXValue(
            ctx, id, id, node, node->storageType);
    case XL6_IR_NODE_LITERAL:
        if ( node->text == NULL ) return 0;
        if ( node->sourceKind == XL6_AST_CHAR ) {
            const XL6_IrType* literalType =
                xl6IrTypeGet(&ctx->module->types, node->storageType);
            char scalarText[32];
            if ( !node->literalDecoded || literalType == NULL ||
                 literalType->cAbi != XL6_IR_C_ABI_CHAR_U32 ||
                 node->literalScalar > 0x10ffffu ||
                 (node->literalScalar >= 0xd800u &&
                  node->literalScalar <= 0xdfffu) ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR char literal has no validated Unicode-scalar payload");
                return XL6_IR_VALUE_INVALID;
            }
            if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id,
                                 node->storageType, 0, NULL, 0, &result) )
                return XL6_IR_VALUE_INVALID;
            snprintf(scalarText, sizeof(scalarText), "%u",
                     (unsigned int)node->literalScalar);
            ctx->module->instructions[
                ctx->module->instructionCount - 1].immediateText =
                    xrtStrDup(scalarText);
            if ( ctx->module->instructions[
                     ctx->module->instructionCount - 1].immediateText == NULL ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR char literal payload is out of memory");
                return XL6_IR_VALUE_INVALID;
            }
            return result;
        }
        if ( node->sourceKind == XL6_AST_BYTES ) {
            if ( !node->literalDecoded ||
                 !xl6IrLowerTypeIsManagedBytes(ctx->module, node->storageType) ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR bytes literal has no explicit-length bytes ABI");
                return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerEmitRuntimeDataCall(
                ctx, id, node->storageType, XL6_IR_RUNTIME_BYTES_FROM_DATA,
                node->literalData, node->literalSize);
        }
        if ( xl6IrLowerTypeIsRuntimeXValue(ctx->module, node->storageType) ) {
            XL6_IrRuntimeOp runtimeOp;
            switch ( node->sourceKind ) {
            case XL6_AST_NULL: runtimeOp = XL6_IR_RUNTIME_XVALUE_NULL; break;
            default:
                xl6IrLowerDiag(ctx, id, "XLIR dynamic literal requires an explicit runtime boxing ABI");
                return 0;
            }
            if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RUNTIME_CALL, id, node->storageType,
                                 0, NULL, 0, &result) ) return 0;
            ctx->module->instructions[ctx->module->instructionCount - 1].runtimeOp = runtimeOp;
            ctx->module->instructions[ctx->module->instructionCount - 1].immediateText =
                xrtStrDupN(node->text, strlen(node->text));
            if ( ctx->module->instructions[ctx->module->instructionCount - 1].immediateText == NULL ) {
                xl6IrLowerDiag(ctx, id, "XLIR dynamic literal has no canonical runtime payload");
                return 0;
            }
            return result;
        }
        if ( node->sourceKind == XL6_AST_FLOAT &&
             xl6IrTypeGet(&ctx->module->types, node->storageType) != NULL &&
             xl6IrTypeGet(&ctx->module->types, node->storageType)->cAbi ==
                 XL6_IR_C_ABI_F64 &&
             (strcmp(node->text, "(0.0/0.0)") == 0 ||
              strcmp(node->text, "(1.0/0.0)") == 0) ) {
            if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RUNTIME_CALL, id,
                                 node->storageType, 0, NULL, 0, &result) )
                return XL6_IR_VALUE_INVALID;
            ctx->module->instructions[
                ctx->module->instructionCount - 1].runtimeOp =
                    strcmp(node->text, "(0.0/0.0)") == 0
                        ? XL6_IR_RUNTIME_F64_NAN
                        : XL6_IR_RUNTIME_F64_POSITIVE_INFINITY;
            return result;
        }
        if (xl6IrLowerTypeIsManagedString(ctx->module, node->storageType)) {
            if ( node->sourceKind != XL6_AST_STRING || !node->literalDecoded ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR managed string literal has no decoded UTF-8 payload");
                return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerEmitRuntimeDataCall(
                ctx, id, node->storageType, XL6_IR_RUNTIME_STRING_FROM_UTF8,
                node->literalData, node->literalSize);
        }
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id, node->storageType, 0, NULL, 0, &result))
            return XL6_IR_VALUE_INVALID;
        ctx->module->instructions[ctx->module->instructionCount - 1].immediateText =
            node->sourceKind == XL6_AST_INT
                    ? (xl6IrTypeGet(&ctx->module->types, node->storageType) != NULL &&
                       xl6IrTypeGet(&ctx->module->types, node->storageType)->cAbi == XL6_IR_C_ABI_U64
                        ? xl6IrLowerCanonicalUnsignedIntegerLiteral(node->text)
                        : xl6IrLowerCanonicalIntegerLiteral(node->text))
                    : node->sourceKind == XL6_AST_FLOAT
                        ? xl6IrLowerCanonicalFloatLiteral(node->text)
                        : node->sourceKind == XL6_AST_TIME
                            ? xl6IrLowerCanonicalTimeLiteral(node->text)
                            : xrtStrDupN(node->text, strlen(node->text));
        if ( ctx->module->instructions[ctx->module->instructionCount - 1].immediateText == NULL ) {
            xl6IrLowerDiag(ctx, id,
                            node->sourceKind == XL6_AST_INT
                                    ? "integer literal is too large or invalid"
                                    : "XLIR literal has no canonical C runtime payload");
            return 0;
        }
        return result;
    case XL6_IR_NODE_NAME:
        {
            const XL6_IrLowerCatchPayload* payload;
            XL6_IrTypeId storageType;
            const XL6_IrStorage* storage;
            if ( node->typeValueTarget != XL6_IR_TYPE_INVALID ) {
                const XL6_IrType* valueType =
                    xl6IrTypeGet(&ctx->module->types, node->storageType);
                const XL6_IrType* targetType =
                    xl6IrTypeGet(&ctx->module->types, node->typeValueTarget);
                char immediate[32];
                int written;
                if ( node->targetSymbol != 0 || valueType == NULL ||
                     valueType->cAbi != XL6_IR_C_ABI_TYPE_ID ||
                     targetType == NULL || targetType->typeValueId == 0 ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id,
                                      node->storageType, 0, NULL, 0, &result) ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR type literal has no exact target identity ABI");
                    return XL6_IR_VALUE_INVALID;
                }
                written = snprintf(immediate, sizeof(immediate),
                    "0x%016llXULL",
                    (unsigned long long)targetType->typeValueId);
                if ( written < 0 || (size_t)written >= sizeof(immediate) ||
                     (ctx->module->instructions[
                         ctx->module->instructionCount - 1].immediateText =
                          xrtStrDupN(immediate, (size_t)written)) == NULL ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR type literal has no canonical identity payload");
                    return XL6_IR_VALUE_INVALID;
                }
                return result;
            }
            if ( node->implicitNameAbi != XL6_IR_IMPLICIT_NAME_NONE )
                return xl6IrLowerImplicitName(ctx, id, node);
            if ( node->namedCallableAbi != XL6_IR_NAMED_CALLABLE_NONE ) {
                const XL6_IrClosureTarget* adapter =
                    xl6IrLowerRegisterNamedAdapter(ctx, id, node);
                if ( node->namedCallableAbi !=
                         XL6_IR_NAMED_CALLABLE_CAPTURE_FREE_ADAPTER ||
                     adapter == NULL || !xl6IrLowerEmit(
                         ctx, XL6_IR_INSTR_CLOSURE_MAKE, id,
                         node->namedCallableSignatureType,
                         adapter->targetSymbol, NULL, 0, &result) )
                    return XL6_IR_VALUE_INVALID;
                if (!xl6IrLowerEmitRuntimeErrorEdge(ctx, id, node, result)) return XL6_IR_VALUE_INVALID;
                return result;
            }
            if ( node->targetSymbol == 0 ) { xl6IrLowerDiag(ctx, id, "XLIR name has no resolved symbol"); return 0; }
            /* Frontend catch bindings are syntactically untyped and therefore
             * arrive as `var`.  Inside their active handler the owned catch
             * storage is the authoritative ABI, including for a borrowed
             * observer load; Cgen never performs this refinement. */
            payload = xl6IrLowerActiveCatchPayload(ctx);
            storageType = payload != NULL && payload->symbol == node->targetSymbol
                ? payload->type : node->storageType;
            XL6_SymbolId captureStorage = xl6IrLowerClosureCaptureStorage(ctx, node->targetSymbol);
            XL6_SymbolId promotedStorage = xl6IrLowerPromotedParameterStorage(ctx, node->targetSymbol);
            XL6_SymbolId storageSymbol = captureStorage != 0 ? captureStorage
                : promotedStorage != 0 ? promotedStorage : node->targetSymbol;
            storage = xl6IrStorageGet(ctx->module, storageSymbol);
            /* Lowered storage is the authoritative TypeId for synthetic and
             * pattern-bound locals.  Their source NAME can carry an
             * equivalent contextual builtin TypeId, but LOAD must name the
             * exact registered cell ABI. */
            if ( storage != NULL ) storageType = storage->type;
            if ( !xl6IrLowerEmit(ctx,
                                  storage != NULL && storage->cellType != XL6_IR_TYPE_INVALID
                                      ? XL6_IR_INSTR_CELL_LOAD : XL6_IR_INSTR_LOAD,
                                  id, storageType, storageSymbol,
                                  NULL, 0, &result) ) return XL6_IR_VALUE_INVALID;
            /* Catch dispatch owns one canonical runtime-error storage TypeId.
             * Frontend error annotations may refer to an equivalent builtin
             * pool entry, but that is not nullable flow narrowing.  Keep the
             * authoritative catch-storage TypeId for error member/call ABI. */
            if ( payload != NULL && payload->symbol == node->targetSymbol )
                return result;
            /* Semantic flow analysis records a narrowed expression TypeId on
             * the NAME while preserving its declared nullable or open-xvalue
             * storage TypeId. Materialize that already-proven projection as
             * explicit XLIR; later scalar/call/member lowering and Cgen never
             * rediscover the surrounding type/null test or inspect source CFG. */
            if ( node->type != XL6_IR_TYPE_INVALID &&
                 node->type != storageType ) {
                const XL6_IrType* nullable =
                    xl6IrTypeGet(&ctx->module->types, storageType);
                const XL6_IrType* observed =
                    xl6IrTypeGet(&ctx->module->types, node->type);
                XL6_IrValueId narrowed;
                /* Contextual scalar typing may intern an equivalent builtin
                 * more than once.  That is not flow narrowing and needs no
                 * physical operation: keep the authoritative storage TypeId.
                 * Nominal and parameterized values are deliberately excluded. */
                if ( nullable != NULL && observed != NULL &&
                     nullable->kind == XL6_IR_TYPE_BUILTIN &&
                     observed->kind == XL6_IR_TYPE_BUILTIN &&
                     nullable->paramCount == 0 && observed->paramCount == 0 &&
                     nullable->nominalSymbol == XL6_SYMBOL_ID_INVALID &&
                     observed->nominalSymbol == XL6_SYMBOL_ID_INVALID &&
                     nullable->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
                     observed->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
                     nullable->cAbi == observed->cAbi &&
                     nullable->nullAbi == observed->nullAbi &&
                     nullable->integerTarget == observed->integerTarget &&
                     nullable->typeValueId == observed->typeValueId )
                    return result;
                if ( xl6IrLowerTypeIsDynamicXValueBuiltin(
                         ctx->module, storageType) ) {
                    narrowed = observed != NULL && observed->kind == XL6_IR_TYPE_NULLABLE
                        ? xl6IrLowerProjectBorrowedXValueAsNullable(
                            ctx, id, result, node->type)
                        : xl6IrLowerProjectBorrowedXValueAsExactType(
                            ctx, id, result, node->type);
                    if ( narrowed == XL6_IR_VALUE_INVALID ) {
                        xl6IrLowerDiag(ctx, id,
                            "XLIR narrowed xvalue name has no exact projection ABI");
                    }
                    return narrowed;
                }
                if ( nullable == NULL ||
                     nullable->kind != XL6_IR_TYPE_NULLABLE ||
                     nullable->paramCount != 1 || nullable->params == NULL ||
                     nullable->params[0] != node->type ||
                     (nullable->nullAbi != XL6_IR_NULL_ABI_TAGGED_VALUE &&
                      nullable->nullAbi != XL6_IR_NULL_ABI_POINTER_SENTINEL &&
                      nullable->nullAbi != XL6_IR_NULL_ABI_XVALUE_SENTINEL) ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULLABLE_UNWRAP, id,
                                      node->type, 0, &result, 1, &narrowed) ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR narrowed name has no exact nullable storage projection ABI");
                    return XL6_IR_VALUE_INVALID;
                }
                return narrowed;
            }
            return result;
        }
    case XL6_IR_NODE_VALUE_DECL:
        {
            const XL6_IrType* product = xl6IrTypeGet(&ctx->module->types, node->storageType);
            const XL6_IrNode* names = node->childCount == 2
                ? xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]) : NULL;
            const XL6_IrNode* source = node->childCount == 2
                ? xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]) : NULL;
            if ( product != NULL && product->kind == XL6_IR_TYPE_TUPLE &&
                 product->cAbi == XL6_IR_C_ABI_PRODUCT ) {
                if (source == NULL || source->storageType != node->storageType ||
                    !xl6IrLowerProductBindings(ctx, id, names,
                        ctx->module->children[node->firstChild + 1], node->storageType, 1)) {
                    if (!ctx->failed) xl6IrLowerDiag(ctx, id,
                        "XLIR destructuring declaration has no exact product ownership ABI");
                }
                return XL6_IR_VALUE_INVALID;
            }
        }
        if ( xl6IrLowerValueDeclarationSymbol(ctx->module, node) == 0 ) {
            xl6IrLowerDiag(ctx, id, "XLIR value declaration has no canonical symbol"); return 0;
        }
        if ( !xl6IrLowerRegisterStorage(
                 ctx,
                 node->sourceKind == XL6_AST_EXTERN_VAR
                     ? XL6_IR_STORAGE_EXTERN_GLOBAL
                     : (ctx->module->functions[ctx->functionIndex].kind == XL6_IR_FUNCTION_MODULE_INIT &&
                        ctx->moduleTopLevel
                            ? XL6_IR_STORAGE_GLOBAL : XL6_IR_STORAGE_LOCAL),
                 xl6IrLowerValueDeclarationSymbol(ctx->module, node), node->storageType, id,
                  ctx->module->functions[ctx->functionIndex].declaration) ) return 0;
        {
            XL6_IrTypeId cellType = xl6IrLowerCaptureCellTypeForSource(
                ctx->module, xl6IrLowerValueDeclarationSymbol(ctx->module, node));
            if ( cellType != XL6_IR_TYPE_INVALID &&
                 !xl6IrLowerSetStorageCell(
                     ctx, xl6IrLowerValueDeclarationSymbol(ctx->module, node), cellType, id) ) return 0;
        }
        if ( node->sourceKind == XL6_AST_EXTERN_VAR ) {
            return xl6IrLowerRegisterExternGlobal(
                ctx, id, xl6IrLowerValueDeclarationSymbol(ctx->module, node)) ? 0 : 0;
        }
        /* An explicit C data export is initialized by its public static
         * definition.  Emitting a second STORE in module-init would make a
         * const export illegal and would expose zero before initialization to
         * direct C readers. */
        if ( (node->sourceKind == XL6_AST_EXPORT_VAR ||
              node->sourceKind == XL6_AST_EXPORT_CONST) &&
             node->text != NULL && node->text[0] != '\0' ) {
            return xl6IrLowerRegisterGlobalExport(
                ctx, id, xl6IrLowerValueDeclarationSymbol(ctx->module, node)) ? 0 : 0;
        }
        {
            const XL6_IrValueInitializer* initializer =
                xl6IrValueInitializerGet(ctx->module, id);
            result = xl6IrLowerValueInitializer(ctx, id, initializer);
            if ( result == XL6_IR_VALUE_INVALID ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR value declaration has no verified initializer ABI");
                return XL6_IR_VALUE_INVALID;
            }
        }
        if ( node->storageType != XL6_IR_TYPE_INVALID && result != XL6_IR_VALUE_INVALID ) {
            const XL6_IrInstruction* definition = NULL;
            size_t instruction;
            for ( instruction = ctx->module->instructionCount; instruction > 0; --instruction )
                if ( ctx->module->instructions[instruction - 1].result == result ) {
                    definition = &ctx->module->instructions[instruction - 1]; break;
                }
            if ( definition != NULL && definition->type != node->storageType ) {
                XL6_IrValueId normalized = xl6IrLowerEmitIntegerStorageNormalize(
                    ctx, id, node->storageType, result);
                if ( normalized != XL6_IR_VALUE_INVALID ) {
                    result = normalized;
                } else if ( !xl6IrLowerCallableTypesCompatible(
                                ctx->module, definition->type,
                                node->storageType) ) {
                    xl6IrLowerDiag(ctx, id, "XLIR value declaration initializer does not match its storage ABI");
                    return XL6_IR_VALUE_INVALID;
                } else {
                    result = xl6IrLowerEmitValueCopy(
                        ctx, id, node->storageType, result);
                    if ( result == XL6_IR_VALUE_INVALID )
                        return XL6_IR_VALUE_INVALID;
                }
            }
        }
        /* A declaration is an owning boundary.  Normalize every explicit
         * managed initializer before it reaches its storage so later async
         * frame analysis can consume only instruction-level ownership facts. */
        if ( node->storageType != XL6_IR_TYPE_INVALID ) {
            const XL6_IrValueInitializer* initializerAbi =
                xl6IrValueInitializerGet(ctx->module, id);
            const XL6_IrNode* initializer = initializerAbi != NULL &&
                initializerAbi->abi == XL6_IR_INITIALIZER_EXPLICIT
                ? xl6IrNodeGet(ctx->module, initializerAbi->expression) : NULL;
            const XL6_IrType* type = xl6IrTypeGet(&ctx->module->types, node->storageType);
            if ( initializer != NULL && type != NULL &&
                 type->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ) {
                result = xl6IrLowerOwnedStorageValue(
                    ctx, id, node->storageType, initializer, result);
                if ( result == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
            }
        }
        {
            XL6_SymbolId storageSymbol = xl6IrLowerValueDeclarationSymbol(ctx->module, node);
            const XL6_IrStorage* storage = xl6IrStorageGet(ctx->module, storageSymbol);
            if (storage != NULL && storage->cellType != XL6_IR_TYPE_INVALID)
                (void)xl6IrLowerConstructCell(ctx, id, id, storageSymbol, result);
            else (void)xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id, node->storageType,
                storageSymbol, &result, 1, NULL);
            return 0;
        }
    case XL6_IR_NODE_ASSIGN:
        if (xl6IrNodeIsDynamicMemberWrite(ctx->module, id)) {
            XL6_IrValueId unit = xl6IrLowerDynamicCall(ctx, id, node);
            XL6_IrTypeId unitType = xl6IrLowerValueType(ctx, unit);
            XL6_SymbolId temporary;
            if (unit == XL6_IR_VALUE_INVALID) return XL6_IR_VALUE_INVALID;
            temporary = xl6IrLowerNewTempStorage(ctx, unitType, id);
            if (temporary == 0 || !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id, unitType, temporary, &unit, 1, NULL) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RELEASE, id, unitType, temporary, NULL, 0, NULL))
                return XL6_IR_VALUE_INVALID;
            return 0;
        }
        if ( node->childCount != 2 ) { xl6IrLowerDiag(ctx, id, "XLIR assignment has invalid arity"); return 0; }
        {
            const XL6_IrNode* lhs = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
            XL6_IrNodeId rhsId = ctx->module->children[node->firstChild + 1];
            const XL6_IrNode* rhs = xl6IrNodeGet(ctx->module, rhsId);
            const XL6_IrType* product = rhs != NULL
                ? xl6IrTypeGet(&ctx->module->types, rhs->storageType) : NULL;
            if ( node->callKind == XL6_SEM_CALL_PROTOCOL ) {
                const XL6_IrCallSite* setterSite =
                    xl6IrCallSiteGet(ctx->module, id);
                if ( setterSite == NULL ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR resolved protocol setter has no canonical CallSite");
                    return XL6_IR_VALUE_INVALID;
                }
                (void)xl6IrLowerResolvedSyntaxCall(
                    ctx, id, node, setterSite);
                return ctx->failed ? XL6_IR_VALUE_INVALID : 0;
            }
            if ( node->opcode == XL6_IR_OPCODE_NULL_COALESCE ) {
                int assignIfNull = xl6IrLowerStorageAssignIfNull(
                    ctx, id, node, lhs, rhsId, rhs);
                return assignIfNull > 0 ? 0 : XL6_IR_VALUE_INVALID;
            }
            if ( lhs != NULL && lhs->kind == XL6_IR_NODE_LIST && product != NULL &&
                 product->kind == XL6_IR_TYPE_TUPLE && product->cAbi == XL6_IR_C_ABI_PRODUCT ) {
                if (node->opcode != XL6_IR_OPCODE_INVALID ||
                    !xl6IrLowerProductBindings(ctx, id, lhs, rhsId, rhs->storageType, 0)) {
                    if (!ctx->failed) xl6IrLowerDiag(ctx, id,
                        "XLIR multi-assignment has no exact product ownership ABI");
                }
                return XL6_IR_VALUE_INVALID;
            }
            if ( lhs != NULL && rhs != NULL &&
                 node->opcode != XL6_IR_OPCODE_INVALID ) {
                if ( node->lvalueKind == XL6_SEM_LVALUE_PROPERTY ) {
                    int lowered = xl6IrLowerResolvedPropertyCompoundAssign(
                        ctx, id, node,
                        ctx->module->children[node->firstChild], lhs,
                        rhsId, rhs);
                    if (lowered <= 0 && !ctx->failed)
                        xl6IrLowerDiag(ctx, id, "XLIR property update was not materialized as a destination transaction");
                    return lowered > 0 ? 0 : XL6_IR_VALUE_INVALID;
                }
                int storage = xl6IrLowerStorageCompoundAssign(ctx, id, node, lhs, rhsId, rhs);
                if (storage != 0) return storage > 0 ? 0 : XL6_IR_VALUE_INVALID;
                if ( node->lvalueKind == XL6_SEM_LVALUE_INDEX ||
                     node->lvalueKind == XL6_SEM_LVALUE_FIELD ||
                     node->lvalueKind == XL6_SEM_LVALUE_DYNAMIC_MEMBER ) {
                    int lowered = xl6IrLowerElementCompoundAssign(
                        ctx, id, node, lhs, rhsId, rhs);
                    return lowered > 0 ? 0 : XL6_IR_VALUE_INVALID;
                }
                xl6IrLowerDiag(ctx, id, "XLIR compound assignment has no resolved destination transaction");
                return XL6_IR_VALUE_INVALID;
            }
            {
                int storage = xl6IrLowerStorageAssign(ctx, id, lhs, rhsId, rhs);
                if (storage != 0) return storage > 0 ? 0 : XL6_IR_VALUE_INVALID;
            }
            {
                int witnessSet = xl6IrLowerProtocolPropertySet(ctx, id, node, lhs, rhsId, rhs);
                if (witnessSet != 0) return witnessSet > 0 ? 0 : XL6_IR_VALUE_INVALID;
                int propertySet = xl6IrLowerResolvedPropertySet(
                    ctx, id, node, ctx->module->children[node->firstChild], lhs, rhsId, rhs);
                if ( propertySet != 0 )
                    return propertySet > 0 ? 0 : XL6_IR_VALUE_INVALID;
            }
            if (node->lvalueKind == XL6_SEM_LVALUE_PROPERTY) {
                xl6IrLowerDiag(ctx, id, "XLIR property assignment has no resolved accessor transaction");
                return XL6_IR_VALUE_INVALID;
            }
            values[0] = lhs != NULL
                ? xl6IrLowerNodeAsType(ctx, id, rhsId, rhs, lhs->storageType)
                : XL6_IR_VALUE_INVALID;
            if ( lhs == NULL || values[0] == 0 ) { xl6IrLowerDiag(ctx, id, "XLIR assignment lacks a resolved target or value"); return 0; }
            if ( node->lvalueKind == XL6_SEM_LVALUE_INDEX ) {
                if ( node->opcode != XL6_IR_OPCODE_INVALID ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR index compound assignment bypassed its explicit read-modify-write plan");
                    return XL6_IR_VALUE_INVALID;
                }
                if ( lhs->indexWriteAbi ==
                         XL6_IR_INDEX_WRITE_STRING_SCALAR_SET_COPY ||
                     lhs->indexWriteAbi ==
                         XL6_IR_INDEX_WRITE_BYTES_SET_COPY ) {
                    if ( !xl6IrLowerValueSequenceElementAssign(
                             ctx, id, lhs, values[0]) )
                        return XL6_IR_VALUE_INVALID;
                    return 0;
                }
                if (!xl6IrLowerElementAssign(ctx, id, lhs, values[0], rhs)) return 0;
                return 0;
            }
            if ( lhs != NULL &&
                 (lhs->memberAbi == XL6_IR_MEMBER_ABI_UNION_FIELD ||
                  lhs->memberAbi ==
                      XL6_IR_MEMBER_ABI_UNION_FIELD_DIRECT_STORAGE_WRITE ||
                  lhs->memberAbi ==
                      XL6_IR_MEMBER_ABI_UNION_FIELD_CLASS_FIELD_WRITE) ) {
                int unionSet;
                if ( node->opcode != XL6_IR_OPCODE_INVALID ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR union field compound assignment has no explicit read-modify-write ABI");
                    return 0;
                }
                unionSet = xl6IrLowerUnionFieldSet(ctx, id, lhs, values[0]);
                return unionSet > 0 ? 0 : XL6_IR_VALUE_INVALID;
            }
            if ( node->lvalueKind == XL6_SEM_LVALUE_DYNAMIC_MEMBER ||
                 node->lvalueKind == XL6_SEM_LVALUE_FIELD ) {
                if ( node->opcode != XL6_IR_OPCODE_INVALID ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR element compound assignment bypassed its explicit read-modify-write plan");
                    return XL6_IR_VALUE_INVALID;
                }
                if (!xl6IrLowerElementAssign(ctx, id, lhs, values[0], rhs)) return XL6_IR_VALUE_INVALID;
                return 0;
            }
            xl6IrLowerDiag(ctx, id, "XLIR assignment has no resolved destination transaction");
            return XL6_IR_VALUE_INVALID;
        }
    case XL6_IR_NODE_INDEX:
        if (node->indexReceiverGate != XL6_IR_INDEX_RECEIVER_UNCONDITIONAL)
            return xl6IrLowerSafeIndexReceiverGate(ctx, id, node);
        if (node->sourceKind == XL6_AST_SAFE_INDEX && node->childCount == 2) {
            const XL6_IrNode* sequence = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
            if (sequence != NULL &&
                (xl6IrLowerTypeIsManagedString(ctx->module, sequence->storageType) ||
                 xl6IrLowerTypeIsManagedBytes(ctx->module, sequence->storageType)))
                return xl6IrLowerSafeSequenceIndex(ctx, id, node, XL6_IR_VALUE_INVALID);
        }
        if (node->callKind == XL6_SEM_CALL_WITNESS)
            return xl6IrLowerProtocolInvocation(ctx, id, node, xl6IrCallSiteGet(ctx->module, id));
        if (node->callKind == XL6_SEM_CALL_PROPERTY_GET)
            return xl6IrLowerResolvedSyntaxCall(ctx, id, node, xl6IrCallSiteGet(ctx->module, id));
        result = xl6IrLowerResolvedPropertyGet(ctx, id, node);
        if ( result != XL6_IR_VALUE_INVALID ) return result;
        if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
        if ( node->callKind == XL6_SEM_CALL_PROTOCOL ) {
            const XL6_IrCallSite* syntaxSite =
                xl6IrCallSiteGet(ctx->module, id);
            if ( syntaxSite == NULL ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR resolved index protocol has no canonical CallSite");
                return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerResolvedSyntaxCall(
                ctx, id, node, syntaxSite);
        }
        result = xl6IrLowerBuiltinSequenceIndex(ctx, id, node);
        if ( result != XL6_IR_VALUE_INVALID ) return result;
        if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
        if ( node->childCount == 2 ) {
            const XL6_IrNode* key = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
            if ( key != NULL && key->sourceKind == XL6_AST_STRING )
                return xl6IrLowerRuntimeXValueObjectGetLiteral(ctx, id, node);
            if (key != NULL && (xl6IrLowerTypeIsManagedString(ctx->module, key->storageType) ||
                                xl6IrLowerTypeIsRuntimeXValue(ctx->module, key->storageType)))
                return xl6IrLowerRuntimeXValueKeyRead(ctx, id, node, XL6_IR_VALUE_INVALID);
        }
        return xl6IrLowerRuntimeXValueIndexI64(ctx, id, node, XL6_IR_VALUE_INVALID);
    case XL6_IR_NODE_MEMBER:
        {
            const XL6_IrCallSite* memberSite = xl6IrCallSiteGet(ctx->module, id);
            if (memberSite != NULL && memberSite->receiverGate == XL6_IR_CALL_RECEIVER_NULLABLE_GETTER)
                return xl6IrLowerNullablePropertyGet(ctx, id, node, memberSite);
            if (xl6IrNodeIsDynamicMemberRead(ctx->module, id))
                return xl6IrLowerDynamicCall(ctx, id, node);
            result = xl6IrLowerNumericEnumVariantMember(ctx, id, node);
            if ( result != XL6_IR_VALUE_INVALID ) return result;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            result = xl6IrLowerResolvedPropertyGet(ctx, id, node);
            if ( result != XL6_IR_VALUE_INVALID ) return result;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            if ( node->callKind == XL6_SEM_CALL_PROTOCOL ) {
                const XL6_IrCallSite* syntaxSite =
                    xl6IrCallSiteGet(ctx->module, id);
                if ( syntaxSite == NULL ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR resolved member protocol has no canonical CallSite");
                    return XL6_IR_VALUE_INVALID;
                }
                return xl6IrLowerResolvedSyntaxCall(
                    ctx, id, node, syntaxSite);
            }
            int staticFieldLoad = xl6IrLowerClassStaticFieldLoad(ctx, id, node, &result);
            if ( staticFieldLoad > 0 ) return result;
            if ( staticFieldLoad < 0 ) return XL6_IR_VALUE_INVALID;
            result = xl6IrLowerProtocolPropertyGet(ctx, id, node);
            if ( result != XL6_IR_VALUE_INVALID ) return result;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            result = xl6IrLowerErrorMember(ctx, id, node);
            if ( result != XL6_IR_VALUE_INVALID ) return result;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            XL6_IrValueId stringCount = xl6IrLowerBuiltinSequenceLength(ctx, id, node);
            if ( stringCount != XL6_IR_VALUE_INVALID ) return stringCount;
            XL6_IrValueId lengthProtocol =
                xl6IrLowerLengthProtocolCall(ctx, id, node);
            if ( lengthProtocol != XL6_IR_VALUE_INVALID ) return lengthProtocol;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            XL6_IrValueId safeClassField =
                xl6IrLowerSafeClassFieldProject(ctx, id, node);
            if ( safeClassField != XL6_IR_VALUE_INVALID ) return safeClassField;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            XL6_IrValueId classField = xl6IrLowerClassFieldProject(ctx, id, node);
            if ( classField != XL6_IR_VALUE_INVALID ) return classField;
            XL6_IrValueId inlineUnionField =
                xl6IrLowerClassInlineUnionFieldProject(ctx, id, node);
            if ( inlineUnionField != XL6_IR_VALUE_INVALID )
                return inlineUnionField;
            XL6_IrValueId unionField = xl6IrLowerUnionFieldProject(ctx, id, node);
            if ( unionField != XL6_IR_VALUE_INVALID ) return unionField;
            if ( ctx->failed ) return XL6_IR_VALUE_INVALID;
            XL6_IrValueId count = xl6IrLowerRuntimeXValueCount(ctx, id, node);
            if ( count != XL6_IR_VALUE_INVALID ) return count;
            XL6_IrValueId safeCount =
                xl6IrLowerRuntimeXValueSafeCount(ctx, id, node);
            if ( safeCount != XL6_IR_VALUE_INVALID ) return safeCount;
            XL6_IrValueId closureField =
                xl6IrLowerRuntimeXValueMemberGetClosure(ctx, id, node);
            if ( closureField != XL6_IR_VALUE_INVALID ) return closureField;
            XL6_IrValueId integerField = xl6IrLowerRuntimeXValueMemberGetInteger(ctx, id, node);
            if ( integerField != XL6_IR_VALUE_INVALID ) return integerField;
            XL6_IrValueId stringField = xl6IrLowerRuntimeXValueMemberGetStringCopy(ctx, id, node);
            if ( stringField != XL6_IR_VALUE_INVALID ) return stringField;
            XL6_IrValueId taggedNullableField =
                xl6IrLowerRuntimeXValueMemberGetTaggedNullable(ctx, id, node);
            if ( taggedNullableField != XL6_IR_VALUE_INVALID ) return taggedNullableField;
            XL6_IrValueId nativeHandleField =
                xl6IrLowerNativeHandleFieldProject(ctx, id, node);
            if ( nativeHandleField != XL6_IR_VALUE_INVALID ) return nativeHandleField;
        }
        return xl6IrLowerRuntimeXValueMemberGetLiteral(ctx, id, node);
    case XL6_IR_NODE_CALL:
        {
            const XL6_IrNode* args;
            const XL6_IrNode* callee;
            XL6_IrValueId* operands = NULL;
            XL6_SymbolId* borrowedTemps = NULL;
            const XL6_IrCallTarget* target;
            const XL6_IrCallSite* callSite;
            const XL6_IrIntrinsicCall* intrinsic;
            const XL6_IrExitPlan* errorPlan = NULL;
            const XL6_IrType* callResultType;
            XL6_IrTypeId returnType;
            XL6_IrTypeId physicalReturnType;
            char callResultDiagnostic[192];
            size_t argumentOffset = 0;
            size_t operandCount;
            size_t dispatchSlot = SIZE_MAX;
            size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
            int callEmitted;
            int builtinLowered;
            intrinsic = xl6IrIntrinsicCallGet(ctx->module, id);
            if ( node->callKind == XL6_SEM_CALL_ENUM_VARIANT )
                return xl6IrLowerTaggedEnumVariantCall(ctx, id, node);
            if ( node->callKind == XL6_SEM_CALL_BASE_CONSTRUCTOR )
                return xl6IrLowerBaseConstructorCall(ctx, id, node);
            if ( node->callKind == XL6_SEM_CALL_FUNCTION_VALUE )
                return xl6IrLowerFunctionValueCall(ctx, id, node);
            if ( (node->callKind == XL6_SEM_CALL_DYNAMIC_FUNCTION ||
                  node->callKind == XL6_SEM_CALL_DYNAMIC_METHOD) &&
                 intrinsic == NULL )
                return xl6IrLowerDynamicCall(ctx, id, node);
            if ( node->callKind == XL6_SEM_CALL_WITNESS )
                return xl6IrLowerProtocolCall(ctx, id, node);
            if ( node->callKind == XL6_SEM_CALL_CONSTRUCTOR ) {
                const XL6_IrCallTarget* constructor = xl6IrCallTargetGet(ctx->module, node->targetSymbol);
                const XL6_IrNativeHandleBind* nativeBind =
                    xl6IrNativeHandleBindGet(ctx->module, id);
                /* Native/runtime-backed classes expose constructor syntax as
                 * a resolved extern factory.  They already have a complete
                 * ordinary call ABI and must not be rewritten into a `self`
                 * receiver call reserved for source-level create bodies. */
                if ( nativeBind != NULL )
                    return xl6IrLowerNativeHandleBind(ctx, id, nativeBind);
                if ( constructor == NULL || constructor->kind == XL6_IR_CALL_TARGET_INTERNAL )
                    return xl6IrLowerConstructorCall(ctx, id, node);
            }
             if ( intrinsic != NULL ) {
                if ( intrinsic->admission != XL6_IR_INTRINSIC_ADMISSION_VERIFIED ) {
                    switch ( intrinsic->kind ) {
                    case XL6_IR_INTRINSIC_WEAK_LOCK:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR weak lock has no exact borrowed receiver and owned nullable result ABI");
                        break;
                    case XL6_IR_INTRINSIC_RUNTIME_RESOURCE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR runtime resource intrinsic has no exact resource, operation, ownership or failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_CHECKED_INTEGER_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR checked integer intrinsic has no exact conversion and failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_CHECKED_FLOAT_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR checked float intrinsic has no exact borrowed string/xvalue, F64 result and failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_CHECKED_XVALUE_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR checked xvalue intrinsic has no exact borrowed source, raw-pointer result and failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_CHECKED_TIME_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR checked time intrinsic has no exact borrowed string/xvalue, time result and failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_STRING_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR string intrinsic has no exact source and owned result ABI");
                        break;
                    case XL6_IR_INTRINSIC_SCALAR_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR scalar intrinsic has no exact source and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_ERASED_COLLECTION_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR erased collection conversion has no exact consumed source, target tag or failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_COPY:
                    case XL6_IR_INTRINSIC_CLONE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR copy intrinsic has no exact borrowed source and owned result ABI");
                        break;
                    case XL6_IR_INTRINSIC_ARRAY_APPEND:
                    case XL6_IR_INTRINSIC_SET_ADD:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR collection insertion has no complete erased-container ABI");
                        break;
                    case XL6_IR_INTRINSIC_COLLECTION_CONTAINS:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR collection contains has no exact borrowed receiver, item or boolean result ABI");
                        break;
                    case XL6_IR_INTRINSIC_COLLECTION_REMOVE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR collection remove has no exact borrowed receiver, index/element/key or boolean result ABI");
                        break;
                    case XL6_IR_INTRINSIC_ARRAY_REMOVE_VALUE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR array remove-value has no exact borrowed receiver, element TypeId or boolean result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TYPED_COLLECTION_MEMBER:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR typed collection member has no implemented exact operation, receiver, operand or result ABI");
                        break;
                    case XL6_IR_INTRINSIC_DYNAMIC_COLLECTION_MEMBER:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR dynamic collection member has no exact open receiver, operation, consumed arguments or owned result ABI");
                        break;
                    case XL6_IR_INTRINSIC_RANGE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR range intrinsic has no scalar integer descriptor ABI");
                        break;
                    case XL6_IR_INTRINSIC_XCALL:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR xcall intrinsic has no exact callable, owned result or failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_FUTURE_CANCEL:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR future cancel intrinsic has no exact borrowed Future and boolean result ABI");
                        break;
                    case XL6_IR_INTRINSIC_FUTURE_WAIT:
                    case XL6_IR_INTRINSIC_FUTURE_WAIT_TIMEOUT:
                    case XL6_IR_INTRINSIC_FUTURE_WAIT_UNTIL:
                    case XL6_IR_INTRINSIC_FUTURE_IS_DONE:
                    case XL6_IR_INTRINSIC_FUTURE_IS_PENDING:
                    case XL6_IR_INTRINSIC_FUTURE_IS_CANCELLED:
                    case XL6_IR_INTRINSIC_FUTURE_IS_FAILED:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR Future member intrinsic has no exact operation, borrowed receiver, time operand or boolean result ABI");
                        break;
                    case XL6_IR_INTRINSIC_FUTURE_STATE:
                    case XL6_IR_INTRINSIC_FUTURE_STATUS:
                    case XL6_IR_INTRINSIC_FUTURE_ERROR:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR Future state/status/error intrinsic has no exact borrowed receiver and result ownership ABI");
                        break;
                    case XL6_IR_INTRINSIC_FUTURE_SET_DEBUG_NAME:
                    case XL6_IR_INTRINSIC_FUTURE_DEBUG_NAME:
                    case XL6_IR_INTRINSIC_FUTURE_CREATE_TIME_MS:
                    case XL6_IR_INTRINSIC_FUTURE_COMPLETE_TIME_MS:
                    case XL6_IR_INTRINSIC_FUTURE_PENDING_CONTINUATIONS:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR Future metadata intrinsic has no exact borrowed receiver, optional name and result ownership ABI");
                        break;
                    case XL6_IR_INTRINSIC_FUTURE_THEN:
                    case XL6_IR_INTRINSIC_FUTURE_CATCH:
                    case XL6_IR_INTRINSIC_FUTURE_FINALLY:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR Future continuation has no exact receiver, closure, payload and failure ABI");
                        break;
                    case XL6_IR_INTRINSIC_TRIVIAL_INTEGER_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR trivial integer intrinsic has no exact source, target and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_WRAPPING_INTEGER_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR wrapping integer intrinsic has no exact modulo source and target ABI");
                        break;
                    case XL6_IR_INTRINSIC_BOOL_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR bool intrinsic has no exact scalar, null or borrowed xvalue truth ABI");
                        break;
                    case XL6_IR_INTRINSIC_PERSISTENCE_JSON_STRINGIFY:
                    case XL6_IR_INTRINSIC_PERSISTENCE_XLON_STRINGIFY:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR persistence stringify intrinsic has no exact format, borrowed class, schema, pretty flag and owned string ABI");
                        break;
                    case XL6_IR_INTRINSIC_PERSISTENCE_JSON_WRITE:
                    case XL6_IR_INTRINSIC_PERSISTENCE_XLON_WRITE:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR persistence write intrinsic has no exact format, borrowed path/class, schema, pretty flag and boolean ABI");
                        break;
                    case XL6_IR_INTRINSIC_PERSISTENCE_JSON_PARSE:
                    case XL6_IR_INTRINSIC_PERSISTENCE_XLON_PARSE:
                    case XL6_IR_INTRINSIC_PERSISTENCE_JSON_READ:
                    case XL6_IR_INTRINSIC_PERSISTENCE_XLON_READ:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR persistence parse intrinsic has no exact format, borrowed text, default class and schema ABI");
                        break;
                    case XL6_IR_INTRINSIC_TRIVIAL_IDENTITY_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR trivial identity intrinsic has no exact same-type value ABI");
                        break;
                    case XL6_IR_INTRINSIC_RAW_POINTER_NULL_CONVERT:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR raw-pointer null intrinsic has no exact null-sentinel result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TYPE_OF:
                        xl6IrLowerDiag(ctx, id,
                            intrinsic->typeQueryAbi == XL6_IR_TYPE_QUERY_DYNAMIC_XVALUE
                                ? "XLIR type-of dynamic xvalue query has no explicit runtime identity ABI"
                                : "XLIR type-of intrinsic has no exact static type identity ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_ALL:
                        xl6IrLowerDiag(ctx, id,
                            intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_INVALID &&
                            intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID &&
                            !xl6IrLowerTaskAllPayloadBoxerSupported(
                                ctx->module, intrinsic->payloadType,
                                intrinsic->payloadAbi)
                                ? "XLIR task.all payload has no canonical xvalue boxing ABI"
                                : "XLIR task aggregate has no exact flattened Future operands and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_RACE:
                    case XL6_IR_INTRINSIC_TASK_WHEN_ANY:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR task aggregate has no exact flattened Future operands and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_WHEN_ANY_ARRAY:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR task.whenAny has no exact borrowed array<Future<T>> and Future<I64> ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_ALL_ARRAY:
                        xl6IrLowerDiag(ctx, id,
                            intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_INVALID &&
                            intrinsic->payloadAbi != XL6_IR_ASYNC_RESULT_VOID &&
                            !xl6IrLowerTaskAllPayloadBoxerSupported(
                                ctx->module, intrinsic->payloadType,
                                intrinsic->payloadAbi)
                                ? "XLIR task.all array payload has no canonical xvalue boxing ABI"
                                : "XLIR task all/race has no exact borrowed array<Future<T>>, payload and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_RACE_ARRAY:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR task all/race has no exact borrowed array<Future<T>>, payload and result ABI");
                        break;
                    case XL6_IR_INTRINSIC_TASK_SPAWN:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR task spawn has no exact borrowed closure, canonical argument frame and Future payload ABI");
                        break;
                    default:
                        xl6IrLowerDiag(ctx, id,
                            "XLIR intrinsic call has no verified admission ABI");
                        break;
                    }
                    return XL6_IR_VALUE_INVALID;
                }
                 switch ( intrinsic->kind ) {
                case XL6_IR_INTRINSIC_WEAK_LOCK:
                    builtinLowered = xl6IrLowerIntrinsicWeakLock(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_RUNTIME_RESOURCE:
                    builtinLowered = xl6IrLowerIntrinsicRuntimeResource(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_CHECKED_INTEGER_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicCheckedIntegerConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_CHECKED_FLOAT_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicCheckedFloatConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_CHECKED_XVALUE_CONVERT:
                    builtinLowered =
                        xl6IrLowerIntrinsicCheckedXValueConvert(
                            ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_CHECKED_TIME_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicCheckedTimeConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_WRAPPING_INTEGER_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicWrappingIntegerConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_BOOL_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicBoolConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_STRINGIFY:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_STRINGIFY:
                    builtinLowered =
                        xl6IrLowerIntrinsicPersistenceLegacy(
                            ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_WRITER_VALUE:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_WRITER_NAME:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_WRITER_VALUE:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_WRITER_NAME:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_WRITER_INDEX:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_CONFIG_STRINGIFY:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_CONFIG_STRINGIFY:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSONL_CONFIG_STRINGIFY:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLONL_CONFIG_STRINGIFY:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_CONFIG_WRITE:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_CONFIG_WRITE:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSONL_CONFIG_WRITE:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLONL_CONFIG_WRITE:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_CONFIG_SINK:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_CONFIG_SINK:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSONL_CONFIG_SINK:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLONL_CONFIG_SINK:
                    builtinLowered = xl6IrLowerIntrinsicPersistenceInvocation(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_WRITE:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_WRITE:
                    builtinLowered =
                        xl6IrLowerIntrinsicPersistenceLegacy(
                            ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_PARSE:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_PARSE:
                case XL6_IR_INTRINSIC_PERSISTENCE_JSON_READ:
                case XL6_IR_INTRINSIC_PERSISTENCE_XLON_READ:
                    builtinLowered =
                        xl6IrLowerIntrinsicPersistenceParse(
                            ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_STRING_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicStringConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_SCALAR_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicScalarConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_ERASED_COLLECTION_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicErasedCollectionConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_COPY:
                case XL6_IR_INTRINSIC_CLONE:
                    builtinLowered = xl6IrLowerIntrinsicCopyClone(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_ARRAY_APPEND:
                case XL6_IR_INTRINSIC_SET_ADD:
                    builtinLowered = xl6IrLowerIntrinsicCollectionInsert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_COLLECTION_CONTAINS:
                    builtinLowered = xl6IrLowerIntrinsicCollectionContains(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_COLLECTION_REMOVE:
                    builtinLowered = xl6IrLowerIntrinsicCollectionRemove(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_ARRAY_REMOVE_VALUE:
                    builtinLowered = xl6IrLowerIntrinsicArrayRemoveValue(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TYPED_COLLECTION_MEMBER:
                    builtinLowered = xl6IrLowerIntrinsicTypedCollectionMember(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_DYNAMIC_COLLECTION_MEMBER:
                    builtinLowered = xl6IrLowerIntrinsicDynamicCollectionMember(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_XCALL:
                    builtinLowered = xl6IrLowerIntrinsicXCall(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_FUTURE_CANCEL:
                    builtinLowered = xl6IrLowerIntrinsicFutureCancel(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_FUTURE_WAIT:
                case XL6_IR_INTRINSIC_FUTURE_WAIT_TIMEOUT:
                case XL6_IR_INTRINSIC_FUTURE_WAIT_UNTIL:
                case XL6_IR_INTRINSIC_FUTURE_IS_DONE:
                case XL6_IR_INTRINSIC_FUTURE_IS_PENDING:
                case XL6_IR_INTRINSIC_FUTURE_IS_CANCELLED:
                case XL6_IR_INTRINSIC_FUTURE_IS_FAILED:
                    builtinLowered = xl6IrLowerIntrinsicFutureMember(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_FUTURE_STATE:
                case XL6_IR_INTRINSIC_FUTURE_STATUS:
                case XL6_IR_INTRINSIC_FUTURE_ERROR:
                    builtinLowered = xl6IrLowerIntrinsicFutureInspection(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_FUTURE_SET_DEBUG_NAME:
                case XL6_IR_INTRINSIC_FUTURE_DEBUG_NAME:
                case XL6_IR_INTRINSIC_FUTURE_CREATE_TIME_MS:
                case XL6_IR_INTRINSIC_FUTURE_COMPLETE_TIME_MS:
                case XL6_IR_INTRINSIC_FUTURE_PENDING_CONTINUATIONS:
                    builtinLowered = xl6IrLowerIntrinsicFutureMetadata(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_FUTURE_THEN:
                case XL6_IR_INTRINSIC_FUTURE_CATCH:
                case XL6_IR_INTRINSIC_FUTURE_FINALLY:
                    builtinLowered =
                        xl6IrLowerIntrinsicFutureContinuation(
                            ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TRIVIAL_INTEGER_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicTrivialIntegerConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TRIVIAL_IDENTITY_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicTrivialIdentityConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_RAW_POINTER_NULL_CONVERT:
                    builtinLowered = xl6IrLowerIntrinsicRawPointerNullConvert(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TYPE_OF:
                    builtinLowered = xl6IrLowerIntrinsicTypeOf(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TASK_ALL:
                case XL6_IR_INTRINSIC_TASK_RACE:
                case XL6_IR_INTRINSIC_TASK_WHEN_ANY:
                    builtinLowered = xl6IrLowerIntrinsicTaskAggregate(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TASK_WHEN_ANY_ARRAY:
                    builtinLowered = xl6IrLowerIntrinsicTaskWhenAnyArray(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TASK_ALL_ARRAY:
                case XL6_IR_INTRINSIC_TASK_RACE_ARRAY:
                    builtinLowered = xl6IrLowerIntrinsicTaskAggregateArray(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_TASK_SPAWN:
                    builtinLowered = xl6IrLowerIntrinsicTaskSpawn(
                        ctx, id, node, intrinsic, &result);
                    break;
                case XL6_IR_INTRINSIC_RANGE:
                    xl6IrLowerDiag(ctx, id,
                        "XLIR range descriptor may only be consumed by normalized for-loop lowering");
                    return XL6_IR_VALUE_INVALID;
                default:
                    builtinLowered = 0;
                    break;
                }
                if ( builtinLowered <= 0 ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR intrinsic call does not match its verified typed ABI");
                    return XL6_IR_VALUE_INVALID;
                }
                return result;
            }
            if ( node->callKind == XL6_SEM_CALL_NONE || node->targetSymbol == 0 || node->childCount != 2 ) {
                xl6IrLowerDiag(ctx, id, "XLIR call has no resolved direct target or canonical argument list"); return 0;
            }
            target = xl6IrCallTargetGet(ctx->module, node->targetSymbol);
            if ( target != NULL && xl6IrLowerCallTargetNeedsMonomorphization(ctx->module, target) ) {
                xl6IrLowerDiag(ctx, id,
                                "XLIR generic call requires lowering-time monomorphization into a concrete instance ABI");
                return 0;
            }
            callResultType = xl6IrTypeGet(&ctx->module->types, node->storageType);
            if ( !xl6IrLowerResolvedCallReturnType(ctx, node, &returnType) ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR call result has no canonical target function ABI: resolved target has no return contract");
                return 0;
            }
            if ( (returnType == XL6_IR_TYPE_INVALID && node->storageType != XL6_IR_TYPE_INVALID &&
                  (callResultType == NULL || callResultType->cAbi != XL6_IR_C_ABI_VOID)) ||
                 (returnType != XL6_IR_TYPE_INVALID && node->storageType == XL6_IR_TYPE_INVALID) ||
                 (returnType != XL6_IR_TYPE_INVALID && node->storageType != returnType &&
                   !xl6IrLowerCallableTypesCompatible(ctx->module, returnType, node->storageType)) ) {
                (void)snprintf(callResultDiagnostic,
                    sizeof(callResultDiagnostic),
                    "XLIR call result has no canonical target function ABI: target s%u returns t%u, call n%u expects t%u",
                    (unsigned int)node->targetSymbol,
                    (unsigned int)returnType, (unsigned int)id,
                    (unsigned int)node->storageType);
                xl6IrLowerDiag(ctx, id, callResultDiagnostic);
                return 0;
            }
            target = xl6IrCallTargetGet(ctx->module, node->targetSymbol);
            if ( target == NULL ) { xl6IrLowerDiag(ctx, id, "XLIR call has no canonical target ABI"); return 0; }
            physicalReturnType = xl6IrLowerCallTargetPhysicalResultType(
                ctx->module, target);
            if ( target->returnType != XL6_IR_TYPE_INVALID &&
                 physicalReturnType == XL6_IR_TYPE_INVALID ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR call target has no verified physical result ABI");
                return XL6_IR_VALUE_INVALID;
            }
            callSite = xl6IrCallSiteGet(ctx->module, id);
            if ( callSite != NULL && callSite->variadicAbi != XL6_IR_CALL_VARIADIC_NONE &&
                 target->variadicAbi != callSite->variadicAbi ) {
                xl6IrLowerDiag(ctx, id, "XLIR CallSite variadic ABI does not match its target");
                return XL6_IR_VALUE_INVALID;
            }
            if ( target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE ) {
                if ( (errorPlan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW)) == NULL ) {
                    xl6IrLowerDiag(ctx, id, "XLIR may-raise call has no result-carrier or propagation cleanup ABI");
                    return XL6_IR_VALUE_INVALID;
                }
            }
            args = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
            if ( args == NULL || args->kind != XL6_IR_NODE_LIST ) {
                xl6IrLowerDiag(ctx, id, "XLIR call arguments are not normalized"); return 0;
            }
            callee = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
            if ( callSite != NULL ) {
                argumentOffset = callSite->receiver != XL6_IR_NODE_INVALID ? 1 : 0;
            } else if ( callee != NULL && callee->kind == XL6_IR_NODE_MEMBER && callee->childCount == 1 &&
                        target->parameterCount == args->childCount + 1 &&
                        xl6IrLowerTypeIsClassReceiver(ctx->module, target->parameterTypes[0]) ) {
                argumentOffset = 1;
            }
            dispatchSlot = callSite != NULL && callSite->dispatchSlot != 0 &&
                callSite->dispatchSlot <= ctx->module->classDispatchSlotCount
                ? (size_t)(callSite->dispatchSlot - 1) : SIZE_MAX;
            if ( dispatchSlot != SIZE_MAX ) {
                const XL6_IrClassDispatchSlot* slot = &ctx->module->classDispatchSlots[dispatchSlot];
                if ( argumentOffset != 1 ||
                     slot->returnType != returnType ||
                      slot->parameterCount != (callSite != NULL
                          ? callSite->fixedParameterCount +
                            (callSite->variadicAbi != XL6_IR_CALL_VARIADIC_NONE ? 1u : 0u)
                          : args->childCount) ) {
                    xl6IrLowerDiag(ctx, id,
                                    "XLIR virtual call has no exact receiver or result dispatch ABI");
                    return XL6_IR_VALUE_INVALID;
                }
            }
            /* An explicit native lifecycle destroy consumes its owned local
             * handle.  Remove the same typed cleanup action that would run
             * on every exit edge, so normal fallthrough and exceptional paths
             * cannot issue a second destructor call. */
            if ( argumentOffset == 1 && xl6IrLowerNativeSpecialIsDestroy(
                     ctx->module, target->symbol) ) {
                const XL6_IrNode* receiver = xl6IrNodeGet(
                    ctx->module, callSite != NULL ? callSite->receiver
                        : ctx->module->children[callee->firstChild]);
                const XL6_IrStorage* receiverStorage = receiver != NULL
                    ? xl6IrStorageGet(ctx->module, receiver->targetSymbol) : NULL;
                const XL6_IrType* receiverType = receiverStorage != NULL
                    ? xl6IrTypeGet(&ctx->module->types, receiverStorage->type) : NULL;
                if ( receiverStorage != NULL && receiverStorage->kind == XL6_IR_STORAGE_LOCAL &&
                     receiverStorage->cellType == XL6_IR_TYPE_INVALID && receiverType != NULL &&
                     receiverType->cAbi == XL6_IR_C_ABI_NATIVE_HANDLE &&
                     !xl6IrLowerRemoveUnmaterializedLocalCleanup(
                         ctx, receiverStorage->declaration, receiverStorage->symbol) ) {
                    xl6IrLowerDiag(ctx, id,
                                    "XLIR explicit native destroy could not consume local cleanup ownership");
                    return XL6_IR_VALUE_INVALID;
                }
            }
            operandCount = (callSite != NULL
                ? callSite->fixedParameterCount +
                  (callSite->variadicAbi == XL6_IR_CALL_VARIADIC_ARRAY ||
                   callSite->variadicAbi == XL6_IR_CALL_VARIADIC_DICT
                      ? 1u
                      : callSite->variadicAbi == XL6_IR_CALL_VARIADIC_C
                          ? callSite->argumentCount - callSite->fixedParameterCount : 0u)
                : args->childCount) +
                argumentOffset;
            if ( target->variadicAbi == XL6_IR_CALL_VARIADIC_C
                    ? operandCount < target->parameterCount
                    : target->parameterCount != operandCount ) {
                xl6IrLowerDiag(ctx, id, "XLIR call arguments do not match its verified target ABI"); return 0;
            }
            if ( operandCount > 0 ) {
                operands = (XL6_IrValueId*)xrtCalloc(operandCount, sizeof(*operands));
                borrowedTemps = (XL6_SymbolId*)xrtCalloc(operandCount, sizeof(*borrowedTemps));
                if ( operands == NULL || borrowedTemps == NULL ) { xrtFree(operands); xrtFree(borrowedTemps); ctx->failed = 1; return 0; }
            }
            if ( argumentOffset != 0 ) {
                XL6_IrNodeId receiverId = callSite != NULL ? callSite->receiver
                    : ctx->module->children[callee->firstChild];
                const XL6_IrNode* receiverNode =
                    xl6IrNodeGet(ctx->module, receiverId);
                const XL6_IrNativeHandleBind* receiverBind;
                operands[0] = xl6IrLowerNodeAsType(
                    ctx, id, receiverId, receiverNode,
                    target->parameterTypes[0]);
                operands[0] = xl6IrLowerAnchorResolvedCallBorrow(
                    ctx, id, receiverId, receiverNode,
                    target->parameterTypes[0], target->parameterAbis[0],
                    operands[0], &borrowedTemps[0]);
                if ( operands[0] == XL6_IR_VALUE_INVALID ) { xrtFree(operands); xrtFree(borrowedTemps); return 0; }
                receiverBind = xl6IrNativeHandleBindGet(ctx->module, receiverId);
                if ( borrowedTemps[0] == 0 && receiverBind != NULL &&
                     receiverBind->abi == XL6_IR_NATIVE_HANDLE_BIND_TAKE &&
                     target->parameterAbis[0] == XL6_IR_PARAMETER_ABI_BORROW &&
                     target->parameterTypes[0] == receiverBind->targetType ) {
                    XL6_IrValueId loaded;
                    borrowedTemps[0] = xl6IrLowerNewTempStorage(
                        ctx, receiverBind->targetType, id);
                    if ( borrowedTemps[0] == 0 ||
                         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, receiverId,
                                          receiverBind->targetType, borrowedTemps[0],
                                          &operands[0], 1, NULL) ||
                         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, receiverId,
                                          receiverBind->targetType, borrowedTemps[0],
                                          NULL, 0, &loaded) ) {
                        xrtFree(operands); xrtFree(borrowedTemps); return 0;
                    }
                    operands[0] = loaded;
                }
                if ( borrowedTemps[0] != 0 && !xl6IrLowerProtectEvaluationStorage(
                         ctx, receiverId, borrowedTemps[0], operands[0], 0,
                         receiverBind != NULL && receiverBind->abi == XL6_IR_NATIVE_HANDLE_BIND_TAKE
                             ? receiverBind->destroySymbol : 0) ) {
                    xrtFree(operands); xrtFree(borrowedTemps); return 0;
                }
            }
            for ( i = 0; i < (callSite != NULL ? callSite->argumentCount : args->childCount); ++i ) {
                const XL6_IrCallArgument* binding = callSite != NULL
                    ? xl6IrCallSiteEvaluationArgument(ctx->module, callSite, i) : NULL;
                if (binding != NULL && binding->source == XL6_IR_CALL_ARGUMENT_C_VARARG_ITEM) {
                    const XL6_IrNode* expression = xl6IrNodeGet(ctx->module, binding->expression);
                    size_t operandIndex = argumentOffset + (size_t)(binding - &ctx->module->callArguments[callSite->firstArgument]);
                    if ( expression == NULL ||
                         !xl6IrTypeSupportsCVararg(ctx->module, expression->storageType) ) {
                        xrtFree(operands); xrtFree(borrowedTemps);
                        xl6IrLowerDiag(ctx, id,
                                       "XLIR C variadic tail item has no native scalar or pointer ABI");
                        return XL6_IR_VALUE_INVALID;
                    }
                    operands[operandIndex] = xl6IrLowerNode(ctx, binding->expression);
                    if ( operands[operandIndex] == XL6_IR_VALUE_INVALID ) {
                        xrtFree(operands); xrtFree(borrowedTemps);
                        return XL6_IR_VALUE_INVALID;
                    }
                    if ( xl6IrTypeGet(&ctx->module->types, expression->storageType)->ownershipAbi ==
                             XL6_IR_OWNERSHIP_ABI_MANAGED ) {
                        XL6_IrValueId loaded;
                        borrowedTemps[operandIndex] = xl6IrLowerNewTempStorage(
                            ctx, expression->storageType, id);
                        if ( borrowedTemps[operandIndex] == 0 ||
                             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, binding->expression,
                                              expression->storageType, borrowedTemps[operandIndex],
                                              &operands[operandIndex], 1, NULL) ||
                             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, binding->expression,
                                              expression->storageType, borrowedTemps[operandIndex],
                                              NULL, 0, &loaded) ) {
                            xrtFree(operands); xrtFree(borrowedTemps);
                            return XL6_IR_VALUE_INVALID;
                        }
                        operands[operandIndex] = loaded;
                        if ( !xl6IrLowerProtectEvaluationStorage(
                                 ctx, binding->expression, borrowedTemps[operandIndex],
                                 loaded, 0, 0) ) {
                            xrtFree(operands); xrtFree(borrowedTemps);
                            return XL6_IR_VALUE_INVALID;
                        }
                    }
                    continue;
                }
                if (binding != NULL && (binding->source == XL6_IR_CALL_ARGUMENT_ARRAY_VARARG_ITEM ||
                    binding->source == XL6_IR_CALL_ARGUMENT_DICT_VARARG_ITEM)) {
                    size_t parameter = callSite->fixedParameterCount + argumentOffset;
                    if (!xl6IrLowerPrepareCallSiteAggregate(ctx, id, callSite, target->parameterTypes[parameter],
                            target->parameterAbis[parameter], &operands[parameter], &borrowedTemps[parameter]) ||
                        !xl6IrLowerCallSiteAggregateAppend(ctx, id, callSite, binding, operands[parameter])) {
                        xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
                    }
                    continue;
                }
                size_t parameterIndex = (binding != NULL ? binding->parameter : i) + argumentOffset;
                const XL6_IrNode* argument = binding == NULL
                    ? xl6IrNodeGet(ctx->module, ctx->module->children[args->firstChild + i]) : NULL;
                XL6_IrNodeId argumentExprId;
                const XL6_IrNode* argumentExpr;
                if ( binding != NULL ) {
                    argumentExprId = binding->expression;
                } else if ( argument == NULL || argument->sourceKind != XL6_AST_ARG ||
                            argument->flags != 0 || argument->childCount != 1 ) {
                    xrtFree(operands); xrtFree(borrowedTemps);
                    xl6IrLowerDiag(ctx, id, "XLIR call requires normalized positional value arguments"); return 0;
                } else {
                    argumentExprId = ctx->module->children[argument->firstChild];
                }
                argumentExpr = xl6IrNodeGet(ctx->module, argumentExprId);
                if ( target->parameterAbis[parameterIndex] ==
                         XL6_IR_PARAMETER_ABI_INOUT ||
                     target->parameterAbis[parameterIndex] ==
                         XL6_IR_PARAMETER_ABI_OUT ) {
                    operands[parameterIndex] = xl6IrLowerEmitStorageAddress(
                        ctx, id, argumentExprId, argumentExpr,
                        target->parameterTypes[parameterIndex]);
                    if ( operands[parameterIndex] == XL6_IR_VALUE_INVALID ) {
                        xrtFree(operands); xrtFree(borrowedTemps);
                        return 0;
                    }
                    continue;
                }
                operands[parameterIndex] = binding != NULL
                    ? xl6IrLowerCallArgumentAsType(ctx, id, binding, target->parameterTypes[parameterIndex])
                    : xl6IrLowerNodeAsType(ctx, id, argumentExprId, argumentExpr, target->parameterTypes[parameterIndex]);
                if ( operands[parameterIndex] != XL6_IR_VALUE_INVALID &&
                     target->parameterTypes[parameterIndex] != XL6_IR_TYPE_INVALID &&
                     xl6IrLowerValueType(ctx, operands[parameterIndex]) !=
                         target->parameterTypes[parameterIndex] &&
                     xl6IrLowerCallableTypesCompatible(
                         ctx->module, xl6IrLowerValueType(ctx, operands[parameterIndex]),
                         target->parameterTypes[parameterIndex]) )
                    operands[parameterIndex] = xl6IrLowerEmitValueCopy(
                        ctx, argumentExprId, target->parameterTypes[parameterIndex],
                        operands[parameterIndex]);
                operands[parameterIndex] = xl6IrLowerPrepareOwnedCallArgument(
                    ctx, id, target->parameterTypes[parameterIndex],
                    target->parameterAbis[parameterIndex], argumentExpr,
                    operands[parameterIndex]);
                if ( operands[parameterIndex] == XL6_IR_VALUE_INVALID ) { xrtFree(operands); xrtFree(borrowedTemps); return 0; }
                if ( target->parameterPhysicalAbis[parameterIndex] ==
                         XL6_IR_CALL_PARAMETER_PHYSICAL_RAW_C_CALLBACK ) {
                    const XL6_IrFunction* owner =
                        ctx->functionIndex < ctx->module->functionCount
                            ? &ctx->module->functions[ctx->functionIndex] : NULL;
                    size_t forwardedParameter = SIZE_MAX;
                    XL6_IrLowerRawCallbackProvenance provenance =
                        xl6IrLowerRawCallbackValueProvenance(
                            ctx->module, owner, ctx->block,
                            operands[parameterIndex],
                            &forwardedParameter, 0);
                    if ( provenance ==
                         XL6_IR_LOWER_RAW_CALLBACK_FUNCTION_PARAMETER ) {
                        XL6_IrCallTarget* ownerTarget = NULL;
                        size_t targetIndex;
                        for ( targetIndex = 0;
                              owner != NULL &&
                              targetIndex < ctx->module->callTargetCount;
                              ++targetIndex )
                            if ( ctx->module->callTargets[targetIndex].symbol ==
                                 owner->symbol ) {
                                ownerTarget =
                                    &ctx->module->callTargets[targetIndex];
                                break;
                            }
                        if ( ownerTarget == NULL ||
                             forwardedParameter >= ownerTarget->parameterCount ||
                             ownerTarget->parameterConstraintAbis == NULL ||
                             ownerTarget->parameterTypes[forwardedParameter] !=
                                 target->parameterTypes[parameterIndex] )
                            provenance = XL6_IR_LOWER_RAW_CALLBACK_UNKNOWN;
                        else
                            ownerTarget->parameterConstraintAbis[
                                forwardedParameter] =
                                XL6_IR_CALL_PARAMETER_CONSTRAINT_RAW_CALLBACK_DIRECT_THUNK;
                    }
                    if ( provenance == XL6_IR_LOWER_RAW_CALLBACK_UNKNOWN ) {
                        xrtFree(operands); xrtFree(borrowedTemps);
                        xl6IrLowerDiag(ctx, argumentExprId,
                            "XLIR raw C callback argument has no verified direct-thunk provenance or propagated parameter contract");
                        return XL6_IR_VALUE_INVALID;
                    }
                }
                /* Route every ordinary borrowed operand through the one
                 * producer-aware anchoring rule.  Native TAKE is separate: it
                 * owns a raw handle plus an explicit destroy target rather
                 * than a ref-counted managed value. */
                {
                    const XL6_IrNativeHandleBind* nativeBind =
                        xl6IrNativeHandleBindGet(ctx->module, argumentExprId);
                    if ( nativeBind != NULL &&
                         nativeBind->abi == XL6_IR_NATIVE_HANDLE_BIND_TAKE &&
                         target->parameterAbis[parameterIndex] == XL6_IR_PARAMETER_ABI_BORROW &&
                         target->parameterTypes[parameterIndex] == nativeBind->targetType ) {
                        XL6_IrValueId loaded;
                        borrowedTemps[parameterIndex] = xl6IrLowerNewTempStorage(
                            ctx, nativeBind->targetType, id);
                        if ( borrowedTemps[parameterIndex] == 0 ||
                             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, argumentExprId,
                                              nativeBind->targetType,
                                              borrowedTemps[parameterIndex],
                                              &operands[parameterIndex], 1, NULL) ||
                             !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, argumentExprId,
                                              nativeBind->targetType,
                                              borrowedTemps[parameterIndex], NULL, 0, &loaded) ) {
                            xrtFree(operands); xrtFree(borrowedTemps); return 0;
                        }
                        operands[parameterIndex] = loaded;
                    } else {
                        operands[parameterIndex] =
                            xl6IrLowerAnchorResolvedCallBorrow(
                                ctx, id, argumentExprId, argumentExpr,
                                target->parameterTypes[parameterIndex],
                                target->parameterAbis[parameterIndex],
                                operands[parameterIndex],
                                &borrowedTemps[parameterIndex]);
                        if ( operands[parameterIndex] == XL6_IR_VALUE_INVALID ) {
                            xrtFree(operands); xrtFree(borrowedTemps);
                            return 0;
                        }
                    }
                }
                if ( target->parameterAbis[parameterIndex] == XL6_IR_PARAMETER_ABI_OWNED ) {
                    operands[parameterIndex] = xl6IrLowerProtectEvaluationValue(
                        ctx, argumentExprId, target->parameterTypes[parameterIndex],
                        operands[parameterIndex]);
                    if ( operands[parameterIndex] == XL6_IR_VALUE_INVALID ) {
                        xrtFree(operands); xrtFree(borrowedTemps); return 0;
                    }
                } else if ( borrowedTemps[parameterIndex] != 0 ) {
                    const XL6_IrNativeHandleBind* nativeBind =
                        xl6IrNativeHandleBindGet(ctx->module, argumentExprId);
                    if ( !xl6IrLowerProtectEvaluationStorage(
                             ctx, argumentExprId, borrowedTemps[parameterIndex],
                             operands[parameterIndex], 0,
                             nativeBind != NULL && nativeBind->abi == XL6_IR_NATIVE_HANDLE_BIND_TAKE
                                 ? nativeBind->destroySymbol : 0) ) {
                        xrtFree(operands); xrtFree(borrowedTemps); return 0;
                    }
                }
            }
            if (callSite != NULL && (callSite->variadicAbi == XL6_IR_CALL_VARIADIC_ARRAY ||
                callSite->variadicAbi == XL6_IR_CALL_VARIADIC_DICT)) {
                size_t parameter = callSite->fixedParameterCount + argumentOffset;
                if (!xl6IrLowerPrepareCallSiteAggregate(ctx, id, callSite, target->parameterTypes[parameter],
                        target->parameterAbis[parameter], &operands[parameter], &borrowedTemps[parameter])) {
                    xrtFree(operands); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
                }
            }
            /* Cross the CallTarget's single semantic-to-physical boundary only
             * after ownership and callback preparation has finished. */
            if ( !xl6IrLowerProjectCallTargetPhysicalOperands(
                     ctx, id, target, operands, operandCount) ||
                 !xl6IrLowerCommitEvaluationOwners(ctx, id, evaluationOwnerFirst) ) {
                xrtFree(operands); xrtFree(borrowedTemps);
                return XL6_IR_VALUE_INVALID;
            }
            callEmitted = xl6IrLowerEmit(ctx,
                                          dispatchSlot != SIZE_MAX ? XL6_IR_INSTR_VIRTUAL_CALL :
                                          (target->kind == XL6_IR_CALL_TARGET_INTERNAL_ASYNC
                                              ? XL6_IR_INSTR_ASYNC_START
                                              : target->kind == XL6_IR_CALL_TARGET_INTERNAL_GENERATOR
                                                  ? XL6_IR_INSTR_GENERATOR_START
                                                  : XL6_IR_INSTR_CALL),
                                          id, physicalReturnType,
                                          dispatchSlot != SIZE_MAX ? 0 : node->targetSymbol,
                                          operands, operandCount,
                                          physicalReturnType == XL6_IR_TYPE_INVALID &&
                                          xl6IrLowerSelectedCallErrorAbi(ctx->module, target, dispatchSlot) != XL6_IR_ERROR_ABI_MAY_RAISE
                                              ? NULL : &result);
            if ( callEmitted && dispatchSlot != SIZE_MAX )
                ctx->module->instructions[ctx->module->instructionCount - 1].dispatchSlot =
                    (uint32)(dispatchSlot + 1);
            xrtFree(operands);
            if (callEmitted) {
                XL6_SymbolId* nativeDestroys = NULL;
                XL6_IrLowerCallCleanup cleanup = {borrowedTemps, operandCount, NULL, 0, 0};
                for (i = 0; i < operandCount; ++i) {
                    const XL6_IrNativeHandleBind* bind = borrowedTemps[i] != 0
                        ? xl6IrLowerNativeBindForCallOperand(
                            ctx->module, callSite, callee, args, argumentOffset, i) : NULL;
                    if (bind != NULL && bind->abi == XL6_IR_NATIVE_HANDLE_BIND_TAKE) {
                        const XL6_IrStorage* storage = xl6IrStorageGet(ctx->module, borrowedTemps[i]);
                        if (storage == NULL || storage->type != bind->targetType || bind->destroySymbol == 0) {
                            xrtFree(nativeDestroys); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
                        }
                        if (nativeDestroys == NULL)
                            nativeDestroys = (XL6_SymbolId*)xrtCalloc(operandCount, sizeof(*nativeDestroys));
                        if (nativeDestroys == NULL) {
                            ctx->failed = 1; xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
                        }
                        nativeDestroys[i] = bind->destroySymbol;
                    }
                }
                if (!xl6IrLowerOrderCallCleanup(ctx, callSite, argumentOffset, borrowedTemps, nativeDestroys, operandCount)) {
                    xrtFree(nativeDestroys); xrtFree(borrowedTemps); return XL6_IR_VALUE_INVALID;
                }
                cleanup.nativeDestroys = nativeDestroys;
                callEmitted = xl6IrLowerCompleteCall(ctx, id, node, target, &result, errorPlan, &cleanup);
                xrtFree(nativeDestroys);
            }
            xrtFree(borrowedTemps);
            if ( callEmitted && returnType != XL6_IR_TYPE_INVALID && node->storageType != returnType ) {
                result = xl6IrLowerEmitValueCopy(ctx, id, node->storageType, result);
                if ( result == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
            }
            /* A may-raise void call still defines a carrier token consumed by
             * ERROR_TEST, but it has no language-level expression value. */
            return callEmitted && returnType != XL6_IR_TYPE_INVALID ? result : 0;
        }
    case XL6_IR_NODE_AWAIT:
        {
            const XL6_IrNode* futureNode;
            const XL6_IrType* futureType;
            const XL6_IrExitPlan* errorPlan;
            XL6_IrAsyncResultAbi resultAbi;
            XL6_IrTypeId awaitResultType;
            XL6_IrValueId future;
            XL6_SymbolId futureTemporary = 0;
            XL6_IrBlockId successBlock;
            XL6_IrBlockId failureBlock;
            XL6_IrInstruction* test;
            size_t awaitInstruction;
            if ( node->childCount != 1 || node->storageType == XL6_IR_TYPE_INVALID ||
                  (futureNode = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild])) == NULL ||
                  (futureType = xl6IrTypeGet(&ctx->module->types, futureNode->type)) == NULL ||
                  futureType->cAbi != XL6_IR_C_ABI_RUNTIME_FUTURE_PTR || futureType->paramCount != 1 ||
                  (errorPlan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW)) == NULL ) {
                xl6IrLowerDiag(ctx, id,
                                "XLIR await requires an exact resolved future result ABI");
                return XL6_IR_VALUE_INVALID;
            }
            awaitResultType = futureType->params[0];
            resultAbi = xl6IrLowerAsyncResultAbi(ctx->module, awaitResultType);
            if ( resultAbi == XL6_IR_ASYNC_RESULT_INVALID ||
                 (awaitResultType != node->storageType &&
                  !xl6IrLowerCallableTypesCompatible(
                      ctx->module, awaitResultType, node->storageType)) ) {
                xl6IrLowerDiag(ctx, id,
                                "XLIR await requires an exact or structurally compatible Future payload ABI");
                return XL6_IR_VALUE_INVALID;
            }
            if ( futureNode->kind != XL6_IR_NODE_NAME &&
                 futureNode->kind != XL6_IR_NODE_CALL &&
                 futureNode->kind != XL6_IR_NODE_CONDITIONAL &&
                 futureNode->kind != XL6_IR_NODE_INDEX ) {
                xl6IrLowerDiag(ctx, id,
                                "XLIR await requires a resolved future storage, call, index or conditional result");
                return XL6_IR_VALUE_INVALID;
            }
            if ( futureNode->kind == XL6_IR_NODE_CONDITIONAL ) {
                future = xl6IrLowerConditionalFutureOwned(ctx, id, futureNode, &futureTemporary);
            } else {
                future = xl6IrLowerNode(ctx, ctx->module->children[node->firstChild]);
            }
            if ( futureNode->kind == XL6_IR_NODE_CALL ||
                 futureNode->kind == XL6_IR_NODE_INDEX ) {
                XL6_IrValueId loaded;
                futureTemporary = xl6IrLowerNewTempStorage(ctx, futureNode->storageType, id);
                if ( future == XL6_IR_VALUE_INVALID || futureTemporary == 0 ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id, futureNode->storageType,
                                     futureTemporary, &future, 1, NULL) ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id, futureNode->storageType,
                                     futureTemporary, NULL, 0, &loaded) ) return XL6_IR_VALUE_INVALID;
                future = loaded;
            }
            awaitInstruction = ctx->module->instructionCount;
            if ( future == XL6_IR_VALUE_INVALID ||
                  !xl6IrLowerEmit(ctx, XL6_IR_INSTR_AWAIT, id,
                                  resultAbi == XL6_IR_ASYNC_RESULT_VOID
                                      ? XL6_IR_TYPE_INVALID : awaitResultType, 0,
                                 &future, 1, &result) ||
                 !xl6IrLowerNewBlock(ctx, &failureBlock) || !xl6IrLowerNewBlock(ctx, &successBlock) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_TEST, id, XL6_IR_TYPE_INVALID,
                                 0, &result, 1, NULL) ) {
                xl6IrLowerDiag(ctx, id, "XLIR await has no explicit success or failure CFG ABI");
                return XL6_IR_VALUE_INVALID;
            }
            /* The result ABI is a first-class instruction fact.  In
             * particular VOID's result id is only an ERROR_TEST dependency
             * token and is never a language value. */
            ctx->module->instructions[awaitInstruction].asyncResultAbi = resultAbi;
            ctx->module->instructions[awaitInstruction].futureOutcomeAbi = XL6_IR_FUTURE_OUTCOME_XRT_ERROR_KIND;
            ctx->module->instructions[awaitInstruction].awaitOutcomeAbi =
                XL6_IR_AWAIT_OUTCOME_STATUS_DIAGNOSTIC_NULL_STATE_ERROR;
            test = &ctx->module->instructions[ctx->module->instructionCount - 1];
            test->trueTarget = successBlock;
            test->falseTarget = failureBlock;
            xl6IrLowerEnterBlock(ctx, failureBlock);
            /* Await failure is selected before destroying its operand. The
             * temporary's release cannot replace that outcome or escape into
             * whichever producer stack happens to run this continuation. */
            if (futureTemporary != 0 &&
                (!xl6IrLowerBeginErrorUnwind(ctx, id) ||
                 !xl6IrLowerReleaseCallOwner(ctx, id, futureTemporary, 0)))
                return XL6_IR_VALUE_INVALID;
            if ( !xl6IrLowerEmitExceptionTransfer(ctx, id, node, errorPlan, 0) )
                return XL6_IR_VALUE_INVALID;
            xl6IrLowerEnterBlock(ctx, successBlock);
            if (futureTemporary != 0) {
                XL6_IrLowerCallCleanup cleanup = {0};
                cleanup.temporaries = &futureTemporary; cleanup.temporaryCount = 1;
                /* Successful await acquisition and expression completion are
                 * separate. Reuse the same owned-result transaction as calls
                 * and projections, including rollback and the full failure bit. */
                if (!xl6IrLowerCompleteOwnedCleanup(ctx, id, node, &result,
                        resultAbi == XL6_IR_ASYNC_RESULT_VOID ? XL6_IR_TYPE_INVALID : awaitResultType,
                        errorPlan, &cleanup)) return XL6_IR_VALUE_INVALID;
            }
            if ( resultAbi != XL6_IR_ASYNC_RESULT_VOID &&
                 awaitResultType != node->storageType ) {
                result = xl6IrLowerEmitValueCopy(
                    ctx, id, node->storageType, result);
                if ( result == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
            }
            return resultAbi == XL6_IR_ASYNC_RESULT_VOID ? XL6_IR_VALUE_INVALID : result;
        }
    case XL6_IR_NODE_BINARY:
        {
        XL6_IrOpcode opcode;
        const XL6_IrNode* operandNodes[2];
        if ( node->childCount != 2 ) { xl6IrLowerDiag(ctx, id, "XLIR binary instruction has invalid arity"); return 0; }
        if ( node->opcode == XL6_IR_OPCODE_LOGICAL_AND ||
             node->opcode == XL6_IR_OPCODE_LOGICAL_OR ) {
            return xl6IrLowerShortCircuit(ctx, id, node);
        }
        if ( node->opcode == XL6_IR_OPCODE_NULL_COALESCE )
            return xl6IrLowerNullableCoalesce(ctx, id, node);
        if ( node->callKind == XL6_SEM_CALL_PROTOCOL ) {
            const XL6_IrCallSite* operatorSite =
                xl6IrCallSiteGet(ctx->module, id);
            if ( operatorSite == NULL ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR resolved binary operator has no canonical CallSite");
                return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerResolvedSyntaxCall(
                ctx, id, node, operatorSite);
        }
        if ( node->sourceKind == XL6_AST_TYPE_IS ) {
            const XL6_IrNode* valueNode = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
            const XL6_IrNode* typeNode = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
            const XL6_IrClassLayout* layout = NULL;
            const XL6_IrNominalIdentitySet* nominalSet = NULL;
            const XL6_IrType* sourceType;
            const XL6_IrType* targetType;
            XL6_IrTypeId typeIdType;
            XL6_IrValueId observed;
            XL6_IrValueId actualTypeId;
            XL6_IrValueId expectedTypeId;
            XL6_IrValueId comparison[2];
            XL6_SymbolId temporary = 0;
            char tag[32];
            if ( valueNode == NULL || typeNode == NULL ||
                 !xl6IrLowerTypeIsBool(ctx->module, node->storageType) ||
                 (sourceType = xl6IrTypeGet(
                      &ctx->module->types, valueNode->storageType)) == NULL ||
                 (targetType = xl6IrTypeGet(
                      &ctx->module->types, typeNode->storageType)) == NULL ||
                 targetType->typeValueId == 0 ) {
                xl6IrLowerDiag(ctx, id, "XLIR type-is requires a concrete xvalue class runtime-tag ABI");
                return XL6_IR_VALUE_INVALID;
            }
            /* A statically trivial builtin cannot inhabit a nominal,
             * function or union target.  Preserve evaluation of the left
             * operand, then materialize the proven false result directly.
             * This is a Typed-XLIR proof, not a backend type-name fallback;
             * managed, nullable and polymorphic carriers still require one of
             * the explicit runtime identity paths below. */
            if ( !xl6IrLowerTypeIsRuntimeXValue(
                     ctx->module, valueNode->storageType) &&
                 sourceType->kind == XL6_IR_TYPE_BUILTIN &&
                 sourceType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
                 sourceType->kind != targetType->kind &&
                 (targetType->kind == XL6_IR_TYPE_CLASS ||
                  targetType->kind == XL6_IR_TYPE_PROTOCOL ||
                  targetType->kind == XL6_IR_TYPE_FUNCTION ||
                  targetType->kind == XL6_IR_TYPE_UNION) ) {
                XL6_IrInstruction* constant;
                observed = xl6IrLowerNode(
                    ctx, ctx->module->children[node->firstChild]);
                if ( observed == XL6_IR_VALUE_INVALID ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id,
                         node->storageType, 0, NULL, 0, &result) )
                    return XL6_IR_VALUE_INVALID;
                constant = &ctx->module->instructions[
                    ctx->module->instructionCount - 1];
                constant->immediateText = xrtStrDupN("false", 5);
                if ( constant->immediateText == NULL ) {
                    ctx->failed = 1;
                    return XL6_IR_VALUE_INVALID;
                }
                return result;
            }
            if ( !xl6IrLowerTypeIsRuntimeXValue(
                     ctx->module, valueNode->storageType) ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR type-is has no static proof or runtime identity carrier ABI");
                return XL6_IR_VALUE_INVALID;
            }
            nominalSet = xl6IrNominalIdentitySetGet(
                ctx->module, typeNode->storageType, NULL);
            if ( nominalSet != NULL ) {
                XL6_IrInstruction* membership;
                observed = xl6IrLowerNode(
                    ctx, ctx->module->children[node->firstChild]);
                observed = xl6IrLowerBorrowRuntimeXValueOperand(
                    ctx, id, valueNode, observed, &temporary);
                result = observed == XL6_IR_VALUE_INVALID
                    ? XL6_IR_VALUE_INVALID
                    : xl6IrLowerEmitRuntimeCall(
                        ctx, id, node->storageType,
                        XL6_IR_RUNTIME_XVALUE_NOMINAL_TEST, &observed, 1);
                if ( result == XL6_IR_VALUE_INVALID ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR nominal type-is has no closed identity-set predicate ABI");
                    return XL6_IR_VALUE_INVALID;
                }
                membership = &ctx->module->instructions[
                    ctx->module->instructionCount - 1];
                membership->payloadType = typeNode->storageType;
                if ( temporary != 0 && !xl6IrLowerEmit(
                        ctx, XL6_IR_INSTR_RELEASE, id,
                        valueNode->storageType, temporary, NULL, 0, NULL) )
                    return XL6_IR_VALUE_INVALID;
                return result;
            }
            layout = xl6IrLowerClassLayoutGet(ctx->module, typeNode->storageType);
            if ( layout == NULL ) {
                typeIdType = xl6IrLowerFindTypeByCAbi(
                    ctx->module, XL6_IR_C_ABI_TYPE_ID);
                if ( typeIdType == XL6_IR_TYPE_INVALID )
                    typeIdType = xl6IrTypeInternTypeIdCarrier(ctx->module);
                observed = xl6IrLowerNode(
                    ctx, ctx->module->children[node->firstChild]);
                observed = xl6IrLowerBorrowRuntimeXValueOperand(
                    ctx, id, valueNode, observed, &temporary);
                actualTypeId = typeIdType == XL6_IR_TYPE_INVALID ||
                    observed == XL6_IR_VALUE_INVALID
                        ? XL6_IR_VALUE_INVALID
                        : xl6IrLowerEmitRuntimeCall(
                            ctx, id, typeIdType,
                            XL6_IR_RUNTIME_XVALUE_TYPE_ID, &observed, 1);
                expectedTypeId = xl6IrLowerEmitTypeIdConst(
                    ctx, id, typeIdType, typeNode->storageType);
                comparison[0] = actualTypeId;
                comparison[1] = expectedTypeId;
                if ( actualTypeId == XL6_IR_VALUE_INVALID ||
                     expectedTypeId == XL6_IR_VALUE_INVALID ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BINARY, id,
                         node->storageType, 0, comparison, 2, &result) ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR exact xvalue type-is has no stable TypeId comparison ABI");
                    return XL6_IR_VALUE_INVALID;
                }
                ctx->module->instructions[
                    ctx->module->instructionCount - 1].opcode = XL6_IR_OPCODE_EQ;
                if ( temporary != 0 && !xl6IrLowerEmit(
                        ctx, XL6_IR_INSTR_RELEASE, id,
                        valueNode->storageType, temporary, NULL, 0, NULL) )
                    return XL6_IR_VALUE_INVALID;
                return result;
            }
            if ( layout->runtimeTypeTag == 0 ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR type-is requires a concrete xvalue class runtime-tag ABI");
                return XL6_IR_VALUE_INVALID;
            }
            values[0] = xl6IrLowerNode(ctx, ctx->module->children[node->firstChild]);
            if ( values[0] == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
            snprintf(tag, sizeof(tag), "%uLL", (unsigned int)layout->runtimeTypeTag);
            return xl6IrLowerEmitRuntimeLiteralCall(ctx, id, node->storageType,
                                                     XL6_IR_RUNTIME_XVALUE_CLASS_IS, tag, values, 1);
        }
        if ( node->sourceKind == XL6_AST_TYPE_AS ) {
            return xl6IrLowerCast(ctx, id, node);
        }
        opcode = node->opcode;
        if ( opcode == XL6_IR_OPCODE_INVALID ) {
            xl6IrLowerDiag(ctx, id, "XLIR binary operator has no canonical opcode");
            return XL6_IR_VALUE_INVALID;
        }
        operandNodes[0] = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
        operandNodes[1] = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]);
        if ( opcode == XL6_IR_OPCODE_POW ) {
            const XL6_IrType* resultType = xl6IrTypeGet(
                &ctx->module->types, node->storageType);
            XL6_IrValueId operands[2];
            size_t operand;
            if ( node->operatorErrorAbi != XL6_IR_ERROR_ABI_NO_RAISE ||
                 resultType == NULL ||
                 resultType->cAbi != XL6_IR_C_ABI_I64 ||
                 resultType->integerTarget !=
                     XL6_IR_INTEGER_TARGET_SIGNED_64 ||
                 resultType->ownershipAbi !=
                     XL6_IR_OWNERSHIP_ABI_TRIVIAL ||
                 operandNodes[0] == NULL || operandNodes[1] == NULL ||
                 operandNodes[0]->storageType != node->storageType ||
                 operandNodes[1]->storageType != node->storageType ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR power requires an exact no-raise i64 operation ABI");
                return XL6_IR_VALUE_INVALID;
            }
            for ( operand = 0; operand < 2; ++operand ) {
                XL6_IrNodeId operandId =
                    ctx->module->children[node->firstChild + operand];
                operands[operand] = xl6IrLowerNodeAsType(
                    ctx, id, operandId, operandNodes[operand],
                    node->storageType);
                if ( operands[operand] == XL6_IR_VALUE_INVALID ||
                     xl6IrLowerValueType(ctx, operands[operand]) !=
                         node->storageType )
                    return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerEmitRuntimeCall(
                ctx, id, node->storageType,
                XL6_IR_RUNTIME_I64_POW, operands, 2);
        }
        if ( opcode == XL6_IR_OPCODE_CONTAINS ) {
            const XL6_IrIntrinsicCall* containsIntrinsic = operandNodes[1] != NULL
                ? xl6IrIntrinsicCallGet(
                    ctx->module, ctx->module->children[node->firstChild + 1])
                : NULL;
            if ( containsIntrinsic != NULL &&
                 containsIntrinsic->kind == XL6_IR_INTRINSIC_RANGE )
                return xl6IrLowerRangeContains(
                    ctx, id, node,
                    ctx->module->children[node->firstChild], operandNodes[0],
                    ctx->module->children[node->firstChild + 1], operandNodes[1]);
            if ( operandNodes[0] != NULL && operandNodes[1] != NULL &&
                 xl6IrLowerTypeIsManagedString(
                     ctx->module, operandNodes[0]->storageType) &&
                 xl6IrLowerTypeIsManagedString(
                     ctx->module, operandNodes[1]->storageType) )
                return xl6IrLowerStringContains(
                    ctx, id, node,
                    ctx->module->children[node->firstChild], operandNodes[0],
                    ctx->module->children[node->firstChild + 1], operandNodes[1]);
            return xl6IrLowerXValueContains(
                ctx, id, node,
                ctx->module->children[node->firstChild], operandNodes[0],
                ctx->module->children[node->firstChild + 1], operandNodes[1],
                XL6_IR_RUNTIME_NONE);
        }
        {
            XL6_IrRuntimeOp collectionOperation =
                operandNodes[0] != NULL && operandNodes[1] != NULL
                    ? xl6IrCollectionAlgebraRuntimeOp(
                        &ctx->module->types, node->storageType,
                        operandNodes[0]->storageType,
                        operandNodes[1]->storageType, opcode)
                    : XL6_IR_RUNTIME_NONE;
            if ( collectionOperation != XL6_IR_RUNTIME_NONE )
                return xl6IrLowerCollectionAlgebraExpression(
                    ctx, id, node, operandNodes, collectionOperation);
        }
        if ( opcode == XL6_IR_OPCODE_EQ || opcode == XL6_IR_OPCODE_NE ) {
            const XL6_IrType* leftType = operandNodes[0] != NULL
                ? xl6IrTypeGet(&ctx->module->types, operandNodes[0]->type) : NULL;
            const XL6_IrType* rightType = operandNodes[1] != NULL
                ? xl6IrTypeGet(&ctx->module->types, operandNodes[1]->type) : NULL;
            int leftTypeValue = leftType != NULL &&
                leftType->cAbi == XL6_IR_C_ABI_TYPE_ID;
            int rightTypeValue = rightType != NULL &&
                rightType->cAbi == XL6_IR_C_ABI_TYPE_ID;
            if ( leftTypeValue || rightTypeValue ) {
                XL6_IrTypeId typeIdType = leftTypeValue
                    ? operandNodes[0]->type : operandNodes[1]->type;
                size_t operandIndex;
                if ( !xl6IrLowerTypeIsBool(ctx->module, node->storageType) )
                    return XL6_IR_VALUE_INVALID;
                for ( operandIndex = 0; operandIndex < 2; ++operandIndex ) {
                    const XL6_IrNode* operand = operandNodes[operandIndex];
                    const XL6_IrType* operandType = operand != NULL
                        ? xl6IrTypeGet(&ctx->module->types, operand->type) : NULL;
                    if ( operandType != NULL &&
                         operandType->cAbi == XL6_IR_C_ABI_TYPE_ID ) {
                        values[operandIndex] = xl6IrLowerNode(
                            ctx, ctx->module->children[
                                node->firstChild + operandIndex]);
                    } else if ( operand != NULL &&
                                operand->sourceKind == XL6_AST_NULL &&
                                operandType != NULL &&
                                operandType->typeValueId != 0 ) {
                        char immediate[32];
                        int written;
                        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id,
                                             typeIdType, 0, NULL, 0,
                                             &values[operandIndex]) )
                            return XL6_IR_VALUE_INVALID;
                        written = snprintf(immediate, sizeof(immediate),
                            "0x%016llXULL",
                            (unsigned long long)operandType->typeValueId);
                        if ( written < 0 ||
                             (size_t)written >= sizeof(immediate) ||
                             (ctx->module->instructions[
                                 ctx->module->instructionCount - 1].immediateText =
                                  xrtStrDupN(immediate, (size_t)written)) == NULL )
                            return XL6_IR_VALUE_INVALID;
                    } else {
                        xl6IrLowerDiag(ctx, id,
                            "XLIR type equality operand has no exact type identity ABI");
                        return XL6_IR_VALUE_INVALID;
                    }
                    if ( values[operandIndex] == XL6_IR_VALUE_INVALID ||
                         xl6IrLowerValueType(ctx, values[operandIndex]) != typeIdType )
                        return XL6_IR_VALUE_INVALID;
                }
                if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BINARY, id,
                                     node->storageType, 0, values, 2,
                                     &result) ) return XL6_IR_VALUE_INVALID;
                ctx->module->instructions[
                    ctx->module->instructionCount - 1].opcode = opcode;
                return result;
            }
        }
        if ( opcode == XL6_IR_OPCODE_EQ || opcode == XL6_IR_OPCODE_NE ) {
            int leftNull = operandNodes[0] != NULL &&
                operandNodes[0]->sourceKind == XL6_AST_NULL;
            int rightNull = operandNodes[1] != NULL &&
                operandNodes[1]->sourceKind == XL6_AST_NULL;
            if ( leftNull && rightNull ) {
                XL6_IrInstruction* constant;
                if ( !xl6IrLowerTypeIsBool(ctx->module, node->storageType) ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CONST, id, node->storageType,
                                      0, NULL, 0, &result) ) return XL6_IR_VALUE_INVALID;
                constant = &ctx->module->instructions[ctx->module->instructionCount - 1];
                constant->immediateText = xrtStrDupN(
                    opcode == XL6_IR_OPCODE_EQ ? "true" : "false",
                    opcode == XL6_IR_OPCODE_EQ ? 4 : 5);
                if ( constant->immediateText == NULL ) return XL6_IR_VALUE_INVALID;
                return result;
            }
            if ( leftNull != rightNull ) {
                size_t otherIndex = leftNull ? 1u : 0u;
                XL6_IrNodeId otherId = ctx->module->children[node->firstChild + otherIndex];
                const XL6_IrNode* other = operandNodes[otherIndex];
                const XL6_IrType* otherType = other != NULL
                    ? xl6IrTypeGet(&ctx->module->types, other->storageType) : NULL;
                size_t first = ctx->evaluationOwnerCount;
                XL6_IrValueId tested;
                if ( !xl6IrLowerTypeIsBool(ctx->module, node->storageType) || otherType == NULL ||
                     (otherType->nullAbi != XL6_IR_NULL_ABI_POINTER_SENTINEL &&
                      otherType->nullAbi != XL6_IR_NULL_ABI_XVALUE_SENTINEL &&
                      !(otherType->nullAbi == XL6_IR_NULL_ABI_TAGGED_VALUE &&
                        otherType->cAbi == XL6_IR_C_ABI_TAGGED_NULLABLE)) ) {
                    xl6IrLowerDiag(ctx, id,
                                    otherType != NULL && otherType->nullAbi == XL6_IR_NULL_ABI_TAGGED_VALUE
                                        ? "XLIR tagged nullable null test requires an explicit product ABI"
                                        : "XLIR null comparison has no resolved operand representation");
                    return XL6_IR_VALUE_INVALID;
                }
                /* Null testing observes the slot sentinel itself. A narrowed
                 * NAME projection would create an unnecessary owned copy and
                 * can even erase the absence this predicate must observe. */
                values[0] = other->kind == XL6_IR_NODE_NAME
                    ? xl6IrLowerNamePhysicalStorageValue(ctx, id, otherId, other)
                    : xl6IrLowerNodeAsType(ctx, id, otherId, other, other->storageType);
                if ( values[0] == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
                values[0] = xl6IrLowerProtectOwnedBorrow(ctx, id, values[0]);
                if (values[0] == XL6_IR_VALUE_INVALID ||
                    !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, id, node->storageType,
                        0, values, 1, &tested) ||
                    !xl6IrLowerCompleteEvaluationBorrows(ctx, id, first, &tested))
                    return XL6_IR_VALUE_INVALID;
                if ( opcode == XL6_IR_OPCODE_EQ ) return tested;
                if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_UNARY, id, node->storageType,
                                     0, &tested, 1, &result) ) return XL6_IR_VALUE_INVALID;
                ctx->module->instructions[ctx->module->instructionCount - 1].opcode =
                    XL6_IR_OPCODE_NOT;
                return result;
            }
        }
        if ((opcode==XL6_IR_OPCODE_EQ || opcode==XL6_IR_OPCODE_NE) &&
            operandNodes[0] && operandNodes[1] &&
            operandNodes[0]->storageType==operandNodes[1]->storageType &&
            xl6IrNullableScalarElementAbi(ctx->module,operandNodes[0]->storageType)!=XL6_IR_C_ABI_UNSUPPORTED) {
            for (size_t i=0;i<2;++i) {
                values[i]=xl6IrLowerNodeAsType(ctx,id,ctx->module->children[node->firstChild+i],
                    operandNodes[i],operandNodes[i]->storageType);
                if (values[i]==XL6_IR_VALUE_INVALID) return XL6_IR_VALUE_INVALID;
            }
            result=xl6IrLowerEmitRuntimeCall(ctx,id,node->storageType,
                XL6_IR_RUNTIME_NULLABLE_SCALAR_EQUAL,values,2);
            if (result==XL6_IR_VALUE_INVALID || opcode==XL6_IR_OPCODE_EQ) return result;
            XL6_IrValueId equal=result;
            if (!xl6IrLowerEmit(ctx,XL6_IR_INSTR_UNARY,id,node->storageType,0,&equal,1,&result))
                return XL6_IR_VALUE_INVALID;
            ctx->module->instructions[ctx->module->instructionCount-1].opcode=XL6_IR_OPCODE_NOT;
            return result;
        }
        {
            int managed = xl6IrLowerManagedBinary(ctx, id, node, operandNodes, &result);
            if ( managed != 0 ) return managed > 0 ? result : XL6_IR_VALUE_INVALID;
        }
        {
            XL6_IrTypeId executionType = node->operatorExecutionType;
            size_t operandIndex;
            for ( operandIndex = 0; operandIndex < 2; ++operandIndex ) {
                XL6_IrNodeId operandId =
                    ctx->module->children[node->firstChild + operandIndex];
                values[operandIndex] = executionType != XL6_IR_TYPE_INVALID
                    ? xl6IrLowerOperatorOperandAsExecutionType(
                        ctx, id, node, operandIndex, operandId,
                        operandNodes[operandIndex], executionType)
                    : xl6IrLowerNode(ctx, operandId);
                if ( executionType != XL6_IR_TYPE_INVALID &&
                     values[operandIndex] != XL6_IR_VALUE_INVALID &&
                     xl6IrLowerValueType(ctx, values[operandIndex]) != executionType ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR numeric operator has no explicit scalar promotion ABI");
                    return XL6_IR_VALUE_INVALID;
                }
            }
        }
        if ( values[0] == XL6_IR_VALUE_INVALID || values[1] == XL6_IR_VALUE_INVALID ) {
            xl6IrLowerDiag(ctx, id, values[0] == XL6_IR_VALUE_INVALID
                            ? "XLIR binary left operand has no lowered value ABI"
                            : "XLIR binary right operand has no lowered value ABI");
            return 0;
        }
        if ( node->operatorErrorAbi == XL6_IR_ERROR_ABI_MAY_RAISE &&
             xl6IrLowerCheckedIntegerRuntimeOp(opcode) != XL6_IR_RUNTIME_NONE &&
             xl6IrTypeGet(&ctx->module->types, node->storageType) != NULL &&
             xl6IrTypeGet(&ctx->module->types, node->storageType)->integerTarget !=
                 XL6_IR_INTEGER_TARGET_INVALID ) {
            return xl6IrLowerEmitCheckedIntegerArithmetic(
                ctx, id, node, node->storageType, opcode, values[0], values[1]);
        }
        if ( opcode == XL6_IR_OPCODE_APPROX ) {
            const XL6_IrType* leftType = xl6IrTypeGet(
                &ctx->module->types, xl6IrLowerValueType(ctx, values[0]));
            const XL6_IrType* rightType = xl6IrTypeGet(
                &ctx->module->types, xl6IrLowerValueType(ctx, values[1]));
            XL6_IrRuntimeOp approximateOp = XL6_IR_RUNTIME_NONE;
            if ( !xl6IrLowerTypeIsBool(ctx->module, node->storageType) ||
                 leftType == NULL || rightType == NULL ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR approximate comparison has no resolved scalar result ABI");
                return XL6_IR_VALUE_INVALID;
            }
            if ( leftType->cAbi == XL6_IR_C_ABI_I64 &&
                 rightType->cAbi == XL6_IR_C_ABI_I64 )
                approximateOp = XL6_IR_RUNTIME_I64_APPROX;
            else if ( leftType->cAbi == XL6_IR_C_ABI_U64 &&
                      rightType->cAbi == XL6_IR_C_ABI_U64 )
                approximateOp = XL6_IR_RUNTIME_U64_APPROX;
            else if ( (leftType->cAbi == XL6_IR_C_ABI_I64 ||
                       leftType->cAbi == XL6_IR_C_ABI_U64 ||
                       leftType->cAbi == XL6_IR_C_ABI_F64) &&
                      (rightType->cAbi == XL6_IR_C_ABI_I64 ||
                       rightType->cAbi == XL6_IR_C_ABI_U64 ||
                       rightType->cAbi == XL6_IR_C_ABI_F64) &&
                       (leftType->cAbi == XL6_IR_C_ABI_F64 ||
                        rightType->cAbi == XL6_IR_C_ABI_F64) )
                approximateOp = XL6_IR_RUNTIME_F64_APPROX;
            else if ( leftType->cAbi == XL6_IR_C_ABI_TIME_I64 &&
                      rightType->cAbi == XL6_IR_C_ABI_TIME_I64 &&
                      xl6IrLowerValueType(ctx, values[0]) ==
                          xl6IrLowerValueType(ctx, values[1]) &&
                      leftType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL &&
                      rightType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_TRIVIAL )
                approximateOp = XL6_IR_RUNTIME_TIME_APPROX;
            if ( approximateOp != XL6_IR_RUNTIME_NONE )
                return xl6IrLowerEmitRuntimeCall(
                    ctx, id, node->storageType, approximateOp, values, 2);
            xl6IrLowerDiag(ctx, id,
                "XLIR approximate comparison has no admitted numeric, time or string runtime ABI");
            return XL6_IR_VALUE_INVALID;
        }
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BINARY, id, node->storageType, 0, values, 2, &result) ) return 0;
        ctx->module->instructions[ctx->module->instructionCount - 1].opcode = opcode;
        return result;
        }
    case XL6_IR_NODE_UNARY:
        if ( node->childCount != 1 ) { xl6IrLowerDiag(ctx, id, "XLIR unary instruction has invalid arity"); return 0; }
        if ( node->callKind == XL6_SEM_CALL_PROTOCOL ) {
            const XL6_IrCallSite* operatorSite =
                xl6IrCallSiteGet(ctx->module, id);
            if ( operatorSite == NULL ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR resolved unary operator has no canonical CallSite");
                return XL6_IR_VALUE_INVALID;
            }
            return xl6IrLowerResolvedSyntaxCall(
                ctx, id, node, operatorSite);
        }
        if ( node->opcode < XL6_IR_OPCODE_POS || node->opcode > XL6_IR_OPCODE_BIT_NOT ) {
            xl6IrLowerDiag(ctx, id, "XLIR unary operator has no canonical opcode");
            return XL6_IR_VALUE_INVALID;
        }
        {
            XL6_IrNodeId operandId = ctx->module->children[node->firstChild];
            const XL6_IrNode* operandNode = xl6IrNodeGet(ctx->module, operandId);
            const XL6_IrType* resultType = xl6IrTypeGet(
                &ctx->module->types, node->storageType);
            const XL6_IrType* operandType = operandNode != NULL
                ? xl6IrTypeGet(&ctx->module->types, operandNode->storageType) : NULL;
            /* Fold the signed literal as a value, before forming an operand.
             * INT64_MIN has no positive signed counterpart. Materializing
             * its magnitude then negating an int64 temporary would overflow
             * in C. The closed canonical payload uses only representable LL
             * operands; Cgen remains a serializer, not a literal parser. */
            if (node->opcode == XL6_IR_OPCODE_NEG && resultType != NULL &&
                resultType->cAbi == XL6_IR_C_ABI_I64 &&
                (resultType->integerTarget == XL6_IR_INTEGER_TARGET_SIGNED_8 ||
                 resultType->integerTarget == XL6_IR_INTEGER_TARGET_SIGNED_16 ||
                 resultType->integerTarget == XL6_IR_INTEGER_TARGET_SIGNED_32 ||
                 resultType->integerTarget == XL6_IR_INTEGER_TARGET_SIGNED_64) &&
                operandNode != NULL && operandNode->kind == XL6_IR_NODE_LITERAL &&
                operandNode->sourceKind == XL6_AST_INT) {
                uint64_t magnitude;
                char payload[48];
                int length;
                if (!xl6IrLowerIntegerMagnitude(operandNode->text, &magnitude) ||
                    magnitude > (uint64_t)INT64_MAX + 1u ||
                    (magnitude == (uint64_t)INT64_MAX + 1u &&
                     resultType->integerTarget != XL6_IR_INTEGER_TARGET_SIGNED_64)) {
                    xl6IrLowerDiag(ctx,id,"XLIR signed literal magnitude is out of range");
                    return XL6_IR_VALUE_INVALID;
                }
                length = magnitude == (uint64_t)INT64_MAX + 1u
                    ? snprintf(payload,sizeof(payload),"(-9223372036854775807LL - 1LL)")
                    : snprintf(payload,sizeof(payload),"-%lluLL",(unsigned long long)magnitude);
                if (length <= 0 || (size_t)length >= sizeof(payload) ||
                    !xl6IrLowerEmit(ctx,XL6_IR_INSTR_CONST,id,node->storageType,0,NULL,0,&result))
                    return XL6_IR_VALUE_INVALID;
                ctx->module->instructions[ctx->module->instructionCount-1].immediateText = xrtStrDupN(payload,(size_t)length);
                if (!ctx->module->instructions[ctx->module->instructionCount-1].immediateText) {
                    ctx->failed = 1; return XL6_IR_VALUE_INVALID;
                }
                return result;
            }
            int canonicalScalarOperand = resultType != NULL &&
                operandType != NULL &&
                ((node->opcode == XL6_IR_OPCODE_NOT &&
                  xl6IrLowerCAbiIsBoolScalar(resultType->cAbi) &&
                  xl6IrLowerCAbiIsBoolScalar(operandType->cAbi)) ||
                 ((node->opcode == XL6_IR_OPCODE_POS ||
                   node->opcode == XL6_IR_OPCODE_NEG ||
                   node->opcode == XL6_IR_OPCODE_BIT_NOT) &&
                  (operandNode->storageType == node->storageType ||
                   xl6IrLowerCanScalarConvert(ctx->module,
                       operandNode->storageType, node->storageType))));
            /* The operator result TypeId is its execution ABI.  When the
             * frontend supplies an equivalent/widenable literal or builtin
             * TypeId, make that transition explicit before UNARY so Cgen
             * never relies on C promotions or verifier-side equivalence. */
            values[0] = canonicalScalarOperand
                ? xl6IrLowerNodeAsType(
                    ctx, id, operandId, operandNode, node->storageType)
                : xl6IrLowerNode(ctx, operandId);
            if ( values[0] != XL6_IR_VALUE_INVALID &&
                 node->opcode == XL6_IR_OPCODE_NOT &&
                 resultType != NULL && operandType != NULL &&
                 xl6IrLowerCAbiIsBoolScalar(resultType->cAbi) &&
                 xl6IrLowerTypeIsRuntimeXValue(
                     ctx->module, operandNode->storageType) ) {
                /* Dynamic truth is an explicit runtime projection to the
                 * canonical bool ABI.  UNARY NOT then remains a plain,
                 * verifier-exact boolean instruction. */
                values[0] = xl6IrLowerTruthValue(
                    ctx, id, operandNode, values[0]);
            }
        }
        if ( values[0] == XL6_IR_VALUE_INVALID ) return 0;
        if ( xl6IrLowerTypeIsRuntimeXValue(ctx->module, node->storageType) &&
             xl6IrLowerTypeIsRuntimeXValue(
                 ctx->module, xl6IrLowerValueType(ctx, values[0])) &&
             (node->opcode == XL6_IR_OPCODE_POS ||
              node->opcode == XL6_IR_OPCODE_NEG ||
              node->opcode == XL6_IR_OPCODE_BIT_NOT) ) {
            XL6_IrRuntimeOp unaryOp = node->opcode == XL6_IR_OPCODE_POS
                ? XL6_IR_RUNTIME_XVALUE_UNARY_POS
                : node->opcode == XL6_IR_OPCODE_NEG
                    ? XL6_IR_RUNTIME_XVALUE_UNARY_NEG
                    : XL6_IR_RUNTIME_XVALUE_UNARY_BIT_NOT;
            size_t first = ctx->evaluationOwnerCount;
            /* Unary arithmetic also allocates. Register its operand with the
             * shared evaluation transaction before emitting the checked box;
             * both success cleanup and the exceptional edge own that anchor. */
            XL6_IrValueId borrowed = xl6IrLowerProtectOwnedBorrow(ctx, id, values[0]);
            if ( borrowed == XL6_IR_VALUE_INVALID ) return XL6_IR_VALUE_INVALID;
            result = xl6IrLowerEmitRuntimeCall(
                ctx, id, node->storageType, unaryOp, &borrowed, 1);
            if ( result == XL6_IR_VALUE_INVALID ||
                 !xl6IrLowerCompleteEvaluationBorrows(ctx, id, first, &result) ) {
                ctx->evaluationOwnerCount = first;
                return XL6_IR_VALUE_INVALID;
            }
            return result;
        }
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_UNARY, id, node->storageType, 0, values, 1, &result) ) return 0;
        ctx->module->instructions[ctx->module->instructionCount - 1].opcode = node->opcode;
        return result;
    case XL6_IR_NODE_YIELD:
        {
        const XL6_IrFunction* function =
            &ctx->module->functions[ctx->functionIndex];
        const XL6_IrCallTarget* target =
            xl6IrCallTargetGet(ctx->module, function->symbol);
        const XL6_IrNode* yielded;
        const XL6_IrType* itemType;
        XL6_IrValueId value;
        XL6_IrInstruction* instruction;
        if ( function->kind != XL6_IR_FUNCTION_GENERATOR_WORKER ||
             target == NULL ||
             target->kind != XL6_IR_CALL_TARGET_INTERNAL_GENERATOR ||
             node->childCount != 1 ||
             target->generatorItemType == XL6_IR_TYPE_INVALID ||
             target->generatorYieldAbi == XL6_IR_GENERATOR_YIELD_INVALID ||
             (yielded = xl6IrNodeGet(ctx->module,
                 ctx->module->children[node->firstChild])) == NULL ||
             (itemType = xl6IrTypeGet(&ctx->module->types,
                 target->generatorItemType)) == NULL ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR yield has no exact owning generator item ABI");
            return XL6_IR_VALUE_INVALID;
        }
        value = yielded->storageType == target->generatorItemType
            ? xl6IrLowerNode(ctx, ctx->module->children[node->firstChild])
            : xl6IrLowerNodeAsType(ctx, id,
                ctx->module->children[node->firstChild], yielded,
                target->generatorItemType);
        if ( value == XL6_IR_VALUE_INVALID ||
             xl6IrLowerValueType(ctx, value) != target->generatorItemType ) {
            xl6IrLowerDiag(ctx, id,
                "XLIR yield value does not match generator<T>");
            return XL6_IR_VALUE_INVALID;
        }
        if ( itemType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ) {
            value = xl6IrLowerOwnedValueBoundary(
                ctx, id, target->generatorItemType, yielded, value);
            if ( value == XL6_IR_VALUE_INVALID ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR managed yield has no explicit owned transfer");
                return XL6_IR_VALUE_INVALID;
            }
        }
        if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_YIELD, id,
                              target->generatorItemType, 0,
                              &value, 1, NULL) ) return XL6_IR_VALUE_INVALID;
        instruction = &ctx->module->instructions[
            ctx->module->instructionCount - 1];
        instruction->generatorYieldAbi = target->generatorYieldAbi;
        instruction->generatorClosePointAbi = node->generatorClosePointAbi;
        if (!xl6IrLowerGeneratorCloseCheck(ctx, id)) return XL6_IR_VALUE_INVALID;
        return XL6_IR_VALUE_INVALID;
        }
    case XL6_IR_NODE_RETURN:
        {
        const XL6_IrExitPlan* plan;
        const XL6_IrNode* returned = NULL;
        XL6_IrLowerDeferredReturn* deferred = xl6IrLowerActiveDeferredReturn(ctx);
        XL6_SymbolId transferredStorage = 0;
        XL6_SymbolId pendingReturn = 0;
        if ( (plan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_RETURN)) == NULL ) return 0;
        if ( node->childCount > 1 ) {
            XL6_IrTypeId productType = ctx->module->functions[ctx->functionIndex].returnType;
            const XL6_IrType* product = xl6IrTypeGet(&ctx->module->types, productType);
            XL6_IrValueId* elements;
            XL6_SymbolId* transferredElements;
            XL6_IrValueId productValue = XL6_IR_VALUE_INVALID;
            size_t elementIndex;
            size_t evaluationOwnerFirst = ctx->evaluationOwnerCount;
            if ( product == NULL || product->kind != XL6_IR_TYPE_TUPLE ||
                  product->cAbi != XL6_IR_C_ABI_PRODUCT ||
                  product->paramCount != node->childCount ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR multi-result return has no exact product ownership ABI");
                return 0;
            }
            elements = (XL6_IrValueId*)xrtCalloc(node->childCount, sizeof(*elements));
            transferredElements = (XL6_SymbolId*)xrtCalloc(
                node->childCount, sizeof(*transferredElements));
            if ( elements == NULL || transferredElements == NULL ) {
                xrtFree(elements); xrtFree(transferredElements);
                ctx->failed = 1; return 0;
            }
            for ( elementIndex = 0; elementIndex < node->childCount; ++elementIndex ) {
                XL6_IrNodeId elementId = ctx->module->children[node->firstChild + elementIndex];
                const XL6_IrNode* element = xl6IrNodeGet(ctx->module, elementId);
                const XL6_IrType* elementType = xl6IrTypeGet(
                    &ctx->module->types, product->params[elementIndex]);
                if ( elementType != NULL &&
                     elementType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ) {
                    XL6_SymbolId candidate =
                        xl6IrLowerReturnTransferredStorage(
                            ctx, id, element, product->params[elementIndex],
                            deferred == NULL);
                    if ( xl6IrLowerTransferredStorageContains(
                             transferredElements, elementIndex, candidate) )
                        candidate = 0;
                    transferredElements[elementIndex] = candidate;
                }
                elements[elementIndex] = transferredElements[elementIndex] != 0
                    ? xl6IrLowerTransferredReturnValueAsType(
                        ctx, id, elementId, element,
                        product->params[elementIndex])
                    : xl6IrLowerNodeAsType(
                        ctx, id, elementId, element,
                        product->params[elementIndex]);
                if ( elements[elementIndex] == XL6_IR_VALUE_INVALID ||
                     xl6IrLowerValueType(ctx, elements[elementIndex]) != product->params[elementIndex] ||
                     elementType == NULL ) break;
                if ( elementType->ownershipAbi == XL6_IR_OWNERSHIP_ABI_MANAGED ) {
                    if ( transferredElements[elementIndex] == 0 ) {
                        elements[elementIndex] = xl6IrLowerOwnedValueBoundary(
                            ctx, id, product->params[elementIndex], element,
                            elements[elementIndex]);
                        if ( elements[elementIndex] == XL6_IR_VALUE_INVALID ) break;
                        elements[elementIndex] = xl6IrLowerProtectEvaluationValue(
                            ctx, elementId, product->params[elementIndex],
                            elements[elementIndex]);
                        if ( elements[elementIndex] == XL6_IR_VALUE_INVALID ) break;
                    }
                }
            }
            if ( elementIndex != node->childCount ||
                  !xl6IrLowerCommitEvaluationOwners(ctx, id, evaluationOwnerFirst) ) {
                xrtFree(elements); xrtFree(transferredElements);
                xl6IrLowerDiag(ctx, id,
                    "XLIR multi-result return elements do not match the product signature");
                return 0;
            }
            for ( elementIndex = 0; elementIndex < node->childCount; ++elementIndex ) {
                if ( transferredElements[elementIndex] != 0 &&
                     !xl6IrLowerEmitTransferredStorageMove(
                         ctx, id, transferredElements[elementIndex],
                         elements[elementIndex]) ) {
                    xrtFree(elements); xrtFree(transferredElements); return 0;
                }
            }
            if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_PRODUCT_MAKE, id, productType, 0,
                    elements, node->childCount, &productValue)) {
                xrtFree(elements); xrtFree(transferredElements); return 0;
            }
            pendingReturn = xl6IrLowerPrepareReturnValue(ctx, id, productType, productValue);
            if (ctx->failed ||
                !xl6IrLowerEmitExitCleanupSet(
                    ctx, id, plan, transferredElements, node->childCount, UINT32_MAX)) {
                xrtFree(elements); xrtFree(transferredElements); return 0;
            }
            xrtFree(elements); xrtFree(transferredElements);
            if ( deferred != NULL ) {
                if ( deferred->type != productType || deferred->storage == 0 ||
                     (pendingReturn != 0 &&
                      (productValue = xl6IrLowerCommitReturnValue(ctx, id, pendingReturn)) ==
                          XL6_IR_VALUE_INVALID) ||
                     !xl6IrLowerEmit(ctx, XL6_IR_INSTR_PRODUCT_STORE_MOVE, id,
                                      productType, deferred->storage,
                                      &productValue, 1, NULL) ||
                     !xl6IrLowerEmitJump(ctx, id, deferred->finallyBlock) )
                    return 0;
                return XL6_IR_VALUE_INVALID;
            }
            if ( !xl6IrLowerEmitTerminal(ctx, XL6_IR_INSTR_RETURN, id,
                                          &productValue, 1, pendingReturn) ) return 0;
            return XL6_IR_VALUE_INVALID;
        }
        if ( deferred != NULL ) {
            if ( (deferred->type == XL6_IR_TYPE_INVALID) != (node->childCount == 0) ) {
                xl6IrLowerDiag(ctx, id, "XLIR deferred return does not match its canonical function ABI");
                return 0;
            }
            if ( node->childCount == 1 ) {
                returned = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
                transferredStorage = xl6IrLowerReturnTransferredStorage(
                    ctx, id, returned, deferred->type, 0);
                values[0] = xl6IrLowerOwnedReturnExpression(ctx, id,
                    ctx->module->children[node->firstChild], returned, deferred->type);
                if ( values[0] == XL6_IR_VALUE_INVALID ) return 0;
            }
            if (transferredStorage != 0 &&
                !xl6IrLowerEmitTransferredStorageMove(ctx, id, transferredStorage, values[0])) return 0;
            if (node->childCount == 1)
                pendingReturn = xl6IrLowerPrepareReturnValue(ctx, id, deferred->type, values[0]);
            if (ctx->failed) return 0;
            if ( !xl6IrLowerEmitExitCleanup(ctx, id, plan, transferredStorage, UINT32_MAX) ||
                 (pendingReturn != 0 &&
                  (values[0] = xl6IrLowerCommitReturnValue(ctx, id, pendingReturn)) ==
                     XL6_IR_VALUE_INVALID) ||
                  (node->childCount == 1 && !xl6IrLowerEmit(
                     ctx, xl6IrLowerDeferredStoreKind(
                              ctx->module, deferred->type),
                     id, deferred->type, deferred->storage,
                     values, 1, NULL)) ||
                 !xl6IrLowerEmitJump(ctx, id, deferred->finallyBlock) ) return 0;
            return XL6_IR_VALUE_INVALID;
        }
        if ( node->childCount == 1 ) {
            XL6_IrTypeId returnType = ctx->module->functions[ctx->functionIndex].returnType;
            returned = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
            transferredStorage = xl6IrLowerReturnTransferredStorage(ctx, id, returned, returnType, 1);
            values[0] = transferredStorage != 0
                ? xl6IrLowerTransferredReturnValueAsType(ctx, id,
                    ctx->module->children[node->firstChild], returned, returnType)
                : xl6IrLowerOwnedReturnExpression(ctx, id,
                    ctx->module->children[node->firstChild], returned, returnType);
        }
        if ( node->childCount == 1 && values[0] == XL6_IR_VALUE_INVALID ) return 0;
        if ( node->childCount == 1 ) {
            XL6_IrTypeId returnType = ctx->module->functions[ctx->functionIndex].returnType;
            if ( xl6IrLowerValueType(ctx, values[0]) != returnType ) {
                if ( !xl6IrLowerCallableTypesCompatible(
                         ctx->module, xl6IrLowerValueType(ctx, values[0]), returnType) ) {
                    xl6IrLowerDiag(ctx, id, "XLIR return value does not match its function ABI");
                    return 0;
                }
                values[0] = xl6IrLowerEmitValueCopy(ctx, id, returnType,
                                                     values[0]);
                if ( values[0] == XL6_IR_VALUE_INVALID ) return 0;
            }
        }
        if ( transferredStorage != 0 &&
             !xl6IrLowerEmitTransferredStorageMove(
                 ctx, id, transferredStorage, values[0]) ) return 0;
        if (node->childCount == 1)
            pendingReturn = xl6IrLowerPrepareReturnValue(ctx, id,
                ctx->module->functions[ctx->functionIndex].returnType, values[0]);
        if (ctx->failed) return 0;
        if ( !xl6IrLowerEmitExitCleanup(ctx, id, plan, transferredStorage, UINT32_MAX) ) return 0;
        (void)xl6IrLowerEmitTerminal(ctx, XL6_IR_INSTR_RETURN, id, values, node->childCount, pendingReturn);
        return XL6_IR_VALUE_INVALID;
        }
    case XL6_IR_NODE_THROW:
        {
        const XL6_IrExitPlan* plan;
        XL6_IrInstruction* raise;
        const XL6_IrLowerCatchPayload* payload;
        const XL6_IrNode* kindNode = NULL;
        const XL6_IrNode* payloadNode = NULL;
        XL6_IrTypeId payloadType;
        XL6_IrNodeId payloadId = XL6_IR_NODE_INVALID;
        XL6_IrValueId transferredError;
        XL6_SymbolId transferredStorage = 0;
        if ( node->exitKind != XL6_SEM_EXIT_THROW || node->childCount > 2 ) {
            xl6IrLowerDiag(ctx, id, "XLIR throw has no canonical exception payload"); return 0;
        }
        if ( (plan = xl6IrLowerExitPlan(ctx, id, XL6_SEM_EXIT_THROW)) == NULL ) return 0;
        if ( node->childCount > 0 ) {
            if ( node->childCount == 2 ) {
                kindNode = xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild]);
                payloadId = ctx->module->children[node->firstChild + 1];
                if ( kindNode == NULL || kindNode->kind != XL6_IR_NODE_NAME ||
                     kindNode->text == NULL || kindNode->text[0] == '\0' ) {
                    xl6IrLowerDiag(ctx, id, "XLIR typed throw has no canonical error kind ABI"); return 0;
                }
            } else payloadId = ctx->module->children[node->firstChild];
            values[0] = xl6IrLowerNode(ctx, payloadId);
            if ( values[0] == XL6_IR_VALUE_INVALID ) return 0;
            payloadType = xl6IrLowerValueType(ctx, values[0]);
            payloadNode = xl6IrNodeGet(ctx->module, payloadId);
            if ( payloadType == XL6_IR_TYPE_INVALID || !xl6IrLowerTypeIsManagedString(ctx->module, payloadType) ) {
                xl6IrLowerDiag(ctx, id, "XLIR throw payload requires a managed-string error-state ABI");
                return 0;
            }
            values[0] = xl6IrLowerOwnedManagedStringValue(
                ctx, id, payloadType, payloadNode, values[0]);
            if ( values[0] == XL6_IR_VALUE_INVALID ) {
                xl6IrLowerDiag(ctx, id,
                    "XLIR throw payload has no owned error-raise transfer ABI");
                return 0;
            }
            if ( !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_RAISE, id, XL6_IR_TYPE_INVALID, 0,
                                  values, 1, NULL) ) return 0;
            raise = &ctx->module->instructions[ctx->module->instructionCount - 1];
            raise->immediateText = xl6IrCanonicalCStringBytes(
                kindNode != NULL ? kindNode->text : "Error");
            if ( raise->immediateText == NULL ) {
                xl6IrLowerDiag(ctx, id, "XLIR throw has no canonical error kind ABI");
                return 0;
            }
        } else {
            payload = xl6IrLowerActiveCatchPayload(ctx);
            if ( payload == NULL || payload->type == XL6_IR_TYPE_INVALID || payload->symbol == 0 ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, id, payload->type, payload->symbol,
                                  NULL, 0, &transferredError) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_MOVE, id, payload->type, payload->symbol,
                                  &transferredError, 1, NULL) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_SET_TAKE, id, XL6_IR_TYPE_INVALID, 0,
                                  &transferredError, 1, NULL) ) {
                xl6IrLowerDiag(ctx, id, "XLIR catch rethrow requires an owned error payload transfer ABI");
                return 0;
            }
            transferredStorage = payload->symbol;
        }
        return xl6IrLowerEmitExceptionTransfer(ctx, id, node, plan, transferredStorage) ? 0 : 0;
        }
    case XL6_IR_NODE_IF:
        return xl6IrLowerIf(ctx, id, node);
    case XL6_IR_NODE_CONDITIONAL:
        return xl6IrLowerConditional(ctx, id, node);
    case XL6_IR_NODE_LOOP:
        if ( node->sourceKind == XL6_AST_WHILE ) return xl6IrLowerWhile(ctx, id, node);
        if ( node->sourceKind == XL6_AST_DO_WHILE ) return xl6IrLowerDoWhile(ctx, id, node);
        if ( node->sourceKind == XL6_AST_FOR ) return xl6IrLowerFor(ctx, id, node);
        xl6IrLowerDiag(ctx, id, "XLIR loop kind is not normalized for CFG lowering");
        return 0;
    case XL6_IR_NODE_MATCH:
        {
            XL6_IrNodeId subjectId = node->childCount != 0
                ? ctx->module->children[node->firstChild]
                : XL6_IR_NODE_INVALID;
            const XL6_IrNode* subjectNode =
                xl6IrNodeGet(ctx->module, subjectId);
            XL6_IrTypeId subjectType = subjectNode != NULL &&
                subjectNode->type != XL6_IR_TYPE_INVALID
                    ? subjectNode->type
                    : (subjectNode != NULL
                        ? subjectNode->storageType : XL6_IR_TYPE_INVALID);
            const XL6_IrType* subjectInfo =
                xl6IrTypeGet(&ctx->module->types, subjectType);
            if ( subjectInfo != NULL &&
                 subjectInfo->kind == XL6_IR_TYPE_TAGGED_ENUM ) {
                XL6_IrValueId subject = xl6IrLowerNode(ctx, subjectId);
                if ( subject == XL6_IR_VALUE_INVALID ||
                     xl6IrLowerValueType(ctx, subject) != subjectType ) {
                    xl6IrLowerDiag(ctx, id,
                        "XLIR tagged enum match subject has no exact lowered TypeId");
                    return XL6_IR_VALUE_INVALID;
                }
                return xl6IrLowerTaggedEnumMatch(
                    ctx, id, node, subjectNode, subject, subjectType);
            }
            return xl6IrLowerScalarMatch(ctx, id, node);
        }
    case XL6_IR_NODE_TRY:
        {
            const XL6_IrNode* catches = node->childCount > 1
                ? xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 1]) : NULL;
            const XL6_IrNode* finallyBlock = node->childCount > 2
                ? xl6IrNodeGet(ctx->module, ctx->module->children[node->firstChild + 2]) : NULL;
            if ( catches != NULL && catches->kind == XL6_IR_NODE_LIST && catches->childCount == 0 &&
                 finallyBlock != NULL && finallyBlock->childCount > 0 )
                (void)xl6IrLowerTryFinally(ctx, id, node);
            else if ( catches != NULL && catches->kind == XL6_IR_NODE_LIST && catches->childCount == 1 &&
                 finallyBlock != NULL && finallyBlock->childCount > 0 )
                (void)xl6IrLowerTryCatchFinally(ctx, id, node);
            else if ( catches != NULL && catches->kind == XL6_IR_NODE_LIST && catches->childCount > 1 &&
                 finallyBlock != NULL && finallyBlock->childCount > 0 )
                (void)xl6IrLowerTryCatchMultiFinally(ctx, id, node);
            else if ( catches != NULL && catches->kind == XL6_IR_NODE_LIST && catches->childCount > 1 &&
                 finallyBlock != NULL && finallyBlock->childCount == 0 )
                (void)xl6IrLowerTryCatchMulti(ctx, id, node);
            else (void)xl6IrLowerTryCatch(ctx, id, node);
            (void)xl6IrLowerGeneratorCloseCheck(ctx, id);
            return XL6_IR_VALUE_INVALID;
        }
    case XL6_IR_NODE_ASSERT:
        return xl6IrLowerAssert(ctx, id, node);
    case XL6_IR_NODE_BREAK:
    case XL6_IR_NODE_CONTINUE:
        {
            XL6_IrBlockId target;
            const XL6_IrExitPlan* plan;
            XL6_IrLowerDeferredLoopExit* deferred = NULL;
            int isContinue = node->kind == XL6_IR_NODE_CONTINUE;
            if (!xl6IrLowerGeneratorCloseCheck(ctx, id)) return 0;
            if ( node->exitKind != (isContinue ? XL6_SEM_EXIT_CONTINUE : XL6_SEM_EXIT_BREAK) ||
                 (plan = xl6IrLowerExitPlan(ctx, id, isContinue ? XL6_SEM_EXIT_CONTINUE : XL6_SEM_EXIT_BREAK)) == NULL ||
                 !xl6IrLowerExitTarget(ctx, node, isContinue, &target) ||
                 !xl6IrLowerFindDeferredLoopExit(ctx, id, node->targetRegion, isContinue,
                                                  target, &deferred) ) {
                xl6IrLowerDiag(ctx, id, "XLIR loop exit has no resolved CFG target");
                return 0;
            }
            if ( !xl6IrLowerEmitExitCleanup(ctx, id, plan, 0, UINT32_MAX) ) return 0;
            return xl6IrLowerEmitJump(ctx, id, deferred != NULL ? deferred->finallyBlock : target) ? 0 : 0;
        }
    case XL6_IR_NODE_OTHER:
        if ( node->sourceKind == XL6_AST_EXPR_STMT && node->childCount == 1 ) {
            XL6_IrNodeId expressionId = ctx->module->children[node->firstChild];
            const XL6_IrNode* expression = xl6IrNodeGet(ctx->module, expressionId);
            XL6_IrValueId discarded = xl6IrLowerNode(ctx, expressionId);
            if ( discarded != XL6_IR_VALUE_INVALID ) {
                XL6_IrTypeId discardedType = xl6IrLowerValueType(ctx, discarded);
                if ( discardedType != XL6_IR_TYPE_INVALID &&
                     xl6IrLowerTypeNeedsOwnership(ctx->module, discardedType) &&
                     !xl6IrLowerTypeIsRuntimeError(ctx->module, discardedType) ) {
                    XL6_SymbolId temporary = 0;
                    if ( expression == NULL || expression->valueCategory != XL6_IR_VALUE_RVALUE ||
                         !xl6IrLowerTypeHasStorageReleaseAbi(ctx->module, discardedType) ||
                         (temporary = xl6IrLowerNewTempStorage(ctx, discardedType, id)) == 0 ||
                         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, id, discardedType,
                                         temporary, &discarded, 1, NULL) ||
                         !xl6IrLowerEmit(ctx, XL6_IR_INSTR_RELEASE, id, discardedType,
                                         temporary, NULL, 0, NULL) ) {
                        xl6IrLowerDiag(ctx, id,
                            "XLIR expression statement has no exact owned-rvalue storage release ABI");
                        return 0;
                    }
                } else if ( discardedType == XL6_IR_TYPE_INVALID ||
                            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_DISCARD, id, discardedType, 0,
                                            &discarded, 1, NULL) ) {
                    xl6IrLowerDiag(ctx, id,
                                    "XLIR expression statement requires explicit trivial-value or error-observer discard ABI");
                    return 0;
                }
            }
            return 0;
        }
        xl6IrLowerDiag(ctx, id, "XLIR lowering has no rule for this semantic statement node");
        return 0;
    default:
        xl6IrLowerDiag(ctx, id, "XLIR lowering has no rule for this semantic node");
        return 0;
    }
}

static int xl6IrLowerAddFunctionFailurePlan(XL6_IrLowerContext* ctx, XL6_IrNodeId origin)
{
    XL6_IrModule* module = ctx->module;
    XL6_IrExitPlan* plan;
    size_t step;
    if (!xl6IrLowerGrow((void**)&module->exitPlans, &module->exitPlanCapacity,
            module->exitPlanCount, sizeof(*module->exitPlans))) { ctx->failed = 1; return 0; }
    plan = &module->exitPlans[module->exitPlanCount++];
    memset(plan, 0, sizeof(*plan));
    plan->origin = origin;
    plan->point = XL6_IR_EXIT_POINT_FUNCTION_FAILURE;
    plan->kind = XL6_SEM_EXIT_THROW;
    plan->firstStep = module->exitStepCount;
    for (step = 0; step < 2; ++step) {
        XL6_IrExitStep* item;
        if (!xl6IrLowerGrow((void**)&module->exitSteps, &module->exitStepCapacity,
                module->exitStepCount, sizeof(*module->exitSteps))) { ctx->failed = 1; return 0; }
        item = &module->exitSteps[module->exitStepCount++];
        memset(item, 0, sizeof(*item));
        item->kind = step == 0 ? XL6_IR_EXIT_STEP_PARAMETERS : XL6_IR_EXIT_STEP_TERMINAL;
        item->origin = origin;
        item->failureTarget = step == 0 ? origin : XL6_IR_NODE_INVALID;
        ++plan->stepCount;
    }
    return 1;
}

static int xl6IrLowerBeginNamedAdapterFunction(
    XL6_IrLowerContext* ctx, const XL6_IrClosureTarget* closure)
{
    XL6_IrModule* module = ctx != NULL ? ctx->module : NULL;
    const XL6_IrType* signature = module != NULL && closure != NULL
        ? xl6IrTypeGet(&module->types, closure->signatureType) : NULL;
    const XL6_IrCallTarget* target = module != NULL && closure != NULL
        ? xl6IrCallTargetGet(module, closure->adaptedTargetSymbol) : NULL;
    const XL6_IrNode* declaration = target != NULL
        ? xl6IrNodeGet(module, target->declaration) : NULL;
    const XL6_IrNode* parameters = declaration != NULL && declaration->childCount > 1
        ? xl6IrNodeGet(module, module->children[declaration->firstChild + 1]) : NULL;
    XL6_IrFunction* function;
    XL6_IrBlock* block;
    size_t parameter;
    if ( module == NULL || closure == NULL ||
         closure->kind != XL6_IR_CLOSURE_TARGET_NAMED_ADAPTER ||
         signature == NULL || signature->kind != XL6_IR_TYPE_FUNCTION ||
         target == NULL ||
         (target->kind != XL6_IR_CALL_TARGET_INTERNAL &&
          target->kind != XL6_IR_CALL_TARGET_INTERNAL_GENERATOR &&
          target->kind != XL6_IR_CALL_TARGET_EXTERN_C) ||
         (target->errorAbi != XL6_IR_ERROR_ABI_NO_RAISE &&
          target->errorAbi != XL6_IR_ERROR_ABI_MAY_RAISE) ||
         parameters == NULL || parameters->kind != XL6_IR_NODE_LIST ||
         parameters->childCount != target->parameterCount ||
         !xl6IrLowerGrow((void**)&module->functions, &module->functionCapacity,
                          module->functionCount, sizeof(*module->functions)) ||
         !xl6IrLowerGrow((void**)&module->blocks, &module->blockCapacity,
                          module->blockCount, sizeof(*module->blocks)) ) {
        if ( ctx != NULL ) ctx->failed = 1;
        return 0;
    }
    ctx->promotedParameterCount = 0;
    function = &module->functions[module->functionCount];
    memset(function, 0, sizeof(*function));
    function->kind = XL6_IR_FUNCTION_NAMED_ADAPTER;
    function->symbol = closure->targetSymbol;
    function->declaration = closure->declaration;
    if ( declaration->childCount != 0 ) {
        const XL6_IrNode* name = xl6IrNodeGet(
            module, module->children[declaration->firstChild]);
        function->debugName = name != NULL && name->text != NULL &&
                name->text[0] != '\0'
            ? name->text : "<callable-adapter>";
    } else {
        function->debugName = declaration->text != NULL &&
                declaration->text[0] != '\0'
            ? declaration->text : "<callable-adapter>";
    }
    function->returnType = signature->callableResultType;
    /* The adapter owns argument evaluation and cleanup, independently of
     * whether the eventual target raises. Closure invocation already has an
     * outcome-bearing ABI; never infer adaptation success from that target. */
    function->errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
    function->firstBlock = module->blockCount;
    function->firstInstruction = module->instructionCount;
    function->firstValue = ctx->nextValue;
    function->firstParameter = module->functionParameterCount;
    for ( parameter = 0; parameter < signature->paramCount; ++parameter ) {
        size_t targetParameter = xl6IrLowerNamedAdapterTargetParameter(
            signature, target, parameter);
        const XL6_IrNode* sourceParameter = xl6IrNodeGet(
            module, targetParameter != SIZE_MAX
                ? module->children[parameters->firstChild + targetParameter]
                : XL6_IR_NODE_INVALID);
        XL6_SymbolId symbol = xl6IrLowerNewSyntheticSymbol(ctx);
        if ( sourceParameter == NULL || sourceParameter->kind != XL6_IR_NODE_PARAM_DECL ||
             symbol == 0 ||
             !xl6IrLowerGrow((void**)&module->functionParameters,
                              &module->functionParameterCapacity,
                              module->functionParameterCount,
                              sizeof(*module->functionParameters)) ||
             !xl6IrLowerRegisterStorage(ctx, XL6_IR_STORAGE_PARAMETER, symbol,
                                         signature->params[parameter], closure->declaration,
                                         closure->declaration) ||
             (sourceParameter->symbol != 0 &&
              !xl6IrLowerAddPromotedParameter(ctx, sourceParameter->symbol, symbol)) ) {
            ctx->failed = 1;
            return 0;
        }
        module->functionParameters[module->functionParameterCount++] = symbol;
        function->parameterCount += 1;
    }
    block = &module->blocks[module->blockCount];
    memset(block, 0, sizeof(*block));
    block->firstInstruction = module->instructionCount;
    module->blockCount += 1;
    function->entryBlock = (XL6_IrBlockId)module->blockCount;
    function->blockCount = 1;
    ctx->block = function->entryBlock;
    ctx->functionIndex = module->functionCount;
    module->functionCount += 1;
    /* A generated callable has a distinct invocation boundary. Its source
     * NAME belongs to the creator's lexical scopes; defaults belong to the
     * adapted declaration. Neither source ancestry owns this invocation. */
    return xl6IrLowerAddFunctionFailurePlan(ctx, closure->declaration);
}

static int xl6IrLowerNamedAdapterBody(
    XL6_IrLowerContext* ctx, const XL6_IrClosureTarget* closure)
{
    XL6_IrClosureTarget stableClosure;
    const XL6_IrType* signature;
    const XL6_IrCallTarget* target;
    const XL6_IrNode* declaration;
    const XL6_IrNode* parameters;
    XL6_IrFunction* function;
    XL6_IrValueId* operands = NULL;
    XL6_SymbolId* defaultStorages = NULL;
    XL6_IrValueId result = XL6_IR_VALUE_INVALID;
    XL6_IrValueId callResult = XL6_IR_VALUE_INVALID;
    XL6_SymbolId pendingReturn = 0;
    size_t parameter, first;
    int ok = 0;
    if ( ctx == NULL || closure == NULL ) return 0;
    stableClosure = *closure;
    closure = &stableClosure;
    if (
         (signature = xl6IrTypeGet(&ctx->module->types, closure->signatureType)) == NULL ||
         (target = xl6IrCallTargetGet(ctx->module, closure->adaptedTargetSymbol)) == NULL ||
         (declaration = xl6IrNodeGet(ctx->module, target->declaration)) == NULL ||
         declaration->childCount <= 1 ||
         (parameters = xl6IrNodeGet(
             ctx->module, ctx->module->children[declaration->firstChild + 1])) == NULL ||
         !xl6IrLowerBeginNamedAdapterFunction(ctx, closure) ) return 0;
    function = &ctx->module->functions[ctx->functionIndex];
    first = ctx->evaluationOwnerCount;
    if ( target->parameterCount != 0 ) {
        operands = (XL6_IrValueId*)xrtCalloc(target->parameterCount, sizeof(*operands));
        defaultStorages = (XL6_SymbolId*)xrtCalloc(
            target->parameterCount, sizeof(*defaultStorages));
        if ( operands == NULL || defaultStorages == NULL ) {
            ctx->failed = 1;
            goto done;
        }
    }
    /* All consuming inputs belong to the adapter on entry, including a
     * parameter located after a failing default. Protect them before any
     * default expression is evaluated, using the shared owner transaction. */
    for (parameter = 0; parameter < target->parameterCount; ++parameter) {
        size_t incoming = xl6IrLowerNamedAdapterSignatureParameter(signature, target, parameter);
        XL6_SymbolId symbol;
        if (incoming == SIZE_MAX || target->parameterAbis[parameter] != XL6_IR_PARAMETER_ABI_OWNED) continue;
        symbol = ctx->module->functionParameters[function->firstParameter + incoming];
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, closure->declaration,
                target->parameterTypes[parameter], symbol, NULL, 0, &operands[parameter]) ||
            !xl6IrLowerProtectEvaluationStorage(ctx, closure->declaration, symbol, operands[parameter], 1, 0)) goto done;
    }
    for ( parameter = 0; parameter < target->parameterCount; ++parameter ) {
        size_t signatureParameter = xl6IrLowerNamedAdapterSignatureParameter(
            signature, target, parameter);
        const XL6_IrNode* sourceParameter = xl6IrNodeGet(
            ctx->module, ctx->module->children[parameters->firstChild + parameter]);
        if ( sourceParameter == NULL || sourceParameter->kind != XL6_IR_NODE_PARAM_DECL ) goto done;
        if ( signatureParameter != SIZE_MAX ) {
            if (target->parameterAbis[parameter] == XL6_IR_PARAMETER_ABI_OWNED) continue;
            XL6_SymbolId symbol = ctx->module->functionParameters[
                function->firstParameter + signatureParameter];
            if ( target->parameterAbis[parameter] == XL6_IR_PARAMETER_ABI_INOUT ||
                 target->parameterAbis[parameter] == XL6_IR_PARAMETER_ABI_OUT ) {
                operands[parameter] = xl6IrLowerEmitStorageSymbolAddress(
                    ctx, closure->declaration, closure->declaration, symbol,
                    target->parameterTypes[parameter]);
                if ( operands[parameter] == XL6_IR_VALUE_INVALID ) goto done;
            } else if ( !xl6IrLowerEmit(
                           ctx, XL6_IR_INSTR_LOAD, closure->declaration,
                           target->parameterTypes[parameter], symbol,
                           NULL, 0, &operands[parameter]) ) goto done;
        } else {
            XL6_IrNodeId defaultId;
            const XL6_IrNode* expression;
            XL6_IrValueId loaded;
            if ( sourceParameter->symbol == 0 || sourceParameter->childCount < 2 ) goto done;
            defaultId = ctx->module->children[sourceParameter->firstChild + 1];
            expression = xl6IrNodeGet(ctx->module, defaultId);
            operands[parameter] = xl6IrLowerNodeAsType(
                ctx, defaultId, defaultId, expression,
                target->parameterTypes[parameter]);
            if (operands[parameter] != XL6_IR_VALUE_INVALID)
                operands[parameter] = xl6IrLowerOwnedStorageValue(ctx, defaultId,
                    target->parameterTypes[parameter], expression, operands[parameter]);
            defaultStorages[parameter] = xl6IrLowerNewTempStorage(
                ctx, target->parameterTypes[parameter], defaultId);
            if ( operands[parameter] == XL6_IR_VALUE_INVALID ||
                 defaultStorages[parameter] == 0 ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, defaultId,
                                  target->parameterTypes[parameter],
                                  defaultStorages[parameter], &operands[parameter], 1, NULL) ||
                 !xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, defaultId,
                                  target->parameterTypes[parameter],
                                  defaultStorages[parameter], NULL, 0, &loaded) ||
                 !xl6IrLowerAddPromotedParameter(
                      ctx, sourceParameter->symbol, defaultStorages[parameter]) ) goto done;
            operands[parameter] = loaded;
            if (xl6IrTypeHasStorageReleaseAbi(ctx->module, target->parameterTypes[parameter]) &&
                !xl6IrLowerProtectEvaluationStorage(ctx, defaultId, defaultStorages[parameter], loaded,
                    target->parameterAbis[parameter] == XL6_IR_PARAMETER_ABI_OWNED, 0)) goto done;
        }
    }
    /* Adapter parameters already own BYVAL inputs. Detach those slots only
     * after all argument/default binding is complete, immediately before the
     * consuming call. A LOAD alone is a borrow, not permission to consume.
     * Default temporaries use the same commit as incoming parameter slots. */
    if (!xl6IrLowerCommitEvaluationOwners(ctx, closure->declaration, first)) goto done;
    if ( !xl6IrLowerEmit(ctx,
                          target->kind == XL6_IR_CALL_TARGET_INTERNAL_GENERATOR
                              ? XL6_IR_INSTR_GENERATOR_START
                              : XL6_IR_INSTR_CALL,
                          closure->declaration,
                          target->returnType, target->symbol,
                          operands, target->parameterCount,
                          target->returnType == XL6_IR_TYPE_INVALID &&
                          target->errorAbi == XL6_IR_ERROR_ABI_NO_RAISE
                              ? NULL : &callResult) ) goto done;
    {
        XL6_IrLowerCallCleanup cleanup = {0};
        size_t count = 0;
        /* Consuming defaults are already owned by the target. Borrowed
         * defaults remain adapter owners through outcome observation and
         * result commit, using the same transaction as every ordinary call. */
        for (parameter = 0; parameter < target->parameterCount; ++parameter) {
            if (defaultStorages[parameter] == 0 ||
                !xl6IrTypeHasStorageReleaseAbi(ctx->module, target->parameterTypes[parameter]) ||
                target->parameterAbis[parameter] == XL6_IR_PARAMETER_ABI_OWNED) continue;
            if (target->parameterAbis[parameter] != XL6_IR_PARAMETER_ABI_BORROW) goto done;
            defaultStorages[count++] = defaultStorages[parameter];
        }
        cleanup.temporaries = defaultStorages; cleanup.temporaryCount = count;
        if (!xl6IrLowerCompleteCall(ctx, closure->declaration,
                xl6IrNodeGet(ctx->module, closure->declaration), target, &callResult, NULL, &cleanup)) goto done;
    }
    result = target->returnType == XL6_IR_TYPE_INVALID
        ? XL6_IR_VALUE_INVALID : callResult;
    if ( result != XL6_IR_VALUE_INVALID && target->returnType != function->returnType ) {
        result = xl6IrLowerEmitValueCopy(
            ctx, closure->declaration, function->returnType,
            result);
        if ( result == XL6_IR_VALUE_INVALID ) goto done;
    }
    if (result != XL6_IR_VALUE_INVALID)
        pendingReturn = xl6IrLowerPrepareReturnValue(ctx, closure->declaration, function->returnType, result);
    if (ctx->failed ||
        !xl6IrLowerEmitTerminal(ctx, XL6_IR_INSTR_RETURN, closure->declaration,
                                  result == XL6_IR_VALUE_INVALID ? NULL : &result,
                                  result == XL6_IR_VALUE_INVALID ? 0 : 1, pendingReturn) ) goto done;
    ok = 1;
done:
    ctx->evaluationOwnerCount = first;
    xrtFree(operands);
    xrtFree(defaultStorages);
    xl6IrLowerEndFunction(ctx);
    if ( !ok && !ctx->failed )
        xl6IrLowerDiag(ctx, closure->declaration,
                        "XLIR named function adapter CFG could not be materialized exactly");
    return ok;
}

/* Default reconstruction is an ordinary checked invocation, independent of
 * the lexical scopes in which its class declaration appeared. */
static int xl6IrLowerPersistenceDefaultFunctions(XL6_IrLowerContext* ctx)
{
    XL6_IrModule* module = ctx->module;
    for (size_t layoutIndex = 0; layoutIndex < module->classLayoutCount; ++layoutIndex) {
        XL6_IrClassLayout* layout = &module->classLayouts[layoutIndex];
        XL6_IrTypeId type = layout->type;
        XL6_IrNodeId origin = layout->declaration;
        XL6_IrValueId result;
        XL6_SymbolId pending;
        size_t first = ctx->evaluationOwnerCount;
        if (layout->persistenceDefaultFunction != 0 ||
            layout->persistenceConstructionAbi != XL6_IR_PERSISTENCE_CONSTRUCTION_DECLARATION_DEFAULT)
            continue;
        if (module->functionCount >= UINT32_MAX ||
            !xl6IrLowerBeginFunction(ctx, origin, XL6_IR_FUNCTION_CLASS_DEFAULT)) return 0;
        /* Initializer lowering can grow arenas. Do not keep an arena pointer
         * across the call, and publish the function identity beforehand. */
        layout->persistenceDefaultFunction = (uint32)module->functionCount;
        module->functions[ctx->functionIndex].symbol = xl6IrLowerNewSyntheticSymbol(ctx);
        module->functions[ctx->functionIndex].debugName = "<persistence-default>";
        module->functions[ctx->functionIndex].returnType = type;
        module->functions[ctx->functionIndex].errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
        if (module->functions[ctx->functionIndex].symbol == 0 ||
            !xl6IrLowerAddFunctionFailurePlan(ctx, origin)) return 0;
        result = xl6IrLowerPersistenceClassDefault(ctx, origin, type);
        if (result == XL6_IR_VALUE_INVALID) return 0;
        pending = xl6IrLowerPrepareReturnValue(ctx, origin, type, result);
        if (ctx->failed || !xl6IrLowerEmitTerminal(ctx, XL6_IR_INSTR_RETURN,
                origin, &result, 1, pending)) return 0;
        ctx->evaluationOwnerCount = first;
        xl6IrLowerEndFunction(ctx);
    }
    return !ctx->failed;
}

/* Class destruction is an effect-bearing IR program, including every base
 * destructor and its failure edge. The native callback only borrows the dying
 * receiver and adapts this program's aggregate outcome to the runtime ABI. */
static int xl6IrLowerClassFinalizers(XL6_IrLowerContext* ctx)
{
    XL6_IrModule* module = ctx->module;
    size_t layoutIndex;
    for (layoutIndex = 0; layoutIndex < module->classLayoutCount; ++layoutIndex) {
        XL6_IrClassLayout* layout = &module->classLayouts[layoutIndex];
        XL6_IrValueId receiver, outcome;
        XL6_IrTypeId boolean = xl6IrLowerFindTypeByCAbi(module, XL6_IR_C_ABI_BOOL);
        XL6_IrBlockId success, failure;
        XL6_SymbolId parameter;
        size_t stepIndex;
        layout->destroyFunction = 0;
        if (layout->destroyStepCount == 0) continue;
        if (module->functionCount >= UINT32_MAX || boolean == XL6_IR_TYPE_INVALID ||
            !xl6IrLowerBeginFunction(ctx, layout->declaration, XL6_IR_FUNCTION_CLASS_FINI)) return 0;
        layout->destroyFunction = (uint32)module->functionCount;
        module->functions[ctx->functionIndex].symbol = xl6IrLowerNewSyntheticSymbol(ctx);
        module->functions[ctx->functionIndex].errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
        parameter = xl6IrLowerNewSyntheticSymbol(ctx);
        if (parameter == 0 || !xl6IrLowerGrow((void**)&module->functionParameters,
                &module->functionParameterCapacity, module->functionParameterCount,
                sizeof(*module->functionParameters)) ||
            !xl6IrLowerRegisterStorage(ctx, XL6_IR_STORAGE_PARAMETER, parameter,
                layout->type, layout->declaration, layout->declaration)) return 0;
        module->functionParameters[module->functionParameterCount++] = parameter;
        module->functions[ctx->functionIndex].parameterCount = 1;
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, layout->declaration,
                layout->type, parameter, NULL, 0, &receiver) || ctx->errorUnwindScope != 0 ||
            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_INHERIT_BEGIN, layout->declaration,
                XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
        ctx->errorUnwindScope = module->instructionCount;
        module->instructions[ctx->errorUnwindScope - 1].errorScope = ctx->errorUnwindScope;
        for (stepIndex = 0; stepIndex < layout->destroyStepCount; ++stepIndex) {
            const XL6_IrClassDestroyStep* step = &module->classDestroySteps[layout->firstDestroyStep + stepIndex];
            const XL6_IrCallTarget* target = xl6IrCallTargetGet(module, step->targetSymbol);
            XL6_IrValueId view, result;
            XL6_IrInstruction* test;
            if (target == NULL ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_VALUE, step->declaration,
                    step->receiverType, 0, &receiver, 1, &view) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CALL, step->declaration,
                    XL6_IR_TYPE_INVALID, step->targetSymbol, &view, 1,
                    target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE ? &result : NULL)) return 0;
            if (target->errorAbi == XL6_IR_ERROR_ABI_MAY_RAISE) {
                XL6_IrBlockId failed, next;
                if (!xl6IrLowerNewBlock(ctx, &failed) || !xl6IrLowerNewBlock(ctx, &next) ||
                    !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_TEST, step->declaration,
                        XL6_IR_TYPE_INVALID, step->targetSymbol, &result, 1, NULL)) return 0;
                test = &module->instructions[module->instructionCount - 1];
                test->trueTarget = next; test->falseTarget = failed;
                xl6IrLowerEnterBlock(ctx, failed);
                if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_FAIL, step->declaration,
                        XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL) ||
                    !xl6IrLowerEmitJump(ctx, step->declaration, next)) return 0;
                xl6IrLowerEnterBlock(ctx, next);
            }
            if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_CAPTURE, step->declaration,
                    XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
        }
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_END, layout->declaration,
                boolean, 0, NULL, 0, &outcome)) return 0;
        ctx->errorUnwindScope = 0;
        if (!xl6IrLowerNewBlock(ctx, &success) || !xl6IrLowerNewBlock(ctx, &failure) ||
            !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_TEST, layout->declaration,
                XL6_IR_TYPE_INVALID, 0, &outcome, 1, NULL)) return 0;
        module->instructions[module->instructionCount - 1].trueTarget = success;
        module->instructions[module->instructionCount - 1].falseTarget = failure;
        xl6IrLowerEnterBlock(ctx, failure);
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_THROW, layout->declaration,
                XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
        xl6IrLowerEnterBlock(ctx, success);
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_RETURN, layout->declaration,
                XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
        xl6IrLowerEndFunction(ctx);
    }
    return !ctx->failed;
}

static int xl6IrLowerModuleFinalizer(XL6_IrLowerContext* ctx)
{
    XL6_IrModule* module = ctx->module;
    XL6_IrTypeId boolean;
    XL6_IrValueId outcome;
    XL6_IrBlockId success, failure;
    XL6_IrInstruction* test;
    size_t i, cleanupCount = 0;
    for (i = 0; i < module->storageCount; ++i) {
        int cleanup = xl6IrGlobalStorageCleanup(module, &module->storages[i], NULL);
        if (cleanup < 0) return xl6IrLowerDiag(ctx, module->storages[i].declaration,
            "XLIR module storage has no exact finalization ABI");
        cleanupCount += cleanup != 0;
    }
    if (module->functionCount >= UINT32_MAX ||
        !xl6IrLowerBeginFunction(ctx, module->root, XL6_IR_FUNCTION_MODULE_FINI)) return 0;
    module->abi.finalizerFunction = (uint32)module->functionCount;
    module->abi.finalizerCleanupCount = cleanupCount;
    module->abi.taskPoolAbi = xl6IrModuleTaskPoolRequirement(module);
    module->abi.continuationAbi = xl6IrModuleContinuationRequirement(module);
    module->abi.executorOwnershipAbi = xl6IrModuleExecutorOwnershipRequirement(module);
    module->abi.taskPoolOwnershipAbi = xl6IrModuleTaskPoolOwnershipRequirement(module);
    if (module->abi.taskPoolAbi != XL6_IR_MODULE_TASK_POOL_NONE &&
        module->abi.taskPoolAbi != XL6_IR_MODULE_TASK_POOL_XRT_GUARDED_QUIESCE)
        return xl6IrLowerDiag(ctx, module->root, "XLIR module task pool resource ABI is unresolved");
    if (xl6IrModuleHasFinalizerWork(module))
        module->functions[ctx->functionIndex].errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
    if (cleanupCount == 0) {
        xl6IrLowerEndFunction(ctx);
        return !ctx->failed;
    }
    boolean = xl6IrLowerFindTypeByCAbi(module, XL6_IR_C_ABI_BOOL);
    module->functions[ctx->functionIndex].errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
    if (boolean == XL6_IR_TYPE_INVALID || ctx->errorUnwindScope != 0 ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_INHERIT_BEGIN, module->root,
            XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
    ctx->errorUnwindScope = module->instructionCount;
    module->instructions[ctx->errorUnwindScope - 1].errorScope = ctx->errorUnwindScope;
    for (i = module->storageCount; i > 0; --i) {
        XL6_IrCleanupAction action;
        int cleanup = xl6IrGlobalStorageCleanup(module, &module->storages[i - 1], &action);
        if (cleanup < 0) return 0;
        if (cleanup == 0) continue;
        if (action.kind == XL6_IR_CLEANUP_NATIVE_DESTROY) {
            XL6_IrValueId owned, empty, isNull;
            XL6_IrBlockId destroy, next;
            /* Detach before invoking user/native code. A callback must never
             * see or replace an owner that finalization will clear afterward. */
            if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_LOAD, action.origin, action.type,
                    action.targetSymbol, NULL, 0, &owned) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL, action.origin, action.type, 0, NULL, 0, &empty) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_STORE, action.origin, action.type,
                    action.targetSymbol, &empty, 1, NULL) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_NULL_TEST, action.origin, boolean, 0, &owned, 1, &isNull) ||
                !xl6IrLowerNewBlock(ctx, &destroy) || !xl6IrLowerNewBlock(ctx, &next) ||
                !xl6IrLowerEmit(ctx, XL6_IR_INSTR_BRANCH, action.origin, XL6_IR_TYPE_INVALID,
                    0, &isNull, 1, NULL)) return 0;
            test = &module->instructions[module->instructionCount - 1];
            test->trueTarget = next; test->falseTarget = destroy;
            xl6IrLowerEnterBlock(ctx, destroy);
            if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CALL, action.origin, XL6_IR_TYPE_INVALID,
                    action.calleeSymbol, &owned, 1, NULL) ||
                !xl6IrLowerEmitJump(ctx, action.origin, next)) return 0;
            xl6IrLowerEnterBlock(ctx, next);
        } else if (!xl6IrLowerEmit(ctx,
                action.kind == XL6_IR_CLEANUP_CELL_RELEASE ? XL6_IR_INSTR_CELL_RELEASE : XL6_IR_INSTR_RELEASE,
                action.origin, action.type, action.targetSymbol, NULL, 0, NULL)) return 0;
        if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_CAPTURE, action.origin,
                XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
    }
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_CLEANUP_END, module->root, boolean, 0, NULL, 0, &outcome)) return 0;
    ctx->errorUnwindScope = 0;
    if (!xl6IrLowerNewBlock(ctx, &success) || !xl6IrLowerNewBlock(ctx, &failure) ||
        !xl6IrLowerEmit(ctx, XL6_IR_INSTR_ERROR_TEST, module->root, XL6_IR_TYPE_INVALID, 0, &outcome, 1, NULL)) return 0;
    test = &module->instructions[module->instructionCount - 1];
    test->trueTarget = success; test->falseTarget = failure;
    xl6IrLowerEnterBlock(ctx, failure);
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_THROW, module->root, XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
    xl6IrLowerEnterBlock(ctx, success);
    if (!xl6IrLowerEmit(ctx, XL6_IR_INSTR_RETURN, module->root, XL6_IR_TYPE_INVALID, 0, NULL, 0, NULL)) return 0;
    xl6IrLowerEndFunction(ctx);
    return !ctx->failed;
}

/* Unsupported declaration partitions must fail at the XLIR boundary with a
 * source-owned diagnostic, before CFG construction or backend dispatch. */
static int xl6IrLowerRejectUnsupportedDeclarations(XL6_IrLowerContext* ctx)
{
    size_t i;
    if ( ctx == NULL || ctx->module == NULL ) return 0;
    /* A protocol declaration is compile-time metadata, not an executable
     * dispatch request.  Unused protocols (including generic requirements)
     * therefore need no runtime table.  Every actual PROTOCOL_CALL still
     * carries a one-based verified slot and Cgen remains fail-closed on that
     * instruction, so declaration-only modules cannot manufacture dispatch. */
    for ( i = 0; i < ctx->module->nodeCount; ++i ) {
        XL6_IrNodeId id = (XL6_IrNodeId)(i + 1);
        const XL6_IrNode* node = &ctx->module->nodes[i];
        if ( node->kind == XL6_IR_NODE_FUNC_DECL &&
              (node->flags & (XL6_AST_FLAG_VIRTUAL | XL6_AST_FLAG_OVERRIDE)) != 0 &&
              xl6IrLowerEnclosingClass(ctx->module, id) != XL6_IR_NODE_INVALID ) {
            if ( xl6IrLowerClassDispatchSlotByDeclarationSymbol(ctx->module, node->symbol) == SIZE_MAX )
                return xl6IrLowerDiag(ctx, id,
                                      "XLIR virtual declaration has no canonical class dispatch slot");
        }
    }
    return 1;
}

/* A source declaration may intentionally evaluate a fallible expression and
 * never observe its trivial result (for example `bool ignored = await f`).
 * Canonical lowered XLIR keeps the evaluation/failure CFG, but represents the
 * unused value as DISCARD instead of a write-only C-shaped storage slot.
 * Managed slots are excluded because their stores and cleanup carry ownership
 * effects even when no LOAD observes the payload. */
static int xl6IrLowerCanonicalizeDeadTrivialStorages(XL6_IrModule* module)
{
    size_t storageIndex = 0;
    if ( module == NULL ) return 0;
    while ( storageIndex < module->storageCount ) {
        XL6_IrStorage* storage = &module->storages[storageIndex];
        const XL6_IrType* type = xl6IrTypeGet(&module->types, storage->type);
        size_t instructionIndex;
        size_t captureIndex;
        int hasStore = 0;
        int hasNonStoreUse = 0;
        if ( (storage->kind != XL6_IR_STORAGE_LOCAL &&
              storage->kind != XL6_IR_STORAGE_TEMPORARY) ||
             storage->cellType != XL6_IR_TYPE_INVALID || type == NULL ||
             type->ownershipAbi != XL6_IR_OWNERSHIP_ABI_TRIVIAL ) {
            storageIndex += 1;
            continue;
        }
        for ( instructionIndex = 0;
              instructionIndex < module->instructionCount; ++instructionIndex ) {
            const XL6_IrInstruction* instruction =
                &module->instructions[instructionIndex];
            if ( instruction->targetSymbol != storage->symbol ) continue;
            if ( instruction->kind == XL6_IR_INSTR_STORE ) hasStore = 1;
            else hasNonStoreUse = 1;
        }
        for ( captureIndex = 0;
              !hasNonStoreUse && captureIndex < module->closureCaptureCount;
              ++captureIndex ) {
            const XL6_IrClosureCapture* capture =
                &module->closureCaptures[captureIndex];
            if ( capture->sourceSymbol == storage->symbol ||
                 capture->storageSymbol == storage->symbol )
                hasNonStoreUse = 1;
        }
        if ( hasNonStoreUse ) {
            storageIndex += 1;
            continue;
        }
        if ( hasStore ) {
            for ( instructionIndex = 0;
                  instructionIndex < module->instructionCount; ++instructionIndex ) {
                XL6_IrInstruction* instruction =
                    &module->instructions[instructionIndex];
                if ( instruction->kind != XL6_IR_INSTR_STORE ||
                     instruction->targetSymbol != storage->symbol ) continue;
                instruction->kind = XL6_IR_INSTR_DISCARD;
                /* STORE carries its value type through the storage record;
                 * DISCARD has no storage indirection and must own that TypeId
                 * directly for verifier/Cgen to observe an exact ABI. */
                instruction->type = storage->type;
                instruction->targetSymbol = 0;
            }
        }
        if ( storageIndex + 1 < module->storageCount )
            memmove(module->storages + storageIndex,
                    module->storages + storageIndex + 1,
                    (module->storageCount - storageIndex - 1) *
                        sizeof(*module->storages));
        module->storageCount -= 1;
    }
    return 1;
}

int xl6IrLowerModule(XL6_IrModule* module, XL6_DiagList* diags)
{
    XL6_IrLowerContext ctx;
    size_t i;
    if ( module == NULL || module->stage != XL6_IR_STAGE_TYPED || !xl6IrVerifyModule(module, diags) ) return 0;
    xrtFree(module->blocks); module->blocks = NULL; module->blockCount = 0; module->blockCapacity = 0;
    xrtFree(module->functions); module->functions = NULL; module->functionCount = 0; module->functionCapacity = 0;
    for (i = 0; i < module->classLayoutCount; ++i)
        module->classLayouts[i].persistenceDefaultFunction = 0;
    xl6IrLowerClearCallTargets(module);
    xl6IrLowerClearExports(module);
    xl6IrLowerClearGenericSpecializations(module);
    memset(&module->abi, 0, sizeof(module->abi));
    xrtFree(module->functionParameters); module->functionParameters = NULL; module->functionParameterCount = 0; module->functionParameterCapacity = 0;
    xrtFree(module->storages); module->storages = NULL; module->storageCount = 0; module->storageCapacity = 0;
    xl6IrLowerClearInstructions(module);
    xrtFree(module->operands); module->operands = NULL; module->operandCount = 0; module->operandCapacity = 0;
    module->entryBlock = XL6_IR_BLOCK_INVALID; module->valueCount = XL6_IR_VALUE_INVALID;
    for ( i = 0; i < module->dynamicMethodCount; ++i )
        module->dynamicMethods[i].targetErrorAbi =
            XL6_IR_ERROR_ABI_INVALID;
    memset(&ctx, 0, sizeof(ctx));
    ctx.module = module; ctx.diags = diags; ctx.nextValue = 1; ctx.nextSyntheticSymbol = UINT32_MAX;
    if ( !xl6IrLowerRejectUnsupportedDeclarations(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering declaration admission failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericSpecializations(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic specialization materialization failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericClassSyntaxUses(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic syntax materialization failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericClassCopyProtocols(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic class protocol materialization failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericProtocolWitnesses(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic protocol witness materialization failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericLoopProtocols(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic loop protocol materialization failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshClassLayouts(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic class-layout refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshNominalIdentitySets(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering nominal identity refresh failed without diagnostic provenance");
        return 0;
    }
    /* The implicit __iter__ specialization may itself contain ordinary
     * generic calls (for example I::<T> construction).  Close that newly
     * appended call graph before call-target registration. */
    if ( !xl6IrLowerMaterializeGenericSpecializations(&ctx) ||
         !xl6IrLowerMaterializeGenericClassSyntaxUses(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic loop specialization closure failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerMaterializeGenericDynamicMethods(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering generic dynamic method materialization failed without diagnostic provenance");
        return 0;
    }
    /* Registry-only specializations may introduce concrete nullable/product
     * types after layout construction. Derive their persistence contracts
     * from the final TypePool just as for source-instantiated types. */
    if (!xl6IrRefreshPersistenceTypeAbis(module))
        return xl6IrLowerDiag(&ctx, module->root,
            "XLIR specialization persistence-type refresh failed");
    if ( !xl6IrRefreshOperatorAbis(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering operator ABI refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshMemberAbis(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering member ABI refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshIndexWriteAbis(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering index-write ABI refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshLoopAbis(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering loop ABI refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrRefreshConversionAbis(module) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering conversion ABI refresh failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerRegisterClassStaticFields(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering class static-field registration failed without diagnostic provenance");
        return 0;
    }
    if ( !xl6IrLowerRegisterModuleCallTargets(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering call-target registration failed without diagnostic provenance");
        return 0;
    }
    if (!xl6IrRefreshConstructionAbis(module) || !xl6IrRefreshExitPlans(module)) {
        if (diags == NULL || diags->count == 0)
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering capture construction and exit-plan closure failed");
        return 0;
    }
    if ( !xl6IrLowerPrecomputeCallTargetErrorAbis(&ctx) ) {
        if ( diags == NULL || diags->count == 0 )
            xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering call-target error ABI analysis failed without diagnostic provenance");
        return 0;
    }
    xl6IrLowerRefreshRawCallbackAbis(module);
    if ( !xl6IrLowerLinkDynamicMethods(&ctx) ) return 0;
    if ( !xl6IrLowerRegisterModuleExports(&ctx) ) return 0;
    if ( !xl6IrLowerBuildModuleAbi(&ctx) ) return 0;
    if ( !xl6IrLowerBeginFunction(&ctx, module->root, XL6_IR_FUNCTION_MODULE_INIT) ) return 0;
    if ( xl6IrLowerModuleInitializationMayEscapeRaise(module) )
        module->functions[ctx.functionIndex].errorAbi = XL6_IR_ERROR_ABI_MAY_RAISE;
    module->entryBlock = ctx.block;
    if ( !xl6IrLowerInitializeClassStaticFields(&ctx) ) ctx.failed = 1;
    (void)xl6IrLowerNode(&ctx, module->root);
    xl6IrLowerEndFunction(&ctx);
    /* Initializers may instantiate generic bodies or closures. Materialize
     * factories before walking those executable declarations so dependencies
     * use the ordinary lowering pass, not a second backend implementation. */
    if (!ctx.failed && !xl6IrLowerPersistenceDefaultFunctions(&ctx)) ctx.failed = 1;
    {
        const XL6_IrNode* root = xl6IrNodeGet(module, module->root);
        for ( i = 0; root != NULL && i < root->childCount; ++i ) {
            XL6_IrNodeId candidate = module->children[root->firstChild + i];
            const XL6_IrNode* node = xl6IrNodeGet(module, candidate);
            if ( node != NULL && node->kind == XL6_IR_NODE_FUNC_DECL &&
                 node->sourceKind != XL6_AST_EXTERN_FUNC &&
                 node->sourceKind != XL6_AST_NATIVE_EXTERN_SPECIAL &&
                  node->sourceKind != XL6_AST_NATIVE_EXTERN_FUNC && node->childCount > 3 &&
                  !xl6IrLowerIsGenericDeclaration(module, candidate) ) {
                const XL6_IrCallTarget* callable =
                    xl6IrCallTargetGet(module, node->symbol);
                XL6_IrFunctionKind functionKind = callable != NULL &&
                    callable->kind == XL6_IR_CALL_TARGET_INTERNAL_GENERATOR
                    ? XL6_IR_FUNCTION_GENERATOR_WORKER
                    : node->sourceKind != XL6_AST_ASYNC_FUNC
                        ? XL6_IR_FUNCTION_USER : XL6_IR_FUNCTION_ASYNC_WORKER;
                if ( !xl6IrLowerBeginFunction(
                         &ctx, candidate, functionKind) ) break;
                (void)xl6IrLowerNode(&ctx, module->children[node->firstChild + 3]);
                xl6IrLowerEndFunction(&ctx);
            }
        }
    }
    /* Class constructors, property getters and instance methods use ordinary
     * function CFG with their already-registered borrowed receiver in slot
     * zero.  No Cgen class-body traversal is permitted. */
    for ( i = 0; !ctx.failed && i < module->nodeCount; ++i ) {
        XL6_IrNodeId candidate = (XL6_IrNodeId)(i + 1);
        const XL6_IrNode* node = &module->nodes[i];
        int classProperty =
            (node->sourceKind == XL6_AST_GET || node->sourceKind == XL6_AST_LET) &&
            (node->flags & XL6_AST_FLAG_EXTERN) == 0 &&
            xl6IrLowerEnclosingClass(module, candidate) != XL6_IR_NODE_INVALID;
        XL6_IrNodeId body = node->sourceKind == XL6_AST_CREATE
            ? xl6IrLowerCreateSignaturePart(module, candidate, XL6_IR_NODE_BLOCK)
            : ((classProperty ||
                xl6IrLowerIsInstanceClassMethod(module, candidate, node) ||
                (node->sourceKind == XL6_AST_FUNC && (node->flags & XL6_AST_FLAG_STATIC) != 0 &&
                  xl6IrLowerEnclosingClass(module, candidate) != XL6_IR_NODE_INVALID)) && node->childCount > 3
                ? module->children[node->firstChild + 3] : XL6_IR_NODE_INVALID);
        if ( node->kind == XL6_IR_NODE_FUNC_DECL &&
            (node->sourceKind == XL6_AST_CREATE || classProperty ||
              xl6IrLowerIsInstanceClassMethod(module, candidate, node) ||
              (node->sourceKind == XL6_AST_FUNC && (node->flags & XL6_AST_FLAG_STATIC) != 0 &&
               xl6IrLowerEnclosingClass(module, candidate) != XL6_IR_NODE_INVALID)) &&
              body != XL6_IR_NODE_INVALID &&
              !xl6IrLowerIsGenericDeclaration(module, candidate) ) {
            const XL6_IrCallTarget* callable =
                xl6IrCallTargetGet(module, node->symbol);
            XL6_IrFunctionKind functionKind = callable != NULL &&
                callable->kind == XL6_IR_CALL_TARGET_INTERNAL_GENERATOR
                ? XL6_IR_FUNCTION_GENERATOR_WORKER
                : node->sourceKind != XL6_AST_ASYNC_FUNC
                    ? XL6_IR_FUNCTION_USER : XL6_IR_FUNCTION_ASYNC_WORKER;
            if ( !xl6IrLowerBeginFunction(
                     &ctx, candidate, functionKind) ) break;
            (void)xl6IrLowerNode(&ctx, body);
            xl6IrLowerEndFunction(&ctx);
        }
    }
    /* Closure bodies are lowered independently from the activation that
     * constructs them.  Their empty capture slice is already recorded in the
     * closure arena; capture-bearing bodies will receive frame storage rather
     * than sharing their creator's C locals. */
    for ( i = 0; !ctx.failed && i < module->closureTargetCount; ++i ) {
        XL6_IrClosureTarget closure = module->closureTargets[i];
        const XL6_IrNode* node = xl6IrNodeGet(module, closure.declaration);
        if ( closure.kind == XL6_IR_CLOSURE_TARGET_NAMED_ADAPTER ) {
            if ( !xl6IrLowerNamedAdapterBody(&ctx, &closure) ) break;
            continue;
        }
        if ( closure.kind != XL6_IR_CLOSURE_TARGET_ANONYMOUS ||
             node == NULL || node->sourceKind != XL6_AST_ANON_FUNC || node->childCount <= 2 ||
             !xl6IrLowerBeginFunction(&ctx, closure.declaration, XL6_IR_FUNCTION_USER) ) break;
        (void)xl6IrLowerNode(&ctx, module->children[node->firstChild + 2]);
        xl6IrLowerEndFunction(&ctx);
    }
    if ( !ctx.failed &&
         !xl6IrLowerPropagateRawCallbackConstraints(&ctx) ) ctx.failed = 1;
    if ( !ctx.failed && !xl6IrLowerModuleFinalizer(&ctx) ) ctx.failed = 1;
    if ( !ctx.failed && !xl6IrLowerClassFinalizers(&ctx) ) ctx.failed = 1;
    if ( !ctx.failed && !xl6IrLowerVerifyErrorAbis(&ctx) ) ctx.failed = 1;
    if ( ctx.failed ) {
        /* Every rejected typed tree must leave a diagnostic.  Allocation and
         * structural helpers historically only set this flag, which made the
         * public XLIR path report an opaque compile failure. */
        if ( diags == NULL || diags->count == 0 ) {
            char message[256];
            const XL6_IrFunction* active = ctx.functionIndex < module->functionCount
                ? &module->functions[ctx.functionIndex] : NULL;
            const XL6_IrInstruction* last = module->instructionCount != 0
                ? &module->instructions[module->instructionCount - 1] : NULL;
            snprintf(message, sizeof(message),
                     "XLIR lowering aborted without diagnostic provenance "
                     "(function=%lu declaration=n%u block=b%u instructions=%lu last-origin=n%u last-kind=%d)",
                     (unsigned long)ctx.functionIndex,
                     (unsigned int)(active != NULL ? active->declaration : XL6_IR_NODE_INVALID),
                     (unsigned int)ctx.block,
                     (unsigned long)module->instructionCount,
                     (unsigned int)(last != NULL ? last->origin : XL6_IR_NODE_INVALID),
                     last != NULL ? (int)last->kind : (int)XL6_IR_INSTR_INVALID);
            xl6IrLowerDiag(&ctx,
                           last != NULL ? last->origin : module->root,
                           message);
        }
        xrtFree(module->blocks); module->blocks = NULL; module->blockCount = 0; module->blockCapacity = 0;
        xrtFree(module->functions); module->functions = NULL; module->functionCount = 0; module->functionCapacity = 0;
        for (i = 0; i < module->classLayoutCount; ++i) {
            module->classLayouts[i].destroyFunction = 0;
            module->classLayouts[i].persistenceDefaultFunction = 0;
        }
        xl6IrLowerClearCallTargets(module);
        xl6IrLowerClearExports(module);
        xl6IrLowerClearGenericSpecializations(module);
        memset(&module->abi, 0, sizeof(module->abi));
        xrtFree(module->functionParameters); module->functionParameters = NULL; module->functionParameterCount = 0; module->functionParameterCapacity = 0;
        xrtFree(module->storages); module->storages = NULL; module->storageCount = 0; module->storageCapacity = 0;
        xl6IrLowerClearInstructions(module);
        xrtFree(module->operands); module->operands = NULL; module->operandCount = 0; module->operandCapacity = 0;
        module->entryBlock = XL6_IR_BLOCK_INVALID; module->valueCount = XL6_IR_VALUE_INVALID;
        xrtFree(ctx.loops);
        xrtFree(ctx.loopResources);
        xrtFree(ctx.exceptions);
        xrtFree(ctx.catchPayloads);
        xl6IrLowerDisposeDeferredReturns(&ctx);
        xrtFree(ctx.finallyBarriers);
        xrtFree(ctx.deferredLoopExits);
        xrtFree(ctx.promotedParameters);
        return 0;
    }
    module->valueCount = ctx.nextValue - 1;
    module->abi.closureStorageAbi = XL6_IR_CLOSURE_STORAGE_RESIDENT_LAYOUT_V2;
    module->abi.retirementAbi = module->abi.codeOwnerAbi == XL6_IR_MODULE_CODE_OWNER_BIND_BEFORE_INIT
        ? (module->abi.executorOwnershipAbi == XL6_IR_MODULE_EXECUTOR_OWNERSHIP_RESIDENT_WAIT_SLOTS_JOIN_V1 ||
           module->abi.taskPoolOwnershipAbi == XL6_IR_MODULE_TASK_POOL_OWNERSHIP_RESIDENT_NATIVE_JOBS_JOIN_V1
            ? XL6_IR_MODULE_RETIREMENT_OWNED_SERVICES_GRAPH_V3 : XL6_IR_MODULE_RETIREMENT_PREPARED_GRAPH_V2)
        : XL6_IR_MODULE_RETIREMENT_NONE;
    module->abi.cellStorageAbi = XL6_IR_CELL_STORAGE_RESIDENT_TRANSFER_V1;
    module->abi.valueIteratorStorageAbi = XL6_IR_VALUE_ITERATOR_STORAGE_RESIDENT_CHECKED_SNAPSHOT_V2;
    module->abi.slotTransferAbi = XL6_IR_SLOT_TRANSFER_RESIDENT_ORDERED_WRITES_V1;
    module->abi.generatorStorageAbi = XL6_IR_GENERATOR_STORAGE_RESIDENT_CLOSED_FRAME_V2;
    module->abi.asyncStorageAbi = XL6_IR_ASYNC_STORAGE_RESIDENT_CLOSED_FRAME_V2;
    module->abi.taskStorageAbi = XL6_IR_TASK_STORAGE_RESIDENT_LAYOUT_FRAME_POOL_V2;
    module->abi.classStorageAbi = XL6_IR_CLASS_STORAGE_RESIDENT_GRAPH_V2;
    module->abi.futureAggregateAbi = xl6IrModuleFutureAggregateRequirement(module);
    module->stage = XL6_IR_STAGE_LOWERED;
    if ( !xl6IrRefreshReachability(module) ) {
        (void)xl6IrLowerDiag(&ctx, module->root,
                            "XLIR lowering could not build canonical callable reachability");
        xrtFree(ctx.loops);
        xrtFree(ctx.loopResources);
        xrtFree(ctx.exceptions);
        xrtFree(ctx.catchPayloads);
        xl6IrLowerDisposeDeferredReturns(&ctx);
        xrtFree(ctx.finallyBarriers);
        xrtFree(ctx.deferredLoopExits);
        xrtFree(ctx.promotedParameters);
        return 0;
    }
    if ( !xl6IrLowerCanonicalizeDeadTrivialStorages(module) ) {
        (void)xl6IrLowerDiag(&ctx, module->root,
                            "XLIR lowering could not canonicalize dead trivial storage");
        xrtFree(ctx.loops);
        xrtFree(ctx.loopResources);
        xrtFree(ctx.exceptions);
        xrtFree(ctx.catchPayloads);
        xl6IrLowerDisposeDeferredReturns(&ctx);
        xrtFree(ctx.finallyBarriers);
        xrtFree(ctx.deferredLoopExits);
        xrtFree(ctx.promotedParameters);
        return 0;
    }
    if ( !xl6IrBuildCallbackBoundaries(module, diags) ||
         !xl6IrBuildAsyncMachines(module, diags) ) {
        if ( diags == NULL || diags->count == 0 )
            (void)xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering could not derive async suspension/liveness facts");
        xrtFree(ctx.loops);
        xrtFree(ctx.loopResources);
        xrtFree(ctx.exceptions);
        xrtFree(ctx.catchPayloads);
        xl6IrLowerDisposeDeferredReturns(&ctx);
        xrtFree(ctx.finallyBarriers);
        xrtFree(ctx.deferredLoopExits);
        xrtFree(ctx.promotedParameters);
        return 0;
    }
    if ( !xl6IrBuildGeneratorMachines(module, diags) ||
         !xl6IrBuildCallableBridges(module, diags) ||
         !xl6IrBuildPersistenceProjectPlans(module) ||
         !xl6IrBuildPersistenceRestorePlans(module) ) {
        if ( diags == NULL || diags->count == 0 )
            (void)xl6IrLowerDiag(&ctx, module->root,
                "XLIR lowering could not derive generator, callable or persistence schema facts");
        xrtFree(ctx.loops);
        xrtFree(ctx.loopResources);
        xrtFree(ctx.exceptions);
        xrtFree(ctx.catchPayloads);
        xl6IrLowerDisposeDeferredReturns(&ctx);
        xrtFree(ctx.finallyBarriers);
        xrtFree(ctx.deferredLoopExits);
        xrtFree(ctx.promotedParameters);
        return 0;
    }
    xl6IrBindModuleStorageTrace(module);
    xl6IrLowerRefreshStats(module);
    xrtFree(ctx.loops);
    xrtFree(ctx.loopResources);
    xrtFree(ctx.exceptions);
    xrtFree(ctx.catchPayloads);
    xl6IrLowerDisposeDeferredReturns(&ctx);
    xrtFree(ctx.finallyBarriers);
    xrtFree(ctx.deferredLoopExits);
    xrtFree(ctx.promotedParameters);
    return xl6IrVerifyModule(module, diags);
}
